#nullable enable
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;

namespace Stomme.Models.Pipelines
{
    /// <summary>
    /// BL-229 - an n8n workflow brought over, for a team leaving n8n: its nodes become this site's steps where a step does the same
    /// - a webhook, a schedule, an HTTP request, IF, Switch, Wait, Edit Fields and Rename Keys, the record steps, a Code node's
    /// JavaScript, Stop and Error, a wait on a call or a form, any node's "send and wait" (Ask for approval, or a form), an AI
    /// agent, an LLM chain, an extractor and a classifier - with
    /// what of their parameters maps plainly, and its connections, positions, sticky notes, switched-off nodes, notes and retry
    /// settings come too. A node no step here does stays in its place as a switched-off placeholder, connected as it was, and a
    /// note on the canvas lists what is left to finish - placeholders, conditions to set, expressions written for n8n's items,
    /// credentials. The result is a graph like any other: the save judges it, and nothing runs that an author has not looked at.
    /// </summary>
    public static class N8nWorkflowImport
    {
        /// <summary>The name a converted document carries in <see cref="PipelineExchangeDocument.ConvertedFrom"/>.</summary>
        public const string Source = "n8n";

        /// <summary>The step a node with no counterpart here becomes - switched off, so it runs nothing.</summary>
        public const string PlaceholderType = "Stomme.LogMessage";

        // n8n's canvas is denser than this one's: its node is a 100px square, a step here twice as wide.
        private const double ScaleX = 1.25;
        private const double ScaleY = 1.0;
        private const double Left = 330; // the to-do note's column comes first
        private const double Top = 40;

        /// <summary>Whether a JSON document is an n8n workflow export: nodes with types, and connections by node name.</summary>
        public static bool IsWorkflow(JsonElement root) =>
            root.ValueKind == JsonValueKind.Object
            && root.TryGetProperty("nodes", out var nodes) && nodes.ValueKind == JsonValueKind.Array
            && root.TryGetProperty("connections", out var connections) && connections.ValueKind == JsonValueKind.Object
            && !root.TryGetProperty("format", out _);

        // Ports: what n8n's own outputs become, in n8n's order ("" for one no outcome here matches; none at all, the step's one
        // outcome) - then Failed, when the step has a Failed path for n8n's error output to become.
        private sealed record Mapping(string Type, string[] Ports, Action<JsonElement, PipelineGraphStep, Todo>? Fill = null);

        // What is left to finish, said per node, in the order the nodes come.
        private sealed class Todo
        {
            public List<string> Lines { get; } = new();

            public string Node { get; set; } = "";

            // The node's typeVersion, for a node whose parameters changed meaning across n8n's versions (Edit Fields).
            public double Version { get; set; }

            public void Add(string what) => Lines.Add("'" + Node + "': " + what);
        }

        private const string Done = "Done";
        private const string Failed = "Failed";
        private static readonly string[] None = Array.Empty<string>();
        private static readonly string[] DoneFailed = { Done, Failed };

        // n8n's node types (the part after "n8n-nodes-base.") and what each becomes.
        private static readonly Dictionary<string, Mapping> Base = new(StringComparer.OrdinalIgnoreCase)
        {
            ["webhook"] = new("Stomme.Webhook", None, (p, step, todo) =>
            {
                Set(step, "WebhookName", Text(p, "path").Trim('/'));
                if (Text(p, "responseMode") == "responseNode")
                {
                    Set(step, "Answer", "FromThePipeline");
                }

                // Its callers change how they call: here every call is a POST signed with the site's webhook secret.
                var method = Text(p, "httpMethod") is { Length: > 0 } verb ? verb.ToUpperInvariant() : "GET";
                var signedIn = Text(p, "authentication") is { Length: > 0 } auth && auth != "none" ? "with its " + auth : "unsigned";
                todo.Add("n8n took its calls by " + method + ", " + signedIn + " - here a caller POSTs to api/Pipelines/webhooks/" + Text(p, "path").Trim('/')
                    + ", signed with X-Signature-256 (an HMAC-SHA256 of the body under the site's webhook secret).");
            }),
            ["scheduleTrigger"] = new("Stomme.Schedule", None, (p, step, todo) =>
            {
                // Every rule a cron line of its own (one schedule fires on each); a rule that maps to none, said.
                var rules = Items(p, "rule", "interval").ToList();
                var lines = rules.Select(Cron).Where(line => line is not null).Select(line => FiveFields(line!, todo)).Distinct().ToList();
                if (lines.Count > 0)
                {
                    Set(step, "Cron", string.Join("\n", lines));
                }

                if (lines.Count < Math.Max(1, rules.Count))
                {
                    todo.Add(lines.Count == 0 ? "set its schedule - n8n's rule did not map to a cron line." : "one of n8n's rules did not map to a cron line - add it as a line of its own.");
                }
            }),
            ["formTrigger"] = new("Stomme.Form", None, (p, step, todo) =>
            {
                Set(step, "FormName", Text(p, "path").Trim('/'));
                Set(step, "Title", Text(p, "formTitle"));
                Set(step, "Description", Text(p, "formDescription"));
                FormFields(p, step, todo);
                Set(step, "SubmitLabel", Text(p, "options", "buttonLabel"));
                Set(step, "Answer", Text(p, "options", "respondWithOptions", "values", "formSubmittedText"));
                if (Text(p, "options", "respondWithOptions", "values", "respondWith") == "redirect")
                {
                    Set(step, "Redirect", Text(p, "options", "respondWithOptions", "values", "redirectUrl")); // n8n's redirect once sent
                }

                if (Text(p, "responseMode") is "lastNode" or "responseNode")
                {
                    todo.Add("it answered the person with what the workflow made - here the form shows its Answer once submitted.");
                }
            }),
            ["errorTrigger"] = new("Stomme.PipelineFailed", None),
            ["executeWorkflowTrigger"] = new("Stomme.WhenCalled", None),
            ["localFileTrigger"] = new(PipelineFileEvent.StepType, None, LocalFileTrigger),
            ["emailReadImap"] = new(PipelineEmailEvent.StepType, None, EmailTrigger),
            ["gmailTrigger"] = new(PipelineEmailEvent.StepType, None, GmailTrigger),
            ["telegramTrigger"] = new(PipelineTelegramEvent.StepType, None, TelegramTrigger),
            ["httpRequest"] = new("Stomme.SendHttpRequest", DoneFailed, Http),
            // n8n's GraphQL node: its query and variables POSTed as JSON to its endpoint - the HTTP request it is.
            ["graphql"] = new("Stomme.SendHttpRequest", DoneFailed, (p, step, todo) =>
            {
                Set(step, "Url", Text(p, "endpoint"));
                var query = Text(p, "query");
                var variables = Text(p, "variables");
                if (Text(p, "requestMethod") == "GET")
                {
                    Set(step, "Method", "GET");
                    todo.Add("it sent its query in the address (GET) - here add it to the URL as ?query=...");
                }
                else if (query.StartsWith('=') || variables.StartsWith('='))
                {
                    Set(step, "Method", "POST");
                    Set(step, "ContentType", "application/json");
                    todo.Add("its query or variables were n8n expressions - here write the JSON body, {\"query\": ..., \"variables\": ...}.");
                }
                else
                {
                    Set(step, "Method", "POST");
                    Set(step, "ContentType", "application/json");
                    var body = new System.Text.Json.Nodes.JsonObject { ["query"] = query };
                    if (variables.Trim().Length > 0)
                    {
                        try
                        {
                            body["variables"] = System.Text.Json.Nodes.JsonNode.Parse(variables);
                        }
                        catch (JsonException)
                        {
                            todo.Add("its variables were not JSON - add them to the body.");
                        }
                    }

                    Set(step, "Body", body.ToJsonString());
                }

                var headers = Items(p, "headerParametersUi", "parameter").Where(header => Text(header, "name").Length > 0).Select(header => Text(header, "name") + ": " + Text(header, "value")).ToList();
                Set(step, "Headers", string.Join("\n", headers));
                todo.Add("its answer is GraphQL's: the records are in the body's data.");
            }),
            // n8n's FTP node, over FTP or SFTP, as Extract from connection through the site's FTP or SFTP connection: every operation.
            ["ftp.list"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Ftp(p, step, todo, "list")),
            ["ftp.download"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Ftp(p, step, todo, "download")),
            ["ftp.upload"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Ftp(p, step, todo, "upload")),
            ["ftp.delete"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Ftp(p, step, todo, "delete")),
            ["ftp.rename"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Ftp(p, step, todo, "rename")),
            // n8n's SSH node, as Extract from connection through the site's SSH connection: a command, a file's download and upload.
            ["ssh.execute"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Ssh(p, step, todo, "execute")),
            ["ssh.download"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Ssh(p, step, todo, "download")),
            ["ssh.upload"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Ssh(p, step, todo, "upload")),
            ["postgres.query"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => SqlQuery(p, step, todo, "PostgreSQL", numbered: true)),
            ["microsoftSql.query"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => SqlQuery(p, step, todo, "SQL Server", numbered: false)),
            ["postgres.statement"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => SqlStatement(p, step, todo, "PostgreSQL", SqlDialect.Postgres)),
            // n8n's TimescaleDB, QuestDB and CrateDB nodes - PostgreSQL's protocol, so the PostgreSQL connector's: their Execute Query,
            // their insert (and update), the key 'id' when the export leaves n8n's default out.
            ["timescaleDb.query"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => SqlQuery(p, step, todo, "PostgreSQL", numbered: true, TimescaleConnection)),
            ["timescaleDb.statement"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => SqlStatement(p, step, todo, "PostgreSQL", SqlDialect.Postgres, TimescaleConnection, "id")),
            ["questDb.query"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => SqlQuery(p, step, todo, "PostgreSQL", numbered: true, QuestConnection)),
            ["questDb.statement"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => SqlStatement(p, step, todo, "PostgreSQL", SqlDialect.QuestDb, QuestConnection)),
            ["crateDb.query"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => SqlQuery(p, step, todo, "PostgreSQL", numbered: true, CrateConnection)),
            ["crateDb.statement"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => SqlStatement(p, step, todo, "PostgreSQL", SqlDialect.Postgres, CrateConnection, "id")),
            ["microsoftSql.statement"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => SqlStatement(p, step, todo, "SQL Server", SqlDialect.SqlServer)),
            ["mySql.query"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => SqlQuery(p, step, todo, "MySQL", numbered: true)),
            ["mySql.statement"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => SqlStatement(p, step, todo, "MySQL", SqlDialect.MySql)),
            ["redis.info"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Redis(p, step, todo, "info")),
            ["redis.get"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Redis(p, step, todo, "get")),
            ["redis.set"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Redis(p, step, todo, "set")),
            ["redis.delete"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Redis(p, step, todo, "delete")),
            ["redis.incr"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Redis(p, step, todo, "incr")),
            ["redis.keys"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Redis(p, step, todo, "keys")),
            ["redis.llen"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Redis(p, step, todo, "llen")),
            ["redis.push"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Redis(p, step, todo, "push")),
            ["redis.pop"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Redis(p, step, todo, "pop")),
            ["redis.publish"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => Redis(p, step, todo, "publish")),
            ["mongoDb.find"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => MongoDb(p, step, todo, "find")),
            ["mongoDb.insert"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => MongoDb(p, step, todo, "insert")),
            ["mongoDb.update"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => MongoDb(p, step, todo, "update")),
            ["mongoDb.find_and_update"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => MongoDb(p, step, todo, "find_and_update")),
            ["mongoDb.find_and_replace"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => MongoDb(p, step, todo, "find_and_replace")),
            ["mongoDb.delete"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => MongoDb(p, step, todo, "delete")),
            ["mongoDb.aggregate"] = new("Stomme.ExtractFromConnection", DoneFailed, (p, step, todo) => MongoDb(p, step, todo, "aggregate")),
            ["if"] = new("Stomme.FlowDecision", new[] { "True", "False" }, (p, step, todo) =>
            {
                var condition = Condition(p, records: false, todo);
                if (condition.Rules.Count > 0)
                {
                    step.InputConditions["Condition"] = condition;
                }
            }),
            ["switch"] = new("Stomme.FlowSwitch", None, Switch),
            ["wait"] = new("Stomme.Wait", None, (p, step, todo) =>
            {
                var resume = Text(p, "resume");
                if (resume is "" or "timeInterval")
                {
                    Set(step, "For", (Text(p, "amount") is { Length: > 0 } amount ? amount : "1") + " " + (Text(p, "unit") is { Length: > 0 } unit ? unit : "hours"));
                }
                else if (resume == "specificTime")
                {
                    Set(step, "Until", Text(p, "dateTime"));
                }
                else
                {
                    todo.Add("it waited for " + resume + " in n8n - here, Wait for a call, Wait for a form or Ask for approval do that.");
                }
            }),

            // n8n's waits on a person or another system, and its "send and wait" on any node: the run parked here the same way. A
            // wait's time limit is its Timed out, and n8n's one output is every way it goes on (see Fan).
            ["wait.webhook"] = new(PipelineCalls.WaitStepType, new[] { PipelineCalls.Called }, (p, step, todo) =>
            {
                Set(step, PipelineCalls.TimeOutInput, Bool(p, "limitWaitTime") ? Limit(p, todo) : null);
                todo.Add("it waited for a call to n8n's resume address ($execution.resumeUrl) - here a 'Call address' step makes the address: put one before the step that hands it on.");
            }),
            ["wait.form"] = new(WaitForFormType, new[] { FormSubmitted }, (p, step, todo) =>
            {
                Set(step, "Title", Text(p, "formTitle"));
                Set(step, "Description", Text(p, "formDescription"));
                FormFields(p, step, todo);
                Set(step, "SubmitLabel", Text(p, "options", "buttonLabel"));
                Set(step, PipelineCalls.TimeOutInput, Bool(p, "limitWaitTime") ? Limit(p, todo) : null);
                todo.Add("it waited for n8n's form ($execution.resumeFormUrl) - here a 'Call address' step makes the form's address, its Form address: put one before the step that hands it on.");
            }),
            ["form.page"] = new(WaitForFormType, new[] { FormSubmitted }, (p, step, todo) =>
            {
                Set(step, "Title", Text(p, "formTitle") is { Length: > 0 } title ? title : Text(p, "options", "formTitle"));
                Set(step, "Description", Text(p, "formDescription") is { Length: > 0 } description ? description : Text(p, "options", "formDescription"));
                FormFields(p, step, todo);
                Set(step, "SubmitLabel", Text(p, "options", "buttonLabel"));
                Set(step, PipelineForms.NextPageInput, "true"); // the person who sent the form before it is taken on to it, as in n8n
            }),
            ["sendAndWait.approval"] = new("Stomme.AskForApproval", new[] { PipelineApprovals.Approved }, (p, step, todo) =>
            {
                var subject = Unmarked(Text(p, "subject"));
                var message = Unmarked(Text(p, "message"));
                Set(step, "Question", subject.Length > 0 ? subject : message);
                Set(step, "Details", subject.Length > 0 ? message : null);
                Set(step, "DecideWithin", Find(p, "options", "limitWaitTime", "values") is { ValueKind: JsonValueKind.Object } limit ? Limit(limit, todo) : null);
                var recipients = Recipients(p);
                if (recipients.Count > 0)
                {
                    Set(step, "Notify", string.Join("\n", recipients.Select(address => "email:" + address)));
                    Set(step, "NotifyBy", "Email");
                }
                else
                {
                    todo.Add("it asked through its own channel in n8n - here those who may decide are told in the app or by e-mail: set Notify.");
                }

                if (ReadsN8nItems(subject) || ReadsN8nItems(message))
                {
                    todo.Add("its question reads n8n's items ($json) - here it reads the run's variables; rewrite it.");
                }

                todo.Add("its answer is the way the run goes on here, Approved or Rejected - both go on as n8n's one output did, so an IF on $json.data.approved after it can go.");
            }),
            ["sendAndWait.form"] = new(WaitForFormType, new[] { FormSubmitted }, (p, step, todo) =>
            {
                Set(step, "Title", Text(p, "options", "responseFormTitle") is { Length: > 0 } title ? title
                    : Unmarked(Text(p, "subject")) is { Length: > 0 } subject ? subject : step.Name); // a chat message has no subject
                Set(step, "Description", Text(p, "options", "responseFormDescription") is { Length: > 0 } description ? description : Unmarked(Text(p, "message")));
                if (Text(p, "responseType") == "freeText")
                {
                    Set(step, "Fields", PipelineForms.Serialize(new[] { new PipelineFormField { Label = "Response", Name = "text", Type = PipelineFormFieldTypes.LongText, Required = true } }));
                }
                else
                {
                    FormFields(p, step, todo);
                }

                Set(step, "SubmitLabel", Text(p, "options", "responseFormButtonLabel"));
                Set(step, PipelineCalls.TimeOutInput, Find(p, "options", "limitWaitTime", "values") is { ValueKind: JsonValueKind.Object } limit ? Limit(limit, todo) : null);
                if (ReadsN8nItems(Text(p, "subject")) || ReadsN8nItems(Text(p, "message")))
                {
                    todo.Add("its message reads n8n's items ($json) - here the form's words read the run's variables; rewrite them.");
                }
                todo.Add("it sent a link to its form in a message - here a 'Call address' step makes the form's address, its Form address: send it with a notification before this step.");
            }),
            ["noOp"] = new("Stomme.FlowNode", None, (p, step, todo) =>
                step.Comment ??= "n8n's No Operation: it does nothing, and the run goes on."), // an empty container, which the problems list says
            ["set"] = new("Stomme.MapFields", DoneFailed, EditFields),
            ["code"] = new("Stomme.RunScript", DoneFailed, (p, step, todo) =>
            {
                if (Text(p, "language") == "python")
                {
                    Set(step, "Script", Text(p, "pythonCode"));
                    todo.Add("its code is Python - Run script runs JavaScript.");
                }
                else
                {
                    Set(step, "Script", Text(p, "jsCode"));
                    Set(step, "Style", Text(p, "mode") == "runOnceForEachItem" ? EachItem : AllItems);
                    todo.Add(CodeNote(Text(p, "jsCode")));
                }
            }),
            ["filter"] = new("Stomme.FilterRecords", DoneFailed, (p, step, todo) =>
            {
                var condition = Condition(p, records: true, todo);
                if (condition.Rules.Count > 0)
                {
                    step.Inputs["Condition"] = PipelineConditions.Write(condition);
                }
            }),
            ["sort"] = new("Stomme.SortRecords", DoneFailed, (p, step, todo) =>
            {
                var lines = Items(p, "sortFieldsUi", "sortField")
                    .Select(field => Text(field, "fieldName") + (Text(field, "order") == "descending" ? " desc" : ""))
                    .Where(line => line.Trim().Length > 0);
                Set(step, "SortBy", string.Join("\n", lines));
            }),
            ["limit"] = new("Stomme.LimitRecords", DoneFailed, (p, step, todo) =>
            {
                Set(step, "MaxRecords", Text(p, "maxItems") is { Length: > 0 } max ? max : "1");
                if (Text(p, "keep") == "lastItems")
                {
                    Set(step, "Keep", "Last");
                }
            }),
            ["removeDuplicates"] = new("Stomme.RemoveDuplicates", DoneFailed, (p, step, todo) =>
            {
                if (Text(p, "operation") is "removeItemsRepeatedWithinPreviousExecutions" or "clearDeduplicationHistory")
                {
                    // BL-229: what earlier runs had seen - Remove records seen before.
                    SeenBefore(p, step, todo);
                }
                else if (Text(p, "compare") == "selectedFields")
                {
                    Set(step, "CompareFields", FieldNames(p, "fieldsToCompare"));
                }
                else if (Text(p, "compare") == "allFieldsExcept")
                {
                    todo.Add("it compared every field but " + FieldNames(p, "fieldsToExclude") + " - here name the fields it compares.");
                }
            }),
            ["splitOut"] = new("Stomme.SplitOut", DoneFailed, (p, step, todo) => Set(step, "Field", Text(p, "fieldToSplitOut"))),
            ["summarize"] = new("Stomme.SummarizeRecords", DoneFailed, (p, step, todo) =>
            {
                Set(step, "GroupBy", Text(p, "fieldsToSplitBy"));
                var lines = Items(p, "fieldsToSummarize", "values").Select(value => Aggregation(Text(value, "aggregation"), Text(value, "field"))).Where(line => line.Length > 0);
                Set(step, "Aggregations", string.Join("\n", lines));
            }),
            ["aggregate"] = new("Stomme.SummarizeRecords", DoneFailed, (p, step, todo) =>
            {
                // Each field into a list of its values, named as n8n named it - all the records one group, as n8n's one item.
                if (Text(p, "aggregate") == "aggregateAllItemData")
                {
                    todo.Add("it gathered every item into one list (" + (Text(p, "destinationFieldName") is { Length: > 0 } field ? field : "data") + ") - here list the fields it gathers.");
                    return;
                }

                var lines = Items(p, "fieldsToAggregate", "fieldToAggregate").Where(field => Text(field, "fieldToAggregate").Trim().Length > 0).Select(field =>
                {
                    var name = Text(field, "fieldToAggregate").Trim();
                    return "list " + name + " as " + (Bool(field, "renameField") && Text(field, "outputFieldName").Trim() is { Length: > 0 } output ? output : name);
                }).ToList();
                Set(step, "Aggregations", string.Join("\n", lines));
                if (lines.Count == 0)
                {
                    todo.Add("set its aggregations - n8n's Aggregate named no field.");
                }
            }),
            ["merge"] = new("Stomme.MergeRecords", DoneFailed, (p, step, todo) =>
            {
                // Appending, and a join on fields kept as n8n kept its rows (matches, all of the first, everything); its other ways
                // - by position, every pair, SQL, a chosen branch, the right join - named.
                var mode = Text(p, "mode") is { Length: > 0 } named ? named : "append";
                var joined = mode switch
                {
                    "append" => "Append",
                    "combine" when Text(p, "combineBy") is "" or "combineByFields" => Text(p, "joinMode") switch
                    {
                        "" or "keepMatches" => "KeepMatches",
                        "keepEverything" => "KeepEverything",
                        "enrichInput1" => "KeepAllFirst",
                        _ => null,
                    },
                    "mergeByKey" => "KeepAllFirst", // n8n's first Merge: the second input's data into the first's items
                    _ => null,
                };
                if (joined is null)
                {
                    todo.Add("it merged its inputs by " + (Text(p, "combineBy") is { Length: > 0 } by && mode == "combine" ? by + (Text(p, "joinMode") is { Length: > 0 } join ? " (" + join + ")" : "") : mode) + " - here Append, or a join on fields; choose its Mode.");
                }
                else
                {
                    Set(step, "Mode", joined);
                }

                var keys = Text(p, "fieldsToMatchString") is { Length: > 0 } listed
                    ? listed.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
                    : Items(p, "mergeByFields", "values").Select(value => (A: Text(value, "field1").Trim(), B: Text(value, "field2").Trim())).Where(key => key.A.Length > 0)
                        .Select(key => key.B.Length == 0 || key.B == key.A ? key.A : key.A + " = " + key.B).ToList();
                if (mode == "mergeByKey" && Text(p, "propertyName1").Trim() is { Length: > 0 } first)
