                Set(step, "To", !Bool(p, "toWhatsapp") || to.Length == 0 ? to : to.StartsWith('=') ? "=whatsapp:" + to[1..] : "whatsapp:" + to); // n8n's To WhatsApp: both ends whatsapp:
                Set(step, "Text", Text(p, "message"));
                var from = Text(p, "from");
                todo.Add("its account was n8n's Twilio credential, which an export never carries - make a Twilio connection (Admin > Connections) with the account's SID and auth token"
                    + (from.Length == 0 || from.StartsWith('=') ? ", its From the number the messages come from," : ", its From " + from + ",") + " and choose it here.");
            }),
            ["emailSend"] = new("Stomme.SendNotification", DoneFailed, (p, step, todo) =>
            {
                var to = Text(p, "toEmail");
                if (to.StartsWith('='))
                {
                    todo.Add("its recipients are an n8n expression - set Recipients here, email:address one per line.");
                }
                else
                {
                    Set(step, "Recipients", string.Join("\n", to.Split(new[] { ',', ';' }, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).Select(address => "email:" + address)));
                }

                Set(step, "Channels", "Email");
                var body = Unmarked(Text(p, "emailFormat") == "html" ? Text(p, "html") : Text(p, "text") is { Length: > 0 } text ? text : Text(p, "html"));
                var parameters = new List<string> { "subject = " + Unmarked(Text(p, "subject")) };
                if (!body.Contains('\n'))
                {
                    parameters.Add("body = " + body);
                }

                Set(step, "Parameters", string.Join("\n", parameters));
                todo.Add(body.Contains('\n')
                    ? "choose the notification template it sends - n8n's subject is its subject parameter; its text has several lines, so it goes in the template."
                    : "choose the notification template it sends - n8n's subject and text are its subject and body parameters.");
            }),
            ["executionData"] = new("Stomme.SaveRunData", DoneFailed, (p, step, todo) =>
            {
                var values = Items(p, "dataToSave", "values").Select(value => (Key: Text(value, "key").Trim(), Value: Unmarked(Text(value, "value")))).Where(value => value.Key.Length > 0).ToList();
                Set(step, "Data", string.Join("\n", values.Select(value => value.Key + ": " + value.Value)));
                if (values.Any(value => ReadsN8nItems(value.Value)))
                {
                    todo.Add("its values read n8n's items ($json) - here they read variables; rewrite them.");
                }
            }),
            ["cron"] = new("Stomme.Schedule", None, (p, step, todo) =>
            {
                var times = Items(p, "triggerTimes", "item").ToList();
                if (times.Count > 0 && LegacyCron(times[0]) is { } cron)
                {
                    Set(step, "Cron", FiveFields(cron, todo));
                }
                else
                {
                    todo.Add("set its schedule - n8n's trigger times did not map to a cron line.");
                }

                if (times.Count > 1)
                {
                    todo.Add("it had " + times.Count + " trigger times - a Schedule here has one; add a Schedule for each of the others.");
                }
            }),
            ["interval"] = new("Stomme.Schedule", None, (p, step, todo) =>
            {
                var every = Math.Max(1, Number(p, "interval") ?? 1);
                var unit = Text(p, "unit") is { Length: > 0 } named ? named : "seconds";
                if (unit == "seconds")
                {
                    Set(step, "Cron", "* * * * *");
                    todo.Add("it ran every " + every + " seconds - a schedule here runs at most once a minute.");
                }
                else if (unit == "minutes" && every < 60)
                {
                    Set(step, "Cron", $"*/{every} * * * *");
                }
                else if (unit == "hours" && every < 24)
                {
                    Set(step, "Cron", $"0 */{every} * * *");
                }
                else
                {
                    todo.Add("set its schedule - every " + every + " " + unit + " is not one cron line.");
                }
            }),
            // n8n's files: where n8n passes binary data between nodes, a step here reads and writes files in the site's pipeline
            // folder - so a file n8n named keeps its name there, and where n8n's binary data came from or went is named.
            ["readWriteFile"] = new("Stomme.ReadTextFile", DoneFailed, (p, step, todo) => FilePath(step, "Path", Text(p, "fileSelector"), todo)),
            ["readWriteFile.write"] = new("Stomme.WriteTextFile", DoneFailed, (p, step, todo) =>
            {
                FilePath(step, "Path", Text(p, "fileName"), todo);
                todo.Add("it wrote n8n's binary data - here Content is the text it writes (empty: the previous step's result).");
            }),
            ["readBinaryFile"] = new("Stomme.ReadTextFile", DoneFailed, (p, step, todo) => FilePath(step, "Path", Text(p, "filePath"), todo)),
            ["writeBinaryFile"] = new("Stomme.WriteTextFile", DoneFailed, (p, step, todo) => FilePath(step, "Path", Text(p, "fileName"), todo)),
            ["spreadsheetFile"] = new("Stomme.ReadSpreadsheet", DoneFailed, (p, step, todo) =>
                todo.Add("it read the spreadsheet n8n's binary data held - here Path names the file in the pipeline folder.")),
            ["spreadsheetFile.to"] = new("Stomme.WriteSpreadsheet", DoneFailed, (p, step, todo) =>
                FilePath(step, "Path", Text(p, "options", "fileName") is { Length: > 0 } file ? file : "spreadsheet." + (Text(p, "fileFormat") is { Length: > 0 } format ? format : "xlsx"), todo)),
            ["convertToFile.csv"] = new("Stomme.ToCsv", DoneFailed, (p, step, todo) => Set(step, "Delimiter", Text(p, "options", "delimiter"))),
            ["convertToFile.xlsx"] = new("Stomme.WriteSpreadsheet", DoneFailed, (p, step, todo) =>
                FilePath(step, "Path", Text(p, "options", "fileName") is { Length: > 0 } file ? file : "data.xlsx", todo)),
            ["extractFromFile.csv"] = new("Stomme.ParseCsv", DoneFailed, (p, step, todo) =>
            {
                Set(step, "Delimiter", Text(p, "options", "delimiter"));
                Set(step, "HasHeader", Text(p, "options", "headerRow") == "false" ? "false" : null);
                Set(step, "SkipLines", Number(p, "options", "fromLine") is int skip && skip > 0 ? skip.ToString(CultureInfo.InvariantCulture) : null);
                Set(step, "MaxRows", Number(p, "options", "maxRowCount") is int rows && rows > 0 ? rows.ToString(CultureInfo.InvariantCulture) : null);
            }),
            ["extractFromFile.sheet"] = new("Stomme.ReadSpreadsheet", DoneFailed, (p, step, todo) =>
                todo.Add("it read the spreadsheet in n8n's binary data - here Path names the file in the pipeline folder.")),
            ["extractFromFile.pdf"] = new("Stomme.ReadDocument", DoneFailed, (p, step, todo) =>
                todo.Add("it read the PDF in n8n's binary data - here Path names the file in the pipeline folder.")),
            ["compression"] = new("Stomme.CreateZipArchive", DoneFailed, (p, step, todo) =>
                todo.Add("it zipped n8n's binary data - here Source and Destination name files in the pipeline folder.")),
            ["compression.unzip"] = new("Stomme.ExtractZipArchive", DoneFailed, (p, step, todo) =>
                todo.Add("it unzipped n8n's binary data - here Path and Destination name files in the pipeline folder.")),
            ["compareDatasets"] = new("Stomme.CompareRecords", new[] { Done, Done, Done, Done, Failed }, (p, step, todo) =>
            {
                var keys = Items(p, "mergeByFields", "values").Select(value => (A: Text(value, "field1").Trim(), B: Text(value, "field2").Trim())).Where(key => key.A.Length > 0);
                Set(step, "MatchFields", string.Join("\n", keys.Select(key => key.B.Length == 0 || key.B == key.A ? key.A : key.A + " = " + key.B)));
                todo.Add("set Other records - n8n compared its two inputs; here one comes in, the other is a variable a branch saved. Its four outputs all go on from Done: each branch reads the one it needs - Only in first, Same, Different or Only in other.");
            }),
        };

        // Nodes whose meaning is their operation, as the entry that operation is (an operation with none stays a placeholder). Any
        // node's "send and wait" - e-mail, Gmail, Slack, Telegram... - asks a person, as Ask for approval or a form here does.
        private static string ByOperation(string kind, JsonElement p)
        {
            if (Text(p, "operation") == "sendAndWait")
            {
                return Text(p, "responseType") is "freeText" or "customForm" ? "sendAndWait.form" : "sendAndWait.approval";
            }

            return kind switch
            {
                "itemLists" => Text(p, "operation") switch
                {
                    "" or "splitOutItems" => "splitOut",
                    "sort" => "sort",
                    "limit" => "limit",
                    "removeDuplicates" => "removeDuplicates",
                    "summarize" => "summarize",
                    "aggregateItems" or "concatenateItems" => "aggregate",
                    _ => kind,
                },
                "wait" => Text(p, "resume") switch
                {
                    "webhook" => "wait.webhook",
                    "form" => "wait.form",
                    _ => kind,
                },
                "form" => Text(p, "operation") is "" or "page" ? "form.page" : kind, // its completion page has no step here
                "html" => Text(p, "operation") switch
                {
                    "extractHtmlContent" => kind,
                    "convertToHtmlTable" => "html.table",
                    _ => "html.template",
                },
                "readWriteFile" => Text(p, "operation") == "write" ? "readWriteFile.write" : kind,
                "spreadsheetFile" => Text(p, "operation") == "toFile" ? "spreadsheetFile.to" : kind,
                "convertToFile" => Text(p, "operation") is "" or "csv" ? "convertToFile.csv" : Text(p, "operation") == "xlsx" ? "convertToFile.xlsx" : kind,
                "extractFromFile" => Text(p, "operation") switch
                {
                    "" or "csv" => "extractFromFile.csv",
                    "xlsx" or "xls" or "ods" => "extractFromFile.sheet",
                    "pdf" => "extractFromFile.pdf",
                    _ => kind,
                },
                "compression" => Text(p, "operation") == "decompress" ? "compression.unzip" : kind,
                // Jira's issues created, updated, got and listed, and comments added; the rest have no step here.
                "jira" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "issue", Text(p, "operation")) switch
                {
                    ("issue", "" or "create") => "jira.create",
                    ("issue", "update") => "jira.update",
                    ("issue", "get") => "jira.get",
                    ("issue", "getAll") => "jira.getAll",
                    ("issueComment", "" or "add") => "jira.comment",
                    _ => kind,
                },
                // GitHub's issues, a release, a file and a workflow; its locks, reviews, users and the rest have no operation here.
                "github" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "issue", Text(p, "operation")) switch
                {
                    ("issue", "" or "create") => "github.createIssue",
                    ("issue", "createComment") => "github.createComment",
                    ("issue", "edit") => "github.editIssue",
                    ("issue", "get") => "github.getIssue",
                    ("repository", "getIssues") => "github.getIssues",
                    ("release", "create") => "github.createRelease",
                    ("file", "get") => "github.getFile",
                    ("file", "create" or "edit") => "github.commitFile",
                    ("workflow", "dispatch") => "github.dispatch",
                    _ => kind,
                },
                // Google Calendar's events and a calendar's availability; the rest have no operation here.
                "googleCalendar" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "event", Text(p, "operation")) switch
                {
                    ("event", "" or "create") => "googleCalendar.create",
                    ("event", "get") => "googleCalendar.get",
                    ("event", "getAll") => "googleCalendar.getAll",
                    ("event", "update") => "googleCalendar.update",
                    ("event", "delete") => "googleCalendar.delete",
                    ("calendar", "" or "availability") => "googleCalendar.availability",
                    _ => kind,
                },
                // Trello's cards, their comments and a list's cards; its boards, checklists, labels and the rest have no operation here.
                "trello" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "card", Text(p, "operation")) switch
                {
                    ("card", "" or "create") => "trello.createCard",
                    ("card", "get") => "trello.getCard",
                    ("card", "update") => "trello.updateCard",
                    ("card", "delete") => "trello.deleteCard",
                    ("cardComment", "" or "create") => "trello.comment",
                    ("list", "getCards") => "trello.listCards",
                    _ => kind,
                },
                // Asana's tasks and their comments; its search, subtasks, tags, projects and users have no operation here.
                "asana" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "task", Text(p, "operation")) switch
                {
                    ("task", "" or "create") => "asana.create",
                    ("task", "get") => "asana.get",
                    ("task", "getAll") => "asana.getAll",
                    ("task", "update") => "asana.update",
                    ("task", "move") => "asana.move",
                    ("task", "delete") => "asana.delete",
                    ("taskComment", "" or "add") => "asana.comment",
                    _ => kind,
                },
                // ClickUp's tasks and their comments; its lists, goals, time entries and the rest have no operation here.
                "clickUp" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "task", Text(p, "operation")) switch
                {
                    ("task", "" or "create") => "clickUp.create",
                    ("task", "get") => "clickUp.get",
                    ("task", "getAll") => "clickUp.getAll",
                    ("task", "update") => "clickUp.update",
                    ("task", "delete") => "clickUp.delete",
                    ("comment", "" or "create") => "clickUp.comment",
                    _ => kind,
                },
                // Stripe's customers, its charges listed and its balance; a charge made, coupons, cards, sources and tokens have no
                // operation here.
                "stripe" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "balance", Text(p, "operation")) switch
                {
                    ("balance", "" or "get") => "stripe.balance",
                    ("customer", "create") => "stripe.createCustomer",
                    ("customer", "get") => "stripe.getCustomer",
                    ("customer", "getAll") => "stripe.getCustomers",
                    ("customer", "update") => "stripe.updateCustomer",
                    ("customer", "delete") => "stripe.deleteCustomer",
                    ("charge", "getAll") => "stripe.getCharges",
                    _ => kind,
                },
                // Supabase's rows created, got, read, updated and deleted - every operation its node has.
                "supabase" => Text(p, "resource") is "" or "row" ? Text(p, "operation") switch
                {
                    "" or "create" => "supabase.create_rows",
                    "get" => "supabase.get_row",
                    "getAll" => "supabase.rows",
                    "update" => "supabase.update_rows",
                    "delete" => "supabase.delete_rows",
                    _ => kind,
                } : kind,
                // Mailchimp's members created, got, read, updated and deleted, their tags added and removed, and its campaigns got, read,
                // sent, replicated, resent and deleted; an audience's groups have no operation here.
                "mailchimp" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "member", Text(p, "operation")) switch
                {
                    ("member", "" or "create") => "mailchimp.add_member",
                    ("member", "get") => "mailchimp.get_member",
                    ("member", "getAll") => "mailchimp.members",
                    ("member", "update") => "mailchimp.update_member",
                    ("member", "delete") => "mailchimp.delete_member",
                    ("memberTag", "" or "create") => "mailchimp.tag_add",
                    ("memberTag", "delete") => "mailchimp.tag_remove",
                    ("campaign", "get") => "mailchimp.get_campaign",
                    ("campaign", "getAll") => "mailchimp.campaigns",
                    ("campaign", "send") => "mailchimp.send_campaign",
                    ("campaign", "replicate") => "mailchimp.replicate_campaign",
                    ("campaign", "resend") => "mailchimp.resend_campaign",
                    ("campaign", "delete") => "mailchimp.delete_campaign",
                    _ => kind,
                },
                // WooCommerce's orders, products and customers created, got, read, updated and deleted - every operation its node has.
                "wooCommerce" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "product", Text(p, "operation")) switch
                {
                    (var one and ("order" or "product" or "customer"), "" or "create") => "woocommerce.create_" + one,
                    (var one and ("order" or "product" or "customer"), "get") => "woocommerce.get_" + one,
                    (var one and ("order" or "product" or "customer"), "getAll") => "woocommerce." + one + "s",
                    (var one and ("order" or "product" or "customer"), "update") => "woocommerce.update_" + one,
                    (var one and ("order" or "product" or "customer"), "delete") => "woocommerce.delete_" + one,
                    _ => kind,
                },
                // Linear's issues created, got, read, updated, deleted and linked, and its comments added - every operation its node has.
                "linear" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "issue", Text(p, "operation")) switch
                {
                    ("issue", "" or "create") => "linear.create_issue",
                    ("issue", "get") => "linear.get_issue",
                    ("issue", "getAll") => "linear.issues",
                    ("issue", "update") => "linear.update_issue",
                    ("issue", "delete") => "linear.delete_issue",
                    ("issue", "addLink") => "linear.add_link",
                    ("comment", "" or "addComment") => "linear.add_comment",
                    _ => kind,
                },
                // GitLab's issues created, got, edited and commented on, a project's issues read, a release created and a file got,
                // created and edited; an issue locked, a release read, changed or deleted, a file deleted or listed and a user's
                // projects have no operation here.
                "gitlab" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "issue", Text(p, "operation")) switch
                {
                    ("issue", "" or "create") => "gitlab.create_issue",
                    ("issue", "get") => "gitlab.get_issue",
                    ("issue", "edit") => "gitlab.update_issue",
                    ("issue", "createComment") => "gitlab.comment",
                    ("repository", "" or "getIssues") => "gitlab.issues",
                    ("release", "" or "create") => "gitlab.release",
                    ("file", "get") => "gitlab.file",
                    ("file", "" or "create" or "edit") => "gitlab.commit_file",
                    _ => kind,
                },
                // Freshdesk's tickets and contacts created, got, read, updated and deleted - every operation its node has.
                "freshdesk" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "ticket", Text(p, "operation")) switch
                {
                    (var one and ("ticket" or "contact"), "" or "create") => "freshdesk.create_" + one,
                    (var one and ("ticket" or "contact"), "get") => "freshdesk.get_" + one,
                    (var one and ("ticket" or "contact"), "getAll") => "freshdesk." + one + "s",
                    (var one and ("ticket" or "contact"), "update") => "freshdesk.update_" + one,
                    (var one and ("ticket" or "contact"), "delete") => "freshdesk.delete_" + one,
                    _ => kind,
                },
                // monday.com's board items created, got, read (by a column's value too), changed, moved, deleted and updated, and its
                // boards read; a board made, archived or got, its columns and its groups have no operation here.
                "mondayCom" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "board", Text(p, "operation")) switch
                {
                    ("boardItem", "" or "create") => "monday.create_item",
                    ("boardItem", "get") => "monday.get_item",
                    ("boardItem", "getAll") => "monday.items",
                    ("boardItem", "getByColumnValue") => "monday.items_by_column_value",
                    ("boardItem", "changeMultipleColumnValues") => "monday.update_item",
                    ("boardItem", "changeColumnValue") => "monday.change_column",
                    ("boardItem", "move") => "monday.move_item",
                    ("boardItem", "delete") => "monday.delete_item",
                    ("boardItem", "addUpdate") => "monday.add_update",
                    ("board", "getAll") => "monday.boards",
                    _ => kind,
                },
                // Todoist's tasks created, quick-added, got, read, updated, closed, reopened, moved and deleted, a comment added and the
                // projects read; its sections, labels, reminders and the rest of its comments and projects have no operation here.
                "todoist" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "task", Text(p, "operation")) switch
                {
                    ("task", "" or "create") => "todoist.create_task",
                    ("task", "quickAdd") => "todoist.quick_add",
                    ("task", "get") => "todoist.get_task",
                    ("task", "getAll") => "todoist.tasks",
                    ("task", "update") => "todoist.update_task",
                    ("task", "close") => "todoist.close_task",
                    ("task", "reopen") => "todoist.reopen_task",
                    ("task", "move") => "todoist.move_task",
                    ("task", "delete") => "todoist.delete_task",
                    ("comment", "" or "create") => "todoist.add_comment",
                    ("project", "getAll") => "todoist.projects",
                    _ => kind,
                },
                // WordPress's posts and pages created, got, read, updated and deleted, its users created, got, read and updated; a
                // user deleted has no operation here.
                "wordpress" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "post", Text(p, "operation")) switch
                {
                    (var one and ("post" or "page"), "" or "create") => "wordpress.create_" + one,
                    (var one and ("post" or "page"), "get") => "wordpress.get_" + one,
                    (var one and ("post" or "page"), "getAll") => "wordpress." + one + "s",
                    (var one and ("post" or "page"), "update") => "wordpress.update_" + one,
                    (var one and ("post" or "page"), "delete") => "wordpress.delete_" + one,
                    ("user", "" or "create") => "wordpress.create_user",
                    ("user", "get") => "wordpress.get_user",
                    ("user", "getAll") => "wordpress.users",
                    ("user", "update") => "wordpress.update_user",
                    _ => kind,
                },
                // SendGrid's contacts added or changed, got, found and deleted, its lists made, got, read, renamed and deleted, and a
                // mail sent - every operation its node has.
                "sendGrid" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "list", Text(p, "operation")) switch
                {
                    ("list", "" or "create") => "sendgrid.create_list",
                    ("list", "get") => "sendgrid.get_list",
                    ("list", "getAll") => "sendgrid.lists",
                    ("list", "update") => "sendgrid.rename_list",
                    ("list", "delete") => "sendgrid.delete_list",
                    ("contact", "" or "upsert") => "sendgrid.upsert_contacts",
                    ("contact", "get") => "sendgrid.get_contact",
                    ("contact", "getAll") => "sendgrid.contacts",
                    ("contact", "delete") => "sendgrid.delete_contacts",
                    ("mail", "" or "send") => "sendgrid.send_mail",
                    _ => kind,
                },
                // Google Tasks' tasks created, got, read, updated and deleted - every operation its node has.
                "googleTasks" => Text(p, "operation") switch
                {
                    "" or "create" => "googletasks.create_task",
                    "get" => "googletasks.get_task",
                    "getAll" => "googletasks.tasks",
                    "update" => "googletasks.update_task",
                    "delete" => "googletasks.delete_task",
                    _ => kind,
                },
                // Google Docs' documents created, got and updated - every operation and update action its node has.
                "googleDocs" => Text(p, "operation") switch
                {
                    "" or "create" => "googledocs.create_document",
                    "get" => "googledocs.get_document",
                    "update" => "googledocs.update_document",
                    _ => kind,
                },
                // Brevo's (Sendinblue's) contacts, contact attributes, transactional e-mail and senders - every operation its node has.
                "sendInBlue" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "email", Text(p, "operation")) switch
                {
                    ("email", "" or "send" or "sendTemplate") => "brevo.send_email",
                    ("contact", "" or "create") => "brevo.create_contact",
                    ("contact", "upsert") => "brevo.upsert_contact",
                    ("contact", "get") => "brevo.get_contact",
                    ("contact", "getAll") => "brevo.contacts",
                    ("contact", "update") => "brevo.update_contact",
                    ("contact", "delete") => "brevo.delete_contact",
                    ("attribute", "" or "create") => "brevo.create_attribute",
                    ("attribute", "update") => "brevo.update_attribute",
                    ("attribute", "delete") => "brevo.delete_attribute",
                    ("attribute", "getAll") => "brevo.attributes",
                    ("sender", "" or "create") => "brevo.create_sender",
                    ("sender", "delete") => "brevo.delete_sender",
                    ("sender", "getAll") => "brevo.senders",
                    _ => kind,
                },
                // ActiveCampaign's contacts, lists, tags, deals, accounts and e-commerce records - every operation its node has; a contact the
                // default resource, each resource's default operation its own (Create, Add, or Get Many); a contact made with Update If Exists
                // made or changed.
                "activeCampaign" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "contact", Text(p, "operation")) switch
                {
                    ("contact", "" or "create") => Bool(p, "updateIfExists") ? "activecampaign.sync_contact" : "activecampaign.create_contact",
                    ("contact", "get") => "activecampaign.get_contact",
                    ("contact", "getAll") => "activecampaign.contacts",
                    ("contact", "update") => "activecampaign.update_contact",
                    ("contact", "delete") => "activecampaign.delete_contact",
                    ("contactList", "" or "add") => "activecampaign.add_to_list",
                    ("contactList", "remove") => "activecampaign.remove_from_list",
                    ("contactTag", "" or "add") => "activecampaign.add_tag",
                    ("contactTag", "remove") => "activecampaign.remove_tag",
