                    ("file", "update") => "googleDrive.update",
                    ("file", "copy") => "googleDrive.copy",
                    ("file", "move") => "googleDrive.move",
                    ("file", "deleteFile") or ("folder", "deleteFolder") => "googleDrive.delete",
                    ("file" or "folder", "share") => "googleDrive.share",
                    ("fileFolder", "" or "search") => "googleDrive.search",
                    ("folder", "" or "create") => "googleDrive.create_folder",
                    ("drive", "" or "create") => "googleDrive.create_drive",
                    ("drive", "deleteDrive") => "googleDrive.delete_drive",
                    ("drive", "get") => "googleDrive.get_drive",
                    ("drive", "list") => "googleDrive.drives",
                    ("drive", "update") => "googleDrive.update_drive",
                    _ => kind,
                },
                // Grist's rows - every operation its node has; its default Get Many Rows.
                "grist" => Text(p, "operation") switch
                {
                    "" or "getAll" => "grist.records",
                    "create" => "grist.create_record",
                    "update" => "grist.update_record",
                    "upsert" => "grist.upsert_record",
                    "delete" => "grist.delete_records",
                    _ => kind,
                },
                // NocoDB's rows - every operation its node has but an attachment's upload; its default Get, its Search and its older
                // Get Many a read of many.
                "nocoDb" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "row", Text(p, "operation")) switch
                {
                    ("row", "" or "get") => "nocodb.get_record",
                    ("row", "search" or "getAll") => "nocodb.records",
                    ("row", "create") => "nocodb.create_record",
                    ("row", "update") => "nocodb.update_record",
                    ("row", "upsert") => "nocodb.upsert_record",
                    ("row", "delete") => "nocodb.delete_record",
                    ("row", "count") => "nocodb.count_records",
                    _ => kind,
                },
                // Odoo's contacts, opportunities, notes, activities and any model's records created, got, read, updated and deleted - every
                // operation its node has; its default operation is its version's (Get Many, or Create in the first).
                "odoo" => Text(p, "operation") switch
                {
                    "" => "odoo.default",
                    "create" => "odoo.create_record",
                    "get" => "odoo.get_records",
                    "getAll" => "odoo.records",
                    "update" => "odoo.update_records",
                    "delete" => "odoo.delete_records",
                    _ => kind,
                },
                // Google Contacts' contacts created, got, read, updated and deleted - every operation its node has.
                "googleContacts" => Text(p, "operation") switch
                {
                    "" or "create" => "googlecontacts.create_contact",
                    "get" => "googlecontacts.get_contact",
                    "getAll" => "googlecontacts.contacts",
                    "update" => "googlecontacts.update_contact",
                    "delete" => "googlecontacts.delete_contact",
                    _ => kind,
                },
                // Microsoft To Do's lists and tasks created, got, read, updated and deleted; its linked resources have no operation
                // here. A task's and a list's default operation is Get.
                "microsoftToDo" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "task", Text(p, "operation")) switch
                {
                    ("task", "" or "get") => "microsofttodo.get_task",
                    ("task", "getAll") => "microsofttodo.tasks",
                    ("task", "create") => "microsofttodo.create_task",
                    ("task", "update") => "microsofttodo.update_task",
                    ("task", "delete") => "microsofttodo.delete_task",
                    ("list", "" or "get") => "microsofttodo.get_list",
                    ("list", "getAll") => "microsofttodo.lists",
                    ("list", "create") => "microsofttodo.create_list",
                    ("list", "update") => "microsofttodo.rename_list",
                    ("list", "delete") => "microsofttodo.delete_list",
                    _ => kind,
                },
                // Microsoft Excel 365's workbooks, sheets and tables - every operation its node has, its first version's too.
                "microsoftExcel" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "workbook", Text(p, "operation")) switch
                {
                    ("workbook", "" or "getAll") => "microsoftexcel.workbooks",
                    ("workbook", "addWorksheet") => "microsoftexcel.add_worksheet",
                    ("workbook", "deleteWorkbook") => "microsoftexcel.delete_workbook",
                    ("worksheet", "" or "getAll") => "microsoftexcel.worksheets",
                    ("worksheet", "readRows" or "getContent") => "microsoftexcel.read_rows",
                    ("worksheet", "append") => "microsoftexcel.append_rows",
                    ("worksheet", "update") => "microsoftexcel.update_rows",
                    ("worksheet", "upsert") => "microsoftexcel.upsert_rows",
                    ("worksheet", "clear") => "microsoftexcel.clear",
                    ("worksheet", "deleteWorksheet") => "microsoftexcel.delete_worksheet",
                    ("table", "" or "append" or "addRow") => "microsoftexcel.append_table_rows",
                    ("table", "getRows") => "microsoftexcel.table_rows",
                    ("table", "lookup") => "microsoftexcel.lookup",
                    ("table", "getColumns") => "microsoftexcel.table_columns",
                    ("table", "addTable") => "microsoftexcel.add_table",
                    ("table", "deleteTable") => "microsoftexcel.delete_table",
                    ("table", "convertToRange") => "microsoftexcel.convert_table",
                    _ => kind,
                },
                // Zendesk's tickets found, got, created, updated and deleted, its users searched, got and created, its organizations
                // read, got and created; a ticket recovered, ticket fields and the rest have no operation here.
                "zendesk" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "ticket", Text(p, "operation")) switch
                {
                    ("ticket", "" or "create") => "zendesk.create_ticket",
                    ("ticket", "get") => "zendesk.get_ticket",
                    ("ticket", "getAll") => "zendesk.tickets",
                    ("ticket", "update") => "zendesk.update_ticket",
                    ("ticket", "delete") => "zendesk.delete_ticket",
                    ("user", "" or "create") => "zendesk.create_user",
                    ("user", "get") => "zendesk.get_user",
                    ("user", "search" or "getAll") => "zendesk.users",
                    ("organization", "" or "create") => "zendesk.create_organization",
                    ("organization", "get") => "zendesk.get_organization",
                    ("organization", "getAll") => "zendesk.organizations",
                    _ => kind,
                },
                // Pipedrive's deals, persons, organizations, activities and products created, got, read, searched, updated and
                // deleted, and its notes added; leads, files, a deal's products, a duplicate and the rest have no operation here.
                "pipedrive" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "deal", Text(p, "operation")) switch
                {
                    ("note", "" or "create") => "pipedrive.note",
                    ("deal" or "person" or "organization" or "activity" or "product", var operation) => operation switch
                    {
                        "" or "create" => "pipedrive.create",
                        "get" => "pipedrive.get",
                        "getAll" => "pipedrive.getAll",
                        "search" => "pipedrive.search",
                        "update" => "pipedrive.update",
                        "delete" => "pipedrive.delete",
                        _ => kind,
                    },
                    _ => kind,
                },
                // Shopify's orders and products created, got, read, updated and deleted - every operation its node has.
                "shopify" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "order", Text(p, "operation")) switch
                {
                    ("order" or "product", "" or "create") => "shopify.create",
                    ("order" or "product", "get") => "shopify.get",
                    ("order" or "product", "getAll") => "shopify.getAll",
                    ("order" or "product", "update") => "shopify.update",
                    ("order" or "product", "delete") => "shopify.delete",
                    _ => kind,
                },
                // Salesforce's accounts, contacts, leads, opportunities, cases, tasks and custom objects created, created or updated,
                // got, read, updated and deleted, its users got and read, and its SOQL search; a lead or contact added to a campaign,
                // a note, a summary, attachments, documents and flows have no operation here.
                "salesforce" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "lead", Text(p, "operation")) switch
                {
                    ("search", "" or "query") => "salesforce.query",
                    ("user", "" or "get") => "salesforce.get",
                    ("user", "getAll") => "salesforce.getAll",
                    ("account" or "contact" or "lead" or "opportunity" or "case" or "task" or "customObject", var operation) => operation switch
                    {
                        "" or "create" => "salesforce.create",
                        "upsert" => "salesforce.upsert",
                        "get" => "salesforce.get",
                        "getAll" => "salesforce.getAll",
                        "update" => "salesforce.update",
                        "delete" => "salesforce.delete",
                        _ => kind,
                    },
                    _ => kind,
                },
                // HubSpot's contacts created or updated and got, its companies and deals created; the rest have no step here.
                "hubspot" => (Text(p, "resource") is { Length: > 0 } resource ? resource : "contact", Text(p, "operation")) switch
                {
                    ("contact", "" or "upsert") => "hubspot.contact.upsert",
                    ("contact" or "company" or "deal" or "ticket", "getAll") => "hubspot.getAll",
                    ("company" or "deal", "create") => "hubspot.create",
                    _ => kind,
                },
                // Outlook's messages sent, replied to and got; its folders, drafts, contacts and calendars have no step here.
                "microsoftOutlook" => Text(p, "resource") is "" or "message" ? Text(p, "operation") switch
                {
                    "" or "send" => "outlook.send",
                    "reply" => "outlook.reply",
                    "getAll" => "outlook.search",
                    _ => kind,
                } : kind,
                // Gmail's messages sent, replied to, got and marked as read; its labels, drafts and threads have no step here.
                "gmail" => Text(p, "resource") is "" or "message" ? Text(p, "operation") switch
                {
                    "" or "send" => "gmail.send",
                    "reply" => "gmail.reply",
                    "getAll" => "gmail.search",
                    "markAsRead" => "gmail.mark_read",
                    _ => kind,
                } : kind,
                // Notion's database pages got, created and updated; its blocks, databases, users and plain pages have none here.
                "notion" => Text(p, "resource") == "databasePage" ? Text(p, "operation") switch
                {
                    "getAll" => "notion.query",
                    "create" => "notion.create",
                    "update" => "notion.update",
                    _ => kind,
                } : kind,
                // Airtable's search and create (its newer node's names and its older one's); the rest have no operation here.
                "airtable" => Text(p, "operation") switch
                {
                    "" or "search" or "list" => "airtable.search",
                    "create" or "append" => "airtable.create",
                    _ => kind,
                },
                // Google Sheets' Get Rows and Append Row; its updates, deletes and clears have no operation here.
                "googleSheets" => Text(p, "resource") is "" or "sheet" && Text(p, "operation") is "" or "read" or "append" ? "googleSheets." + (Text(p, "operation") == "append" ? "append" : "read") : kind,
                // A chat node's message sent; its other operations (channels, files, reactions...) have no step here.
                "slack" => Text(p, "resource") is "" or "message" && (Text(p, "operation") is "" or "post") ? "slack.message" : kind,
                "telegram" => Text(p, "resource") is "" or "message" && (Text(p, "operation") is "" or "sendMessage") ? "telegram.message" : kind,
                "discord" => Text(p, "resource") is "" or "message" && (Text(p, "operation") is "" or "send") ? "discord.message" : kind,
                "mattermost" => Text(p, "resource") is "" or "message" && (Text(p, "operation") is "" or "post") ? "mattermost.message" : "mattermost.rest",
                "twilio" => Text(p, "resource") is "" or "sms" && (Text(p, "operation") is "" or "send") ? "twilio.sms" : kind,
                // WhatsApp's text message sent; a template (its default), media, a location, contacts and the rest have no step here.
                "whatsApp" => Text(p, "resource") is "" or "message" && Text(p, "operation") == "send" && Text(p, "messageType") is "" or "text" ? "whatsapp.message" : kind,
                // Microsoft Teams' channel and chat messages sent; its channels, tasks and the rest have no step here.
                "microsoftTeams" => (Text(p, "resource"), Text(p, "operation")) switch
                {
                    ("channelMessage", "" or "create") => "teams.channel",
                    ("chatMessage", "" or "create") => "teams.chat",
                    _ => kind,
                },
                // A truncate or a drop has no step here: it stays a placeholder rather than be written for the author.
                // n8n's TimescaleDB and CrateDB: Execute Query, Insert (their default) and Update; QuestDB's: Execute Query and Insert.
                "timescaleDb" or "crateDb" or "questDb" => Text(p, "operation") switch
                {
                    "executeQuery" => kind + ".query",
                    "" or "insert" or "update" => kind + ".statement",
                    _ => kind,
                },
                "postgres" => Text(p, "operation") switch
                {
                    "executeQuery" => "postgres.query",
                    "" or "insert" or "update" or "upsert" or "select" => "postgres.statement",
                    "deleteTable" => Text(p, "deleteCommand") == "delete" ? "postgres.statement" : kind,
                    _ => kind,
                },
                // n8n's SSH node: its command's Execute (the default) and its file's Download and Upload (the file's default).
                "ssh" => Text(p, "resource") == "file"
                    ? Text(p, "operation") switch
                    {
                        "download" => "ssh.download",
                        "" or "upload" => "ssh.upload",
                        _ => kind,
                    }
                    : Text(p, "operation") is "" or "execute" ? "ssh.execute" : kind,
                // n8n's FTP node, over FTP or SFTP: every operation, Download its default.
                "ftp" => Text(p, "operation") switch
                {
                    "" or "download" => "ftp.download",
                    "list" or "upload" or "delete" or "rename" => "ftp." + Text(p, "operation"),
                    _ => kind,
                },
                "microsoftSql" => Text(p, "operation") switch
                {
                    "executeQuery" => "microsoftSql.query",
                    "" or "insert" or "update" or "delete" => "microsoftSql.statement",
                    _ => kind,
                },
                // n8n's MongoDB: every document operation, Find its default; its search indexes have no step here.
                "mongoDb" => Text(p, "resource") is "" or "document" ? Text(p, "operation") switch
                    {
                        "" or "find" => "mongoDb.find",
                        "insert" => "mongoDb.insert",
                        "update" => "mongoDb.update",
                        "findOneAndUpdate" => "mongoDb.find_and_update",
                        "findOneAndReplace" => "mongoDb.find_and_replace",
                        "delete" => "mongoDb.delete",
                        "aggregate" => "mongoDb.aggregate",
                        _ => kind,
                    }
                    : kind,
                // n8n's Redis: every operation its node has, Info its default.
                "redis" => Text(p, "operation") switch
                {
                    "" or "info" => "redis.info",
                    "get" or "set" or "delete" or "incr" or "keys" or "llen" or "push" or "pop" or "publish" => "redis." + Text(p, "operation"),
                    _ => kind,
                },
                // n8n's MySQL (and its MariaDB use): a truncate or a drop stays a placeholder, as Postgres's does.
                "mySql" => Text(p, "operation") switch
                {
                    "executeQuery" => "mySql.query",
                    "" or "insert" or "update" or "upsert" or "select" => "mySql.statement",
                    "deleteTable" => Text(p, "deleteCommand") == "delete" ? "mySql.statement" : kind,
                    _ => kind,
                },
                _ => kind,
            };
        }

        // n8n's JWT node as JWT: sign, decode or verify, its algorithm, its claims - as JSON, or its registered claims as this
        // step's inputs, the rest into the claims - and its verify options. Its key was n8n's credential, never in the workflow.
        private static void JwtNode(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            var operation = Text(p, "operation") is { Length: > 0 } named ? named : "sign";
            Set(step, "Operation", operation switch { "decode" => "Decode", "verify" => "Verify", _ => "Sign" });
            if (Text(p, "options", "algorithm") is { Length: > 0 } algorithm)
            {
                if (algorithm is "HS256" or "HS384" or "HS512" or "RS256" or "RS384" or "RS512" or "ES256" or "ES384" or "ES512")
                {
                    Set(step, "Algorithm", algorithm);
                }
                else
                {
                    todo.Add("it signed with " + algorithm + " - here HS, RS or ES with 256, 384 or 512.");
                }
            }

            if (operation == "sign")
            {
                if (Bool(p, "useJson"))
                {
                    Set(step, "Claims", Text(p, "claimsJson"));
                }
                else
                {
                    var claims = new System.Text.Json.Nodes.JsonObject();
                    if (Text(p, "claims", "jwtid") is { Length: > 0 } id)
                    {
                        claims["jti"] = id;
                    }

                    if (claims.Count > 0)
                    {
                        Set(step, "Claims", claims.ToJsonString());
                    }

                    if (Text(p, "claims", "notBefore") is { Length: > 0 } notBefore)
                    {
                        todo.Add("it set not-before " + notBefore + " - here put \"nbf\" (seconds since 1970) in Claims.");
                    }
                }

                // n8n's token expires only when it says; this step's does in an hour unless told otherwise.
                Set(step, "ExpiresInSeconds", Text(p, "claims", "expiresIn") is { Length: > 0 } expires ? expires : "0");
                Set(step, "Issuer", Text(p, "claims", "issuer"));
                Set(step, "Audience", Text(p, "claims", "audience"));
                Set(step, "Subject", Text(p, "claims", "subject"));
            }
            else
            {
                Set(step, "Token", Text(p, "token"));
                if (operation == "verify")
                {
                    Set(step, "IgnoreExpiration", Bool(p, "options", "ignoreExpiration") ? "true" : null);
                    Set(step, "ClockToleranceSeconds", Text(p, "options", "clockTolerance"));
                    if (Bool(p, "options", "ignoreNotBefore"))
                    {
                        todo.Add("it ignored not-before - here a token used before its \"nbf\" is refused.");
                    }
                }

                if (Bool(p, "options", "complete"))
                {
                    todo.Add("it returned the header and signature too - here the result is the claims.");
                }
            }

            if (operation != "decode")
            {
                todo.Add("its key was n8n's JWT credential, which an export never carries - set Key here: the shared secret, or a PEM key (a run's data shows it hidden).");
            }
        }

        // n8n's TOTP node as TOTP's Generate: its algorithm, digits and period. Its secret was n8n's credential.
        private static void TotpNode(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            Set(step, "Operation", "Generate");
            Set(step, "Algorithm", Text(p, "options", "algorithm") switch { "SHA256" => "Sha256", "SHA512" => "Sha512", "SHA1" => "Sha1", _ => null });
            Set(step, "Digits", Text(p, "options", "digits"));
            Set(step, "Period", Text(p, "options", "period"));
            todo.Add("its secret was n8n's TOTP credential, which an export never carries - set Secret here: base32, or the otpauth:// link (a run's data shows it hidden).");
        }

        // n8n's Email Trigger (IMAP) as "Email received": its mailbox, its marking read (n8n's default) and its attachments. n8n
        // chose unread messages; here every message that arrives starts it, read or not - said, as its account is: an export
        // never carries n8n's credential, so the connection is chosen here.
        private static void EmailTrigger(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            Set(step, "Mailbox", Text(p, "mailbox"));
            Set(step, "MarkRead", Text(p, "postProcessAction") == "nothing" ? null : "true");
            Set(step, "KeepAttachments", Bool(p, "downloadAttachments") ? "true" : null);
            todo.Add("its account was n8n's IMAP credential, which an export never carries - make an IMAP connection (Admin > Connections) and choose it here.");
            var rules = Text(p, "options", "customEmailConfig");
            todo.Add(rules.Length == 0 || rules.Replace(" ", "", StringComparison.Ordinal) == "[\"UNSEEN\"]"
                ? "it started for unread messages - here for each message that arrives, read or not, followed by its UID."
                : "it chose messages by " + rules + " - here each message that arrives starts it.");
            if (Text(p, "format") == "raw")
            {
                todo.Add("it gave the raw message - here its headers, text, HTML and attachments.");
            }
        }

        // n8n's Gmail Trigger as "Email received" through a Gmail connection: the label it watched (INBOX when it named none) and
        // its attachments. Its filters - a search, read or unread, a sender - have no counterpart here: every message reaching the
        // label starts it, said; as are a second label, and its credential.
        private static void GmailTrigger(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            var filters = p.ValueKind == JsonValueKind.Object && p.TryGetProperty("filters", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            var labels = filters.ValueKind == JsonValueKind.Object && filters.TryGetProperty("labelIds", out var ids) && ids.ValueKind == JsonValueKind.Array
                ? ids.EnumerateArray().Select(id => id.GetString() ?? "").Where(id => id.Length > 0).ToList()
                : new List<string>();
            Set(step, "Mailbox", labels.FirstOrDefault());
            if (labels.Count > 1)
            {
                todo.Add($"it watched the labels {string.Join(", ", labels)} - here one label is watched, {labels[0]}: add a pipeline for each other.");
            }

            Set(step, "KeepAttachments", Bool(p, "options", "downloadAttachments") ? "true" : null);
            var kept = new[] { Text(filters, "q"), Text(filters, "readStatus") is "unread" or "read" ? "is:" + Text(filters, "readStatus") : "", Text(filters, "sender") is { Length: > 0 } sender ? "from:" + sender : "" }
                .Where(word => word.Length > 0).ToList();
            if (kept.Count > 0)
            {
                todo.Add($"it started only for the messages its filters kept ({string.Join(" ", kept)}) - here every message reaching the label starts it: put a Decision after it.");
            }

            todo.Add(GmailConnection);
        }

        // n8n's Telegram Trigger as "Telegram message received": its messages and channel posts; any other kind of update it started
        // on said; its webhook said, since here the bot is asked instead; its files downloaded said.
        private static void TelegramTrigger(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            todo.Add("its bot was n8n's Telegram credential, which an export never carries - make a Telegram connection (Admin > Connections) with the bot's token and choose it here.");
            var kinds = p.ValueKind == JsonValueKind.Object && p.TryGetProperty("updates", out var updates) && updates.ValueKind == JsonValueKind.Array
                ? updates.EnumerateArray().Select(update => update.ValueKind == JsonValueKind.String ? update.GetString() ?? "" : "").Where(kind => kind.Length > 0).ToList()
                : new List<string>();
            var others = kinds.Where(kind => kind is not ("message" or "channel_post" or "*")).ToList();
            if (kinds.Contains("*") || others.Count > 0)
            {
                todo.Add("it started on " + (kinds.Contains("*") ? "every kind of update" : string.Join(", ", others)) + " - here only messages and channel posts start it.");
            }

            todo.Add("n8n's trigger set a webhook on the bot - here the bot is asked for its messages instead, so delete that webhook (n8n deletes it when its workflow is switched off) or the bot answers no one else.");
            if (Text(p, "additionalFields", "download") == "true")
            {
                todo.Add("it downloaded the files sent - here a message's text, or a file's caption, starts it.");
            }
        }

        // n8n's Local File Trigger as "File added": a folder on n8n's disk as the folder of that name in the site's pipeline folder,
        // or a file watched as its name to match in the pipeline folder, written again included (all a file watch ever sees); File
        // Changed as "changed files too"; its depth as subfolders or none. What has no counterpart here is said: deletions and
        // folders, a depth stopped part way down, an ignore pattern, existing files counted.
        private static void LocalFileTrigger(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            var path = Text(p, "path");
            var name = path.Replace('\\', '/').Split('/', StringSplitOptions.RemoveEmptyEntries).LastOrDefault() ?? "";
            if (path.StartsWith('='))
            {
                todo.Add("it watched " + path + " - here it watches a folder of the site's pipeline folder; name it.");
            }
            else if (Text(p, "triggerOn") == "file")
            {
                Set(step, "Pattern", name);
                Set(step, "Changed", "true");
                if (name.Length > 0)
                {
                    todo.Add("it watched the file " + path + " on n8n's disk - here " + name + " in the site's pipeline folder starts it, put there or written again.");
                }
            }
            else
            {
                Set(step, "Folder", name);
                if (name.Length > 0 && name != path)
                {
                    todo.Add("its folder was " + path + " on n8n's disk - here it is " + name + " in the site's pipeline folder.");
                }

                var events = new List<string>();
                if (p.TryGetProperty("events", out var listed) && listed.ValueKind == JsonValueKind.Array)
                {
                    events.AddRange(listed.EnumerateArray().Where(item => item.ValueKind == JsonValueKind.String).Select(item => item.GetString()!));
                }

                if (events.Contains("change"))
                {
                    Set(step, "Changed", "true");
                }

                if (!events.Contains("add"))
                {
                    todo.Add("it did not watch for files added - here every file put there starts it.");
                }

                var unwatched = events.Where(watched => watched is "unlink" or "addDir" or "unlinkDir").ToList();
                if (unwatched.Count > 0)
                {
                    todo.Add("it watched for " + string.Join(", ", unwatched) + " too - here only files added and written again start it.");
                }
            }

            // n8n's Max Folder Depth: -1 (its default) every level, 0 the folder alone, 1 to 5 so many levels down.
            var depth = Number(p, "options", "depth") ?? -1;
            if (depth != 0 && Text(p, "triggerOn") != "file")
            {
                Set(step, "Subfolders", "true");
                if (depth > 0)
                {
                    todo.Add("it looked " + depth + " level(s) down - here every folder inside it is watched.");
                }
            }

            if (Text(p, "options", "ignored") is { Length: > 0 } ignored)
            {
                todo.Add("it ignored " + ignored + " - here name the files it takes in Files matching.");
            }

            if (Text(p, "options", "ignoreInitial") == "false")
            {
                todo.Add("it started for the files already there - here they start nothing.");
            }
        }

        // A file n8n named on its own disk, as a file in the site's pipeline folder: its name alone - a pattern or an expression
        // named instead, and a name that changed said.
        private static void FilePath(PipelineGraphStep step, string input, string path, Todo todo)
        {
            if (path.StartsWith('=') || path.IndexOfAny(new[] { '*', '?' }) >= 0)
            {
                todo.Add("it named its file " + path + " - here " + input + " is one file in the site's pipeline folder; name it.");
                return;
            }

            var name = path.Replace('\\', '/').Split('/', StringSplitOptions.RemoveEmptyEntries).LastOrDefault() ?? "";
            Set(step, input, name);
            if (name.Length > 0 && name != path)
            {
                todo.Add("its file was " + path + " on n8n's disk - here it is " + name + " in the site's pipeline folder.");
            }
        }

        // n8n's Date & Time: now, add and subtract, format, round down, the time between two dates and a part of one - as this
        // site's step's operations; rounding up, quarters and several units at once are named.
        private static void DateAndTime(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            switch (Text(p, "operation") is { Length: > 0 } named ? named : "getCurrentDate")
            {
                case "getCurrentDate":
                    Set(step, "Operation", "Format");
                    Set(step, "Format", Text(p, "includeTime") == "false" ? "date" : "iso");
                    break;
                case "addToDate" or "subtractFromDate":
                    Set(step, "Operation", Text(p, "operation") == "addToDate" ? "Add" : "Subtract");
                    Set(step, "Date", Text(p, "magnitude"));
                    var unit = Text(p, "timeUnit") is { Length: > 0 } timeUnit ? timeUnit : "days";
                    var amount = Text(p, "duration") is { Length: > 0 } duration ? duration : "0";
                    if (unit == "quarters")
                    {
                        todo.Add("it counted in quarters - here say it in months.");
                    }
                    else
                    {
                        Set(step, "Duration", amount + " " + unit); // n8n's expression for it, as an expression here (MoveExpressions)
                    }

                    break;
                case "formatDate":
                    Set(step, "Operation", "Format");
                    Set(step, "Date", Text(p, "date"));
                    Set(step, "Format", Text(p, "format") switch
                    {
                        "custom" => Text(p, "customFormat"),
                        "X" => "unix",
                        "x" => "unix-ms",
                        "" => "MM/dd/yyyy",
                        var preset => preset,
                    });
                    break;
                case "roundDate" when Text(p, "mode") != "roundUp":
                    Set(step, "Operation", "StartOf");
                    Set(step, "Date", Text(p, "date"));
                    Set(step, "Unit", DateUnit(Text(p, "toNearest") is { Length: > 0 } nearest ? nearest : "day"));
                    break;
                case "getTimeBetweenDates":
                    Set(step, "Operation", "Difference");
                    Set(step, "Date", Text(p, "startDate"));
                    Set(step, "OtherDate", Text(p, "endDate"));
                    var units = Find(p, "units").ValueKind == JsonValueKind.Array ? Find(p, "units").EnumerateArray().Select(value => Text(value)).Where(value => value.Length > 0).ToList() : new List<string>();
                    units = units.Count > 0 ? units : new List<string> { "day" };
                    Set(step, "Unit", DateUnit(units.FirstOrDefault() ?? "day"));
                    if (units.Count > 1)
                    {
                        todo.Add("it counted in " + string.Join(", ", units) + " at once - here the time between is counted in one unit.");
                    }

                    break;
                case "extractDate":
                    Set(step, "Operation", "Format");
                    Set(step, "Date", Text(p, "date"));
                    var part = Text(p, "part") is { Length: > 0 } which ? which : "year";
                    Set(step, "Format", part switch { "month" => "MM", "day" => "dd", "hour" => "HH", "minute" => "mm", "second" => "ss", "week" => null, _ => "yyyy" });
                    todo.Add(part == "week"
                        ? "it took the week out of the date - here say the date's format."
                        : "it took the " + part + " out as a number - here it is that part of the date, formatted.");
                    break;
                default:
                    todo.Add("set its operation - n8n's " + Text(p, "operation") + (Text(p, "mode") is { Length: > 0 } mode ? " (" + mode + ")" : "") + " has no counterpart here.");
                    break;
            }
        }

        private static string DateUnit(string unit) => unit.TrimEnd('s') switch
        {
            "second" => "Seconds",
            "minute" => "Minutes",
            "hour" => "Hours",
            "week" => "Weeks",
            "month" => "Months",
            "year" => "Years",
            _ => "Days",
        };

        // n8n's Crypto: a hash or an HMAC (MD5, SHA1, SHA256, SHA512, in hex or base64), a UUID or random text; a signature, or
        // another algorithm, is named.
        private static void Crypto(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            switch (Text(p, "action") is { Length: > 0 } named ? named : "hash")
            {
                case "hash" or "hmac":
                    Set(step, "Operation", Text(p, "action") == "hmac" ? "Hmac" : "Hash");
                    Set(step, "Value", Text(p, "value"));
                    Set(step, "Encoding", Text(p, "encoding") == "base64" ? "Base64" : "Hex");
                    Set(step, "Key", Text(p, "action") == "hmac" ? Text(p, "secret") : null);
                    var algorithm = Text(p, "type") is { Length: > 0 } type ? type : "MD5";
                    if ((algorithm switch { "MD5" => "Md5", "SHA1" => "Sha1", "SHA256" => "Sha256", "SHA512" => "Sha512", _ => null }) is { } known)
                    {
                        Set(step, "Algorithm", known);
                    }
                    else
                    {
                        todo.Add("it hashed with " + algorithm + " - here MD5, SHA1, SHA256 or SHA512.");
                    }

                    break;
                case "generate":
                    if (Text(p, "encodingType") is "" or "uuid")
                    {
                        Set(step, "Operation", "Uuid");
                    }
                    else
                    {
                        Set(step, "Operation", "RandomText");
                        Set(step, "Length", Text(p, "stringLength") is { Length: > 0 } length ? length : "32");
                        Set(step, "Encoding", Text(p, "encodingType") == "base64" ? "Base64" : "Hex");
                    }

                    break;
                default:
                    todo.Add("it signed a value in n8n - no step here signs; it is kept as a hash for now.");
                    Set(step, "Operation", "Hash");
                    break;
            }
        }

        // n8n's HTML extraction: each value's key and CSS selector, an attribute where it took one, as this site's fields; the HTML
        // is the previous step's result here, as an HTTP request's answer was the item's data there.
        private static void ExtractHtml(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            var values = Items(p, "extractionValues", "values").Where(value => Text(value, "key").Length > 0 && Text(value, "cssSelector").Length > 0).ToList();
            Set(step, "Fields", string.Join("\n", values.Select(value => Text(value, "key") + " = " + Text(value, "cssSelector")
                + (Text(value, "returnValue") == "attribute" && Text(value, "attribute") is { Length: > 0 } attribute ? " @" + attribute : ""))));
            var asHtml = values.Where(value => Text(value, "returnValue") == "html").Select(value => Text(value, "key")).ToList();
            if (asHtml.Count > 0)
            {
                todo.Add("its " + string.Join(", ", asHtml) + " took the element's HTML - here a field is its text or an attribute.");
            }

            if (Text(p, "sourceData") == "binary")
            {
                todo.Add("it read n8n's binary data - here HTML is the HTML it reads (empty: the previous step's result).");
            }
        }

        // n8n's AI nodes ("@n8n/n8n-nodes-langchain.").
        private static readonly Dictionary<string, Mapping> Ai = new(StringComparer.OrdinalIgnoreCase)
        {
            ["agent"] = new("Stomme.AiAgent", DoneFailed, (p, step, todo) =>
            {
                Set(step, "Prompt", Text(p, "text"));
                Set(step, "Instructions", Text(p, "options", "systemMessage"));
            }),
            ["chatTrigger"] = new("Stomme.ChatTrigger", None),
            // n8n's Sentiment Analysis: a text classified by its sentiment, each category an outcome as an output is there.
            ["sentimentAnalysis"] = new("Stomme.ClassifyText", new[] { Failed }, (p, step, todo) =>
            {
                Set(step, "Text", Text(p, "inputText"));
                var categories = (Text(p, "options", "categories") is { Length: > 0 } named ? named : "Positive, Neutral, Negative")
                    .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                Set(step, StepCatalogEntry.BranchesOutcomes, PipelineOutcomes.WriteBranches(categories));
                Set(step, "Instructions", Text(p, "options", "systemPromptTemplate") is { Length: > 0 } prompt && !prompt.Contains('{')
                    ? prompt
                    : "Classify the text by the sentiment it expresses.");
                if (Bool(p, "options", "includeDetailedResults"))
                {
                    todo.Add("it gave the sentiment's strength and confidence too - here the category alone.");
                }
            }),
            // n8n's Summarization Chain: the text it is given summarised by the site's model.
            ["chainSummarization"] = new("Stomme.AskAi", DoneFailed, (p, step, todo) =>
            {
                var custom = Text(p, "options", "summarizationMethodAndPrompts", "values", "prompt");
                Set(step, "Instructions", custom.Length > 0
                    ? custom.Replace("{text}", "the text you are given", StringComparison.Ordinal)
                    : "Summarize the text you are given concisely, keeping what matters.");
                if (Text(p, "operationMode") is "documentLoader" or "nodeInputBinary")
                {
                    todo.Add("it summarised a document n8n loaded - here it summarises the previous step's result: read the document first (Read document).");
                }
            }),
            ["chainLlm"] = new("Stomme.AskAi", DoneFailed, (p, step, todo) =>
            {
                if (Text(p, "promptType") == "define")
                {
                    Set(step, "Prompt", Text(p, "text")); // otherwise the chat's message - the previous step's result here
                }

                var system = Items(p, "messages", "messageValues").Where(message => Text(message, "type") is "" or "SystemMessagePromptTemplate").Select(message => Text(message, "message"));
                Set(step, "Instructions", string.Join("\n\n", system.Where(text => text.Length > 0)));
                if (Bool(p, "hasOutputParser"))
                {
                    Set(step, "AnswerAs", "Json");
                    todo.Add("its answer went through n8n's output parser - here it is JSON the step checks; say its shape in Instructions.");
                }
            }),
            ["openAi"] = new("Stomme.AskAi", DoneFailed, (p, step, todo) =>
            {
                var messages = Items(p, "messages", "values").ToList();
                Set(step, "Prompt", string.Join("\n\n", messages.Where(message => Text(message, "role") is "" or "user").Select(message => Text(message, "content")).Where(text => text.Length > 0)));
                Set(step, "Instructions", string.Join("\n\n", messages.Where(message => Text(message, "role") == "system").Select(message => Text(message, "content")).Where(text => text.Length > 0)));
                if (Bool(p, "jsonOutput"))
                {
                    Set(step, "AnswerAs", "Json");
                }

                if (messages.Any(message => Text(message, "role") == "assistant"))
                {
                    todo.Add("its messages included the model's own turns - here Prompt asks once.");
                }
            }),
            ["informationExtractor"] = new("Stomme.ExtractInformation", DoneFailed, (p, step, todo) =>
            {
                Set(step, "Text", Text(p, "text"));
                var fields = Items(p, "attributes", "attributes").Where(attribute => Text(attribute, "name").Trim().Length > 0).Select(attribute =>
                    Text(attribute, "name").Trim()
                    + Text(attribute, "type") switch { "number" => " (number)", "boolean" => " (true or false)", "date" => " (date)", _ => "" }
                    + (Text(attribute, "description").Trim() is { Length: > 0 } what ? ": " + what : ""));
                Set(step, "Fields", string.Join("\n", fields));
                if (Text(p, "schemaType") is "fromJson" or "manual")
                {
                    todo.Add("its fields were a JSON schema in n8n - name them here, one per line.");
                }

                if (Text(p, "options", "systemPromptTemplate") is { Length: > 0 } prompt && !prompt.Contains('{'))
                {
                    Set(step, "Instructions", prompt);
                }
            }),
            ["textClassifier"] = new("Stomme.ClassifyText", new[] { Failed }, (p, step, todo) =>
            {
                // A category is an outcome here as an output is there, in the same order; n8n's Other output is a category too.
                Set(step, "Text", Text(p, "inputText"));
                var categories = Items(p, "categories", "categories").Select(category => (Name: Text(category, "category").Trim(), What: Text(category, "description").Trim())).Where(category => category.Name.Length > 0).ToList();
                if (Text(p, "options", "fallback") == "other")
                {
                    categories.Add(("Other", "a text that belongs in none of the other categories"));
                }

                Set(step, StepCatalogEntry.BranchesOutcomes, PipelineOutcomes.WriteBranches(categories.Select(category => category.Name)));
                Set(step, "Descriptions", string.Join("\n", categories.Where(category => category.What.Length > 0).Select(category => category.Name + ": " + category.What)));
                if (Text(p, "options", "systemPromptTemplate") is { Length: > 0 } prompt && !prompt.Contains('{'))
                {
                    Set(step, "Instructions", prompt);
                }

                if (Bool(p, "options", "multiClass"))
                {
                    todo.Add("it could put a text in several categories - here a text goes on through one.");
                }
            }),
            // n8n's Guardrails node: its checks as Check text's - its Pass and Fail as Passed and Flagged - and its sanitizing as
            // Sanitize text; its guardrails as the steps' inputs, what has no input here said.
            ["guardrails"] = new(GuardrailCheckType, new[] { "Passed", "Flagged" }, (p, step, todo) => Guardrails(p, step, todo, check: true)),
            ["guardrails.sanitize"] = new(GuardrailSanitizeType, DoneFailed, (p, step, todo) => Guardrails(p, step, todo, check: false)),
        };

        /// <summary>The workflow as this site's pipeline document - always one, its to-do note saying what is left to finish.</summary>
        public static PipelineExchangeDocument Convert(JsonElement root)
        {
            var graph = new PipelineGraph();
            var todo = new Todo();
            var byName = new Dictionary<string, (PipelineGraphStep Step, Mapping Mapping, JsonElement Node)>(StringComparer.Ordinal);
            var dropped = new List<string>();
            var parsers = new List<(string Name, string Kind, JsonElement Parameters)>();
            var placeholders = 0;
            var nodes = root.GetProperty("nodes").EnumerateArray().Where(node => node.ValueKind == JsonValueKind.Object).ToList();
            var mainFlow = MainFlow(root);
            var positions = nodes.Select(Position).ToList();
            var (minX, minY) = positions.Count == 0 ? (0d, 0d) : (positions.Min(at => at.X), positions.Min(at => at.Y));

            for (var index = 0; index < nodes.Count; index++)
            {
                var node = nodes[index];
                var name = Text(node, "name") is { Length: > 0 } named ? named : "Node " + (index + 1);
                var type = Text(node, "type");
                var parameters = node.TryGetProperty("parameters", out var found) && found.ValueKind == JsonValueKind.Object ? found : default;
                var at = new GraphPosition { X = Math.Round(Left + (positions[index].X - minX) * ScaleX), Y = Math.Round(Top + (positions[index].Y - minY) * ScaleY) };
                todo.Node = name;
                todo.Version = VersionOf(node);

                if (type.EndsWith(".stickyNote", StringComparison.OrdinalIgnoreCase))
                {
                    graph.Notes.Add(new PipelineGraphNote { Id = "note-" + (graph.Notes.Count + 1), Text = Text(parameters, "content"), Position = at, Color = NoteColor(parameters) });
                    continue;
                }

                if (type.EndsWith(".manualTrigger", StringComparison.OrdinalIgnoreCase))
                {
                    continue; // a pipeline here runs by hand without a trigger: the steps it led to start the run
                }

                Mapping? mapping = null;
                if (type.StartsWith("n8n-nodes-base.", StringComparison.OrdinalIgnoreCase))
                {
                    Base.TryGetValue(ByOperation(type["n8n-nodes-base.".Length..], parameters), out mapping);
                }
                else if (type.StartsWith("@n8n/n8n-nodes-langchain.", StringComparison.OrdinalIgnoreCase))
                {
                    var kind = type["@n8n/n8n-nodes-langchain.".Length..];
                    if (kind.Equals("openAi", StringComparison.OrdinalIgnoreCase) && !(Text(parameters, "resource") is "" or "text" && Text(parameters, "operation") is "" or "message"))
                    {
                        mapping = null; // an image, a sound or a file made: no step here does it, so it stays as a placeholder
                    }
                    else if (Ai.TryGetValue(kind.Equals("guardrails", StringComparison.OrdinalIgnoreCase) && Text(parameters, "operation") == "sanitize" ? "guardrails.sanitize" : kind, out mapping))
                    {
                    }
                    else if (kind.StartsWith("vectorStore", StringComparison.OrdinalIgnoreCase) && VectorStore(kind, parameters) is { } store)
                    {
                        mapping = store;
                    }
                    else if (!mainFlow.Contains(name) && kind.StartsWith("outputParser", StringComparison.OrdinalIgnoreCase))
                    {
                        parsers.Add((name, kind, parameters)); // the shape it held goes to the step it hangs off (OutputParsers)
                        continue;
                    }
                    else if (!mainFlow.Contains(name))
                    {
                        // A model, a memory or a tool hangs off an agent in n8n; here the site's model serves every agent.
                        dropped.Add("'" + name + "' (" + kind + ")");
                        continue;
                    }
                    else if (kind.Equals("chainRetrievalQa", StringComparison.OrdinalIgnoreCase))
                    {
                        todo.Add("here a question is answered from your documents by Find passages, then Ask AI given what it found ({{ context }}).");
                    }

                    // Otherwise a node of the flow no step does: a placeholder, its connections kept - never dropped as a part of an agent.
                }

                var step = new PipelineGraphStep
                {
                    Id = "n8n-" + (index + 1),
                    Type = mapping?.Type ?? PlaceholderType,
                    Name = name,
                    Position = at,
                    Comment = Text(node, "notes") is { Length: > 0 } notes ? notes : null,
                    Disabled = Bool(node, "disabled") || mapping is null,
                };

                if (mapping is null)
                {
                    placeholders++;
                    Set(step, "Message", "n8n's " + name + " (" + type + ") - no step here does it yet.");
                    todo.Add("no step here does what " + type + " did - kept in its place, switched off.");
                }
                else if (parameters.ValueKind == JsonValueKind.Object)
                {
                    mapping.Fill?.Invoke(parameters, step, todo);
                }

                Settings(node, step);
                if (node.TryGetProperty("credentials", out var credentials) && credentials.ValueKind == JsonValueKind.Object && credentials.EnumerateObject().Any())
                {
                    todo.Add("credentials do not travel - give it the site's connection, or the secret it needs.");
                }

                MoveExpressions(step, todo);
                graph.Steps.Add(step);
                byName[name] = (step, mapping ?? new Mapping(PlaceholderType, None), node);
            }

            NodeReferences(graph, byName, todo);
            Connect(root, graph, byName, todo);
            OutputParsers(root, parsers, byName, todo);
            Fan(graph);
            WorkflowSettings(root, graph, todo);

            var steps = graph.Steps.Count - placeholders;
            var report = new StringBuilder("### Brought over from n8n\n");
            report.Append(nodes.Count == 1 ? "1 node: " : nodes.Count + " nodes: ").Append(steps == 1 ? "1 step" : steps + " steps");
            if (placeholders > 0)
            {
                report.Append(placeholders == 1 ? ", 1 placeholder" : ", " + placeholders + " placeholders");
            }

            if (graph.Notes.Count > 0)
            {
                report.Append(graph.Notes.Count == 1 ? ", 1 note" : ", " + graph.Notes.Count + " notes");
            }

            report.Append(".\n");
            if (dropped.Count > 0)
            {
                todo.Lines.Add("the site's model serves every AI agent here, so n8n's " + string.Join(", ", dropped) + (dropped.Count == 1 ? " is" : " are") + " not brought over.");
            }

            if (todo.Lines.Count == 0)
            {
                report.Append("Nothing is left to finish that the import could see - look the steps over before publishing.");
            }
            else
            {
                report.Append("To finish:\n").Append(string.Join("\n", todo.Lines.Select(line => "- " + line)));
            }

            graph.Notes.Insert(0, new PipelineGraphNote { Id = "note-n8n", Text = report.ToString(), Position = new GraphPosition { X = 30, Y = Top }, Color = PipelineNoteColors.Amber });
            return new PipelineExchangeDocument
            {
                Name = Text(root, "name") is { Length: > 0 } workflow ? workflow : null,
                Description = "Brought over from n8n.",
                Graph = graph,
                ConvertedFrom = Source,
            };
        }

        // n8n's output parsers, which hang off a chain by an ai_outputParser connection: a structured one's example - or its schema,
        // given by hand - as the Ask AI step's answer shape, through an auto-fixing one (which Ask AI is: it asks once more). A
        // parser on a node with no answer shape here, or of another kind, said.
        private static void OutputParsers(JsonElement root, List<(string Name, string Kind, JsonElement Parameters)> parsers,
            Dictionary<string, (PipelineGraphStep Step, Mapping Mapping, JsonElement Node)> byName, Todo todo)
        {
            var targets = new Dictionary<string, string>(StringComparer.Ordinal);
            if (root.TryGetProperty("connections", out var connections) && connections.ValueKind == JsonValueKind.Object)
            {
                foreach (var source in connections.EnumerateObject().Where(source => source.Value.ValueKind == JsonValueKind.Object))
                {
                    if (source.Value.TryGetProperty("ai_outputParser", out var outputs) && outputs.ValueKind == JsonValueKind.Array
                        && outputs.EnumerateArray().SelectMany(output => output.ValueKind == JsonValueKind.Array ? output.EnumerateArray() : Enumerable.Empty<JsonElement>())
                            .Select(target => Text(target, "node")).FirstOrDefault(target => target.Length > 0) is { } to)
                    {
                        targets[source.Name] = to;
                    }
                }
            }

            var autofixing = parsers.Where(parser => parser.Kind.Equals("outputParserAutofixing", StringComparison.OrdinalIgnoreCase)).Select(parser => parser.Name).ToHashSet(StringComparer.Ordinal);
            foreach (var parser in parsers.Where(parser => !autofixing.Contains(parser.Name)))
            {
                todo.Node = parser.Name;
                if (!parser.Kind.Equals("outputParserStructured", StringComparison.OrdinalIgnoreCase))
                {
                    todo.Add("n8n's " + parser.Kind + " has no counterpart here - Ask AI's answer shape takes an example of the answer or a JSON Schema.");
                    continue;
                }

                var target = targets.GetValueOrDefault(parser.Name);
                for (var hops = 0; target is not null && autofixing.Contains(target) && hops < 4; hops++)
                {
                    target = targets.GetValueOrDefault(target);
                }

                if (target is null || !byName.TryGetValue(target, out var found) || found.Step.Type != "Stomme.AskAi")
                {
                    todo.Add("its shape held an AI node's answer - here only Ask AI takes an answer shape; say the shape in that step's instructions.");
                    continue;
                }

                Set(found.Step, "Shape", Text(parser.Parameters, "schemaType") == "manual" ? Text(parser.Parameters, "inputSchema") : Text(parser.Parameters, "jsonSchemaExample"));
                todo.Lines.Remove("'" + target + "': its answer went through n8n's output parser - here it is JSON the step checks; say its shape in Instructions.");
            }
        }

        // n8n's connections, by node name: { "From": { "main": [ [ { "node": "To", "index": 0 } ], ... ] } } - the list's place is
        // the output. n8n numbers a node's own outputs first, then - when it goes on through its error output ("continue using
        // error output") - that one. An own output here is the step's outcome in that place, the error output its Failed path.
        private static void Connect(JsonElement root, PipelineGraph graph, Dictionary<string, (PipelineGraphStep Step, Mapping Mapping, JsonElement Node)> byName, Todo todo)
        {
            foreach (var source in root.GetProperty("connections").EnumerateObject())
            {
                if (!byName.TryGetValue(source.Name, out var from) || !source.Value.TryGetProperty("main", out var main) || main.ValueKind != JsonValueKind.Array)
                {
                    continue;
                }

                var outputs = main.EnumerateArray().ToList();
                for (var output = 0; output < outputs.Count; output++)
                {
                    var targets = outputs[output].ValueKind == JsonValueKind.Array
                        ? outputs[output].EnumerateArray().Select(target => Text(target, "node")).Where(byName.ContainsKey).ToList()
                        : new List<string>();
                    if (targets.Count == 0)
                    {
                        continue;
                    }

                    var (port, unmatched) = PortOf(from.Step, from.Mapping, from.Node, output);
                    foreach (var target in targets)
                    {
                        if (unmatched is not null)
                        {
                            todo.Node = source.Name;
                            todo.Add(unmatched + " led to '" + target + "' - " + (unmatched == ErrorOutput ? "this step has no Failed path" : "no outcome here matches it") + "; connect it as it should go.");
                            continue;
                        }

                        var targetId = byName[target].Step.Id;
                        if (!graph.Connections.Any(connection => connection.SourceId == from.Step.Id && connection.SourcePort == port && connection.TargetId == targetId))
                        {
                            graph.Connections.Add(new PipelineGraphConnection { SourceId = from.Step.Id, SourcePort = port, TargetId = targetId });
                        }
                    }
                }
            }
        }

        private const string ErrorOutput = "its error output";

        // n8n's workflow settings with a counterpart here - the time a run saves, not keeping the runs that finish well, the time
        // zone its schedules run in, its run time limit - and, named, those without: its error workflow, time saved as it goes.
        private static void WorkflowSettings(JsonElement root, PipelineGraph graph, Todo todo)
        {
            var settings = Find(root, "settings");
            if (Text(settings, "timeSavedMode") == "dynamic")
            {
                todo.Lines.Add("n8n added up the time each run saved as it went - here a run saves the minutes the pipeline says; set them in its editor.");
            }
            else if (double.TryParse(Text(settings, "timeSavedPerExecution"), NumberStyles.Float, CultureInfo.InvariantCulture, out var minutes))
            {
                graph.MinutesSavedPerRun = PipelineInsights.MinutesSaved((int)Math.Round(minutes));
            }

            if (Text(settings, "saveDataSuccessExecution") == "none")
            {
                graph.KeepSuccessfulRuns = false;
            }

            if (Text(settings, "saveExecutionProgress") == "true")
            {
                graph.SaveProgress = true; // n8n's "save execution progress"
            }

            var schedules = graph.Steps.Where(step => step.Type == "Stomme.Schedule").ToList();
            if (Text(settings, "timezone") is { Length: > 0 } zone && zone != "DEFAULT")
            {
                graph.TimeZone = PipelineTimeZone.Normalize(zone); // its $now and $today read there, as n8n's are
                schedules.ForEach(schedule => Set(schedule, "TimeZone", zone));
            }
            else if (schedules.Count > 0)
            {
                todo.Lines.Add("its schedules ran in n8n's own time zone - here they run in UTC, unless a schedule's Time zone says otherwise.");
            }

            if (Text(settings, "errorWorkflow") is { Length: > 0 } errorWorkflow && errorWorkflow != "DEFAULT")
            {
                todo.Lines.Add("n8n ran another workflow when this one failed - here a pipeline that starts with 'Pipeline failed' does.");
            }

            // Its run time limit: a run busy longer is stopped, as here - in whole minutes, up to a day, so a limit that is not
            // is said.
            if (Number(settings, "executionTimeout") is { } seconds && seconds > 0)
            {
                graph.TimeoutMinutes = PipelineRunTimeout.FromSeconds(seconds);
                if (seconds % 60 != 0 || seconds > PipelineRunTimeout.MaxMinutes * 60)
                {
                    todo.Lines.Add("n8n stopped a run after " + seconds + " seconds - here a run's time limit is whole minutes, at most a day: "
                        + PipelineRunTimeout.Said(graph.TimeoutMinutes!.Value) + ".");
                }
            }

            // Which workflows may call it. Its own owner's or any are every pipeline here (a site is the owner); none is none; a
            // list names n8n's workflow ids, which mean nothing here - so none, until the author chooses, never every caller.
            switch (Text(settings, "callerPolicy"))
            {
                case "none":
                    graph.CalledBy = PipelineCallers.Nobody;
                    break;
                case "workflowsFromAList":
                    graph.CalledBy = PipelineCallers.Nobody;
                    todo.Lines.Add("n8n let only the workflows it listed call it" + (Text(settings, "callerIds") is { Length: > 0 } ids ? " (" + ids + ")" : "")
                        + " - here no pipeline may call it until the ones that may are chosen in its settings.");
                    break;
            }
        }

        // Run script's styles for n8n's code (the server's ScriptStyle, by name): once for all items, once for each.
        private const string AllItems = "N8nAllItems";

        private const string EachItem = "N8nEachItem";

        // n8n's helpers a script here does not have, as the code names them, and what the note calls each.
        private static readonly (string Mark, string Name)[] CodeHelpers =
        {
            ("$(", "$('a node')"), ("$node", "$node"), ("$items(", "$items()"), ("$env", "$env"), ("$now", "$now"), ("$today", "$today"),
            ("DateTime", "Luxon's DateTime"), ("$vars", "$vars"), ("$workflow", "$workflow"), ("$execution", "$execution"),
            ("$prevNode", "$prevNode"), ("$runIndex", "$runIndex"), ("$jmespath", "$jmespath"), ("binary", "binary data"),
            ("require(", "require()"), ("getWorkflowStaticData", "workflow static data"), ("helpers.", "n8n's helpers"),
        };

        // A Code or Function node's note: it runs as written here, with scripts on - and the helpers it reads that are not here.
        private static string CodeNote(string code)
        {
            var missing = CodeHelpers.Where(helper => code.Contains(helper.Mark, StringComparison.Ordinal)).Select(helper => helper.Name).Distinct().ToList();
            return "it runs here as n8n ran it (its items, $input and $json) once Pipelines:Scripts:Enabled is on"
                + (missing.Count == 0 ? "." : " - but " + string.Join(", ", missing) + (missing.Count == 1 ? " is" : " are") + " not here; rewrite " + (missing.Count == 1 ? "it." : "them."));
        }

        private const string WaitForFormType = "Stomme.WaitForForm";

        private const string FormSubmitted = "Submitted";

        // n8n's waits go on through their one output whatever came - an answer, an approval or a refusal, or the time limit - where
        // a step here has an outcome for each: each of the others goes where the first one went.
        private static void Fan(PipelineGraph graph)
        {
            foreach (var step in graph.Steps)
            {
                var (first, others) = step.Type switch
                {
                    PipelineCalls.WaitStepType => (PipelineCalls.Called, step.Inputs.ContainsKey(PipelineCalls.TimeOutInput) ? new[] { PipelineCalls.TimedOut } : Array.Empty<string>()),
                    WaitForFormType => (FormSubmitted, step.Inputs.ContainsKey(PipelineCalls.TimeOutInput) ? new[] { PipelineCalls.TimedOut } : Array.Empty<string>()),
                    "Stomme.AskForApproval" => (PipelineApprovals.Approved, step.Inputs.ContainsKey("DecideWithin") ? new[] { PipelineApprovals.Rejected, PipelineApprovals.Expired } : new[] { PipelineApprovals.Rejected }),
                    _ => ("", Array.Empty<string>()),
                };
                foreach (var connection in graph.Connections.Where(connection => connection.SourceId == step.Id && connection.SourcePort == first).ToList())
                {
                    graph.Connections.AddRange(others.Select(port => new PipelineGraphConnection { SourceId = step.Id, SourcePort = port, TargetId = connection.TargetId }));
                }
            }
        }

        // How long a wait may last, as a wait here reads it ("2 hours"), from n8n's limit; one at a time of day is named instead.
        private static string? Limit(JsonElement limit, Todo todo)
        {
            if (Text(limit, "limitType") == "atSpecifiedTime")
            {
                todo.Add("it waited until " + Text(limit, "maxDateAndTime") + " at most - here say how long it waits.");
                return null;
            }

            return (Text(limit, "resumeAmount") is { Length: > 0 } amount ? amount : "1") + " " + (Text(limit, "resumeUnit") is { Length: > 0 } unit ? unit : "hours");
        }

        // The e-mail addresses a node sent to (Send Email's To, Gmail's Send To) - none for a chat, or an n8n expression.
        private static List<string> Recipients(JsonElement p)
        {
            var to = Text(p, "toEmail") is { Length: > 0 } email ? email : Text(p, "sendTo");
            return to.StartsWith('=')
                ? new List<string>()
                : to.Split(new[] { ',', ';' }, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList();
        }

        // n8n's form fields as this site's: text, long text, e-mail, number and date as they are, a dropdown or radio buttons as a
        // dropdown, a lone checkbox as one, a password as text, a file as one with the kinds it accepts. Several checkboxes, or a
        // dropdown taking several, become one choice, and several files one; a hidden value or HTML has no field here - each named.
        private static void FormFields(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            var fields = new List<PipelineFormField>();
            var oneChoice = new List<string>();
            var leftOut = new List<string>();
            foreach (var value in Items(p, "formFields", "values"))
            {
                var label = Text(value, "fieldLabel").Trim();
                var kind = Text(value, "fieldType") is { Length: > 0 } named ? named : "text";
                var options = Items(value, "fieldOptions", "values").Select(option => Text(option, "option").Trim()).Where(option => option.Length > 0).ToList();
                var type = kind switch
                {
                    "text" or "password" => PipelineFormFieldTypes.Text,
                    "textarea" => PipelineFormFieldTypes.LongText,
                    "email" => PipelineFormFieldTypes.Email,
                    "number" => PipelineFormFieldTypes.Number,
                    "date" => PipelineFormFieldTypes.Date,
                    "dropdown" or "radio" => PipelineFormFieldTypes.Dropdown,
                    "checkbox" => options.Count > 1 ? PipelineFormFieldTypes.Dropdown : PipelineFormFieldTypes.Checkbox,
                    "file" => PipelineFormFieldTypes.File,
                    "hiddenField" => PipelineFormFieldTypes.Hidden,
                    _ => null,
                };
                if (type is null || (label.Length == 0 && !(type == PipelineFormFieldTypes.Hidden && Text(value, "fieldName").Trim().Length > 0)))
                {
                    leftOut.Add((label.Length > 0 ? label : Text(value, "fieldName")) + " (" + kind + ")");
                    continue;
                }

                if ((kind == "checkbox" && options.Count > 1) || (kind == "dropdown" && Bool(value, "multiselect")) || (kind == "file" && Bool(value, "multipleFiles")))
                {
                    oneChoice.Add(label);
                }

                fields.Add(new PipelineFormField
                {
                    Label = label,
                    Name = Text(value, "fieldName").Trim() is { Length: > 0 } name ? name : null,
                    Type = type,
                    Required = Bool(value, "requiredField"),
                    Options = type == PipelineFormFieldTypes.Dropdown ? options : new List<string>(),
                    Placeholder = Text(value, "placeholder") is { Length: > 0 } placeholder ? placeholder : null,
                    // n8n's ".pdf, .jpg" - or "pdf" - as the kinds this field takes.
                    Accept = type == PipelineFormFieldTypes.File
                        ? Text(value, "acceptFileTypes").Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                            .Select(kind => (kind.StartsWith('.') ? kind : "." + kind).ToLowerInvariant()).Where(PipelineForms.IsExtension).Distinct().ToList()
                        : new List<string>(),
                    // n8n's hidden field: its value when the address gives none.
                    Value = type == PipelineFormFieldTypes.Hidden && Text(value, "fieldValue") is { Length: > 0 } carried ? carried : null,
                });
            }

            if (fields.Count > 0)
            {
                Set(step, "Fields", PipelineForms.Serialize(fields));
            }

            if (oneChoice.Count > 0)
            {
                todo.Add("its " + string.Join(", ", oneChoice) + " let several be chosen in n8n - here one is.");
            }

            if (leftOut.Count > 0)
            {
                todo.Add("its form's " + string.Join(", ", leftOut) + (leftOut.Count == 1 ? " has" : " have") + " no field here - custom HTML; left out.");
            }

            if (Text(p, "defineForm") == "json")
            {
                todo.Add("its form was JSON in n8n - set its fields here.");
            }
        }

        // An element down a path of objects, or default.
        private static JsonElement Find(JsonElement element, params string[] path)
        {
            foreach (var name in path)
            {
                if (element.ValueKind != JsonValueKind.Object || !element.TryGetProperty(name, out element))
                {
                    return default;
                }
            }

            return element;
        }

        // The port n8n's output becomes - null for a step's one outcome - or, when nothing here matches it, what to tell the author.
        private static (string? Port, string? Unmatched) PortOf(PipelineGraphStep step, Mapping mapping, JsonElement node, int output)
        {
            var own = OwnOutputs(step, mapping, node);
            if (output < own.Count)
            {
                return own[output] == "" ? (null, "its output " + (output + 1)) : (own[output], null);
            }

            if (output == own.Count && Text(node, "onError") == "continueErrorOutput")
            {
                if (!mapping.Ports.Contains(Failed))
                {
                    return (null, ErrorOutput);
                }

                step.FailedPath = true; // the error output taken: the step's own Failed path
                step.ContinueOnError = false;
                return (Failed, null);
            }

            return (null, "its output " + (output + 1));
        }

        // A node's own outputs as this step's outcomes: a Switch's cases (and its fallback, when it had an output of its own), a
        // classifier's categories, Loop Over Items' done and loop (version 3; before it, the batch alone), else the mapping's.
        private static List<string?> OwnOutputs(PipelineGraphStep step, Mapping mapping, JsonElement node)
        {
            switch (step.Type)
            {
                case "Stomme.FlowSwitch":
                    var cases = step.Cases.Select(@case => (string?)@case.Label).ToList();
                    if (Text(node, "parameters", "options", "fallbackOutput") == "extra")
                    {
                        cases.Add("Default");
                    }

                    return cases;
                case "Stomme.ClassifyText":
                    return PipelineOutcomes.Branches(step.Inputs.TryGetValue(StepCatalogEntry.BranchesOutcomes, out var branches) ? branches : null).Select(name => (string?)name).ToList();
                case "Stomme.BatchRecords":
                    return VersionOf(node) >= 3 ? new List<string?> { Done, "" } : new List<string?> { "" };
            }

            var own = mapping.Ports.Where(port => port != Failed).Select(port => (string?)port).ToList();
            return own.Count > 0 ? own : new List<string?> { null };
        }

        private static double VersionOf(JsonElement node) =>
            double.TryParse(Text(node, "typeVersion"), NumberStyles.Float, CultureInfo.InvariantCulture, out var version) ? version : 0;

        // A node's settings: retry on fail, and what it does when it fails (go on, or down its error output).
        private static void Settings(JsonElement node, PipelineGraphStep step)
        {
            if (Bool(node, "retryOnFail"))
            {
                step.Retries = Math.Clamp((Number(node, "maxTries") ?? 3) - 1, 1, 5);
                step.RetryDelaySeconds = Math.Clamp((Number(node, "waitBetweenTries") ?? 1000) / 1000, 0, 60);
            }

            if (Text(node, "onError") == "continueRegularOutput" || Bool(node, "continueOnFail"))
            {
                step.ContinueOnError = true;
            }
        }

        // n8n's Postgres and Microsoft SQL "Execute query", as Extract from connection: the statement as its Query and n8n's Query
        // Parameters (Postgres's $1, $2, a value each; its older "query params", the item's fields in order) as bound @p1, @p2. A
        // value n8n spliced into the statement ({{ }} in it) stays an expression the editor warns of (ValueInSql); the connection
        // is this site's to choose - n8n's credentials stay in n8n.
        private static void SqlQuery(JsonElement p, PipelineGraphStep step, Todo todo, string database, bool numbered, string? connection = null)
        {
            var values = new List<string>();
            if (numbered && Text(p, "options", "queryReplacement") is { Length: > 0 } replacement)
            {
                values.AddRange(CommasOutsidePlaceholders(Unmarked(replacement)));
            }
            else if (numbered && Text(p, "additionalFields", "queryParams") is { Length: > 0 } fields)
            {
                values.AddRange(fields.Split(',').Select(field => field.Trim()).Where(field => field.Length > 0).Select(field => "{{ $json." + field + " }}"));
            }

            var query = Text(p, "query");
            var marked = query.StartsWith('=');
            var sql = marked ? query[1..] : query;
            if (values.Count > 0)
            {
                if (Regex.IsMatch(sql, @"\$\d+:"))
                {
                    todo.Add("its query writes a parameter as $n:name or $n:raw - an identifier or SQL n8n wrote in; a value here is bound, so write that part out.");
                }

                sql = Regex.Replace(sql, @"\$(\d+)(?![\d:])", match => int.Parse(match.Groups[1].Value, CultureInfo.InvariantCulture) is var at && at >= 1 && at <= values.Count ? "@p" + at : match.Value);
                var lines = string.Join("\n", values.Select((value, at) => "@p" + (at + 1) + " = " + value));
                Set(step, "Parameters", lines.Contains("{{", StringComparison.Ordinal) ? "=" + lines : lines);
            }

            Set(step, "Query", marked ? "=" + sql : sql);
            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add " + (connection ?? "a " + database + " connection") + " under Admin > Connections and pick it here.");
        }

        // n8n ran a node once for each item that reached it; a step here runs once.
        // n8n's Return All: every record, as far as the step's own Maximum records (10,000 unless raised, 100,000 at most), which
        // says when it stopped short - a connector's 'max' left out would stop at the connector's default (1,000 for most), silently.
        private static readonly string EveryRecord = Stomme.Connectivity.ConnectorExtractionLimits.MaxMaxRecords.ToString(CultureInfo.InvariantCulture);

        // An n8n Get Many's `max`: Return All every record (up to the step's cap); otherwise its limit - and the node's default limit
        // when the export leaves it out, as n8n leaves out every parameter at its default (read 50 there, not 1,000 here).
        private static string Most(JsonElement p, int n8nDefault) =>
            Bool(p, "returnAll") ? EveryRecord : Text(p, "limit") is { Length: > 0 } limit ? limit : n8nDefault.ToString(CultureInfo.InvariantCulture);

        private const string PerItem = "n8n ran it once for each item that reached it - here it runs once: put it in a For Each over the records when more than one does, its values reading the record (n8n's $json).";

        // n8n's Postgres and Microsoft SQL insert, update, upsert, select and delete, as Extract from connection running the SQL they
        // stood for: the columns' values bound (@name, never spliced), a write returning what it wrote (RETURNING, OUTPUT), a
        // select's conditions bound too. What has no plain statement - a truncate, a drop, columns mapped from the item by name
        // with none listed - stays a placeholder or is named; the connection is this site's to choose. n8n's MySQL (BL-229) the
        // same in MySQL's words: its identifiers in backticks, no RETURNING (the connector answers a write's changed rows and
        // last id), an upsert ON DUPLICATE KEY UPDATE, its Map Each Column Below's values and its Column to Match On - the
        // match's own value among the columns - and its options' IGNORE, priority, DISTINCT and output columns.
        private enum SqlDialect
        {
            Postgres,
            SqlServer,
            MySql,

            /// <summary>QuestDB: PostgreSQL's quoting, no schemas and no RETURNING.</summary>
            QuestDb,
        }

        // The connection a node of a database that speaks PostgreSQL's protocol is reached through - QuestDB's needing Npgsql's
        // type loading off, since QuestDB keeps no type catalogue to read (measured against QuestDB 9.1: every bound value refused).
        private const string TimescaleConnection = "a PostgreSQL connection to its TimescaleDB (PostgreSQL itself)";

        private const string QuestConnection = "a PostgreSQL connection to its QuestDB - its PostgreSQL port, 8812, and 'Server Compatibility Mode=NoTypeLoading' in its connection string, as QuestDB keeps no type catalogue to read -";

        private const string CrateConnection = "a PostgreSQL connection to its CrateDB (its PostgreSQL port, 5432)";

        private static void SqlStatement(JsonElement p, PipelineGraphStep step, Todo todo, string database, SqlDialect dialect, string? connection = null, string? defaultKey = null)
        {
            var postgres = dialect == SqlDialect.Postgres;
            var mySql = dialect == SqlDialect.MySql;
            string Quote(string identifier) => dialect switch
            {
                SqlDialect.Postgres or SqlDialect.QuestDb => "\"" + identifier.Replace("\"", "\"\"") + "\"",
                SqlDialect.MySql => "`" + identifier.Replace("`", "``") + "`",
                _ => "[" + identifier.Replace("]", "]]") + "]",
            };
            string Name(string dotted) => string.Join(".", dotted.Split('.', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).Select(Quote));
            var options = Find(p, "options");

            var operation = Text(p, "operation") is { Length: > 0 } named ? named : "insert";
            var tableName = Locator(p, "table");
            var schema = postgres ? Locator(p, "schema") : "";
            var table = Name(schema.Length > 0 && !tableName.Contains('.') ? schema + "." + tableName : tableName);
            var parameters = new List<(string Name, string Value)>();
            string Bind(string column, string value)
            {
                var name = Regex.IsMatch(column, "^[A-Za-z_][A-Za-z0-9_]*$") && parameters.All(bound => !string.Equals(bound.Name, column, StringComparison.OrdinalIgnoreCase)) ? column : "p" + (parameters.Count + 1);
                parameters.Add((name, value.StartsWith('=') ? value[1..] : value));
                return "@" + name;
            }

            string sql;
            switch (operation)
            {
                case "insert" or "update" or "upsert" or "delete":
                    var columns = mySql && Text(p, "dataMode") == "defineBelow" ? Items(p, "valuesToSend", "values").Where(value => Text(value, "column").Length > 0).Select(value => (Column: Text(value, "column"), Value: Text(value, "value"))).ToList() : SqlColumns(p);
                    var keys = mySql && Text(p, "columnToMatchOn") is { Length: > 0 } matched ? new List<string> { matched } : SqlKeys(p, operation, defaultKey);
                    if (mySql && keys.Count == 1 && Text(p, "dataMode") == "defineBelow" && columns.Count > 0 && columns.All(column => column.Column != keys[0]))
                    {
                        columns.Insert(0, (keys[0], Text(p, "valueToMatchOn"))); // its Column to Match On's value, written as n8n writes it
                    }

                    if (operation != "delete" && columns.Count == 0)
                    {
                        todo.Add("it mapped the item's fields to the table's columns by name - here write the statement in Query, a value as '@name = value' in Parameters.");
                        sql = "";
                        break;
                    }

                    if (operation is "update" or "upsert" or "delete" && keys.Count == 0)
                    {
                        todo.Add("it matched rows by a column n8n's export does not name - here write the statement's WHERE in Query.");
                        sql = "";
                        break;
                    }

                    var set = columns.Where(column => !keys.Contains(column.Column)).ToList();
                    if (operation == "update" && set.Count == 0)
                    {
                        todo.Add("it updated no column but the ones it matched rows by - here write the statement in Query.");
                        sql = "";
                        break;
                    }

                    var keyValues = keys.Select(key => (Key: key, Value: columns.FirstOrDefault(column => column.Column == key).Value ?? "={{ $json." + key + " }}")).ToList();
                    var sqlServer = dialect == SqlDialect.SqlServer;
                    var insert = !mySql ? "INSERT"
                        : "INSERT" + (Text(options, "priority") is "LOW_PRIORITY" or "HIGH_PRIORITY" ? " " + Text(options, "priority") : "")
                            + (Bool(options, "skipOnConflict") || (operation == "upsert" && set.Count == 0) ? " IGNORE" : "");
                    sql = operation switch
                    {
                        "insert" or "upsert" => insert + " INTO " + table + " (" + string.Join(", ", columns.Select(column => Quote(column.Column))) + ")"
                            + (sqlServer ? " OUTPUT INSERTED.*" : "")
                            + " VALUES (" + string.Join(", ", columns.Select(column => Bind(column.Column, column.Value))) + ")"
                            + (operation != "upsert" ? ""
                                : mySql ? (set.Count == 0 ? "" : " ON DUPLICATE KEY UPDATE " + string.Join(", ", set.Select(column => Quote(column.Column) + " = VALUES(" + Quote(column.Column) + ")")))
                                : " ON CONFLICT (" + string.Join(", ", keys.Select(Quote)) + ")" + (set.Count == 0 ? " DO NOTHING" : " DO UPDATE SET " + string.Join(", ", set.Select(column => Quote(column.Column) + " = EXCLUDED." + Quote(column.Column)))))
                            + (postgres ? " RETURNING *" : ""),
                        "update" => "UPDATE " + table + " SET " + string.Join(", ", set.Select(column => Quote(column.Column) + " = " + Bind(column.Column, column.Value)))
                            + (sqlServer ? " OUTPUT INSERTED.*" : "")
                            + " WHERE " + string.Join(" AND ", keyValues.Select(key => Quote(key.Key) + " = " + Bind(key.Key, key.Value)))
                            + (postgres ? " RETURNING *" : ""),
                        _ => "DELETE FROM " + table + (sqlServer ? " OUTPUT DELETED.*" : "")
                            + " WHERE " + string.Join(" AND ", keyValues.Select(key => Quote(key.Key) + " = " + Bind(key.Key, key.Value)))
                            + (postgres ? " RETURNING *" : ""),
                    };
                    if (mySql && Bool(options, "replaceEmptyStrings"))
                    {
                        todo.Add("it wrote an empty value as NULL - here an empty value is written as empty text: write NULL in Query where that matters.");
                    }

                    break;

                default: // select, and Postgres's delete with conditions (deleteTable)
                    var conditions = Items(p, "where", "values").Where(condition => Text(condition, "column").Length > 0).Select(condition =>
                    {
                        var column = Quote(Text(condition, "column"));
                        return Text(condition, "condition") switch
                        {
                            "IS NULL" => column + " IS NULL",
                            "IS NOT NULL" => column + " IS NOT NULL",
                            var compare => column + " " + (compare switch { "" or "equal" => "=", "!=" => "<>", var other => other }) + " " + Bind("w" + (parameters.Count + 1), Text(condition, "value")),
                        };
                    }).ToList();
                    var where = conditions.Count == 0 ? "" : " WHERE " + string.Join(Text(p, "combineConditions") == "OR" ? " OR " : " AND ", conditions);
                    if (operation == "deleteTable")
                    {
                        sql = "DELETE FROM " + table + where + (postgres ? " RETURNING *" : "");
                        break;
                    }

                    var order = Items(p, "sort", "values").Where(sort => Text(sort, "column").Length > 0).Select(sort => Quote(Text(sort, "column")) + (Text(sort, "direction") == "DESC" ? " DESC" : " ASC")).ToList();
                    int? limit = Bool(p, "returnAll") ? null : Number(p, "limit") ?? 50;
                    var shown = mySql && options.ValueKind == JsonValueKind.Object && options.TryGetProperty("outputColumns", out var picked) && picked.ValueKind == JsonValueKind.Array
                        ? picked.EnumerateArray().Select(column => Text(column)).Where(column => column.Length > 0).Select(Quote).ToList()
                        : new List<string>();
                    sql = "SELECT " + (mySql && Bool(options, "selectDistinct") ? "DISTINCT " : "") + (shown.Count == 0 ? "*" : string.Join(", ", shown)) + " FROM " + table + where
                        + (order.Count == 0 ? "" : " ORDER BY " + string.Join(", ", order)) + (limit is { } rows ? " LIMIT " + rows : "");
                    break;
            }

            if (sql.Length > 0)
            {
                // A table named by an n8n expression stays one, written into the statement - which the editor then warns of.
                Set(step, "Query", sql.Contains("{{", StringComparison.Ordinal) ? "=" + sql : sql);
            }

            if (parameters.Count > 0)
            {
                var lines = string.Join("\n", parameters.Select(bound => "@" + bound.Name + " = " + bound.Value));
                Set(step, "Parameters", lines.Contains("{{", StringComparison.Ordinal) ? "=" + lines : lines);
            }

            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add " + (connection ?? "a " + database + " connection") + " under Admin > Connections and pick it here.");
        }

        // An FTP operation's parameters, one 'name = value' per line - an n8n expression among them making them one.
        // n8n's FTP node as the FTP or SFTP connector's operation: a folder listed (its folders too, as n8n lists them; its
        // subfolders' when recursive), a file downloaded into the site's pipeline folder or uploaded from it (or its text), a file
        // or a folder deleted, an entry renamed - its connection, FTP's or SFTP's, chosen here.
        private static void Ftp(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            var options = Find(p, "options");
            var binary = Text(p, "binaryPropertyName") is { Length: > 0 } property ? property : "data";
            var path = Text(p, "path");
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "list":
                    Set(step, "Operation", "list");
                    lines.Add(("path", path.Length > 0 ? path : "/"));
                    lines.Add(("folders", "true"));
                    if (Bool(p, "recursive"))
                    {
                        lines.Add(("recursive", "true"));
                    }

                    break;
                case "download":
                    Set(step, "Operation", "download_file");
                    lines.Add(("path", path));
                    lines.Add(("file", path.StartsWith('=') ? path : path.TrimStart('/')));
                    todo.Add($"n8n kept the file in the item's binary '{binary}' - here it is written into the site's pipeline folder at 'file =' (its path on the server, as a guess), for the file steps to read.");
                    break;
                case "upload":
                    Set(step, "Operation", "upload");
                    lines.Add(("path", path));
                    if (Text(p, "binaryData") != "false")
                    {
                        lines.Add(("file", path.StartsWith('=') ? path : path.TrimEnd('/')[(path.TrimEnd('/').LastIndexOf('/') + 1)..]));
                        todo.Add($"n8n sent the item's binary '{binary}' - here the file is read from the site's pipeline folder: 'file =' is its name, as a guess.");
                    }
                    else
                    {
                        // A parameter is one line: text over several is a file's.
                        var content = Text(p, "fileContent");
                        if (content.Contains('\n') || content.Contains('\r'))
                        {
                            todo.Add("its text runs over several lines - here write it to a file with Write text file and give that file.");
                        }
                        else
                        {
                            lines.Add(("text", content));
                        }
                    }

                    break;
                case "delete":
                    Set(step, "Operation", "delete");
                    lines.Add(("path", path));
                    if (Bool(options, "folder"))
                    {
                        lines.Add(("folder", "true"));
                        if (Bool(options, "recursive"))
                        {
                            lines.Add(("recursive", "true"));
                        }
                    }

                    break;
                case "rename":
                    Set(step, "Operation", "rename");
                    lines.Add(("from", Text(p, "oldPath")));
                    lines.Add(("to", Text(p, "newPath")));
                    if (Bool(options, "createDirectories"))
                    {
                        lines.Add(("create_folders", "true"));
                    }

                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.ToArray()));
            todo.Add(Text(p, "protocol") == "sftp"
                ? "choose its connection - n8n's credentials stay in n8n: add an SFTP connection under Admin > Connections - SFTP for a password, SFTP (private key) for a key - with its server's host key, and pick it here."
                : "choose its connection - n8n's credentials stay in n8n: add an FTP connection under Admin > Connections and pick it here.");
        }

        // n8n's SSH node as the SSH connector's operation: a command - one line as 'command', several in the step's Query box - in
        // its folder (n8n's cd, '/' by default); a file downloaded into the site's pipeline folder; one uploaded to a folder under
        // its name. Its connection, by a password or a key, chosen here.
        private static void Ssh(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            var binary = Text(p, "binaryPropertyName") is { Length: > 0 } property ? property : "data";
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "execute":
                    Set(step, "Operation", "execute");
                    var command = Text(p, "command");
                    if (command.Contains('\n') || command.Contains('\r'))
                    {
                        Set(step, "Query", command);
                    }
                    else
                    {
                        lines.Add(("command", command));
                    }

                    lines.Add(("cwd", Text(p, "cwd") is { Length: > 0 } cwd ? cwd : "/"));
                    todo.Add(PerItem);
                    break;
                case "download":
                    Set(step, "Operation", "download_file");
                    var path = Text(p, "path");
                    lines.Add(("path", path));
                    lines.Add(("file", path.StartsWith('=') ? path : path.TrimStart('/')));
                    todo.Add($"n8n kept the file in the item's binary '{binary}' - here it is written into the site's pipeline folder at 'file =' (its path on the server, as a guess), for the file steps to read.");
                    break;
                case "upload":
                    Set(step, "Operation", "upload");
                    var folder = Text(p, "path");
                    var named = Text(Find(p, "options"), "fileName");
                    var name = named.Length > 0 ? named : binary;
                    lines.Add(("path", (folder.StartsWith('=') || name.StartsWith('=') ? "=" : "") + Unmarked(folder).TrimEnd('/') + "/" + Unmarked(name)));
                    lines.Add(("file", name));
                    todo.Add(named.Length > 0
                        ? $"n8n sent the item's binary '{binary}' - here the file is read from the site's pipeline folder: 'file =' is its name, as a guess."
                        : $"n8n sent the item's binary '{binary}' under its own file name - here 'path =' and 'file =' name it '{binary}', as a guess: name it.");
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.ToArray()));
            todo.Add(Text(p, "authentication") == "privateKey"
                ? "choose its connection - n8n's credentials stay in n8n: add an SSH (private key) connection under Admin > Connections, with its server's host key, and pick it here."
                : "choose its connection - n8n's credentials stay in n8n: add an SSH connection under Admin > Connections - SSH for a password, SSH (private key) for a key - with its server's host key, and pick it here.");
        }

        private static string FtpParameters(params (string Name, string Value)[] values)
        {
            var lines = string.Join("\n", values.Select(value => value.Name + " = " + (value.Value.StartsWith('=') ? value.Value[1..] : value.Value)));
            return values.Any(value => value.Value.StartsWith('=')) ? "=" + lines : lines;
        }

        private const string ChatMessageType = "Stomme.SendChatMessage";

        private const string EmailType = "Stomme.SendEmail";

        private const string GmailConnection = "choose its connection - n8n's credentials stay in n8n: add a Gmail connection under Admin > Connections (an OAuth client's id and secret and a refresh token granted the Gmail scopes) and pick it here.";

        // n8n's Gmail Send or Reply as Send email: its recipients, subject and message - its HTML or its text, as its email type
        // says or, where its export left the type out, as the message reads - and its cc and bcc. A sender's name, a reply-to
        // address and attachments have no input here: each named.
        private static void GmailSend(JsonElement p, PipelineGraphStep step, Todo todo, bool reply)
        {
            if (reply)
            {
                Set(step, "ReplyTo", Text(p, "messageId"));
            }
            else
            {
                Set(step, "To", Text(p, "sendTo"));
                Set(step, "Subject", Text(p, "subject"));
            }

            var message = Text(p, "message");
            var html = Text(p, "emailType") switch
            {
                "html" => true,
                "text" => false,
                _ => Regex.IsMatch(message, "<[A-Za-z/][^>]*>"),
            };
            Set(step, html ? "Html" : "Text", message);
            Set(step, "Cc", Text(p, "options", "ccList"));
            Set(step, "Bcc", Text(p, "options", "bccList"));
            if (Text(p, "options", "senderName") is { Length: > 0 } sender)
            {
                todo.Add($"it named its sender '{Unmarked(sender)}' - here the mailbox's own name is used.");
            }

            if (Text(p, "options", "replyTo") is { Length: > 0 } replyTo)
            {
                todo.Add($"it asked replies to go to '{Unmarked(replyTo)}' - here they go to the mailbox.");
            }

            if (Text(p, "options", "attachmentsUi").Length > 0)
            {
                todo.Add("it attached files - here the email is sent without them.");
            }

            todo.Add(PerItem);
            todo.Add(GmailConnection);
        }

        // n8n's Gmail Get Many as Extract from connection's search: its filters as Gmail's own search words - its search, read
        // status, sender and dates - its labels, how many.
        private static void GmailSearch(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            Set(step, "Operation", "search");
            var filters = p.ValueKind == JsonValueKind.Object && p.TryGetProperty("filters", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            var words = new List<string>();
            var expression = false;
            void Word(string value, Func<string, string> written)
            {
                if (value.Length == 0)
                {
                    return;
                }

                expression |= value.StartsWith('=');
                words.Add(written(Unmarked(value)));
            }

            Word(Text(filters, "q"), value => value);
            Word(Text(filters, "readStatus") switch { "unread" => "is:unread", "read" => "is:read", _ => "" }, value => value);
            Word(Text(filters, "sender"), value => "from:" + value);
            Word(GmailDate(Text(filters, "receivedAfter")), value => "after:" + value);
            Word(GmailDate(Text(filters, "receivedBefore")), value => "before:" + value);
            if (Bool(filters, "includeSpamTrash"))
            {
                words.Add("in:anywhere");
            }

            var lines = new List<(string Name, string Value)>();
            if (words.Count > 0)
            {
                lines.Add(("query", (expression ? "=" : "") + string.Join(" ", words)));
            }

            var labels = filters.ValueKind == JsonValueKind.Object && filters.TryGetProperty("labelIds", out var ids)
                ? ids.ValueKind == JsonValueKind.Array ? string.Join(", ", ids.EnumerateArray().Select(id => id.GetString() ?? "")) : Text(filters, "labelIds")
                : "";
            lines.Add(("labels", labels));
            if (Bool(p, "returnAll"))
            {
                lines.Add(("max", "500"));
                todo.Add("it read every message - here at most 500 are read; narrow the search to read fewer.");
            }
            else
            {
                lines.Add(("max", Most(p, todo.Version >= 2 ? 50 : 10)));
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add("n8n gave each message as an item - here the messages are the step's result, a list of records, each its id, headers, text and HTML.");
            todo.Add(GmailConnection);
        }

        private const string JiraConnection = "choose its connection - n8n's credentials stay in n8n: add a Jira connection under Admin > Connections (the site's address, an account's email and API token) and pick it here.";

        // n8n's Jira issue Create, Update, Get, Get Many and its comment Add as Extract from connection's create, update, search and
        // comment: its project and type (by key or id), summary, description and labels; a JQL query; an n8n expression among them
        // making the parameters one. A status it set is a transition here - said.
        private static void Jira(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            var lines = new List<(string Name, string Value)>();
            var fields = p.ValueKind == JsonValueKind.Object && p.TryGetProperty(operation == "update" ? "updateFields" : "additionalFields", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            string Labels() => fields.ValueKind == JsonValueKind.Object && fields.TryGetProperty("labels", out var labels) && labels.ValueKind == JsonValueKind.Array
                ? string.Join(", ", labels.EnumerateArray().Select(label => label.GetString() ?? "").Where(label => label.Length > 0))
                : Text(fields, "labels");
            switch (operation)
            {
                case "create":
                    Set(step, "Operation", "create");
                    lines.Add(("project", Locator(p, "project")));
                    lines.Add(("issue_type", Locator(p, "issueType")));
                    lines.Add(("summary", Text(p, "summary")));
                    lines.Add(("description", Text(fields, "description")));
                    lines.Add(("labels", Labels()));
                    break;
                case "update":
                    Set(step, "Operation", "update");
                    lines.Add(("issue", Text(p, "issueKey")));
                    lines.Add(("summary", Text(fields, "summary")));
                    lines.Add(("description", Text(fields, "description")));
                    lines.Add(("labels", Labels()));
                    if (Text(fields, "statusId").Length > 0)
                    {
                        todo.Add("it moved the issue to another status - here add Extract from connection's 'transition' after it, 'to =' the status.");
                    }

                    break;
                case "get":
                    Set(step, "Operation", "search");
                    lines.Add(("jql", Text(p, "issueKey") is { Length: > 0 } key ? (key.StartsWith('=') ? "=key = " + key[1..] : "key = " + key) : ""));
                    lines.Add(("max", "1"));
                    break;
                case "comment":
                    Set(step, "Operation", "comment");
                    lines.Add(("issue", Text(p, "issueKey")));
                    lines.Add(("text", Text(p, "comment")));
                    break;
                default:
                    Set(step, "Operation", "search");
                    if (Text(p, "options", "jql") is { Length: > 0 } jql)
                    {
                        lines.Add(("jql", jql));
                    }
                    else
                    {
                        todo.Add("it read every issue it could - here give a JQL query in Parameters, 'jql = project = OPS'.");
                    }

                    lines.Add(("fields", Text(p, "options", "fields")));
                    lines.Add(("max", Most(p, 50)));
                    break;
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: put the text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "create" or "update" or "comment" ? PerItem : "n8n gave each issue as an item - here the issues are the step's result, a list of records, each its key, page and fields.");
            todo.Add(JiraConnection);
        }

        private const string GitHubConnection = "choose its connection - n8n's credentials stay in n8n: add a GitHub connection under Admin > Connections (a personal access token) and pick it here.";

        // n8n's GitHub issue Create, Create Comment, Edit and Get, its repository Get Issues, release Create, file Get, Create and
        // Edit and workflow Dispatch as Extract from connection's operations: the repository its owner and name (an address mode's
        // URL cut to them), an issue's number, its title, body, labels and assignees (n8n keeps each as { label } / { assignee }),
        // a state, a release's tag and notes, a file's path, text and commit message, a workflow and its inputs; an n8n expression
        // among them making the parameters one. A file n8n kept as binary is said.
        private static void GitHub(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var owner = Locator(p, "owner");
            if (Stomme.Shared.Utilities.TryCreateAbsoluteUri(owner, out var ownerAddress) && ownerAddress.AbsolutePath.Trim('/') is { Length: > 0 } ownerPath)
            {
                owner = ownerPath.Split('/')[0]; // its address mode: https://github.com/acme
            }

            var lines = new List<(string Name, string Value)> { ("owner", owner), ("repository", Locator(p, "repository")) };
            string List(JsonElement holder, string collection, string item) =>
                holder.ValueKind == JsonValueKind.Object && holder.TryGetProperty(collection, out var values) && values.ValueKind == JsonValueKind.Array
                    ? string.Join(", ", values.EnumerateArray().Select(value => value.ValueKind == JsonValueKind.Object ? Text(value, item) : value.ValueKind == JsonValueKind.String ? value.GetString() ?? "" : "").Where(value => value.Length > 0))
                    : Text(holder, collection);
            var edit = p.ValueKind == JsonValueKind.Object && p.TryGetProperty("editFields", out var editFields) && editFields.ValueKind == JsonValueKind.Object ? editFields : default;
            switch (operation)
            {
                case "create_issue":
                    lines.Add(("title", Text(p, "title")));
                    lines.Add(("body", Text(p, "body")));
                    lines.Add(("labels", List(p, "labels", "label")));
                    lines.Add(("assignees", List(p, "assignees", "assignee")));
                    break;
                case "comment":
                    lines.Add(("issue", Text(p, "issueNumber")));
                    lines.Add(("body", Text(p, "body")));
                    break;
                case "update_issue":
                    lines.Add(("issue", Text(p, "issueNumber")));
                    lines.Add(("title", Text(edit, "title")));
                    lines.Add(("body", Text(edit, "body")));
                    lines.Add(("state", Text(edit, "state")));
                    lines.Add(("state_reason", Text(edit, "state_reason")));
                    lines.Add(("labels", List(edit, "labels", "label")));
                    lines.Add(("assignees", List(edit, "assignees", "assignee")));
                    break;
                case "get_issue":
                    lines.Add(("issue", Text(p, "issueNumber")));
                    break;
                case "issues":
                    lines.Add(("state", Text(p, "getRepositoryIssuesFilters", "state")));
                    lines.Add(("labels", Text(p, "getRepositoryIssuesFilters", "labels")));
                    lines.Add(("assignee", Text(p, "getRepositoryIssuesFilters", "assignee")));
                    lines.Add(("since", Text(p, "getRepositoryIssuesFilters", "since")));
                    lines.Add(("max", Most(p, 50)));
                    if (Text(p, "getRepositoryIssuesFilters", "creator").Length > 0 || Text(p, "getRepositoryIssuesFilters", "mentioned").Length > 0)
                    {
                        todo.Add("it read the issues by their creator or a mention - here by state, labels, assignee and time; filter the result after it.");
                    }

                    break;
                case "release":
                    lines.Add(("tag", Text(p, "releaseTag")));
                    lines.Add(("name", Text(p, "additionalFields", "name")));
                    lines.Add(("body", Text(p, "additionalFields", "body")));
                    lines.Add(("draft", Text(p, "additionalFields", "draft")));
                    lines.Add(("prerelease", Text(p, "additionalFields", "prerelease")));
                    lines.Add(("target", Text(p, "additionalFields", "target_commitish")));
                    break;
                case "file":
                    lines.Add(("path", Text(p, "filePath")));
                    lines.Add(("ref", Text(p, "additionalParameters", "reference")));
                    if (Text(p, "asBinaryProperty") != "false")
                    {
                        todo.Add("n8n kept the file as binary data - here the step's result is its text (a text file only).");
                    }

                    break;
                case "commit_file":
                    lines.Add(("path", Text(p, "filePath")));
                    lines.Add(("content", Bool(p, "binaryData") ? "" : Text(p, "fileContent")));
                    lines.Add(("message", Text(p, "commitMessage")));
                    lines.Add(("branch", Text(p, "additionalParameters", "branch", "branch")));
                    if (Bool(p, "binaryData"))
                    {
                        todo.Add("it committed a binary file - here a file's content is text: give it in Parameters, 'content = ...'.");
                    }

                    if (Text(p, "additionalParameters", "author").Length > 0 || Text(p, "additionalParameters", "committer").Length > 0)
                    {
                        todo.Add("it named the commit's author or committer - here the token's account makes the commit.");
                    }

                    break;
                case "dispatch":
                    lines.Add(("workflow", Locator(p, "workflowId")));
                    lines.Add(("ref", Text(p, "ref")));
                    lines.Add(("inputs", Text(p, "inputs") is { Length: > 0 } inputs && inputs != "{}" ? inputs : ""));
                    break;
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: put the text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "issues" ? "n8n gave each issue as an item - here the issues are the step's result, a list of records, each its number, title, state and page." : PerItem);
            todo.Add(GitHubConnection);
        }

        private const string GoogleCalendarConnection = "choose its connection - n8n's credentials stay in n8n: add a Google Calendar connection under Admin > Connections (an OAuth client's id and secret and a refresh token granted the calendar scope) and pick it here.";

        // A time n8n wrote as itself, with no offset - a calendar here needs one, or a time zone.
        private static readonly Regex LocalTime = new("^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}(:[0-9]{2}(\\.[0-9]+)?)?$", RegexOptions.CultureInvariant);

        // n8n's Google Calendar event Create, Get, Get Many, Update and Delete and its calendar Availability as Extract from
        // connection's operations: the calendar (its picker's id), an event's id, its title, times, description, place and
        // attendees (a list, or text), a whole day's dates, who n8n told, a window and a search; an n8n expression among them making
        // the parameters one. A time without an offset or a time zone, and an availability n8n gave as slots, are said.
        private static void GoogleCalendar(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)> { ("calendar", Locator(p, "calendar")) };
            var fields = p.ValueKind == JsonValueKind.Object && p.TryGetProperty(operation == "update_event" ? "updateFields" : "additionalFields", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            string Attendees() => fields.ValueKind == JsonValueKind.Object && fields.TryGetProperty("attendees", out var list) && list.ValueKind == JsonValueKind.Array
                ? string.Join(", ", list.EnumerateArray().Where(person => person.ValueKind == JsonValueKind.String).Select(person => person.GetString()))
                : Text(fields, "attendees");
            switch (operation)
            {
                case "create_event":
                case "update_event":
                    if (operation == "update_event")
                    {
                        lines.Add(("event", Text(p, "eventId")));
                    }

                    lines.Add(("summary", Text(fields, "summary")));
                    var start = operation == "create_event" ? Text(p, "start") : Text(fields, "start");
                    var end = operation == "create_event" ? Text(p, "end") : Text(fields, "end");
                    if (Text(fields, "allday") == "yes")
                    {
                        start = start.Length >= 10 && !start.StartsWith('=') ? start[..10] : start; // a whole day: its date
                        end = end.Length >= 10 && !end.StartsWith('=') ? end[..10] : end;
                        if (start.StartsWith('=') || end.StartsWith('='))
                        {
                            todo.Add("it made a whole-day event from expressions - here a whole day is a date (2026-10-12): make its start and end dates.");
                        }
                    }

                    var zone = Text(fields, "timeZone") is { Length: > 0 } fieldZone ? fieldZone : Text(p, "options", "timeZone");
                    lines.Add(("start", start));
                    lines.Add(("end", end));
                    lines.Add(("time_zone", zone));
                    lines.Add(("description", Text(fields, "description")));
                    lines.Add(("location", Text(fields, "location")));
                    lines.Add(("attendees", Attendees()));
                    lines.Add(("notify", Text(fields, "sendUpdates")));
                    if (zone.Length == 0 && (LocalTime.IsMatch(start) || LocalTime.IsMatch(end)))
                    {
                        todo.Add("its times carry no offset - here give one (2026-10-12T10:00:00+02:00) or the time zone, 'time_zone = Europe/Stockholm'.");
                    }

                    break;
                case "get_event":
                    lines.Add(("event", Text(p, "eventId")));
                    break;
                case "delete_event":
                    lines.Add(("event", Text(p, "eventId")));
                    lines.Add(("notify", Text(p, "options", "sendUpdates")));
                    break;
                case "events":
                    lines.Add(("time_min", Text(p, "timeMin") is { Length: > 0 } after ? after : Text(p, "options", "timeMin")));
