        // n8n's Stripe customer Create, Get, Get Many, Update and Delete, its charge Get Many and its balance Get as Extract from
        // connection's operations: a customer's id, its email, name, phone, description and metadata (n8n's key and value pairs
        // made a JSON object); an n8n expression among them making the parameters one. An address or a shipping address is said.
        private static void Stripe(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            var fields = p.ValueKind == JsonValueKind.Object && p.TryGetProperty(operation == "update_customer" ? "updateFields" : operation == "customers" ? "filters" : "additionalFields", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            switch (operation)
            {
                case "create_customer":
                case "update_customer":
                    if (operation == "update_customer")
                    {
                        lines.Add(("customer", Text(p, "customerId")));
                    }

                    lines.Add(("email", Text(fields, "email")));
                    lines.Add(("name", operation == "create_customer" ? Text(p, "name") : Text(fields, "name")));
                    lines.Add(("phone", Text(fields, "phone")));
                    lines.Add(("description", Text(fields, "description")));
                    var pairs = Items(fields, "metadata", "metadataProperties").Select(pair => (Text(pair, "key"), Text(pair, "value"))).Where(pair => pair.Item1.Length > 0).ToList();
                    if (pairs.Count > 0)
                    {
                        var metadata = new System.Text.Json.Nodes.JsonObject();
                        foreach (var (key, value) in pairs)
                        {
                            metadata[key] = value;
                        }

                        lines.Add(("metadata", metadata.ToJsonString()));
                    }

                    if (Text(fields, "address").Length > 0 || Text(fields, "shipping").Length > 0)
                    {
                        todo.Add("it set the customer's address or shipping address - here a customer's email, name, phone, description and metadata are set: add the address in Stripe.");
                    }

                    break;
                case "customers":
                    lines.Add(("email", Text(fields, "email")));
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "charges":
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "balance":
                    break;
                default:
                    lines.Add(("customer", Text(p, "customerId")));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "customers" or "charges" ? "n8n gave each " + (operation == "charges" ? "charge" : "customer") + " as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(StripeConnection);
        }

        private const string SupabaseConnection = "choose its connection - n8n's credentials stay in n8n: add a Supabase connection under Admin > Connections (the project's address and a secret key) and pick it here.";

        // n8n's Supabase row Create, Get, Get Many, Update and Delete as Extract from connection's operations: its table, its fields
        // (n8n's field and value pairs made JSON), its conditions one filter a line - equal the default, full text its search
        // function - any one of them (n8n's default) or all, its filter string as PostgREST's own query, how many.
        private static void Supabase(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)> { ("table", Text(p, "tableId")) };
            if (operation is "create_rows" or "update_rows")
            {
                if (Text(p, "dataToSend") == "autoMapInputData")
                {
                    todo.Add("it wrote each item's own fields - here give the fields as JSON, {\"column\": \"{{ value }}\"}.");
                }

                var record = new System.Text.Json.Nodes.JsonObject();
                var expression = false;
                foreach (var pair in Items(p, "fieldsUi", "fieldValues"))
                {
                    if (Text(pair, "fieldId") is { Length: > 0 } column)
                    {
                        var value = Text(pair, "fieldValue");
                        expression |= value.StartsWith('=');
                        record[column] = Unmarked(value);
                    }
                }

                lines.Add((operation == "create_rows" ? "rows" : "fields", record.Count == 0 ? "" : (expression ? "=" : "") + record.ToJsonString(ReadableJson)));
            }

            if (operation != "create_rows")
            {
                if (Text(p, "filterType") == "string")
                {
                    lines.Add(("query", Text(p, "filterString")));
                }
                else
                {
                    var conditions = Items(p, "filters", "conditions").Select(condition =>
                    {
                        var op = operation == "get_row" ? "eq" : Text(condition, "condition") is { Length: > 0 } written ? written : "eq";
                        return $"{Text(condition, "keyName")} {(op == "fullText" ? (Text(condition, "searchFunction") is { Length: > 0 } search ? search : "fts") : op)} {Unmarked(Text(condition, "keyValue"))}";
                    }).ToList();
                    var expression = Items(p, "filters", "conditions").Any(condition => Text(condition, "keyValue").StartsWith('=') || Text(condition, "keyName").StartsWith('='));
                    if (conditions.Count > 0)
                    {
                        lines.Add(("filters", (expression ? "=" : "") + string.Join("\n", conditions)));
                    }

                    if (operation != "get_row" && conditions.Count > 1 && Text(p, "matchType") is "" or "anyFilter")
                    {
                        lines.Add(("match", "any")); // n8n's default: any one
                    }
                }
            }

            if (operation == "rows")
            {
                lines.Add(("max", Most(p, 50)));
            }

            // A filter a line: the whole of them one parameter, written as lines under it.
            var filters = lines.FirstOrDefault(line => line.Name == "filters");
            var rest = lines.Where(line => line.Name != "filters" && line.Value.Length > 0).ToList();
            var parameters = FtpParameters(rest.ToArray());
            if (filters.Value is { Length: > 0 } list)
            {
                var plain = list.StartsWith('=') ? list[1..] : list;
                var body = (parameters.StartsWith('=') ? parameters[1..] : parameters) + (parameters.Length > 0 ? "\n" : "") + "filters = " + plain.Replace("\n", "\nfilters = ", StringComparison.Ordinal);
                parameters = (list.StartsWith('=') || parameters.StartsWith('=') ? "=" : "") + body;
            }

            Set(step, "Parameters", parameters);
            todo.Add(operation == "rows" ? "n8n gave each row as an item - here the rows are the step's result, a list, each its columns." : PerItem);
            todo.Add(SupabaseConnection);
        }

        private const string MailchimpConnection = "choose its connection - n8n's credentials stay in n8n: add a Mailchimp connection under Admin > Connections (its data center's API address and an API key) and pick it here.";

        // n8n's Mailchimp member Create, Get, Get Many, Update and Delete, its member tag Create and Delete, and its campaign Get, Get
        // Many, Send, Replicate, Resend and Delete as Extract from connection's operations: a member's audience, address and status,
        // its merge fields (n8n's name and value pairs, or its JSON, made a JSON object), tags, language, VIP and email type; a Get
        // Many's status and change; a member's tags added or removed; a campaign's id, and a Get Many's status, audience, order and
        // times. What it set that has no parameter here - a location, interest groups, sign-up and opt-in details - is said.
        private static void Mailchimp(JsonElement p, PipelineGraphStep step, Todo todo, string operation, string? tagging = null)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            var said = new List<string>();
            var fields = p.ValueKind == JsonValueKind.Object && p.TryGetProperty(operation == "update_member" ? "updateFields" : "options", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            void Unmapped(params string[] known)
            {
                if (fields.ValueKind == JsonValueKind.Object)
                {
                    said.AddRange(fields.EnumerateObject().Select(field => field.Name).Where(name => !known.Contains(name)));
                }
            }

            if (operation.EndsWith("_campaign", StringComparison.Ordinal))
            {
                lines.Add(("campaign", Text(p, "campaignId")));
            }
            else if (operation != "campaigns")
            {
                lines.Add(("list", Text(p, "list")));
                if (operation != "members")
                {
                    lines.Add(("email", Text(p, "email")));
                }
            }

            switch (operation)
            {
                case "add_member":
                case "update_member":
                    lines.Add(("status", operation == "add_member" ? Text(p, "status") : Text(fields, "status")));
                    var source = operation == "add_member" ? p : fields;
                    var pairs = Items(source, "mergeFieldsUi", "mergeFieldsValues").Select(pair => (Text(pair, "name"), Text(pair, "value"))).Where(pair => pair.Item1.Length > 0).ToList();
                    if (pairs.Count > 0)
                    {
                        var merge = new System.Text.Json.Nodes.JsonObject();
                        foreach (var (name, value) in pairs)
                        {
                            merge[name] = Unmarked(value);
                        }

                        lines.Add(("merge_fields", (pairs.Any(pair => pair.Item2.StartsWith('=')) ? "=" : "") + merge.ToJsonString(ReadableJson)));
                    }
                    else if ((Text(source, "mergeFieldsJson") is { Length: > 0 } json ? json : Text(p, "mergeFieldsJson")) is { Length: > 0 } written)
                    {
                        lines.Add(("merge_fields", written.StartsWith('=') ? written : Minified(written)));
                    }

                    if (operation == "add_member")
                    {
                        lines.Add(("tags", Joined(fields, "tags")));
                        said.AddRange(new[] { "locationFieldsUi", "locationJson", "groupsUi", "groupJson" }.Where(name => Text(p, name).Length > 0 && Text(p, name) != "{}"));
                    }
                    else if (Text(fields, "tags").Length > 0)
                    {
                        todo.Add("it set the member's tags - here add a Tag a member step for them.");
                    }

                    lines.Add(("language", Text(fields, "language")));
                    lines.Add(("vip", Text(fields, "vip")));
                    lines.Add(("email_type", Text(fields, "emailType")));
                    Unmapped("status", "tags", "language", "vip", "emailType", "mergeFieldsUi", "mergeFieldsJson");
                    break;
                case "members":
                    lines.Add(("status", Text(fields, "status")));
                    lines.Add(("since_last_changed", Text(fields, "sinceLastChanged")));
                    lines.Add(("max", Most(p, 500)));
                    Unmapped("status", "sinceLastChanged");
                    break;
                case "tag_member":
                    lines.Add((tagging ?? "add", Joined(p, "tags")));
                    break;
                case "campaigns":
                    lines.Add(("status", Text(fields, "status")));
                    lines.Add(("list", Text(fields, "listId")));
                    lines.Add(("sort_field", Text(fields, "sortField")));
                    lines.Add(("sort_dir", Text(fields, "sortDirection").ToLowerInvariant()));
                    lines.Add(("since_send_time", Text(fields, "sinceSendTime")));
                    lines.Add(("since_create_time", Text(fields, "sinceCreateTime")));
                    lines.Add(("max", Most(p, 10)));
                    Unmapped("status", "listId", "sortField", "sortDirection", "sinceSendTime", "sinceCreateTime", "fields", "excludeFields");
                    break;
            }

            foreach (var name in said)
            {
                todo.Add($"it set its '{name}' - here it has no parameter: set it in Mailchimp.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "members" or "campaigns" ? "n8n gave each record as an item - here the records are the step's result, a list, each its id, its address or title and its fields." : PerItem);
            todo.Add(MailchimpConnection);
        }

        private const string WooCommerceConnection = "choose its connection - n8n's credentials stay in n8n: add a WooCommerce connection under Admin > Connections (the store's address and a REST API key's consumer key and secret) and pick it here.";

        // n8n's WooCommerce order, product and customer Create, Get, Get Many, Update and Delete as Extract from connection's
