        private static void WooCommerce(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var one = operation.Contains("order", StringComparison.Ordinal) ? "order" : operation.Contains("product", StringComparison.Ordinal) ? "product" : "customer";
            var lines = new List<(string Name, string Value)>();
            var said = new List<string>();
            var expression = false;
            var fields = p.ValueKind == JsonValueKind.Object && p.TryGetProperty(
                operation.StartsWith("update_", StringComparison.Ordinal) ? "updateFields" : operation.StartsWith("create_", StringComparison.Ordinal) ? "additionalFields" : one == "customer" ? "filters" : "options", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            void Unmapped(params string[] known)
            {
                if (fields.ValueKind == JsonValueKind.Object)
                {
                    said.AddRange(fields.EnumerateObject().Select(field => field.Name).Where(name => !known.Contains(name)));
                }
            }

            // A word of n8n's made WooCommerce's - lower case - unless it is an expression, which stays as written.
            static string Lower(string value) => value.StartsWith('=') ? value : value.ToLowerInvariant();

            System.Text.Json.Nodes.JsonObject Object(JsonElement element, Func<string, string>? rename = null)
            {
                var made = new System.Text.Json.Nodes.JsonObject();
                if (element.ValueKind == JsonValueKind.Object)
                {
                    foreach (var field in element.EnumerateObject())
                    {
                        var value = Text(element, field.Name);
                        if (value.Length > 0 && field.Name is not ("metadataUi" or "meta_data"))
                        {
                            expression |= value.StartsWith('=');
                            made[(rename ?? (name => name))(field.Name)] = field.Value.ValueKind switch
                            {
                                JsonValueKind.Number => System.Text.Json.Nodes.JsonNode.Parse(field.Value.GetRawText()),
                                JsonValueKind.True => true,
                                JsonValueKind.False => false,
                                _ => Unmarked(value),
                            };
                        }
                    }
                }

                return made;
            }

            string Snake(string name) => name switch
            {
                "firstName" => "first_name",
                "lastName" => "last_name",
                "postalCode" => "postcode",
                "productId" => "product_id",
                "variationId" => "variation_id",
                "taxClass" => "tax_class",
                "taxStatus" => "tax_status",
                "methodTitle" => "method_title",
                "methodId" or "method ID" => "method_id",
                _ => name,
            };

            void List(string name, string collection, string values)
            {
                var items = Items(p, collection, values).Select(item => (System.Text.Json.Nodes.JsonNode)Object(item, Snake)).Where(item => ((System.Text.Json.Nodes.JsonObject)item).Count > 0).ToArray();
                if (items.Length > 0)
                {
                    lines.Add((name, new System.Text.Json.Nodes.JsonArray(items).ToJsonString(ReadableJson)));
                }
            }

            void Address(string name, JsonElement address, Func<string, string>? rename)
            {
                if (Object(address, rename) is { Count: > 0 } made)
                {
                    lines.Add((name, made.ToJsonString(ReadableJson)));
                }
            }

            if (!operation.EndsWith("s", StringComparison.Ordinal) && !operation.StartsWith("create_", StringComparison.Ordinal))
            {
                lines.Add((one, Text(p, one + "Id")));
            }

            switch (operation)
            {
                case "orders":
                    lines.Add(("status", Lower(Text(fields, "status"))));
                    lines.Add(("customer", Text(fields, "customer")));
                    lines.Add(("product", Text(fields, "product")));
                    lines.Add(("search", Text(fields, "search")));
                    lines.Add(("after", Text(fields, "after")));
                    lines.Add(("before", Text(fields, "before")));
                    lines.Add(("order", Lower(Text(fields, "order"))));
                    lines.Add(("orderby", Lower(Text(fields, "orderBy"))));
                    Unmapped("status", "customer", "product", "search", "after", "before", "order", "orderBy");
                    break;
                case "products":
                    lines.Add(("search", Text(fields, "search")));
                    lines.Add(("sku", Text(fields, "sku")));
                    lines.Add(("status", Lower(Text(fields, "status"))));
                    lines.Add(("type", Lower(Text(fields, "type"))));
                    lines.Add(("category", Text(fields, "category")));
                    lines.Add(("tag", Text(fields, "tag") is "[]" ? "" : Text(fields, "tag")));
                    lines.Add(("stock_status", Lower(Text(fields, "stockStatus"))));
                    lines.Add(("order", Lower(Text(fields, "order"))));
                    lines.Add(("orderby", Lower(Text(fields, "orderBy"))));
                    Unmapped("search", "sku", "status", "type", "category", "tag", "stockStatus", "order", "orderBy");
                    break;
                case "customers":
                    lines.Add(("email", Text(fields, "email")));
                    lines.Add(("order", Lower(Text(fields, "order"))));
                    lines.Add(("orderby", Lower(Text(fields, "orderby"))));
                    Unmapped("email", "order", "orderby");
                    break;
                case "create_order":
                case "update_order":
                    lines.Add(("status", Lower(Text(fields, "status"))));
                    lines.Add(("customer_id", Text(fields, "customerId")));
                    lines.Add(("payment_method", Text(fields, "paymentMethodId")));
                    lines.Add(("payment_method_title", Text(fields, "paymentMethodTitle")));
                    lines.Add(("set_paid", Text(fields, "setPaid")));
                    lines.Add(("currency", Text(fields, "currency")));
                    lines.Add(("customer_note", Text(fields, "customerNote")));
                    lines.Add(("transaction_id", Text(fields, "transactionID")));
                    Address("billing", p.TryGetProperty("billingUi", out var billing) && billing.ValueKind == JsonValueKind.Object && billing.TryGetProperty("billingValues", out var billed) ? billed : default, Snake);
                    Address("shipping", p.TryGetProperty("shippingUi", out var shipping) && shipping.ValueKind == JsonValueKind.Object && shipping.TryGetProperty("shippingValues", out var shipped) ? shipped : default, Snake);
                    List("line_items", "lineItemsUi", "lineItemsValues");
                    List("shipping_lines", "shippingLinesUi", "shippingLinesValues");
                    List("fee_lines", "feeLinesUi", "feeLinesValues");
                    List("coupon_lines", "couponLinesUi", "couponLinesValues");
                    List("meta_data", "metadataUi", "metadataValues");
                    Unmapped("status", "customerId", "paymentMethodId", "paymentMethodTitle", "setPaid", "currency", "customerNote", "transactionID");
                    break;
                case "create_product":
                case "update_product":
                    lines.Add(("name", operation == "create_product" ? Text(p, "name") : Text(fields, "name")));
                    lines.Add(("type", Lower(Text(fields, "type"))));
                    lines.Add(("status", Lower(Text(fields, "status"))));
                    lines.Add(("regular_price", Text(fields, "regularPrice")));
                    lines.Add(("sale_price", Text(fields, "salePrice")));
                    lines.Add(("sku", Text(fields, "sku")));
                    lines.Add(("description", Text(fields, "description")));
                    lines.Add(("short_description", Text(fields, "shortDescription")));
                    lines.Add(("categories", Joined(fields, "categories")));
                    lines.Add(("tags", Joined(fields, "tags")));
                    lines.Add(("manage_stock", Text(fields, "manageStock")));
                    lines.Add(("stock_quantity", Text(fields, "stockQuantity")));
                    lines.Add(("stock_status", Lower(Text(fields, "stockStatus"))));
                    lines.Add(("weight", Text(fields, "weight")));
                    lines.Add(("images", string.Join(", ", Items(p, "imagesUi", "imagesValues").Select(image => Text(image, "src")).Where(src => src.Length > 0))));
                    List("meta_data", "metadataUi", "metadataValues");
                    if (Text(p, "dimensionsUi").Length > 2)
                    {
                        said.Add("dimensionsUi");
                    }

                    Unmapped("name", "type", "status", "regularPrice", "salePrice", "sku", "description", "shortDescription", "categories", "tags", "manageStock", "stockQuantity", "stockStatus", "weight");
                    break;
                case "create_customer":
                case "update_customer":
                    lines.Add(("email", operation == "create_customer" ? Text(p, "email") : Text(fields, "email")));
                    lines.Add(("first_name", Text(fields, "first_name")));
                    lines.Add(("last_name", Text(fields, "last_name")));
                    lines.Add(("username", Text(fields, "username")));
                    Address("billing", fields.ValueKind == JsonValueKind.Object && fields.TryGetProperty("billing", out var billing2) ? billing2 : default, null);
                    Address("shipping", fields.ValueKind == JsonValueKind.Object && fields.TryGetProperty("shipping", out var shipping2) ? shipping2 : default, null);
                    if (fields.ValueKind == JsonValueKind.Object && fields.TryGetProperty("meta_data", out var meta))
                    {
                        var pairs = Items(meta.ValueKind == JsonValueKind.Object ? fields : default, "meta_data", "meta_data_fields").Select(item => (System.Text.Json.Nodes.JsonNode)Object(item)).ToArray();
                        if (pairs.Length > 0)
                        {
                            lines.Add(("meta_data", new System.Text.Json.Nodes.JsonArray(pairs).ToJsonString(ReadableJson)));
                        }
                    }

                    if (Text(fields, "password").Length > 0)
                    {
                        todo.Add("it gave the customer a password - here no password goes through a pipeline: WooCommerce sends the customer a link to set one.");
                    }

                    Unmapped("email", "first_name", "last_name", "username", "billing", "shipping", "meta_data", "password");
                    break;
                case "delete_order":
                case "delete_product":
                    lines.Add(("force", "true")); // n8n deleted for good
                    break;
            }

            if (operation.EndsWith("s", StringComparison.Ordinal))
            {
                lines.Add(("max", Most(p, 50)));
            }

            foreach (var name in said)
            {
                todo.Add($"it set its '{name}' - here it has no parameter: set it in WooCommerce.");
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            var written = lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToList();
            var parameters = FtpParameters(written.ToArray());
            Set(step, "Parameters", expression && !parameters.StartsWith('=') ? "=" + parameters : parameters);
            todo.Add(operation.EndsWith("s", StringComparison.Ordinal) ? "n8n gave each record as an item - here the records are the step's result, a list, each its id and its fields." : PerItem);
            todo.Add(WooCommerceConnection);
        }

        private const string LinearConnection = "choose its connection - n8n's credentials stay in n8n: add a Linear connection under Admin > Connections (an API key) and pick it here.";

        // n8n's Linear issue Create, Get, Get Many, Update, Delete and Add Link and its comment Add as Extract from connection's
        // operations: a team, a title, a description, an assignee, a priority and a state by the ids n8n chose (the connector takes
        // a team's key, a state's name and an address too); a link; a comment - one answering another said.
        private static void Linear(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var fields = p.ValueKind == JsonValueKind.Object && p.TryGetProperty(operation == "update_issue" ? "updateFields" : "additionalFields", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            var lines = new List<(string Name, string Value)>();
            if (operation is not ("create_issue" or "issues"))
            {
                lines.Add(("issue", Text(p, "issueId")));
            }

            switch (operation)
            {
                case "create_issue":
                case "update_issue":
                    lines.Add(("team", operation == "create_issue" ? Text(p, "teamId") : Text(fields, "teamId")));
                    lines.Add(("title", operation == "create_issue" ? Text(p, "title") : Text(fields, "title")));
                    lines.Add(("description", Text(fields, "description")));
                    lines.Add(("assignee", Text(fields, "assigneeId")));
                    lines.Add(("priority", Text(fields, "priorityId")));
                    lines.Add(("state", Text(fields, "stateId")));
                    break;
                case "issues":
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "add_link":
                    lines.Add(("url", Text(p, "link")));
                    break;
                case "add_comment":
                    lines.Add(("body", Text(p, "comment")));
                    if (Text(fields, "parentId").Length > 0)
                    {
                        todo.Add("it answered a comment - here the comment is on the issue itself.");
                    }

                    break;
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation == "issues" ? "n8n gave each issue as an item - here the issues are the step's result, a list, each its identifier, title, state and fields." : PerItem);
            todo.Add(LinearConnection);
        }

        private const string GitLabConnection = "choose its connection - n8n's credentials stay in n8n: add a GitLab connection under Admin > Connections (the instance's address and an access token) and pick it here.";

        // n8n's GitLab issue Create, Get, Edit and Create Comment, its repository Get Issues, its release Create and its file Get,
        // Create and Edit as Extract from connection's operations: the project as n8n's owner and repository joined; an issue's
        // title, body, labels (n8n's list of label items) and assignees (n8n's ids), its due date, an edit's state as a close or a
        // reopen; a Get Issues' filters; a release's tag, name, notes and ref; a file's path, ref, content, branch and message. A
        // binary file, another start branch and an author are said.
        private static void GitLab(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            var said = new List<string>();
            var owner = Text(p, "owner");
            var repository = Text(p, "repository");
            var expression = owner.StartsWith('=') || repository.StartsWith('=');
            lines.Add(("project", owner.Length > 0 && repository.Length > 0 ? (expression ? "=" : "") + Unmarked(owner) + "/" + Unmarked(repository) : ""));
            string Listed(JsonElement holder, string name, string item) =>
                holder.ValueKind == JsonValueKind.Object && holder.TryGetProperty(name, out var list) && list.ValueKind == JsonValueKind.Array
                    ? string.Join(", ", list.EnumerateArray().Select(entry => entry.ValueKind == JsonValueKind.Object ? Text(entry, item) : entry.ValueKind == JsonValueKind.String ? entry.GetString() ?? "" : entry.GetRawText()).Where(value => value.Length > 0))
                    : Text(holder, name);
            switch (operation)
            {
                case "create_issue":
                    lines.Add(("title", Text(p, "title")));
                    lines.Add(("description", Text(p, "body")));
                    lines.Add(("labels", Listed(p, "labels", "label")));
                    lines.Add(("assignees", Listed(p, "assignee_ids", "assignee")));
                    lines.Add(("due_date", Text(p, "due_date") is { Length: >= 10 } due ? due[..10] : Text(p, "due_date")));
                    break;
                case "update_issue":
                    var fields = p.TryGetProperty("editFields", out var edit) && edit.ValueKind == JsonValueKind.Object ? edit : default;
                    lines.Add(("issue", Text(p, "issueNumber")));
                    lines.Add(("title", Text(fields, "title")));
                    lines.Add(("description", Text(fields, "description")));
                    lines.Add(("state", Text(fields, "state") switch { "closed" or "close" => "close", "opened" or "open" or "reopen" => "reopen", var other => other }));
                    lines.Add(("labels", Listed(fields, "labels", "label")));
                    lines.Add(("assignees", Listed(fields, "assignee_ids", "assignee")));
                    lines.Add(("due_date", Text(fields, "due_date") is { Length: >= 10 } changed ? changed[..10] : Text(fields, "due_date")));
                    break;
                case "get_issue":
                    lines.Add(("issue", Text(p, "issueNumber")));
                    break;
                case "comment":
                    lines.Add(("issue", Text(p, "issueNumber")));
                    lines.Add(("body", Text(p, "body")));
                    break;
                case "issues":
                    var filters = p.TryGetProperty("getRepositoryIssuesFilters", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
                    lines.Add(("state", Text(filters, "state")));
                    lines.Add(("labels", Text(filters, "labels")));
                    lines.Add(("assignee", Text(filters, "assignee_username")));
                    lines.Add(("search", Text(filters, "search")));
                    lines.Add(("updated_since", Text(filters, "updated_after")));
                    lines.Add(("max", Most(p, 20)));
                    if (filters.ValueKind == JsonValueKind.Object)
                    {
                        said.AddRange(filters.EnumerateObject().Select(field => field.Name).Where(name => name is not ("state" or "labels" or "assignee_username" or "search" or "updated_after" or "order_by" or "sort")));
                    }

                    break;
                case "release":
                    var extra = p.TryGetProperty("additionalFields", out var more) && more.ValueKind == JsonValueKind.Object ? more : default;
                    lines.Add(("tag", Text(p, "releaseTag")));
                    lines.Add(("name", Text(extra, "name")));
                    lines.Add(("description", Text(extra, "description")));
                    lines.Add(("ref", Text(extra, "ref")));
                    break;
                case "file":
                    lines.Add(("path", Text(p, "filePath")));
                    lines.Add(("ref", Text(p, "additionalParameters", "reference")));
                    if (Bool(p, "asBinaryProperty"))
                    {
                        todo.Add("it read the file as binary - here a file is read as text: a binary file is refused.");
                    }

                    break;
                case "commit_file":
                    lines.Add(("path", Text(p, "filePath")));
                    lines.Add(("branch", Text(p, "branch")));
                    lines.Add(("content", Text(p, "fileContent")));
                    lines.Add(("message", Text(p, "commitMessage")));
                    if (Bool(p, "binaryData"))
                    {
                        todo.Add("it committed a binary file - here a file is committed as text: give its content.");
                    }

                    said.AddRange(new[] { "branchStart", "author" }.Where(name => Text(p, "additionalParameters", name).Length > 0));
                    break;
            }

            foreach (var name in said)
            {
                todo.Add($"it set its '{name}' - here it has no parameter: set it in GitLab.");
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation == "issues" ? "n8n gave each issue as an item - here the issues are the step's result, a list, each its number, title, state and fields." : PerItem);
            todo.Add(GitLabConnection);
        }

        private const string FreshdeskConnection = "choose its connection - n8n's credentials stay in n8n: add a Freshdesk connection under Admin > Connections (the helpdesk's address and an API key) and pick it here.";

        // n8n's Freshdesk ticket and contact Create, Get, Get Many, Update and Delete as Extract from connection's operations: a ticket's
        // requester by the kind n8n chose, its status, priority and source (n8n's words, the connector's), subject, description, type,
        // tags, copies, group, agent, company, product and due times; a Get Many's requester, company, change and order; a contact's
        // name, address, phones, company, job title, tags and the rest. Custom fields and what has no parameter here are said.
        private static void Freshdesk(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            var said = new List<string>();
            var contact = operation.Contains("contact", StringComparison.Ordinal);
            var fields = p.ValueKind == JsonValueKind.Object && p.TryGetProperty(
                operation.StartsWith("update_", StringComparison.Ordinal) ? (contact ? "additionalFields" : "updateFields") : operation.StartsWith("create_", StringComparison.Ordinal) ? (contact ? "additionalFields" : "options") : contact ? "filters" : "options",
                out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            void Unmapped(params string[] known)
            {
                if (fields.ValueKind == JsonValueKind.Object)
                {
                    said.AddRange(fields.EnumerateObject().Select(field => field.Name).Where(name => !known.Contains(name)));
                }
            }

            string Snake(string word) => word switch { "feedbackWidget" => "feedback_widget", "OutboundEmail" => "outbound_email", var other => other };
            string Requester(string kind) => kind switch { "requesterId" => "requester_id", "phone" => "phone", "uniqueExternalId" => "unique_external_id", "email" => "email", _ => "" };
            switch (operation)
            {
                case "create_ticket":
                case "update_ticket":
                    var source = operation == "create_ticket" ? p : fields;
                    if (operation == "update_ticket")
                    {
                        lines.Add(("ticket", Text(p, "ticketId")));
                    }

                    var kind = Text(source, "requester") is { Length: > 0 } chosen ? chosen : "requesterId"; // n8n's default, left out of its export
                    var value = Text(source, "requesterIdentificationValue");
                    if (value.Length > 0)
                    {
                        if (Requester(kind) is { Length: > 0 } named)
                        {
                            lines.Add((named, value));
                        }
                        else
                        {
                            todo.Add($"it named the requester by their {kind} - here give their email, requester_id, phone or unique_external_id.");
                        }
                    }

                    lines.Add(("name", Text(fields, "name")));
                    lines.Add(("subject", Text(fields, "subject")));
                    lines.Add(("description", Text(fields, "description")));
                    // A create's status, priority and source as n8n's defaults when its export leaves them out: pending, low, portal.
                    var create = operation == "create_ticket";
                    lines.Add(("status", Text(source, "status") is { Length: > 0 } status ? status : create ? "pending" : ""));
                    lines.Add(("priority", Text(source, "priority") is { Length: > 0 } priority ? priority : create ? "low" : ""));
                    lines.Add(("source", Snake(Text(source, "source") is { Length: > 0 } from ? from : create ? "portal" : "")));
                    lines.Add(("type", Text(fields, "type")));
                    lines.Add(("tags", Text(fields, "tags")));
                    lines.Add(("cc_emails", Text(fields, "ccEmails")));
                    lines.Add(("group_id", Text(fields, "group")));
                    lines.Add(("responder_id", Text(fields, "agent")));
                    lines.Add(("company_id", Text(fields, "company")));
                    lines.Add(("product_id", Text(fields, "product")));
                    lines.Add(("due_by", Text(fields, "dueBy")));
                    lines.Add(("fr_due_by", Text(fields, "frDueBy")));
                    Unmapped("name", "subject", "description", "status", "priority", "source", "type", "tags", "ccEmails", "group", "agent", "company", "product", "dueBy", "frDueBy", "requester", "requesterIdentificationValue");
                    break;
                case "tickets":
                    lines.Add(("requester_email", Text(fields, "requesterEmail")));
                    lines.Add(("requester_id", Text(fields, "requesterId")));
                    lines.Add(("company_id", Text(fields, "companyId")));
                    lines.Add(("updated_since", Text(fields, "updatedSince")));
                    lines.Add(("order_by", Text(fields, "orderBy")));
                    lines.Add(("order_type", Text(fields, "order")));
                    lines.Add(("max", Most(p, 5)));
                    Unmapped("requesterEmail", "requesterId", "companyId", "updatedSince", "orderBy", "order");
                    break;
                case "contacts":
                    lines.Add(("email", Text(fields, "email")));
                    lines.Add(("phone", Text(fields, "phone")));
                    lines.Add(("mobile", Text(fields, "mobile")));
                    lines.Add(("company_id", Text(fields, "company_id")));
                    lines.Add(("state", Text(fields, "state")));
                    lines.Add(("updated_since", Text(fields, "updated_since")));
                    lines.Add(("max", Bool(p, "returnAll") ? EveryRecord : Text(p, "limit")));
                    Unmapped("email", "phone", "mobile", "company_id", "state", "updated_since");
                    break;
                case "create_contact":
                case "update_contact":
                    if (operation == "update_contact")
                    {
                        lines.Add(("contact", Text(p, "contactId")));
                    }

                    lines.Add(("name", operation == "create_contact" ? Text(p, "name") : Text(fields, "name")));
                    lines.Add(("email", operation == "create_contact" ? Text(p, "email") : Text(fields, "email")));
                    foreach (var name in new[] { "phone", "mobile", "unique_external_id", "company_id", "job_title", "description", "address", "language", "time_zone" })
                    {
                        lines.Add((name, Text(fields, name)));
                    }

                    lines.Add(("tags", Joined(fields, "tags")));
                    lines.Add(("other_emails", Joined(fields, "other_emails")));
                    Unmapped("name", "email", "phone", "mobile", "unique_external_id", "company_id", "job_title", "description", "address", "language", "time_zone", "tags", "other_emails");
                    break;
                default:
                    lines.Add((contact ? "contact" : "ticket", Text(p, contact ? "contactId" : "ticketId")));
                    break;
            }

            foreach (var name in said)
            {
                todo.Add(name == "customFields"
                    ? "it set custom fields - here give them as JSON, 'custom_fields = {\"cf_name\": \"value\"}'."
                    : $"it set its '{name}' - here it has no parameter: set it in Freshdesk.");
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "tickets" or "contacts" ? "n8n gave each record as an item - here the records are the step's result, a list, each its id and its fields." : PerItem);
            todo.Add(FreshdeskConnection);
        }

        private const string MondayConnection = "choose its connection - n8n's credentials stay in n8n: add a monday.com connection under Admin > Connections (an API token) and pick it here.";

        // n8n's Monday.com board item Create, Get, Get Many, Get by Column Value, Change Column Value(s), Move, Delete and Add Update and
        // its board Get Many as Extract from connection's operations: a board, a group, an item and a name; its column values (n8n's
        // JSON, one column's value made an object of its id); an update's text.
        private static void Monday(JsonElement p, PipelineGraphStep step, Todo todo, string key)
        {
            var operation = key == "change_column" ? "update_item" : key;
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            // n8n's export holds only what its form shows; its Move names a board too, which moving to a group does not need here.
            lines.Add(("board", key == "move_item" ? "" : Text(p, "boardId")));
            lines.Add(("item", Text(p, "itemId")));
            lines.Add(("group", Text(p, "groupId")));
            switch (key)
            {
                case "create_item":
                    lines.Add(("name", Text(p, "name")));
                    lines.Add(("columns", Columns(Text(p, "additionalFields", "columnValues"))));
                    break;
                case "update_item":
                    lines.Add(("columns", Columns(Text(p, "columnValues"))));
                    break;
                case "change_column":
                    var column = Text(p, "columnId");
                    var value = Text(p, "value");
                    if (column.Length > 0)
                    {
                        System.Text.Json.Nodes.JsonNode? parsed = null;
                        try
                        {
                            parsed = value.StartsWith('=') ? null : System.Text.Json.Nodes.JsonNode.Parse(value);
                        }
                        catch (JsonException)
                        {
                        }

                        lines.Add(("columns", value.StartsWith('=')
                            ? "={\"" + column + "\": " + Unmarked(value) + "}"
                            : new System.Text.Json.Nodes.JsonObject { [column] = parsed ?? System.Text.Json.Nodes.JsonValue.Create(value) }.ToJsonString(ReadableJson)));
                    }

                    break;
                case "items_by_column_value":
                    lines.Add(("column", Text(p, "columnId")));
                    lines.Add(("values", Text(p, "columnValue")));
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "items":
                case "boards":
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "add_update":
                    lines.Add(("body", Text(p, "value")));
                    break;
            }

            // n8n's column values as one line: its JSON made compact, an expression left as written.
            static string Columns(string given) => given.Length == 0 || given.StartsWith('=') ? given : Minified(given);

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "items" or "items_by_column_value" or "boards" ? "n8n gave each item as an item - here the items are the step's result, a list, each its name, group and columns." : PerItem);
            todo.Add(MondayConnection);
        }

        private const string TodoistConnection = "choose its connection - n8n's credentials stay in n8n: add a Todoist connection under Admin > Connections (an API token) and pick it here.";

        // n8n's Todoist task Create, Quick Add, Get, Get Many, Update, Close, Reopen, Move and Delete, its comment Create and its
        // project Get Many as Extract from connection's operations: a task, a project (n8n's list or its id), a section, a parent,
        // content, a description, labels, a priority, a due date (words, a day or a time), an assignee, a duration and a deadline;
        // a Get Many's project, section, parent, label, ids or filter and n8n's limit; a quick add's line, note and reminder.
        private static void Todoist(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            JsonElement Collection(string name) => p.ValueKind == JsonValueKind.Object && p.TryGetProperty(name, out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            void Fields(JsonElement fields, bool content)
            {
                if (content)
                {
                    lines.Add(("content", Text(fields, "content")));
                }

                lines.Add(("description", Text(fields, "description")));
                lines.Add(("labels", Joined(fields, "labels")));
                lines.Add(("priority", Text(fields, "priority")));
                lines.Add(("due_string", Text(fields, "dueString")));
                lines.Add(("due_date", Text(fields, "dueDate")));
                lines.Add(("due_datetime", Text(fields, "dueDateTime")));
                lines.Add(("due_lang", Text(fields, "dueLang")));
                lines.Add(("assignee", Text(fields, "assigneeId")));
                if (Text(fields, "duration") is { Length: > 0 } duration && duration != "0")
                {
                    lines.Add(("duration", duration));
                    lines.Add(("duration_unit", Text(fields, "durationUnit")));
                }

                lines.Add(("deadline", Text(fields, "deadlineDate")));
                if (Text(fields, "order").Length > 0 && Text(fields, "order") != "0")
                {
                    todo.Add("it set the task's order - here Todoist places it: drag it in Todoist.");
                }
            }

            var options = Collection("options");
            switch (operation)
            {
                case "create_task":
                    lines.Add(("project", Locator(p, "project")));
                    lines.Add(("section", Text(options, "section")));
                    lines.Add(("parent", Text(options, "parentId")));
                    lines.Add(("content", Text(p, "content")));
                    lines.Add(("labels", Joined(p, "labels")));
                    if (todo.Version < 2 && Joined(p, "labels").Length > 0)
                    {
                        todo.Add("n8n's Todoist 1 named its labels by id - here labels are names: give the labels' names.");
                    }

                    Fields(options, content: false);
                    break;
                case "quick_add":
                    lines.Add(("text", Text(p, "text")));
                    lines.Add(("note", Text(options, "note")));
                    lines.Add(("reminder", Text(options, "reminder")));
                    lines.Add(("auto_reminder", Bool(options, "auto_reminder") ? "true" : ""));
                    break;
                case "update_task":
                    lines.Add(("task", Text(p, "taskId")));
                    Fields(Collection("updateFields"), content: true);
                    break;
                case "move_task":
                    // n8n moves it to its section when one is given, else under its parent, else to its project.
                    lines.Add(("task", Text(p, "taskId")));
                    var section = Text(options, "section") is { Length: > 0 } inOptions ? inOptions : Text(p, "section");
                    var parent = Text(options, "parent");
                    lines.Add(section.Length > 0 ? ("section", section) : parent.Length > 0 ? ("parent", parent) : ("project", Locator(p, "project")));
                    break;
                case "tasks":
                    var filters = Collection("filters");
                    lines.Add(("project", Text(filters, "projectId")));
                    lines.Add(("section", Text(filters, "sectionId")));
                    lines.Add(("parent", Text(filters, "parentId")));
                    lines.Add(("label", Text(filters, "labelId")));
                    lines.Add(("ids", Text(filters, "ids")));
                    lines.Add(("filter", Text(filters, "filter")));
                    lines.Add(("lang", Text(filters, "lang")));
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "add_comment":
                    lines.Add(("task", Text(p, "commentTaskId")));
                    lines.Add(("content", Text(p, "commentContent")));
                    break;
                case "projects":
                    lines.Add(("max", EveryRecord)); // n8n read every project
                    break;
                default:
                    lines.Add(("task", Text(p, "taskId")));
                    break;
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "tasks" or "projects" ? "n8n gave each " + (operation == "tasks" ? "task" : "project") + " as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(TodoistConnection);
        }

        private const string WordPressConnection = "choose its connection - n8n's credentials stay in n8n: add a WordPress connection under Admin > Connections (the site's address, a username and an application password) and pick it here.";

        // n8n's WordPress post and page Create, Get, Get Many, Update and Delete and its user Create, Get, Get Many and Update as
        // Extract from connection's operations: a post's, a page's and a user's id, a title, content, a slug, a status, an author,
        // comments and pings, a format, sticky, categories and tags (n8n's lists of ids), a time, a template (n8n's Elementor
        // choice its name), a parent, a menu order, a featured image; a Get Many's filters and n8n's limit; a user's names, address,
        // site and words. A password n8n kept in its export - a user's, a protected post's - is left out and said.
        private static void WordPress(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var users = operation.Contains("user", StringComparison.Ordinal);
            var posts = operation.Contains("post", StringComparison.Ordinal);
            var one = posts ? "post" : users ? "user" : "page";
            var lines = new List<(string Name, string Value)>();
            JsonElement Collection(string name) => p.ValueKind == JsonValueKind.Object && p.TryGetProperty(name, out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            void Password(JsonElement holder)
            {
                if (Text(holder, "password").Length > 0)
                {
                    todo.Add("its password, kept in n8n's export, was left out - give it here from where you keep secrets, not in the pipeline's text.");
                }
            }

            void Content(JsonElement fields)
            {
                lines.Add(("content", Text(fields, "content")));
                lines.Add(("slug", Text(fields, "slug")));
                lines.Add(("status", Text(fields, "status")));
                lines.Add(("author", Text(fields, "authorId")));
                lines.Add(("comment_status", Text(fields, "commentStatus")));
                lines.Add(("ping_status", Text(fields, "pingStatus")));
                var template = Text(fields, posts ? "postTemplate" : "pageTemplate", "values", "template");
                lines.Add(("template", template));
                if (posts)
                {
                    lines.Add(("format", Text(fields, "format")));
                    lines.Add(("sticky", Bool(fields, "sticky") ? "true" : ""));
                    lines.Add(("categories", Joined(fields, "categories")));
                    lines.Add(("tags", Joined(fields, "tags")));
                    lines.Add(("date", Text(fields, "date")));
                }
                else
                {
                    lines.Add(("parent", Text(fields, "parent")));
                    lines.Add(("menu_order", Text(fields, "menuOrder") is { Length: > 0 } order && order != "0" ? order : ""));
                    lines.Add(("featured_media", Text(fields, "featuredMediaId")));
                }

                Password(fields);
            }

            void Person(JsonElement fields)
            {
                lines.Add(("username", Text(fields, "username")));
                lines.Add(("email", Text(fields, "email")));
                lines.Add(("name", Text(fields, "name")));
                lines.Add(("first_name", Text(fields, "firstName")));
                lines.Add(("last_name", Text(fields, "lastName")));
                lines.Add(("nickname", Text(fields, "nickname")));
                lines.Add(("url", Text(fields, "url")));
                lines.Add(("description", Text(fields, "description")));
                lines.Add(("slug", Text(fields, "slug")));
                Password(fields);
            }

            var id = Text(p, one + "Id");
            switch (operation)
            {
                case "create_post":
                case "create_page":
                    lines.Add(("title", Text(p, "title")));
                    Content(Collection("additionalFields"));
                    break;
                case "update_post":
                case "update_page":
                    lines.Add((one, id));
                    var changes = Collection("updateFields");
                    lines.Add(("title", Text(changes, "title")));
                    Content(changes);
                    break;
                case "get_post":
                case "get_page":
                case "get_user":
                    lines.Add((one, id));
                    lines.Add(("context", Text(Collection("options"), "context")));
                    if (!users)
                    {
                        Password(Collection("options"));
                    }

                    break;
                case "delete_post":
                case "delete_page":
                    lines.Add((one, id));
                    lines.Add(("force", Bool(Collection("options"), "force") ? "true" : ""));
                    break;
                case "posts":
                case "pages":
                    var options = Collection("options");
                    lines.Add(("status", Text(options, "status")));
                    lines.Add(("search", Text(options, "search")));
                    lines.Add(("author", Joined(options, "author")));
                    lines.Add(("after", Text(options, "after")));
                    lines.Add(("before", Text(options, "before")));
                    lines.Add(("order_by", Text(options, "orderBy")));
                    lines.Add(("order", Text(options, "order")));
                    lines.Add(("context", Text(options, "context")));
                    if (posts)
                    {
                        lines.Add(("categories", Joined(options, "categories")));
                        lines.Add(("categories_exclude", Joined(options, "excludedCategories")));
                        lines.Add(("tags", Joined(options, "tags")));
                        lines.Add(("tags_exclude", Joined(options, "excludedTags")));
                        lines.Add(("sticky", Bool(options, "sticky") ? "true" : ""));
                    }
                    else
                    {
                        lines.Add(("parent", Text(options, "parent")));
                        lines.Add(("menu_order", Text(options, "menuOrder") is { Length: > 0 } order && order != "0" ? order : ""));
                        if (Text(options, "page") is { Length: > 0 } page && page != "1")
                        {
                            todo.Add("it read page " + page + " of them - here they are read from the first, up to 'max'.");
                        }
                    }

                    lines.Add(("max", Most(p, 5)));
                    break;
                case "users":
                    var filters = Collection("options");
                    lines.Add(("search", Text(filters, "search")));
                    lines.Add(("order_by", Text(filters, "orderBy")));
                    lines.Add(("order", Text(filters, "order")));
                    lines.Add(("context", Text(filters, "context")));
                    if (Text(filters, "who").Length > 0)
                    {
                        todo.Add("it read only the users who write - here users are read by their roles: give 'roles = author, editor' to keep to them.");
                    }

                    lines.Add(("max", Most(p, 5)));
                    break;
                case "create_user":
                    Person(p);
                    Person(Collection("additionalFields"));
                    break;
                case "update_user":
                    lines.Add(("user", Text(p, "userId")));
                    Person(Collection("updateFields"));
                    break;
            }

            // HTML content's lines joined say nothing - a browser reads them as one; any other value's are said.
            if (lines.Any(line => line.Name != "content" && line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "posts" or "pages" or "users" ? "n8n gave each " + one + " as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(WordPressConnection);
        }

        private const string SendGridConnection = "choose its connection - n8n's credentials stay in n8n: add a SendGrid connection under Admin > Connections (an API key) and pick it here.";

        // n8n's SendGrid contact Create or Update, Get, Get Many and Delete, its list Create, Get, Get Many, Update and Delete and
        // its mail Send as Extract from connection's operations: a contact's address, names, address, other addresses, custom fields
        // (n8n's list made a JSON object) and lists; a contact by its id or its address; an SGQL query and n8n's limit; ids or every
        // contact; a list's id, name and sample; a mail's sender, recipients, copies, reply-to, subject and body (HTML when n8n said
        // so) or dynamic template and its fields (a JSON object), categories, headers (a JSON object), IP pool, time and sandbox.
        // Attachments, from n8n's binary data, are said.
        private static void SendGrid(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            var fields = p.ValueKind == JsonValueKind.Object && p.TryGetProperty("additionalFields", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;

            // n8n's key and value pairs as one JSON object - an expression among them making the whole parameter one.
            string Pairs(JsonElement holder, string collection, string group, string keyName, string valueName)
            {
                var pairs = holder.ValueKind == JsonValueKind.Object && holder.TryGetProperty(collection, out var outer) && outer.ValueKind == JsonValueKind.Object
                    && outer.TryGetProperty(group, out var list) && list.ValueKind == JsonValueKind.Array
                    ? list.EnumerateArray().Select(pair => (Key: Text(pair, keyName), Value: Text(pair, valueName))).Where(pair => pair.Key.Length > 0).ToList()
                    : new List<(string Key, string Value)>();
                if (pairs.Count == 0)
                {
                    return "";
                }

                var expression = pairs.Any(pair => pair.Value.StartsWith('='));
                var json = "{" + string.Join(", ", pairs.Select(pair => System.Text.Json.JsonSerializer.Serialize(pair.Key, ReadableJson) + ": "
                    + (pair.Value.StartsWith('=') ? "\"" + Unmarked(pair.Value) + "\"" : System.Text.Json.JsonSerializer.Serialize(pair.Value, ReadableJson)))) + "}";
                return (expression ? "=" : "") + json;
            }

            switch (operation)
            {
                case "upsert_contacts":
                    lines.Add(("email", Text(p, "email")));
                    lines.Add(("first_name", Text(fields, "firstName")));
                    lines.Add(("last_name", Text(fields, "lastName")));
                    lines.Add(("alternate_emails", Text(fields, "alternateEmails")));
                    lines.Add(("address_line_1", Text(fields, "addressUi", "addressValues", "address1")));
                    lines.Add(("address_line_2", Text(fields, "addressUi", "addressValues", "address2")));
                    lines.Add(("city", Text(fields, "city")));
                    lines.Add(("state_province_region", Text(fields, "stateProvinceRegion")));
                    lines.Add(("postal_code", Text(fields, "postalCode")));
                    lines.Add(("country", Text(fields, "country")));
                    lines.Add(("custom_fields", Pairs(fields, "customFieldsUi", "customFieldValues", "fieldId", "fieldValue")));
                    lines.Add(("lists", Joined(fields.ValueKind == JsonValueKind.Object && fields.TryGetProperty("listIdsUi", out var listsUi) && listsUi.ValueKind == JsonValueKind.Object
                        && listsUi.TryGetProperty("listIdValues", out var listValues) ? listValues : default, "listIds")));
                    break;
                case "get_contact":
                    lines.Add(Text(p, "by") == "email" ? ("email", Text(p, "email")) : ("contact", Text(p, "contactId")));
                    break;
                case "contacts":
                    lines.Add(("query", Text(p, "filters", "query")));
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "delete_contacts":
                    lines.Add(Bool(p, "deleteAll") ? ("all", "true") : ("contacts", Text(p, "ids")));
                    break;
                case "lists":
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "get_list":
                    lines.Add(("list", Text(p, "listId")));
                    lines.Add(("contact_sample", Bool(p, "contactSample") ? "true" : ""));
                    break;
                case "create_list":
                    lines.Add(("name", Text(p, "name")));
                    break;
                case "rename_list":
                    lines.Add(("list", Text(p, "listId")));
                    lines.Add(("name", Text(p, "name")));
                    break;
                case "delete_list":
                    lines.Add(("list", Text(p, "listId")));
                    lines.Add(("delete_contacts", Bool(p, "deleteContacts") ? "true" : ""));
                    break;
                case "send_mail":
                    lines.Add(("from", Text(p, "fromEmail")));
                    lines.Add(("from_name", Text(p, "fromName")));
                    lines.Add(("to", Text(p, "toEmail")));
                    lines.Add(("cc", Text(fields, "ccEmail")));
                    lines.Add(("bcc", Text(fields, "bccEmail")));
                    lines.Add(("reply_to", Text(fields, "replyToEmail")));
                    if (Bool(p, "dynamicTemplate"))
                    {
                        lines.Add(("template", Text(p, "templateId")));
                        lines.Add(("template_data", Pairs(p, "dynamicTemplateFields", "fields", "key", "value")));
                    }
                    else
                    {
                        lines.Add(("subject", Text(p, "subject")));
                        lines.Add(("body", Text(p, "contentValue")));
                        lines.Add(("html", Text(p, "contentType") == "text/html" ? "true" : ""));
                    }

                    lines.Add(("categories", Text(fields, "categories")));
                    lines.Add(("headers", Pairs(fields, "headers", "details", "key", "value")));
                    lines.Add(("ip_pool", Text(fields, "ipPoolName")));
                    lines.Add(("send_at", Text(fields, "sendAt")));
                    lines.Add(("sandbox", Bool(fields, "enableSandbox") ? "true" : ""));
                    if (Text(fields, "attachments").Length > 0)
                    {
                        todo.Add("it attached files from n8n's binary data - here a mail carries none: link to them in the body.");
                    }

                    break;
            }

            // An HTML body's lines joined say nothing - a mail client reads them as one; any other value's are said.
            var html = lines.Any(line => line.Name == "html" && line.Value == "true");
            if (lines.Any(line => !(html && line.Name == "body") && line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "contacts" or "lists" ? "n8n gave each " + (operation == "contacts" ? "contact" : "list") + " as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(SendGridConnection);
        }

        private const string GoogleTasksConnection = "choose its connection - n8n's credentials stay in n8n: add a Google Tasks connection under Admin > Connections (an OAuth client's id and secret and a refresh token granted the tasks scope) and pick it here.";

        // n8n's Google Tasks Create, Get, Get Many, Update and Delete as Extract from connection's operations: the task list (n8n's
        // 'task' parameter), a task's id, a title, notes, a due day, finished or not (n8n's status, or a time it was finished), a
        // parent and a sibling; a Get Many's times, its flags (n8n's defaults the connector's) and n8n's limit. A task marked
        // deleted, and an update's place among its siblings, are said.
        private static void GoogleTasks(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)> { ("list", Text(p, "task")) };
            var fields = p.ValueKind == JsonValueKind.Object && p.TryGetProperty(operation == "update_task" ? "updateFields" : "additionalFields", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            void TaskLines(bool create)
            {
                lines.Add(("title", create ? Text(p, "title") : Text(fields, "title")));
                lines.Add(("notes", Text(fields, "notes")));
                lines.Add(("due", Text(fields, "dueDate")));
                lines.Add(("completed", Text(fields, "status") switch
                {
                    "completed" => "true",
                    "needsAction" => "false",
                    _ => Text(fields, "completed").Length > 0 ? "true" : "",
                }));
                if (Bool(fields, "deleted"))
                {
                    todo.Add("it marked the task deleted - here a task is deleted by Delete a task.");
                }
            }

            switch (operation)
            {
                case "create_task":
                    TaskLines(create: true);
                    lines.Add(("parent", Text(fields, "parent")));
                    lines.Add(("previous", Text(fields, "previous")));
                    break;
                case "update_task":
                    lines.Add(("task", Text(p, "taskId")));
                    TaskLines(create: false);
                    if (Text(fields, "previous").Length > 0)
                    {
                        todo.Add("it put the task after another - here Move a task does: give it 'previous = " + Text(fields, "previous") + "'.");
                    }

                    break;
                case "tasks":
                    lines.Add(("show_completed", Text(fields, "showCompleted")));
                    lines.Add(("show_deleted", Text(fields, "showDeleted")));
                    lines.Add(("show_hidden", Text(fields, "showHidden")));
                    lines.Add(("due_min", Text(fields, "dueMin")));
                    lines.Add(("due_max", Text(fields, "dueMax")));
                    lines.Add(("completed_min", Text(fields, "completedMin")));
                    lines.Add(("completed_max", Text(fields, "completedMax")));
                    lines.Add(("updated_min", Text(fields, "updatedMin")));
                    lines.Add(("max", Most(p, 20)));
                    break;
                default:
                    lines.Add(("task", Text(p, "taskId")));
                    break;
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation == "tasks" ? "n8n gave each task as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(GoogleTasksConnection);
        }

        private const string GoogleContactsConnection = "choose its connection - n8n's credentials stay in n8n: add a Google Contacts connection under Admin > Connections (an OAuth client's id and secret and a refresh token granted the contacts scope) and pick it here.";

        // n8n's Google Contacts Create, Get, Get Many, Update and Delete as Extract from connection's operations: a contact's id, its
        // names, its e-mail addresses and phone numbers (each "type: value"), its first company and address, notes, a birthday (its
        // day), groups and custom fields (n8n's pairs made a JSON object); the person fields read (n8n's list, or *); a Get Many's
        // search or order and n8n's limit (100 when its export leaves it out). What it set that a contact here has no parameter for
        // - a second company or address, events, relations, a "file as" - is said.
        private static void GoogleContacts(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var create = operation == "create_contact";
            var fields = p.ValueKind == JsonValueKind.Object && p.TryGetProperty(operation == "update_contact" ? "updateFields" : "additionalFields", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            // A fixed collection's entries: a list (several values), or one object (n8n's single-value collections, the address).
            List<JsonElement> Entries(string ui, string values) =>
                fields.ValueKind == JsonValueKind.Object && fields.TryGetProperty(ui, out var holder) && holder.ValueKind == JsonValueKind.Object && holder.TryGetProperty(values, out var list)
                    ? list.ValueKind == JsonValueKind.Array ? list.EnumerateArray().ToList() : list.ValueKind == JsonValueKind.Object ? new List<JsonElement> { list } : new List<JsonElement>()
                    : new List<JsonElement>();
            string Typed(string ui, string values) =>
                string.Join(", ", Entries(ui, values).Select(entry => (Text(entry, "type") is { Length: > 0 } type ? type + ": " : "") + Text(entry, "value")).Where(entry => !entry.EndsWith(": ", StringComparison.Ordinal) && entry.Length > 0));
            string Read()
            {
                var wanted = p.ValueKind == JsonValueKind.Object && p.TryGetProperty("fields", out var list) && list.ValueKind == JsonValueKind.Array
                    ? list.EnumerateArray().Where(field => field.ValueKind == JsonValueKind.String).Select(field => field.GetString() ?? "").Where(field => field.Length > 0).ToList() : new List<string>();
                return wanted.Contains("*") ? "*" : string.Join(", ", wanted);
            }

            var lines = new List<(string Name, string Value)>();
            if (operation is "get_contact" or "update_contact" or "delete_contact")
            {
                lines.Add(("contact", Text(p, "contactId")));
            }

            switch (operation)
            {
                case "contacts":
                    lines.Add(("query", Bool(p, "useQuery") ? Text(p, "query") : ""));
                    lines.Add(("sort_order", Bool(p, "useQuery") ? "" : Text(p, "options", "sortOrder")));
                    lines.Add(("fields", Read()));
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "get_contact":
                    lines.Add(("fields", Read()));
                    break;
                case "create_contact":
                case "update_contact":
                    lines.Add(("given_name", create ? Text(p, "givenName") : Text(fields, "givenName")));
                    lines.Add(("family_name", create ? Text(p, "familyName") : Text(fields, "familyName")));
                    lines.Add(("middle_name", Text(fields, "middleName")));
                    lines.Add(("prefix", Text(fields, "honorificPrefix")));
                    lines.Add(("suffix", Text(fields, "honorificSuffix")));
                    lines.Add(("emails", Typed("emailsUi", "emailsValues")));
                    lines.Add(("phones", Typed("phoneUi", "phoneValues")));
                    var companies = Entries("companyUi", "companyValues");
                    lines.Add(("company", companies.Count > 0 ? Text(companies[0], "name") : ""));
                    lines.Add(("job_title", companies.Count > 0 ? Text(companies[0], "title") : ""));
                    lines.Add(("notes", Text(fields, "biographies")));
                    var birthday = Text(fields, "birthday");
                    lines.Add(("birthday", birthday.Length >= 10 && !birthday.StartsWith('=') ? birthday[..10] : birthday));
                    var addresses = Entries("addressesUi", "addressesValues");
                    if (addresses.Count > 0)
                    {
                        lines.Add(("address", Text(addresses[0], "streetAddress")));
                        lines.Add(("city", Text(addresses[0], "city")));
                        lines.Add(("region", Text(addresses[0], "region")));
                        lines.Add(("postal_code", Text(addresses[0], "postalCode")));
                        lines.Add(("country_code", Text(addresses[0], "countryCode")));
                        lines.Add(("address_type", Text(addresses[0], "type")));
                    }

                    lines.Add(("groups", Joined(fields, "group")));
                    var custom = Entries("customFieldsUi", "customFieldsValues").Where(pair => Text(pair, "key").Length > 0).ToList();
                    if (custom.Count > 0)
                    {
                        var record = "{" + string.Join(", ", custom.Select(pair => JsonSerializer.Serialize(Text(pair, "key"), ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(Text(pair, "value")), ReadableJson))) + "}";
                        lines.Add(("custom_fields", custom.Any(pair => Text(pair, "value").StartsWith('=')) ? "=" + record : record));
                    }

                    var left = new List<string>();
                    if (companies.Count > 1)
                    {
                        left.Add("a second company");
                    }

                    if (addresses.Count > 1)
                    {
                        left.Add("a second address");
                    }

                    if (Entries("eventsUi", "eventsValues").Count > 0)
                    {
                        left.Add("events");
                    }

                    if (Entries("relationsUi", "relationsValues").Count > 0)
                    {
                        left.Add("relations");
                    }

                    if (Text(fields, "fileAs").Length > 0)
                    {
                        left.Add("a \"file as\"");
                    }

                    if (left.Count > 0)
                    {
                        todo.Add("it set " + string.Join(", ", left) + " - here a contact has its first company and address, and no events, relations or \"file as\": add them in Google Contacts.");
                    }

                    break;
            }

            if (Bool(p, "rawData"))
            {
                todo.Add("it gave Google's raw person - here each contact is a record of its names, e-mail addresses, phone numbers, company, notes, birthday, addresses and groups.");
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation == "contacts" ? "n8n gave each contact as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(GoogleContactsConnection);
        }

        private const string GoogleDocsConnection = "choose its connection - n8n's credentials stay in n8n: add a Google Docs connection under Admin > Connections (an OAuth client's id and secret and a refresh token granted the documents and drive.file scopes) and pick it here.";

        // n8n's Google Docs Create, Get and Update as Extract from connection's operations: a document's id or address, a title in a
        // folder or a shared drive; an update's one text insert or replace as Insert text or Replace text, any other list of
        // actions as the Docs API requests n8n built from them - its index, segment and location defaults written - with a revision
        // required or targeted. Google's whole document n8n gave without simplifying is said.
        private static void GoogleDocs(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            var lines = new List<(string Name, string Value)>();
            if (operation != "create_document")
            {
                lines.Add(("document", Text(p, "documentURL")));
            }

            if (operation == "create_document")
            {
                lines.Add(("title", Text(p, "title")));
                lines.Add(("folder", Locator(p, "folderId") is "default" or "root" ? "" : Locator(p, "folderId")));
                lines.Add(("drive", Locator(p, "driveId") is "myDrive" ? "" : Locator(p, "driveId")));
            }
            else if (operation == "get_document" && Text(p, "simple") == "false")
            {
                todo.Add("it gave Google's whole document - here the step gives its id, title, revision and text.");
            }

            var found = Find(p, "actionsUi", "actionFields");
            var actions = found.ValueKind == JsonValueKind.Array ? found.EnumerateArray().ToList() : found.ValueKind == JsonValueKind.Object ? new List<JsonElement> { found } : new List<JsonElement>();
            if (operation == "update_document")
            {
                string Of(JsonElement action, string name, string fallback) => Text(action, name) is { Length: > 0 } given ? given : fallback;
                var single = actions.Count == 1 ? actions[0] : default;
                if (actions.Count == 1 && Of(single, "object", "text") == "text" && Of(single, "action", "insert") == "insert")
                {
                    operation = "insert_text";
                    lines.Add(("text", Text(single, "text")));
                    lines.Add(("index", Of(single, "locationChoice", "endOfSegmentLocation") == "location" ? Of(single, "index", "1") : ""));
                    lines.Add(("segment", Of(single, "insertSegment", "body") == "body" ? "" : Text(single, "segmentId")));
                }
                else if (actions.Count == 1 && Of(single, "object", "text") == "text" && Of(single, "action", "insert") == "replaceAll")
                {
                    operation = "replace_text";
                    lines.Add(("find", Text(single, "text")));
                    lines.Add(("replace", Text(single, "replaceText")));
                    lines.Add(("match_case", Bool(single, "matchCase") ? "true" : ""));
                }
                else
                {
                    var requests = new JsonArray(actions.Select(action => (JsonNode?)DocsRequest(action, Of)).Where(request => request is not null).ToArray());
                    var json = requests.ToJsonString(ReadableJson);
                    lines.Add(("requests", json.Contains("\"={{", StringComparison.Ordinal) ? "=" + json.Replace("\"={{", "\"{{", StringComparison.Ordinal) : json));
                    if (requests.Count < actions.Count)
                    {
                        todo.Add("an action of it had no Docs request n8n could send - it is left out.");
                    }
                }

                var control = Find(p, "updateFields", "writeControlObject");
                if (control.ValueKind == JsonValueKind.Object && Text(control, "value") is { Length: > 0 } revision)
                {
                    lines.Add((Of(control, "control", "requiredRevisionId") == "targetRevisionId" ? "target_revision" : "required_revision", revision));
                }
            }

            Set(step, "Operation", operation);
            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(PerItem);
            todo.Add(GoogleDocsConnection);
        }

        private const string OdooConnection = "choose its connection - n8n's credentials stay in n8n: add an Odoo connection under Admin > Connections (the instance's address, a login and a password or an API key, and its database) and pick it here.";

        // n8n's Odoo create, get, get many, update and delete, of a contact (res.partner), an opportunity (crm.lead), a note
        // (note.note), an activity (mail.activity) or any model, as Extract from connection's operations: the model, a record's id,
        // n8n's filters as an Odoo domain (its operators Odoo's, an in list made a list), the fields read (n8n's list, or text), its
        // limit (50 when its export leaves it out), the fields written as a JSON object (its second version's mapped fields, its
        // first's name and value pairs, a contact's name, details and address, an opportunity's name, a note's memo). Values mapped
        // from the item by name, and an API key n8n used with Odoo 19's JSON-2 API, are said.
        private static void Odoo(JsonElement p, PipelineGraphStep step, Todo todo, string? operation)
        {
            operation ??= todo.Version >= 2 ? "records" : "create_record";
            Set(step, "Operation", operation);
            var resource = Text(p, "resource") is { Length: > 0 } named ? named : "contact";
            var lines = new List<(string Name, string Value)>
            {
                ("model", resource switch { "contact" => "res.partner", "opportunity" => "crm.lead", "note" => "note.note", "activity" => "mail.activity", _ => Locator(p, "customResource") }),
            };
            if (operation is "get_records" or "update_records" or "delete_records")
            {
                lines.Add(("ids", new[] { "recordId", "contactId", "opportunityId", "noteId", "activityId", "customResourceId" }.Select(name => Locator(p, name)).FirstOrDefault(id => id.Length > 0) ?? ""));
            }

            // The written values as a JSON object, an n8n expression among them making the parameters one.
            string Written(IEnumerable<(string Name, JsonElement Value)> pairs)
            {
                var list = pairs.Where(pair => pair.Name.Length > 0).ToList();
                var expression = list.Any(pair => pair.Value.ValueKind == JsonValueKind.String && (pair.Value.GetString() ?? "").StartsWith('='));
                var record = "{" + string.Join(", ", list.Select(pair => JsonSerializer.Serialize(pair.Name, ReadableJson) + ": "
                    + (pair.Value.ValueKind == JsonValueKind.String ? JsonSerializer.Serialize(Unmarked(pair.Value.GetString() ?? ""), ReadableJson) : pair.Value.GetRawText()))) + "}";
                return expression ? "=" + record : record;
            }

            IEnumerable<(string, JsonElement)> Object(JsonElement holder) =>
                holder.ValueKind == JsonValueKind.Object ? holder.EnumerateObject().Select(field => (field.Name, field.Value)) : Array.Empty<(string, JsonElement)>();

            switch (operation)
            {
                case "records":
                    var filters = Find(p, "filters", "filter") is { ValueKind: JsonValueKind.Array } v2 ? v2 : Find(p, "filterRequest", "filter");
                    if (filters.ValueKind == JsonValueKind.Array && filters.GetArrayLength() > 0)
                    {
                        var domain = new List<string>();
                        foreach (var filter in filters.EnumerateArray())
                        {
                            var op = Text(filter, "operator") switch
                            {
                                "" or "equal" => "=", "notEqual" => "!=", "greaterThen" => ">", "lesserThen" => "<", "greaterOrEqual" => ">=", "lesserOrEqual" => "<=",
                                "notIn" => "not in", "childOf" => "child_of", var other => other,
                            };
                            var value = Text(filter, "value");
                            var term = op is "in" or "not in"
                                ? "[" + string.Join(", ", value.Split(',').Select(part => part.Trim()).Select(part => double.TryParse(part, NumberStyles.Float, CultureInfo.InvariantCulture, out _) && part.Length > 0 ? part : JsonSerializer.Serialize(part, ReadableJson))) + "]"
                                : JsonSerializer.Serialize(Unmarked(value), ReadableJson);
                            domain.Add("[" + JsonSerializer.Serialize(Text(filter, "fieldName"), ReadableJson) + ", " + JsonSerializer.Serialize(op, ReadableJson) + ", " + term + "]");
                        }

                        var json = "[" + string.Join(", ", domain) + "]";
                        lines.Add(("domain", filters.EnumerateArray().Any(filter => Text(filter, "value").StartsWith('=')) ? "=" + json : json));
                    }

                    lines.Add(("fields", Joined(Find(p, "options"), "fieldsList")));
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "get_records":
                    lines.Add(("fields", Joined(Find(p, "options"), "fieldsList")));
                    break;
                case "create_record":
                case "update_records":
                    var mapped = Find(p, "fieldsToSend");
                    if (mapped.ValueKind == JsonValueKind.Object)
                    {
                        if (Text(mapped, "mappingMode") == "autoMapInputData")
                        {
                            todo.Add("it wrote the item's fields by name - here give the values to write in Parameters, 'values = {{ record }}'.");
                        }
                        else
                        {
                            lines.Add(("values", Written(Object(Find(mapped, "value")))));
                        }
                    }
                    else if (resource == "custom")
                    {
                        var pairs = Find(p, "fieldsToCreateOrUpdate", "fields");
                        lines.Add(("values", Written(pairs.ValueKind == JsonValueKind.Array
                            ? pairs.EnumerateArray().Select(pair => (Text(pair, "fieldName"), pair.TryGetProperty("fieldValue", out var value) ? value : default)).Where(pair => pair.Item2.ValueKind != JsonValueKind.Undefined)
                            : Array.Empty<(string, JsonElement)>())));
                    }
                    else
                    {
                        var first = new List<(string, JsonElement)>();
                        foreach (var (name, value) in new[] { ("contactName", "name"), ("opportunityName", "name"), ("memo", "memo") })
                        {
                            if (p.ValueKind == JsonValueKind.Object && p.TryGetProperty(name, out var given))
                            {
                                first.Add((value, given));
                            }
                        }

                        var fields = Find(p, operation == "create_record" ? "additionalFields" : "updateFields");
                        first.AddRange(Object(fields).Where(field => field.Item1 != "address"));
                        first.AddRange(Object(Find(fields, "address", "value")));
                        lines.Add(("values", Written(first)));
                    }

                    break;
            }

            if (todo.Version >= 2 && Text(p, "authentication") is "" or "odooApiKeyApi")
            {
                todo.Add("it called Odoo's JSON-2 API with an API key (Odoo 19 and later) - give the connection 'api = json2' and the key as its password.");
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "records" or "get_records" ? "n8n gave each record as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(OdooConnection);
        }

        private const string BrevoConnection = "choose its connection - n8n's credentials stay in n8n: add a Brevo connection under Admin > Connections (an API key) and pick it here.";

        // n8n's Brevo (Sendinblue) contact, attribute, e-mail and sender operations as Extract from connection's operations: a contact's
        // address or id and its attributes (n8n's name and value pairs made a JSON object), an e-mail's sender, recipients (its first
        // version's misspelling read too), copies, subject, text or HTML, tags, or a template and its parameters; an attribute's
        // category, name, type, value and options (n8n's value and label pairs as 1:Gold); n8n's limits (50 when its export leaves
        // them out). Attachments n8n sent are said.
        private static void Brevo(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var fields = Find(p, "additionalFields");
            List<JsonElement> Entries(JsonElement holder, params string[] path)
            {
                var found = Find(holder, path);
                return found.ValueKind == JsonValueKind.Array ? found.EnumerateArray().ToList() : found.ValueKind == JsonValueKind.Object ? new List<JsonElement> { found } : new List<JsonElement>();
            }

            string Pairs(List<JsonElement> pairs)
            {
                var named = pairs.Where(pair => Text(pair, "fieldName").Length > 0).ToList();
                if (named.Count == 0)
                {
                    return "";
                }

                var record = "{" + string.Join(", ", named.Select(pair => JsonSerializer.Serialize(Text(pair, "fieldName"), ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(Text(pair, "fieldValue")), ReadableJson))) + "}";
                return named.Any(pair => Text(pair, "fieldValue").StartsWith('=')) ? "=" + record : record;
            }

            string Options(List<JsonElement> options) => string.Join(", ", options.Select(option => (Text(option, "attributeCategoryValue") is { Length: > 0 } value ? value : "1") + ":" + Text(option, "attributeCategoryLabel")));
            string Either(JsonElement holder, string modern, string first) => Text(holder, modern) is { Length: > 0 } given ? given : Text(holder, first);

            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "send_email":
                    if (Text(p, "operation") == "sendTemplate")
                    {
                        lines.Add(("to", Either(p, "recipients", "receipients")));
                        lines.Add(("template_id", Text(p, "templateId")));
                        lines.Add(("params", Text(fields, "templateParameters", "parameterValues", "parameters")));
                    }
                    else
                    {
                        lines.Add(("sender", Text(p, "sender")));
                        lines.Add(("to", Either(p, "recipients", "receipients")));
                        lines.Add(("cc", Text(fields, "recipientsCC", "recipientCc") is { Length: > 0 } cc ? cc : Text(fields, "receipientsCC", "receipientCc")));
                        lines.Add(("bcc", Text(fields, "recipientsBCC", "recipientBcc") is { Length: > 0 } bcc ? bcc : Text(fields, "receipientsBCC", "receipientBcc")));
                        lines.Add(("subject", Text(p, "subject")));
                        lines.Add((Bool(p, "sendHTML") ? "html" : "text", Bool(p, "sendHTML") ? Text(p, "htmlContent") : Text(p, "textContent")));
                    }

                    lines.Add(("tags", Text(fields, "emailTags", "tags", "tag")));
                    if (Find(fields, "emailAttachments").ValueKind == JsonValueKind.Object)
                    {
                        todo.Add("it attached n8n's binary data - here an e-mail goes without attachments: link to the file instead.");
                    }

                    break;
                case "contacts":
                    lines.Add(("sort", Text(p, "options", "sort")));
                    lines.Add(("modified_since", Text(p, "filters", "modifiedSince")));
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "attributes":
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "get_contact":
                case "delete_contact":
                    lines.Add(("contact", Text(p, "identifier")));
                    break;
                case "create_contact":
                case "upsert_contact":
                    lines.Add(("email", Text(p, "email")));
                    lines.Add(("attributes", Pairs(operation == "create_contact" ? Entries(p, "createContactAttributes", "attributesValues") : Entries(p, "upsertAttributes", "upsertAttributesValues"))));
                    break;
                case "update_contact":
                    lines.Add(("contact", Text(p, "identifier")));
                    lines.Add(("attributes", Pairs(Entries(p, "updateAttributes", "updateAttributesValues"))));
                    break;
                case "create_attribute":
                    lines.Add(("category", Text(p, "attributeCategory")));
                    lines.Add(("name", Text(p, "attributeName")));
                    lines.Add(("type", Text(p, "attributeType")));
                    lines.Add(("value", Text(p, "attributeValue")));
                    lines.Add(("options", Options(Entries(p, "attributeCategoryList", "categoryEnumeration", "attributesValues"))));
                    break;
                case "update_attribute":
                    lines.Add(("category", Text(p, "updateAttributeCategory")));
                    lines.Add(("name", Text(p, "updateAttributeName")));
                    lines.Add(("value", Text(p, "updateAttributeValue")));
                    lines.Add(("options", Options(Entries(p, "updateAttributeCategoryList", "updateCategoryEnumeration", "updateAttributesValues"))));
                    break;
                case "delete_attribute":
                    lines.Add(("category", Text(p, "deleteAttributeCategory")));
                    lines.Add(("name", Text(p, "deleteAttributeName")));
                    break;
                case "create_sender":
                    lines.Add(("name", Text(p, "name")));
                    lines.Add(("email", Text(p, "email")));
                    break;
                case "delete_sender":
                    lines.Add(("sender_id", Text(p, "id")));
                    break;
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "contacts" or "attributes" or "senders" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(BrevoConnection);
        }

        private const string ActiveCampaignConnection = "choose its connection - n8n's credentials stay in n8n: add an ActiveCampaign connection under Admin > Connections (the account's API URL and an API key) and pick it here.";

        // n8n's ActiveCampaign operations as Extract from connection's operations: a contact's id, address, names, phone and custom
        // fields (n8n's field and value pairs made a JSON object), its Get Many filters (a status by its name, n8n's other filters as
        // ActiveCampaign's own); a list's and a tag's id; a deal's title, contact, value in cents, currency, pipeline, stage, owner,
        // description, probability and status (by its name), a note; an account's name, website and custom fields, an account
        // contact's job title; n8n's connection, e-commerce customer, order and order product operations as records of their
        // collection, their values a JSON object (a customer's consent to marketing ActiveCampaign's 1 or 0, an order's currency in
        // capitals). n8n's limits (100 when its export leaves them out).
        private static void ActiveCampaign(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var resource = Text(p, "resource") is { Length: > 0 } named ? named : "contact";
            var fields = Find(p, "additionalFields");
            var changes = Find(p, "updateFields");
            List<JsonElement> Entries(JsonElement holder, params string[] path)
            {
                var found = Find(holder, path);
                return found.ValueKind == JsonValueKind.Array ? found.EnumerateArray().ToList() : found.ValueKind == JsonValueKind.Object ? new List<JsonElement> { found } : new List<JsonElement>();
            }

            // n8n's pairs as a JSON object - an expression among them making the whole one.
            string Pairs(List<JsonElement> pairs, string key, string value)
            {
                var named = pairs.Where(pair => Text(pair, key).Length > 0).ToList();
                if (named.Count == 0)
                {
                    return "";
                }

                var record = "{" + string.Join(", ", named.Select(pair => JsonSerializer.Serialize(Unmarked(Text(pair, key)), ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(Text(pair, value)), ReadableJson))) + "}";
                return named.Any(pair => Text(pair, key).StartsWith('=') || Text(pair, value).StartsWith('=')) ? "=" + record : record;
            }

            // n8n's own parameters as a record's values, each as n8n held it - an expression among them making the whole one.
            string Record(IEnumerable<(string Name, JsonElement Value)> given)
            {
                var values = new JsonObject();
                var expression = false;
                foreach (var (name, value) in given)
                {
                    if (value.ValueKind is JsonValueKind.Undefined or JsonValueKind.Null || (value.ValueKind == JsonValueKind.String && value.GetString()!.Length == 0))
                    {
                        continue;
                    }

                    if (value.ValueKind == JsonValueKind.String && value.GetString()!.StartsWith('='))
                    {
                        expression = true;
                        values[name] = value.GetString()![1..];
                    }
                    else
                    {
                        values[name] = name == "acceptsMarketing" && value.ValueKind is JsonValueKind.True or JsonValueKind.False ? (value.ValueKind == JsonValueKind.True ? "1" : "0")
                            : name == "currency" && value.ValueKind == JsonValueKind.String ? value.GetString()!.ToUpperInvariant()
                            : JsonNode.Parse(value.GetRawText());
                    }
                }

                return values.Count == 0 ? "" : (expression ? "=" : "") + values.ToJsonString(ReadableJson);
            }

            IEnumerable<(string Name, JsonElement Value)> Own(JsonElement holder) =>
                holder.ValueKind == JsonValueKind.Object ? holder.EnumerateObject().Select(property => (property.Name, property.Value)) : Enumerable.Empty<(string, JsonElement)>();
            string Status(string given) => given switch { "-1" => "any", "0" => "unconfirmed", "1" => "active", "2" => "unsubscribed", "3" => "bounced", _ => given };
            string DealStatus(string given) => given switch { "0" => "open", "1" => "won", "2" => "lost", _ => given };
            var collection = resource switch { "connection" => "connections", "ecommerceCustomer" => "ecomCustomers", "ecommerceOrder" => "ecomOrders", _ => "ecomOrderProducts" };
            var recordId = resource switch { "connection" => Text(p, "connectionId"), "ecommerceCustomer" => Text(p, "ecommerceCustomerId"), "ecommerceOrder" => Text(p, "orderId"), _ => Text(p, "procuctId") };

            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "contacts":
                    {
                        lines.Add(("search", Text(fields, "search")));
                        lines.Add(("email", Text(fields, "email")));
                        lines.Add(("list", Text(fields, "listid")));
                        lines.Add(("tag", Text(fields, "tagid")));
                        lines.Add(("segment", Text(fields, "segmentid")));
                        lines.Add(("status", Status(Text(fields, "status"))));
                        lines.Add(("created_after", Text(fields, "filters[created_after]")));
                        lines.Add(("created_before", Text(fields, "filters[created_before]")));
                        lines.Add(("updated_after", Text(fields, "filters[updated_after]")));
                        lines.Add(("updated_before", Text(fields, "filters[updated_before]")));
                        lines.Add(("order", Text(fields, "orderBy") is { Length: > 0 } order ? order.Replace("orders[", "", StringComparison.Ordinal).TrimEnd(']') : ""));
                        var more = new[] { "datetime", "email_like", "exclude", "formid", "seriesid", "waitid" }.Where(name => Text(fields, name).Length > 0).ToList();
                        var query = string.Join(", ", more.Select(name => name + "=" + Unmarked(Text(fields, name))));
                        lines.Add(("query", more.Any(name => Text(fields, name).StartsWith('=')) ? "=" + query : query));
                        lines.Add(("max", Most(p, 100)));
                        break;
                    }

                case "lists":
                case "tags":
                case "deals":
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "accounts":
                    lines.Add(("search", Text(p, "filters", "search")));
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "get_contact":
                case "delete_contact":
                    lines.Add(("contact", Text(p, "contactId")));
                    break;
                case "create_contact":
                case "sync_contact":
                case "update_contact":
                    {
                        var given = operation == "update_contact" ? changes : fields;
                        lines.Add(("contact", operation == "update_contact" ? Text(p, "contactId") : ""));
                        lines.Add(("email", operation == "update_contact" ? Text(changes, "email") : Text(p, "email")));
                        lines.Add(("first_name", Text(given, "firstName")));
                        lines.Add(("last_name", Text(given, "lastName")));
                        lines.Add(("phone", Text(given, "phone")));
                        lines.Add(("fields", Pairs(Entries(given, "fieldValues", "property"), "field", "value")));
                        break;
                    }

                case "add_to_list":
                case "remove_from_list":
                    lines.Add(("contact", Text(p, "contactId")));
                    lines.Add(("list", Text(p, "listId")));
                    break;
                case "add_tag":
                    lines.Add(("contact", Text(p, "contactId")));
                    lines.Add(("tag", Text(p, "tagId")));
                    break;
                case "remove_tag":
                    lines.Add(("contact_tag", Text(p, "contactTagId")));
                    break;
                case "get_tag":
                case "delete_tag":
                    lines.Add(("tag", Text(p, "tagId")));
                    break;
                case "create_tag":
                    lines.Add(("name", Text(p, "name")));
                    lines.Add(("type", Text(p, "tagType")));
                    lines.Add(("description", Text(fields, "description")));
                    break;
                case "update_tag":
                    lines.Add(("tag", Text(p, "tagId")));
                    lines.Add(("name", Text(changes, "tag")));
                    lines.Add(("description", Text(changes, "description")));
                    break;
                case "get_deal":
                case "delete_deal":
                    lines.Add(("deal", Text(p, "dealId")));
                    break;
                case "create_deal":
                case "update_deal":
                    {
                        var given = operation == "update_deal" ? changes : p;
                        var more = operation == "update_deal" ? changes : fields;
                        lines.Add(("deal", operation == "update_deal" ? Text(p, "dealId") : ""));
                        lines.Add(("title", Text(given, "title")));
                        lines.Add(("contact", Text(given, "contact")));
                        lines.Add(("value", Text(given, "value")));
                        lines.Add(("currency", Text(given, "currency") is { Length: > 0 } currency ? currency : operation == "create_deal" ? "eur" : "")); // n8n's default
                        lines.Add(("pipeline", Text(given, "group")));
                        lines.Add(("stage", Text(given, "stage")));
                        lines.Add(("owner", Text(given, "owner")));
                        lines.Add(("description", Text(more, "description")));
                        lines.Add(("percent", Text(more, "percent")));
                        lines.Add(("status", DealStatus(Text(more, "status"))));
                        break;
                    }

                case "add_deal_note":
                case "update_deal_note":
                    lines.Add(("deal", Text(p, "dealId")));
                    lines.Add(("note_id", operation == "update_deal_note" ? Text(p, "dealNoteId") : ""));
                    lines.Add(("note", Text(p, "dealNote")));
                    break;
                case "get_account":
                case "delete_account":
                    lines.Add(("account", Text(p, "accountId")));
                    break;
                case "create_account":
                case "update_account":
                    {
                        var given = operation == "update_account" ? changes : fields;
                        lines.Add(("account", operation == "update_account" ? Text(p, "accountId") : ""));
                        lines.Add(("name", operation == "update_account" ? Text(changes, "name") : Text(p, "name")));
                        lines.Add(("url", Text(given, "accountUrl")));
                        lines.Add(("fields", Pairs(Entries(given, "fields", "property"), "customFieldId", "fieldValue")));
                        break;
                    }

                case "add_account_contact":
                    lines.Add(("account", Text(p, "account")));
                    lines.Add(("contact", Text(p, "contact")));
                    lines.Add(("job_title", Text(fields, "jobTitle")));
                    break;
                case "update_account_contact":
                case "remove_account_contact":
                    lines.Add(("account_contact", Text(p, "accountContactId")));
                    lines.Add(("job_title", operation == "update_account_contact" ? Text(changes, "jobTitle") : ""));
                    break;
                case "records":
                    {
                        var order = Text(p, "orderId");
                        lines.Add(("resource", Text(p, "operation") != "getByOrderId" ? collection : order.StartsWith('=') ? "=ecomOrders/" + order[1..] + "/orderProducts" : "ecomOrders/" + order + "/orderProducts"));
                        lines.Add(("max", Most(p, 100)));
                        break;
                    }

                case "get_record":
                case "delete_record":
                    lines.Add(("resource", collection));
                    lines.Add(("id", recordId));
                    break;
                case "create_record":
                    {
                        var names = resource switch
                        {
                            "connection" => new[] { "service", "externalid", "name", "logoUrl", "linkUrl" },
                            "ecommerceCustomer" => new[] { "connectionid", "externalid", "email" },
                            _ => new[] { "externalid", "externalcheckoutid", "source", "email", "totalPrice", "currency", "connectionid", "customerid", "externalCreatedDate", "abandonedDate", "orderProducts" },
                        };
                        lines.Add(("resource", collection));
                        // n8n's defaults where its export leaves them out: an order's source, total and currency.
                        JsonElement Given(string name) => Find(p, name).ValueKind != JsonValueKind.Undefined || resource != "ecommerceOrder" ? Find(p, name)
                            : name switch { "source" or "totalPrice" => JsonSerializer.SerializeToElement(0), "currency" => JsonSerializer.SerializeToElement("eur"), _ => Find(p, name) };
                        lines.Add(("values", Record(names.Select(name => (name, Given(name))).Concat(Own(fields)))));
                        break;
                    }

                case "update_record":
                    lines.Add(("resource", collection));
                    lines.Add(("id", recordId));
                    lines.Add(("values", Record(Own(changes))));
                    break;
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "contacts" or "lists" or "tags" or "deals" or "accounts" or "records" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(ActiveCampaignConnection);
        }

        private const string ZohoCrmConnection = "choose its connection - n8n's credentials stay in n8n: add a Zoho CRM connection under Admin > Connections (an OAuth client's id and secret, a refresh token, and your data centre's token endpoint and API address) and pick it here.";

        // n8n's Zoho CRM operations as Extract from connection's: each resource its module (an account the default); a record's
        // values a JSON object of Zoho's API names - the node's required fields by theirs, its additional fields as n8n names them
        // (by API name already), an address's fields at the top, custom fields by their API names, a date its day, an account, a
        // contact, a deal or a vendor by id as Zoho's lookup, product lines as Zoho's ({"product": {"id": ...}, "quantity": 1}); an
        // expression among them making the whole one. Its Get Many's fields, order and Zoho's own options; n8n's limit (5 when its
        // export leaves it out).
        private static void ZohoCrm(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var resource = Text(p, "resource") is { Length: > 0 } named ? named : "account";
            var (module, idName) = resource switch
            {
                "contact" => ("Contacts", "contactId"),
                "deal" => ("Deals", "dealId"),
                "invoice" => ("Invoices", "invoiceId"),
                "lead" => ("Leads", "leadId"),
                "product" => ("Products", "productId"),
                "purchaseOrder" => ("Purchase_Orders", "purchaseOrderId"),
                "quote" => ("Quotes", "quoteId"),
                "salesOrder" => ("Sales_Orders", "salesOrderId"),
                "vendor" => ("Vendors", "vendorId"),
                _ => ("Accounts", "accountId"),
            };
            var expression = false;
            bool Given(JsonElement value) => value.ValueKind is not (JsonValueKind.Undefined or JsonValueKind.Null) && !(value.ValueKind == JsonValueKind.String && value.GetString()!.Length == 0);
            JsonNode? Node(JsonElement value)
            {
                if (value.ValueKind == JsonValueKind.String && value.GetString()!.StartsWith('='))
                {
                    expression = true;
                    return JsonValue.Create(value.GetString()![1..]);
                }

                return JsonNode.Parse(value.GetRawText());
            }

            List<JsonElement> Entries(JsonElement holder, string name)
            {
                var found = Find(holder, name);
                return found.ValueKind == JsonValueKind.Array ? found.EnumerateArray().ToList() : found.ValueKind == JsonValueKind.Object ? new List<JsonElement> { found } : new List<JsonElement>();
            }

            // A product line as Zoho takes it: the product by id, its quantity (1 when n8n gave none), the rest as given.
            JsonArray Products(JsonElement lines)
            {
                var products = new JsonArray();
                foreach (var line in lines.ValueKind == JsonValueKind.Array ? lines.EnumerateArray() : Enumerable.Empty<JsonElement>())
                {
                    var product = new JsonObject { ["product"] = new JsonObject { ["id"] = Node(Find(line, "id")) }, ["quantity"] = Given(Find(line, "quantity")) ? Node(Find(line, "quantity")) : 1 };
                    foreach (var part in line.ValueKind == JsonValueKind.Object ? line.EnumerateObject() : default)
                    {
                        if (part.Name is not ("id" or "quantity" or "product") && Given(part.Value))
                        {
                            product[part.Name] = Node(part.Value);
                        }
                    }

                    products.Add(product);
                }

                return products;
            }

            void Put(JsonObject values, string name, JsonElement value)
            {
                if (!Given(value))
                {
                    return;
                }

                switch (name)
                {
                    case "Billing_Address" or "Shipping_Address" or "Mailing_Address" or "Other_Address" or "Address":
                        var parts = Find(value, "address_fields");
                        foreach (var part in parts.ValueKind == JsonValueKind.Object ? parts.EnumerateObject() : default)
                        {
                            Put(values, part.Name, part.Value);
                        }

                        break;
                    case "customFields":
                        foreach (var field in Entries(value, "customFields"))
                        {
                            if (Text(field, "fieldId") is { Length: > 0 } id)
                            {
                                values[Unmarked(id)] = Node(Find(field, "value"));
                            }
                        }

                        break;
                    case "Date_of_Birth" or "Closing_Date" or "Invoice_Date" or "Due_Date" or "PO_Date" or "Valid_Till" when value.ValueKind == JsonValueKind.String && !value.GetString()!.StartsWith('='):
                        values[name] = value.GetString()!.Split('T')[0]; // the day: n8n's date picker adds a time
                        break;
                    case "accountId" or "contactId" or "dealId" or "vendorId":
                        values[name switch { "accountId" => "Account_Name", "contactId" => "Full_Name", "dealId" => "Deal_Name", _ => "Vendor_Name" }] = new JsonObject { ["id"] = Node(value) };
                        break;
                    case "Product_Details":
                        values[name] = Products(value);
                        break;
                    default:
                        values[name] = Node(value);
                        break;
                }
            }

            string Values(JsonObject values) => values.Count == 0 ? "" : (expression ? "=" : "") + values.ToJsonString(ReadableJson);

            var lines = new List<(string Name, string Value)> { ("module", module) };
            switch (operation)
            {
                case "records":
                    {
                        var options = Find(p, "options");
                        var fields = Find(options, "fields");
                        lines.Add(("fields", fields.ValueKind == JsonValueKind.Array ? string.Join(", ", fields.EnumerateArray().Select(field => field.GetString())) : Text(options, "fields")));
                        lines.Add(("order", Text(options, "sort_by") is { Length: > 0 } sort ? sort + (Text(options, "sort_order") is { Length: > 0 } direction ? " " + direction : "") : ""));
                        lines.Add(("query", string.Join(", ", new[] { "approved", "converted", "include_child", "territory_id" }.Where(name => Text(options, name).Length > 0).Select(name => name + "=" + Text(options, name)))));
                        lines.Add(("max", Most(p, 5)));
                        break;
                    }

                case "get_record":
                case "delete_record":
                    lines.Add(("id", Text(p, idName)));
                    break;
                case "create_record":
                case "upsert_record":
                    {
                        var values = new JsonObject();
                        var required = resource switch
                        {
                            "contact" => new[] { ("lastName", "Last_Name") },
                            "deal" => new[] { ("dealName", "Deal_Name"), ("stage", "Stage") },
                            "invoice" or "quote" => new[] { ("subject", "Subject"), ("Product_Details", "Product_Details") },
                            "lead" => new[] { ("Company", "Company"), ("lastName", "Last_Name") },
                            "product" => new[] { ("productName", "Product_Name") },
                            "purchaseOrder" => new[] { ("subject", "Subject"), ("vendorId", "vendorId"), ("Product_Details", "Product_Details") },
                            "salesOrder" => new[] { ("accountId", "accountId"), ("subject", "Subject"), ("Product_Details", "Product_Details") },
                            "vendor" => new[] { ("vendorName", "Vendor_Name") },
                            _ => new[] { ("accountName", "Account_Name") },
                        };
                        foreach (var (parameter, apiName) in required)
                        {
                            Put(values, apiName, Find(p, parameter));
                        }

                        var more = Find(p, "additionalFields");
                        foreach (var field in more.ValueKind == JsonValueKind.Object ? more.EnumerateObject() : default)
                        {
                            Put(values, field.Name, field.Value);
                        }

                        lines.Add(("values", Values(values)));
                        break;
                    }

                case "update_record":
                    {
                        var values = new JsonObject();
                        var changes = Find(p, "updateFields");
                        foreach (var field in changes.ValueKind == JsonValueKind.Object ? changes.EnumerateObject() : default)
                        {
                            Put(values, field.Name, field.Value);
                        }

                        lines.Add(("id", Text(p, idName)));
                        lines.Add(("values", Values(values)));
                        break;
                    }
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "records" or "fields" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(ZohoCrmConnection);
        }

        private const string IntercomConnection = "choose its connection - n8n's credentials stay in n8n: add an Intercom connection under Admin > Connections (an access token, and your region's API address) and pick it here.";

        // n8n's Intercom user, lead and company operations as Extract from connection's, on Intercom's API 2.x: a user or a lead a
        // contact of that role - by its id, its address, or its user id as its external id; its name, phone, address and whether
        // unsubscribed, its custom attributes a JSON object (n8n's pairs, or its JSON); a lead got by its phone a search; a company
        // by its id, its company id or its name, made or updated by its company id; n8n's limits (50 when its export leaves them
        // out). What Intercom 2.x keeps elsewhere - a contact's companies, avatar, session count, last request and UTM fields, and
        // n8n's company filters - is said.
        private static void Intercom(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var resource = Text(p, "resource") is { Length: > 0 } named ? named : "user";
            var fields = Find(p, "additionalFields");
            string Contact(string by, string value) => value.Length == 0 ? "" : by == "userId" ? (value.StartsWith('=') ? "=external:" + value[1..] : "external:" + value) : value;
            string Company(string by, string value) => value.Length == 0 ? "" : by is "companyId" or "name" ? (value.StartsWith('=') ? "=" : "") + (by == "companyId" ? "company:" : "name:") + Unmarked(value) : value;
            string Custom()
            {
                if (Bool(p, "jsonParameters"))
                {
                    return Text(p, "customAttributesJson");
                }

                var found = Find(p, "customAttributesUi", "customAttributesValues");
                var pairs = (found.ValueKind == JsonValueKind.Array ? found.EnumerateArray().ToList() : found.ValueKind == JsonValueKind.Object ? new List<JsonElement> { found } : new List<JsonElement>())
                    .Where(pair => Text(pair, "name").Length > 0).ToList();
                if (pairs.Count == 0)
                {
                    return "";
                }

                var record = "{" + string.Join(", ", pairs.Select(pair => JsonSerializer.Serialize(Unmarked(Text(pair, "name")), ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(Text(pair, "value")), ReadableJson))) + "}";
                return pairs.Any(pair => Text(pair, "name").StartsWith('=') || Text(pair, "value").StartsWith('=')) ? "=" + record : record;
            }

            // Search conditions as Intercom's query: one alone, several all of them.
            string Query(List<(string Field, string Value)> conditions)
            {
                if (conditions.Count == 0)
                {
                    return "";
                }

                var each = conditions.Select(condition => "{\"field\": " + JsonSerializer.Serialize(condition.Field, ReadableJson) + ", \"operator\": \"=\", \"value\": " + JsonSerializer.Serialize(Unmarked(condition.Value), ReadableJson) + "}").ToList();
                var query = each.Count == 1 ? each[0] : "{\"operator\": \"AND\", \"value\": [" + string.Join(", ", each) + "]}";
                return conditions.Any(condition => condition.Value.StartsWith('=')) ? "=" + query : query;
            }

            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "create_contact":
                case "update_contact":
                    if (operation == "update_contact")
                    {
                        lines.Add(("contact", Contact(Text(p, "updateBy") is { Length: > 0 } by ? by : "id", Text(p, "value"))));
                    }
                    else if (resource == "lead")
                    {
                        lines.Add(("role", "lead"));
                    }

                    lines.Add(("email", operation == "create_contact" ? resource == "lead" ? Text(p, "email") : Text(p, "identifierType") == "email" ? Text(p, "idValue") : "" : Text(fields, "email")));
                    lines.Add(("external_id", operation == "create_contact" ? resource == "user" && Text(p, "identifierType") == "userId" ? Text(p, "idValue") : "" : Text(fields, "userId")));
                    lines.Add(("name", Text(fields, "name")));
                    lines.Add(("phone", Text(fields, "phone")));
                    lines.Add(("unsubscribed_from_emails", Text(fields, "unsubscribedFromEmails")));
                    lines.Add(("custom_attributes", Custom()));
                    var elsewhere = new[] { "companies", "avatar", "sessionCount", "updateLastRequestAt", "utmSource", "utmMedium", "utmCampaign", "utmTerm", "utmContent" }.Where(name => Find(fields, name).ValueKind is not (JsonValueKind.Undefined or JsonValueKind.Null)).ToList();
                    if (elsewhere.Count > 0)
                    {
                        todo.Add($"it set {string.Join(", ", elsewhere)} - Intercom's API keeps a contact's companies by attaching them (Add a contact to a company) and has no place for the rest: left out.");
                    }

                    break;
                case "get_contact":
                    lines.Add(("contact", Contact(Text(p, "selectBy") is { Length: > 0 } select ? select : "id", Text(p, "value"))));
                    break;
                case "delete_contact":
                    lines.Add(("contact", resource == "user" ? Text(p, "id") : Contact(Text(p, "deleteBy") is { Length: > 0 } deleteBy ? deleteBy : "id", Text(p, "value"))));
                    break;
                case "contacts":
                    {
                        lines.Add(("role", resource));
                        var conditions = new List<(string Field, string Value)>();
                        if (Text(p, "operation") == "get")
                        {
                            conditions.Add(("phone", Text(p, "value")));
                            lines.Add(("query", Query(conditions)));
                            lines.Add(("max", "1"));
                            break;
                        }

                        var filters = Find(p, "filters");
                        lines.Add(("email", Text(filters, "email")));
                        foreach (var name in new[] { "phone", "tag_id", "segment_id" })
                        {
                            if (Text(filters, name) is { Length: > 0 } value)
                            {
                                conditions.Add((name, value));
                            }
                        }

                        lines.Add(("query", Query(conditions)));
                        lines.Add(("max", Most(p, 50)));
                        if (Text(filters, "company_id").Length > 0)
                        {
                            todo.Add("it read a company's users - here read them with Get a company's contacts.");
                        }

                        break;
                    }

                case "upsert_company":
                    lines.Add(("company_id", Text(p, "companyId")));
                    lines.Add(("name", Text(fields, "name")));
                    lines.Add(("plan", Text(fields, "plan")));
                    lines.Add(("size", Text(fields, "size")));
                    lines.Add(("website", Text(fields, "website")));
                    lines.Add(("industry", Text(fields, "industry")));
                    lines.Add(("monthly_spend", Text(fields, "monthlySpend")));
                    lines.Add(("custom_attributes", Custom()));
                    break;
                case "get_company":
                    lines.Add(("company", Company(Text(p, "selectBy"), Text(p, "value"))));
                    break;
                case "companies":
                    lines.Add(("max", Most(p, 50)));
                    if (Find(p, "filters", "segment_id").ValueKind != JsonValueKind.Undefined || Find(p, "filters", "tag_id").ValueKind != JsonValueKind.Undefined)
                    {
                        todo.Add("it kept a segment's or a tag's companies - here read them all and keep those with Filter records.");
                    }

                    break;
                case "company_contacts":
                    lines.Add(("company", Company(Text(p, "listBy"), Text(p, "value"))));
                    lines.Add(("max", Most(p, 50)));
                    break;
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "contacts" or "companies" or "company_contacts" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(IntercomConnection);
        }

        private const string ZoomConnection = "choose its connection - n8n's credentials stay in n8n: add a Zoom connection under Admin > Connections (a server-to-server OAuth app's account id, client id and client secret) and pick it here.";

        // n8n's Zoom meeting operations as Extract from connection's: a meeting's id; its topic, kind (n8n's number by its name),
        // start, duration, time zone, passcode, agenda, whom it is for and settings (n8n's names as Zoom's, a JSON object); n8n's
        // Get Many kind (live when its export leaves it out) and its limit (30 when its export leaves it out); an occurrence and
        // the reminder mail. A start n8n read in the workflow's time zone is said.
        private static void Zoom(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var given = operation == "update_meeting" ? Find(p, "updateFields") : Find(p, "additionalFields");
            string Kind(string value) => value switch { "1" => "instant", "2" => "scheduled", "3" => "recurring", "8" => "recurring_fixed", _ => value };

            // n8n's settings by Zoom's names, a JSON object - an expression among them making the whole one.
            string Settings(JsonElement settings)
            {
                if (settings.ValueKind != JsonValueKind.Object)
                {
                    return "";
                }

                var values = new JsonObject();
                var expression = false;
                foreach (var setting in settings.EnumerateObject())
                {
                    var name = setting.Name switch
                    {
                        "autoRecording" => "auto_recording",
                        "alternativeHosts" => "alternative_hosts",
                        "cnMeeting" => "cn_meeting",
                        "inMeeting" => "in_meeting",
                        "hostVideo" => "host_video",
                        "joinBeforeHost" => "join_before_host",
                        "muteUponEntry" => "mute_upon_entry",
                        "participantVideo" => "participant_video",
                        "registrationType" => "registration_type",
                        var other => other,
                    };
                    if (setting.Value.ValueKind == JsonValueKind.String && setting.Value.GetString()!.StartsWith('='))
                    {
                        expression = true;
                        values[name] = setting.Value.GetString()![1..];
                    }
                    else
                    {
                        values[name] = JsonNode.Parse(setting.Value.GetRawText());
                    }
                }

                return values.Count == 0 ? "" : (expression ? "=" : "") + values.ToJsonString(ReadableJson);
            }

            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "meetings":
                    lines.Add(("type", Text(p, "filters", "type") is { Length: > 0 } type ? type : "live"));
                    lines.Add(("max", Most(p, 30)));
                    break;
                case "get_meeting":
                case "delete_meeting":
                    lines.Add(("meeting", Text(p, "meetingId")));
                    lines.Add(("occurrence_id", Text(given, "occurrenceId")));
                    lines.Add(operation == "get_meeting" ? ("show_previous_occurrences", Text(given, "showPreviousOccurrences")) : ("schedule_for_reminder", Text(given, "scheduleForReminder")));
                    break;
                case "create_meeting":
                case "update_meeting":
                    lines.Add(("meeting", operation == "update_meeting" ? Text(p, "meetingId") : ""));
                    lines.Add(("topic", operation == "update_meeting" ? Text(given, "topic") : Text(p, "topic")));
                    lines.Add(("type", Kind(Text(given, "type"))));
                    lines.Add(("start_time", Text(given, "startTime")));
                    lines.Add(("duration", Text(given, "duration")));
                    lines.Add(("timezone", Text(given, "timeZone")));
                    lines.Add(("password", Text(given, "password")));
                    lines.Add(("agenda", Text(given, "agenda")));
                    lines.Add(("schedule_for", Text(given, "scheduleFor")));
                    lines.Add(("settings", Settings(Find(given, "settings"))));
                    if (Text(given, "startTime").Length > 0 && Text(given, "timeZone").Length == 0)
                    {
                        todo.Add("it read its start in the workflow's time zone - here a start without an offset is UTC: give its offset, or the meeting's time zone.");
                    }

                    break;
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation == "meetings" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(ZoomConnection);
        }

        private const string MailgunConnection = "choose its connection - n8n's credentials stay in n8n: add a Mailgun connection under Admin > Connections (an API key, the sending domain, and the EU endpoint when the domain is there) and pick it here.";

        // n8n's Mailgun e-mail as Extract from connection's send_email: its sender, recipients, copies, reply-to, subject, text and
        // HTML, tags, and its own headers (n8n's name and value pairs made a JSON object - an expression among them making the whole
        // one). Attachments n8n sent are said.
        private static void Mailgun(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var found = Find(p, "customHeaders", "headers");
            var pairs = (found.ValueKind == JsonValueKind.Array ? found.EnumerateArray().ToList() : found.ValueKind == JsonValueKind.Object ? new List<JsonElement> { found } : new List<JsonElement>())
                .Where(pair => Text(pair, "name").Length > 0).ToList();
            var headers = pairs.Count == 0 ? "" : "{" + string.Join(", ", pairs.Select(pair => JsonSerializer.Serialize(Unmarked(Text(pair, "name")).Trim(), ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(Text(pair, "value")), ReadableJson))) + "}";
            if (pairs.Any(pair => Text(pair, "name").StartsWith('=') || Text(pair, "value").StartsWith('=')))
            {
                headers = "=" + headers;
            }

            var lines = new List<(string Name, string Value)>
            {
                ("from", Text(p, "fromEmail")),
                ("to", Text(p, "toEmail")),
                ("cc", Text(p, "ccEmail")),
                ("bcc", Text(p, "bccEmail")),
                ("reply_to", Text(p, "replyTo")),
                ("subject", Text(p, "subject")),
                ("text", Text(p, "text")),
                ("html", Text(p, "html")),
                ("tags", Text(p, "tags")),
                ("headers", headers),
            };
            if (Text(p, "attachments").Length > 0)
            {
                todo.Add("it attached n8n's binary data - here an e-mail goes without attachments: link to the file instead.");
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(PerItem);
            todo.Add(MailgunConnection);
        }

        private const string WebflowConnection = "choose its connection - n8n's credentials stay in n8n: add a Webflow connection under Admin > Connections (a site's or a workspace's API token) and pick it here.";

        // n8n's Webflow item operations as Extract from connection's: the collection and the item by their ids (n8n's site only
        // chose the collection); a create's or an update's fields - n8n's field and value pairs by their slugs made a JSON object, an
        // expression among them making the whole one - and whether live; Get Many's limit (100 when its export leaves it out).
        private static void Webflow(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var pairs = Items(p, "fieldsUi", "fieldValues").Where(pair => Text(pair, "fieldId").Length > 0).ToList();
            var fields = pairs.Count == 0 ? "" : "{" + string.Join(", ", pairs.Select(pair => JsonSerializer.Serialize(Unmarked(Text(pair, "fieldId")).Trim(), ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(Text(pair, "fieldValue")), ReadableJson))) + "}";
            if (pairs.Any(pair => Text(pair, "fieldId").StartsWith('=') || Text(pair, "fieldValue").StartsWith('=')))
            {
                fields = "=" + fields;
            }

            var live = Text(p, "live");
            var lines = new List<(string Name, string Value)> { ("collection", Text(p, "collectionId")) };
            switch (operation)
            {
                case "items":
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "create_item":
                case "update_item":
                    lines.Add(("item", operation == "update_item" ? Text(p, "itemId") : ""));
                    lines.Add(("fields", fields));
                    lines.Add(("live", live == "true" || live.StartsWith('=') ? live : ""));
                    break;
                default:
                    lines.Add(("item", Text(p, "itemId")));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation == "items" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(WebflowConnection);
        }

        private const string YouTubeConnection = "choose its connection - n8n's credentials stay in n8n: add a YouTube connection under Admin > Connections (an OAuth client's id and secret and a refresh token granted YouTube's scope) and pick it here.";

        // n8n's YouTube operations as Extract from connection's: a channel's, a playlist's, a playlist item's and a video's ids; its
        // Get Many filters by this connector's names (a channel's ids and user name; a playlist's channel and ids; a search's words,
        // channel, category, region, times, order and safe search - the account's own videos only when it gave no filter) and its
        // limit (25 when its export leaves it out); a channel's description, keywords, country, language and trailer; a playlist's
        // or a video's title, description, tags, language, privacy and status; a playlist item's position and note; a rating. What
        // has no input here - a content owner, a channel's other branding, a video's start and end in a playlist, its recording
        // date, n8n's other search filters - is said.
        private static void YouTube(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var filters = Find(p, "filters");
            var options = Find(p, "options");
            var fields = operation is "update_playlist" or "update_video" ? Find(p, "updateFields") : options;
            var branding = Find(p, "updateFields", "brandingSettingsUi", "channelSettingsValues", "channel");
            var unsaid = new List<string>();
            void Unsaid(JsonElement from, params string[] names) => unsaid.AddRange(names.Where(name => Text(from, name) is { Length: > 0 } given && given != "false"));
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "channels":
                    lines.Add(("id", Text(filters, "id")));
                    lines.Add(("username", Text(filters, "forUsername")));
                    lines.Add(("max", Most(p, 25)));
                    Unsaid(filters, "categoryId", "managedByMe");
                    break;
                case "get_channel":
                    lines.Add(("channel", Text(p, "channelId")));
                    break;
                case "update_channel":
                    lines.Add(("channel", Text(p, "channelId")));
                    lines.Add(("description", Text(branding, "description")));
                    lines.Add(("keywords", Text(branding, "keywords")));
                    lines.Add(("country", Text(branding, "country")));
                    lines.Add(("default_language", Text(branding, "defaultLanguage")));
                    lines.Add(("trailer", Text(branding, "unsubscribedTrailer")));
                    Unsaid(branding, "defaultTab", "featuredChannelsTitle", "featuredChannelsUrls", "moderateComments", "profileColor", "showRelatedChannels", "showBrowseView", "trackingAnalyticsAccountId");
                    Unsaid(Find(p, "updateFields", "brandingSettingsUi"), "imageSettingsValues", "statusValue");
                    Unsaid(Find(p, "updateFields"), "onBehalfOfContentOwner");
                    break;
                case "playlists":
                    lines.Add(("channel", Text(filters, "channelId")));
                    lines.Add(("id", Text(filters, "id")));
                    lines.Add(("max", Most(p, 25)));
                    break;
                case "get_playlist":
                case "delete_playlist":
                    lines.Add(("playlist", Text(p, "playlistId")));
                    break;
                case "create_playlist":
                case "update_playlist":
                    lines.Add(("playlist", operation == "update_playlist" ? Text(p, "playlistId") : ""));
                    lines.Add(("title", Text(p, "title")));
                    lines.Add(("description", Text(fields, "description")));
                    lines.Add(("privacy", Text(fields, "privacyStatus")));
                    lines.Add(("tags", Text(fields, "tags")));
                    lines.Add(("default_language", Text(fields, "defaultLanguage")));
                    Unsaid(fields, "onBehalfOfContentOwner", "onBehalfOfContentOwnerChannel");
                    break;
                case "playlist_items":
                    lines.Add(("playlist", Text(p, "playlistId")));
                    lines.Add(("max", Most(p, 25)));
                    break;
                case "get_playlist_item":
                case "delete_playlist_item":
                    lines.Add(("item", Text(p, "playlistItemId")));
                    break;
                case "add_playlist_item":
                    lines.Add(("playlist", Text(p, "playlistId")));
                    lines.Add(("video", Text(p, "videoId")));
                    lines.Add(("position", Text(options, "position")));
                    lines.Add(("note", Text(options, "note")));
                    Unsaid(options, "startAt", "endAt", "onBehalfOfContentOwner");
                    break;
                case "videos":
                    {
                        lines.Add(("query", Text(filters, "q")));
                        lines.Add(("channel", Text(filters, "channelId")));
                        lines.Add(("category", Text(filters, "videoCategoryId")));
                        lines.Add(("region", Text(filters, "regionCode")));
                        lines.Add(("published_after", Text(filters, "publishedAfter")));
                        lines.Add(("published_before", Text(filters, "publishedBefore")));
                        lines.Add(("order", Text(options, "order")));
                        lines.Add(("safe_search", Text(options, "safeSearch")));
                        // n8n's search is the account's own only with no filter at all; this connector's, with no words, channel,
                        // category or region.
                        var filtered = filters.ValueKind == JsonValueKind.Object && filters.EnumerateObject().Any(filter => Text(filters, filter.Name) is { Length: > 0 } given && given != "false");
                        if (filtered && lines.Take(4).All(line => line.Value.Length == 0))
                        {
                            lines.Add(("mine", "false"));
                        }

                        lines.Add(("max", Most(p, 25)));
                        Unsaid(filters, "forDeveloper", "relatedToVideoId", "videoSyndicated", "videoType");
                        break;
                    }

                case "get_video":
                case "delete_video":
                    lines.Add(("video", Text(p, "videoId")));
                    break;
                case "update_video":
                    lines.Add(("video", Text(p, "videoId")));
                    lines.Add(("title", Text(p, "title")));
                    lines.Add(("description", Text(fields, "description")));
                    lines.Add(("tags", Text(fields, "tags")));
                    lines.Add(("category", Text(p, "categoryId")));
                    lines.Add(("privacy", Text(fields, "privacyStatus")));
                    lines.Add(("publish_at", Text(fields, "publishAt")));
                    lines.Add(("embeddable", Text(fields, "embeddable")));
                    lines.Add(("public_stats", Text(fields, "publicStatsViewable")));
                    lines.Add(("made_for_kids", Text(fields, "selfDeclaredMadeForKids")));
                    lines.Add(("license", Text(fields, "license")));
                    lines.Add(("default_language", Text(fields, "defaultLanguage")));
                    Unsaid(fields, "recordingDate", "notifySubscribers");
                    break;
                case "rate_video":
                    lines.Add(("video", Text(p, "videoId")));
                    lines.Add(("rating", Text(p, "rating")));
                    break;
                default:
                    lines.Add(("region", Text(p, "regionCode")));
                    lines.Add(("max", Most(p, 25)));
                    break;
            }

            Unsaid(operation is "update_playlist" or "update_video" ? fields : options, "onBehalfOfContentOwner");
            if (unsaid.Count > 0)
            {
                todo.Add($"n8n's {string.Join(", ", unsaid.Distinct(StringComparer.Ordinal))} {(unsaid.Distinct(StringComparer.Ordinal).Count() == 1 ? "has" : "have")} no input here - left out.");
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "channels" or "playlists" or "playlist_items" or "videos" or "video_categories" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(YouTubeConnection);
        }

        private const string LinkedInConnection = "choose its connection - n8n's credentials stay in n8n: add a LinkedIn connection under Admin > Connections (a member's access token granted w_member_social - and openid to post as the member) and pick it here.";

        // n8n's LinkedIn post as Extract from connection's create_post: as the person n8n chose or an organization (each its id
        // made the author's URN), its text, a person's visibility, an article's address, title and description. An image n8n
        // uploaded and an article's thumbnail - its binary data - are said.
        private static void LinkedIn(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var fields = Find(p, "additionalFields");
            var organization = Text(p, "postAs") == "organization";
            var who = Text(p, organization ? "organization" : "person");
            var id = Unmarked(who).Replace("urn:li:organization:", "", StringComparison.Ordinal).Replace("urn:li:person:", "", StringComparison.Ordinal).Trim();
            var lines = new List<(string Name, string Value)>
            {
                ("author", id.Length == 0 ? "" : (who.StartsWith('=') ? "=" : "") + (organization ? "organization:" : "person:") + id),
                ("text", Text(p, "text")),
                ("visibility", organization ? "" : Text(fields, "visibility")),
            };
            switch (Text(p, "shareMediaCategory"))
            {
                case "ARTICLE":
                    lines.Add(("article_url", Text(fields, "originalUrl")));
                    lines.Add(("article_title", Text(fields, "title")));
                    lines.Add(("article_description", Text(fields, "description")));
                    if (Text(fields, "thumbnailBinaryPropertyName").Length > 0)
                    {
                        todo.Add("its article's thumbnail was n8n's binary data - here an article goes without one.");
                    }

                    break;
                case "IMAGE":
                    todo.Add("it uploaded n8n's binary image - here the post goes as text: link to the image in it instead.");
                    break;
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(PerItem);
            todo.Add(LinkedInConnection);
        }

        private const string RedditConnection = "choose its connection - n8n's credentials stay in n8n: add a Reddit connection under Admin > Connections (a Reddit app's client id and secret and a permanent refresh token) and pick it here.";

        // n8n's Reddit operations as Extract from connection's: a subreddit, a post's or a comment's id made Reddit's full name (t3_,
        // t1_), a post's title, text or link, a comment's or a reply's text; its Get Many category, search place and order, a
        // subreddit's search words, a user's details, and its limit (100 when its export leaves it out). An image post n8n
        // uploaded is posted as a link to its address; trending subreddits are said.
        private static void Reddit(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            string Full(string prefix, string id) => id.Length == 0 ? "" : id.StartsWith('=') ? "=" + prefix + id[1..] : id.StartsWith(prefix, StringComparison.Ordinal) ? id : prefix + id;
            var comment = Text(p, "resource") == "postComment";
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "submit":
                    lines.Add(("subreddit", Text(p, "subreddit")));
                    lines.Add(("title", Text(p, "title")));
                    if (Text(p, "kind") is "link" or "image")
                    {
                        lines.Add(("url", Text(p, "url")));
                        lines.Add(("resubmit", Bool(p, "resubmit") ? "true" : ""));
                        if (Text(p, "kind") == "image")
                        {
                            todo.Add("it posted an image - here the post is a link to the image's address.");
                        }
                    }
                    else
                    {
                        lines.Add(("text", Text(p, "text")));
                    }

                    break;
                case "get_post":
                case "comments":
                    lines.Add(("post", Full("t3_", Text(p, "postId"))));
                    if (operation == "comments")
                    {
                        lines.Add(("max", Most(p, 100)));
                    }

                    break;
                case "posts":
                    lines.Add(("subreddit", Text(p, "subreddit")));
                    lines.Add(("sort", Text(p, "filters", "category")));
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "search":
                    lines.Add(("query", Text(p, "keyword")));
                    lines.Add(("subreddit", Text(p, "location") == "allReddit" ? "" : Text(p, "subreddit")));
                    lines.Add(("sort", Text(p, "additionalFields", "sort")));
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "delete":
                    lines.Add(("thing", comment ? Full("t1_", Text(p, "commentId")) : Full("t3_", Text(p, "postId"))));
                    break;
                case "comment":
                    lines.Add(("on", Text(p, "operation") == "reply" ? Full("t1_", Text(p, "commentId")) : Full("t3_", Text(p, "postId"))));
                    lines.Add(("text", Text(p, "operation") == "reply" ? Text(p, "replyText") : Text(p, "commentText")));
                    break;
                case "subreddit":
                case "rules":
                    lines.Add(("subreddit", Text(p, "subreddit")));
                    break;
                case "subreddits":
                    lines.Add(("query", Text(p, "filters", "keyword")));
                    lines.Add(("max", Most(p, 100)));
                    if (Bool(p, "filters", "trending"))
                    {
                        todo.Add("it read the trending subreddits - Reddit no longer lists them: here the popular ones.");
                    }

                    break;
                case "user":
                    lines.Add(("user", Text(p, "username")));
                    break;
                case "user_activity":
                    lines.Add(("user", Text(p, "username")));
                    lines.Add(("what", Text(p, "details")));
                    lines.Add(("max", Most(p, 100)));
                    break;
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "posts" or "search" or "comments" or "subreddits" or "user_activity" or "rules" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(RedditConnection);
        }

        private const string AwsSesConnection = "choose its connection - n8n's credentials stay in n8n: add an Amazon SES connection under Admin > Connections (an IAM user's access key and secret, and the region SES sends from) and pick it here.";

        // n8n's AWS SES operations as Extract from connection's: an e-mail's sender, recipients, copies and reply-to addresses (n8n's
        // lists comma-separated, an expression among them making the line one), its subject and its body as HTML or text as n8n's
        // isBodyHtml says, a configuration set; a template's name and data (n8n's key and value pairs a JSON object), its subject,
        // HTML and text parts; a custom verification e-mail's sender, subject, content and two addresses; Get Many's limit (20
        // when its export leaves it out). A return path and the identities' ARNs have no input here - said.
        private static void AwsSes(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "additionalFields");
            var update = Find(p, "updateFields");
            string List(JsonElement list)
            {
                if (list.ValueKind != JsonValueKind.Array)
                {
                    return Text(list);
                }

                var items = list.EnumerateArray().Select(item => item.ValueKind == JsonValueKind.String ? item.GetString() ?? "" : item.GetRawText()).Where(item => item.Length > 0).ToList();
                return (items.Any(item => item.StartsWith('=')) ? "=" : "") + string.Join(", ", items.Select(Unmarked));
            }

            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "send_email":
                case "send_template":
                    if (operation == "send_template")
                    {
                        lines.Add(("template", Text(p, "templateName")));
                        var pairs = Items(p, "templateDataUi", "templateDataValues").Where(pair => Text(pair, "key").Length > 0).ToList();
                        var data = pairs.Count == 0 ? "" : "{" + string.Join(", ", pairs.Select(pair => JsonSerializer.Serialize(Unmarked(Text(pair, "key")).Trim(), ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(Text(pair, "value")), ReadableJson))) + "}";
                        lines.Add(("data", (pairs.Any(pair => Text(pair, "key").StartsWith('=') || Text(pair, "value").StartsWith('=')) ? "=" : "") + data));
                    }

                    lines.Add(("from", Text(p, "fromEmail")));
                    lines.Add(("to", List(Find(p, "toAddresses"))));
                    lines.Add(("cc", List(Find(more, "ccAddresses"))));
                    lines.Add(("bcc", List(Find(more, "bccAddresses"))));
                    lines.Add(("reply_to", List(Find(more, "replyToAddresses"))));
                    if (operation == "send_email")
                    {
                        lines.Add(("subject", Text(p, "subject")));
                        lines.Add((Bool(p, "isBodyHtml") ? "html" : "text", Text(p, "body")));
                    }

                    lines.Add(("configuration_set", Text(more, "configurationSetName")));
                    var unsaid = new[] { "returnPath", "returnPathArn", "sourceArn" }.Where(name => Text(more, name).Length > 0).ToList();
                    if (unsaid.Count > 0)
                    {
                        todo.Add($"n8n's {string.Join(", ", unsaid)} {(unsaid.Count == 1 ? "has" : "have")} no input here - left out: SES sends from the sender's verified identity.");
                    }

                    break;
                case "create_template":
                case "update_template":
                    {
                        var fields = operation == "update_template" ? update : p;
                        lines.Add(("template", Text(p, "templateName")));
                        lines.Add(("subject", Text(fields, "subjectPart")));
                        lines.Add(("html", Text(fields, "htmlPart")));
                        lines.Add(("text", Text(operation == "update_template" ? update : more, "textPart")));
                        break;
                    }

                case "create_verification_template":
                case "update_verification_template":
                    {
                        var fields = operation == "update_verification_template" ? update : p;
                        lines.Add(("template", Text(p, "templateName")));
                        lines.Add(("from", Text(fields, "fromEmailAddress")));
                        lines.Add(("subject", Text(fields, "templateSubject")));
                        lines.Add(("content", Text(fields, "templateContent")));
                        lines.Add(("success_url", Text(fields, "successRedirectionURL")));
                        lines.Add(("failure_url", Text(fields, "failureRedirectionURL")));
                        break;
                    }

                case "templates":
                case "verification_templates":
                    lines.Add(("max", Most(p, 20)));
                    break;
                case "send_verification":
                    lines.Add(("template", Text(p, "templateName")));
                    lines.Add(("email", Text(p, "email")));
                    lines.Add(("configuration_set", Text(more, "configurationSetName")));
                    break;
                default:
                    lines.Add(("template", Text(p, "templateName")));
                    break;
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "templates" or "verification_templates" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(AwsSesConnection);
        }

        private const string AwsSqsConnection = "choose its connection - n8n's credentials stay in n8n: add an Amazon SQS connection under Admin > Connections (an IAM user's access key and secret, and the queues' region) and pick it here.";

        // n8n's AWS SQS Send Message as Extract from connection's: the queue (its URL), the message n8n's Message field gave - or,
        // as n8n's default sent the item's data, said to be given; a standard queue's delay, a FIFO queue's group and
        // deduplication ids; its string and number attributes a JSON object (a number a number, an expression among them making
        // the line one). A binary attribute has no input here - said.
        private static void AwsSqs(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            Set(step, "Operation", "send_message");
            var options = Find(p, "options");
            var fifo = Text(p, "queueType") == "fifo";
            var asked = Text(p, "sendInputData") == "false";
            var pairs = Items(options, "messageAttributes", "string").Select(pair => (Name: Text(pair, "name"), Value: Text(pair, "value"), Number: false))
                .Concat(Items(options, "messageAttributes", "number").Select(pair => (Name: Text(pair, "name"), Value: Text(pair, "value"), Number: true)))
                .Where(pair => pair.Name.Length > 0).ToList();
            var attributes = pairs.Count == 0 ? "" : (pairs.Any(pair => pair.Name.StartsWith('=') || pair.Value.StartsWith('=')) ? "=" : "") + "{" + string.Join(", ", pairs.Select(pair =>
                JsonSerializer.Serialize(Unmarked(pair.Name).Trim(), ReadableJson) + ": " + (pair.Number && double.TryParse(pair.Value, NumberStyles.Float, CultureInfo.InvariantCulture, out _) ? pair.Value : JsonSerializer.Serialize(Unmarked(pair.Value), ReadableJson)))) + "}";
            var lines = new List<(string Name, string Value)>
            {
                ("queue", Text(p, "queue")),
                ("body", asked ? Text(p, "message") : ""),
                ("delay", fifo ? "" : Text(options, "delaySeconds")),
                ("attributes", attributes),
                ("group", fifo ? Text(p, "messageGroupId") : ""),
                ("deduplication", fifo ? Text(options, "messageDeduplicationId") : ""),
            };
            if (!asked)
            {
                todo.Add("n8n sent each item's data as the message (its Send Input Data) - here give the body, the record's fields in a For Each: 'body = {{ order }}'.");
            }

            if (Items(options, "messageAttributes", "binary").Any())
            {
                todo.Add("n8n's binary attributes have no input here - left out: give the data as a string attribute.");
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(PerItem);
            todo.Add(AwsSqsConnection);
        }

        private const string AwsSnsConnection = "choose its connection - n8n's credentials stay in n8n: add an Amazon SNS connection under Admin > Connections (an IAM user's access key and secret, and the topics' region) and pick it here.";

        // n8n's AWS SNS operations as Extract from connection's: a topic by its ARN - n8n's list's, its id, or the ARN in the
        // console's address it was given by - a message's subject and text; a topic made with its name, display name and FIFO.
