            var lines = operation switch
            {
                "create_topic" => new List<(string Name, string Value)> { ("name", Text(p, "name")), ("display_name", Text(p, "options", "displayName")), ("fifo", Bool(p, "options", "fifoTopic") ? "true" : "") },
                "delete_topic" => new List<(string Name, string Value)> { ("topic", topic) },
                _ => new List<(string Name, string Value)> { ("topic", topic), ("subject", Text(p, "subject")), ("message", Text(p, "message")) },
            };
            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(PerItem);
            todo.Add(AwsSnsConnection);
        }

        private const string AwsDynamoDbConnection = "choose its connection - n8n's credentials stay in n8n: add an Amazon DynamoDB connection under Admin > Connections (an IAM user's access key and secret, and the tables' region) and pick it here.";

        // n8n's AWS DynamoDB operations as Extract from connection's: the table; an item's fields (n8n's pairs a JSON object), or -
        // as n8n's Auto-Map wrote the item's own - said to be given; a key's values (a number its type N says); a condition, a key
        // condition, a filter and a projection as written, their names and values JSON objects (a value a number its type N
        // says); a consistent read; an index; Get Many's limit (50 when its export leaves it out). n8n's Simplify needs nothing -
        // a record is always the item's values.
        private static void AwsDynamoDb(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "additionalFields");
            var options = Find(p, "options");
            string Json(IEnumerable<(string Name, string Value, bool Number)> pairs)
            {
                var list = pairs.Where(pair => pair.Name.Length > 0).ToList();
                return list.Count == 0 ? "" : (list.Any(pair => pair.Name.StartsWith('=') || pair.Value.StartsWith('=')) ? "=" : "") + "{" + string.Join(", ", list.Select(pair =>
                    JsonSerializer.Serialize(Unmarked(pair.Name).Trim(), ReadableJson) + ": " + (pair.Number && decimal.TryParse(pair.Value, NumberStyles.Float, CultureInfo.InvariantCulture, out _) ? pair.Value : JsonSerializer.Serialize(Unmarked(pair.Value), ReadableJson)))) + "}";
            }

            var names = Json(new[] { more, options }.SelectMany(holder => Items(holder, "eanUi", "eanValues").Select(pair => (Text(pair, "key"), Text(pair, "value"), false))
                .Concat(Items(holder, "expressionAttributeUi", "expressionAttributeValues").Select(pair => (Text(pair, "attribute"), Text(pair, "value"), false)))));
            var values = Json(new[] { p, more }.SelectMany(holder => Items(holder, "eavUi", "eavValues")).Select(pair => (Text(pair, "attribute"), Text(pair, "value"), Text(pair, "type") == "N")));
            var key = Json(Items(p, "keysUi", "keyValues").Select(pair => (Text(pair, "key"), Text(pair, "value"), Text(pair, "type") == "N")));
            var lines = new List<(string Name, string Value)> { ("table", Locator(p, "tableName")) };
            switch (operation)
            {
                case "put_item":
                    if (Text(p, "dataToSend") == "autoMapInputData")
                    {
                        todo.Add("n8n wrote each item's own fields as the item (its Auto-Map Input Data) - here give the item, a JSON object of the record's fields in a For Each: 'item = {\"pk\": \"{{ pk }}\"}'.");
                    }
                    else
                    {
                        lines.Add(("item", Json(Items(p, "fieldsUi", "fieldValues").Select(pair => (Text(pair, "fieldId"), Text(pair, "fieldValue"), false)))));
                    }

                    lines.Add(("condition", Text(more, "conditionExpression")));
                    break;
                case "get_item":
                    lines.Add(("key", key));
                    lines.Add(("projection", Text(more, "projectionExpression")));
                    lines.Add(("consistent", Text(more, "readType") == "consistentRead" ? "true" : ""));
                    break;
                case "delete_item":
                    lines.Add(("key", key));
                    lines.Add(("condition", Text(more, "conditionExpression")));
                    break;
                default:
                    lines.Add(("key_condition", operation == "query" ? Text(p, "keyConditionExpression") : ""));
                    lines.Add(("filter", operation == "scan" ? Text(p, "filterExpression") : Text(options, "filterExpression")));
                    lines.Add(("index", Text(options, "indexName")));
                    lines.Add(("projection", Text(options, "projectionExpression")));
                    lines.Add(("max", Most(p, 50)));
                    break;
            }

            lines.Add(("names", names));
            lines.Add(("values", operation == "get_item" ? "" : values));
            if (Items(p, "keysUi", "keyValues").Any(pair => Text(pair, "type") == "B"))
            {
                todo.Add("a binary key value has no input here - given as the string n8n held; DynamoDB compares it as a string.");
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "query" or "scan" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(AwsDynamoDbConnection);
        }

        private const string AwsLambdaConnection = "choose its connection - n8n's credentials stay in n8n: add an AWS Lambda connection under Admin > Connections (an IAM user's access key and secret, and the functions' region) and pick it here.";

        // n8n's AWS Lambda Invoke as Extract from connection's: the function (its ARN, as n8n's list gave it), a version or an
        // alias other than $LATEST, its payload, and an Event invocation as one queued.
        private static void AwsLambda(JsonElement p, PipelineGraphStep step, Todo todo)
        {
