                ("qualifier", qualifier == "$LATEST" ? "" : qualifier),
                ("payload", Text(p, "payload")),
                ("event", Text(p, "invocationType") == "Event" ? "true" : ""),
            };
            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
