        private const string ClockifyConnection = "choose its connection - n8n's credentials stay in n8n: add a Clockify connection under Admin > Connections (an API key; a region's address if the workspace lives in one) and pick it here.";

        // n8n's Clockify resource as the connector names it: timeEntry a time_entry.
        private static string Singular(string resource) => resource == "timeEntry" ? "time_entry" : resource;

        // n8n's Clockify node: the workspace and the resource's id; a list's name, archived, billable, active and e-mail filters
        // (any other said) and n8n's limit; what a create or an update writes - the name, a time entry's start and end, every
        // other field as n8n gave it, its estimate and custom fields unwrapped as n8n does, a task's 2:30 estimate as Clockify's
        // PT2H30M.
        private static void Clockify(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)> { ("workspace", Text(p, "workspaceId")) };
            foreach (var (parameter, name) in new[] { ("projectId", "project"), ("clientId", "client"), ("tagId", "tag"), ("taskId", "task"), ("timeEntryId", "time_entry") })
            {
                var wanted = operation.EndsWith("_" + name, StringComparison.Ordinal) || (name == "project" && operation.EndsWith("task", StringComparison.Ordinal)) || (name == "project" && operation == "tasks");
                lines.Add((name, wanted ? Text(p, parameter) : ""));
            }

            if (operation.EndsWith('s'))
            {
                var filters = Find(p, operation == "tasks" ? "filters" : "additionalFields");
                foreach (var (given, name) in new[] { ("name", "name"), ("archived", "archived"), ("billable", "billable"), ("is-active", "active"), ("email", "email") })
                {
                    lines.Add((name, Text(filters, given)));
                }

                var dropped = filters.ValueKind == JsonValueKind.Object ? filters.EnumerateObject().Select(field => field.Name).Where(field => field is not ("name" or "archived" or "billable" or "is-active" or "email")).ToList() : new List<string>();
                if (dropped.Count > 0)
                {
                    todo.Add($"n8n filtered by {string.Join(", ", dropped)} as well - here a list filters by name, archived, billable, active or e-mail: the rest were left out.");
                }

                lines.Add(("max", Most(p, operation == "workspaces" ? 50 : 100)));
            }
            else if (operation.StartsWith("create_", StringComparison.Ordinal) || operation.StartsWith("update_", StringComparison.Ordinal))
            {
                var entry = operation.EndsWith("time_entry", StringComparison.Ordinal);
                var given = Find(p, operation.StartsWith("create_", StringComparison.Ordinal) ? "additionalFields" : "updateFields");
                lines.Add(("name", entry ? "" : Text(p, "name") is { Length: > 0 } name ? name : Text(given, "name")));
                lines.Add(("start", entry ? Text(p, "start") is { Length: > 0 } start ? start : Text(given, "start") : ""));
                lines.Add(("end", entry ? Text(given, "end") : ""));
                if (entry && new[] { Text(p, "start"), Text(given, "start"), Text(given, "end") }.Any(moment => moment.Length > 0 && !moment.StartsWith('=') && !Regex.IsMatch(moment, "(Z|[+-][0-9]{2}:?[0-9]{2})$")))
                {
                    todo.Add("n8n read its times in the workflow's time zone - here a time is given with its zone: add it ('2026-10-13T08:00:00+02:00', or Z for UTC).");
                }

                // Every other field as n8n gave it, its wrappers unwrapped as n8n does.
                var pairs = new List<string>();
                var marked = false;
                foreach (var field in given.ValueKind == JsonValueKind.Object ? given.EnumerateObject().ToList() : new List<JsonProperty>())
                {
                    if (field.Name is "name" or "start" or "end")
                    {
                        continue;
                    }

                    var (key, value) = field.Name switch
                    {
                        "estimateUi" => ("estimate", Find(field.Value, "estimateValues").ValueKind == JsonValueKind.Object ? Find(field.Value, "estimateValues").GetRawText() : "null"),
                        "customFieldsUi" => ("customFields", Find(field.Value, "customFieldsValues").ValueKind == JsonValueKind.Array ? Find(field.Value, "customFieldsValues").GetRawText() : "[]"),
                        "estimate" when operation.EndsWith("task", StringComparison.Ordinal) && Regex.Match(field.Value.ValueKind == JsonValueKind.String ? field.Value.GetString() ?? "" : "", "^([0-9]+):([0-9]{1,2})$") is { Success: true } hours
                            => ("estimate", JsonSerializer.Serialize($"PT{hours.Groups[1].Value}H{int.Parse(hours.Groups[2].Value, CultureInfo.InvariantCulture)}M", ReadableJson)),
                        _ => (field.Name, field.Value.ValueKind == JsonValueKind.String ? JsonSerializer.Serialize(Unmarked(field.Value.GetString() ?? ""), ReadableJson) : field.Value.GetRawText()),
                    };
                    marked |= field.Value.ValueKind == JsonValueKind.String && (field.Value.GetString() ?? "").StartsWith('=');
                    pairs.Add(JsonSerializer.Serialize(key, ReadableJson) + ": " + value);
                }

                lines.Add(("fields", pairs.Count == 0 ? "" : (marked ? "=" : "") + "{" + string.Join(", ", pairs) + "}"));
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation.EndsWith('s') ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(ClockifyConnection);
        }

        private const string CodaConnection = "choose its connection - n8n's credentials stay in n8n: add a Coda connection under Admin > Connections (an API token) and pick it here.";

        // n8n's Coda node: its doc and its table or view; its rows read with a query, a sort, visible rows only, a value format and
        // the columns as n8n named them - Get All Rows by their ids unless n8n was asked for names, Get Row by their names unless
        // it was asked for ids - and n8n's limit; the row, the rows to delete, the button's column, the formula and the control; a
        // create's key columns, and Coda's parsing off when n8n turned it off.
        private static void Coda(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var options = Find(p, "options");
            var lines = new List<(string Name, string Value)> { ("doc", Text(p, "docId")), ("table", Text(p, Text(p, "resource") == "view" ? "viewId" : "tableId")) };
            switch (operation)
            {
                case "rows":
                    lines.Add(("query", Text(options, "query")));
                    lines.Add(("sort_by", Text(options, "sortBy")));
                    lines.Add(("visible_only", Bool(options, "visibleOnly") ? "true" : ""));
                    lines.Add(("column_names", Bool(options, "useColumnNames") ? "" : "false"));
                    lines.Add(("value_format", Text(options, "valueFormat")));
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "get_row":
                    lines.Add(("row", Text(p, "rowId")));
                    lines.Add(("column_names", Text(options, "useColumnNames") == "false" ? "false" : ""));
                    lines.Add(("value_format", Text(options, "valueFormat")));
                    break;
                case "tables":
                    lines.Add(("types", "view"));
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "columns":
                case "formulas":
                case "controls":
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "get_column":
                    lines.Add(("column", Text(p, "columnId")));
                    break;
                case "get_formula":
                    lines.Add(("formula", Text(p, "formulaId")));
                    break;
                case "get_control":
                    lines.Add(("control", Text(p, "controlId")));
                    break;
                case "delete_rows":
                    lines.Add(("rows", Text(p, "rowId")));
                    break;
                case "push_button":
                    lines.Add(("row", Text(p, "rowId")));
                    lines.Add(("column", Text(p, "columnId")));
                    break;
                case "create_rows":
                    lines.Add(("key_columns", Text(options, "keyColumns")));
                    lines.Add(("parse", Bool(options, "disableParsing") ? "false" : ""));
                    todo.Add("n8n wrote each item's own fields as a row - here give the fields, a JSON object of the row's columns in a For Each: 'fields = {\"Name\": \"{{ name }}\"}'.");
                    break;
                default:
                    lines.Add(("row", Text(p, "rowId")));
                    lines.Add(("parse", Bool(options, "disableParsing") ? "false" : ""));
                    todo.Add($"n8n took the row's changes from each item's {(Text(p, "keyName") is { Length: > 0 } key ? key : "columns")} - here give the fields, a JSON object of the columns to change: 'fields = {{\"Paid\": true}}'.");
                    break;
            }

            if (Bool(options, "rawData"))
            {
                todo.Add("n8n gave each row as Coda answered it (its Raw Data) - here a row is its id and its values.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "rows" or "tables" or "columns" or "formulas" or "controls" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(CodaConnection);
        }

        private const string GhostConnection = "choose its connection - n8n's credentials stay in n8n: add a Ghost connection under Admin > Connections (the site's address and an Admin API key from a custom integration) and pick it here.";

        // n8n's Ghost node: a post by its id or slug, the posts with what to include, the fields and the formats (n8n's Content
        // API's html when the export leaves them out, and its published posts only: here the Admin API's key, which sees drafts,
        // filters them) and n8n's limit; a post created or updated with its title, its content as
        // HTML or Lexical - Mobiledoc among the other fields - its status and every other field n8n gave; a post deleted.
        private static void Ghost(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var options = Find(p, "options");
            var content = Text(p, "source") != "adminApi";
            static string Joined(JsonElement holder, string name) =>
                Find(holder, name) is { ValueKind: JsonValueKind.Array } list ? string.Join(",", list.EnumerateArray().Select(item => Text(item)).Where(item => item.Length > 0)) : Text(holder, name);
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "get_post":
                    lines.Add((Text(p, "by") == "slug" ? "slug" : "id", Text(p, "identifier")));
                    lines.Add(("fields", Text(options, "fields")));
                    lines.Add(("formats", Joined(options, "formats") is { Length: > 0 } formats ? formats : content ? "html" : ""));
                    break;
                case "posts":
                    lines.Add(("filter", content ? "status:published" : ""));
                    lines.Add(("include", Joined(options, "include")));
                    lines.Add(("fields", Text(options, "fields")));
                    lines.Add(("formats", Joined(options, "formats") is { Length: > 0 } wanted ? wanted : content ? "html" : ""));
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "delete_post":
                    lines.Add(("id", Text(p, "postId")));
                    break;
                default:
                    {
                        var update = operation == "update_post";
                        var given = Find(p, update ? "updateFields" : "additionalFields");
                        lines.Add(("id", update ? Text(p, "postId") : ""));
                        lines.Add(("title", update ? Text(given, "title") : Text(p, "title")));
                        var format = Text(p, "contentFormat") is { Length: > 0 } chosen ? chosen : "html";
                        var body = update ? Text(given, format == "html" ? "content" : "contentJson") : Text(p, "content");
                        lines.Add(("html", format == "html" ? body : ""));
                        lines.Add(("lexical", format == "lexical" ? body : ""));
                        lines.Add(("status", Text(given, "status")));

                        // Every other field as n8n gave it - Mobiledoc among them, which Ghost still reads.
                        var others = given.ValueKind == JsonValueKind.Object
                            ? given.EnumerateObject().Where(field => field.Name is not ("title" or "content" or "contentJson" or "status")).Select(field => (field.Name, Value: field.Value)).ToList()
                            : new List<(string Name, JsonElement Value)>();
                        var pairs = others.Select(field => JsonSerializer.Serialize(field.Name, ReadableJson) + ": " + (field.Value.ValueKind == JsonValueKind.String ? JsonSerializer.Serialize(Unmarked(field.Value.GetString() ?? ""), ReadableJson) : field.Value.GetRawText())).ToList();
                        if (format == "mobileDoc" && body.Length > 0)
                        {
                            pairs.Add("\"mobiledoc\": " + JsonSerializer.Serialize(Unmarked(body), ReadableJson));
                        }

                        var marked = others.Any(field => field.Value.ValueKind == JsonValueKind.String && (field.Value.GetString() ?? "").StartsWith('=')) || (format == "mobileDoc" && body.StartsWith('='));
                        lines.Add(("fields", pairs.Count == 0 ? "" : (marked ? "=" : "") + "{" + string.Join(", ", pairs) + "}"));
                        break;
                    }
            }

            if (content && operation == "get_post")
            {
                todo.Add("n8n read through Ghost's Content API, which sees published posts only - here the connection's Admin API key reads a draft too.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "posts" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(GhostConnection);
        }

        private const string HarvestConnection = "choose its connection - n8n's credentials stay in n8n: add a Harvest connection under Admin > Connections (a personal access token and the account's id) and pick it here.";

        private static string HarvestPlural(string resource) => resource == "timeEntry" ? "time_entries" : resource + "s";

        // n8n's own names for a create's required fields, as Harvest names them.
        private static readonly Dictionary<string, string> HarvestFields = new(StringComparer.Ordinal)
        {
            ["name"] = "name", ["clientId"] = "client_id", ["projectId"] = "project_id", ["taskId"] = "task_id", ["spentDate"] = "spent_date",
            ["isBillable"] = "is_billable", ["billBy"] = "bill_by", ["budgetBy"] = "budget_by", ["firstName"] = "first_name", ["lastName"] = "last_name",
            ["email"] = "email", ["expenseCategoryId"] = "expense_category_id",
        };

        // n8n's Harvest node: the id; a list's filters as Harvest names them (n8n's starting page said) and n8n's limit of 100; what
        // a create writes - its required fields under Harvest's names, a project's billing as n8n defaults it, and every additional
        // field - or what an update changes; the account n8n acted in said.
        private static void Harvest(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)> { ("id", Text(p, "id")) };
            var listed = operation is "clients" or "contacts" or "projects" or "tasks" or "users" or "invoices" or "estimates" or "expenses" or "time_entries";
            if (listed)
            {
                var filters = Find(p, "filters");
                foreach (var filter in filters.ValueKind == JsonValueKind.Object ? filters.EnumerateObject().ToList() : new List<JsonProperty>())
                {
                    if (filter.Name == "page")
                    {
                        todo.Add($"n8n started at page {Text(filter.Value)} - here a list starts at its first: give 'max' for how many.");
                        continue;
                    }

                    lines.Add((filter.Name, Text(filter.Value)));
                }

                lines.Add(("max", Most(p, 100)));
            }
            else if (operation.StartsWith("create_", StringComparison.Ordinal) || operation.StartsWith("update_", StringComparison.Ordinal))
            {
                var create = operation.StartsWith("create_", StringComparison.Ordinal);
                var given = new List<(string Name, JsonElement Value)>();
                if (create)
                {
                    given.AddRange(HarvestFields.Where(field => p.ValueKind == JsonValueKind.Object && p.TryGetProperty(field.Key, out _)).Select(field => (field.Value, p.GetProperty(field.Key))));
                }

                var more = Find(p, create ? "additionalFields" : "updateFields");
                given.AddRange((more.ValueKind == JsonValueKind.Object ? more.EnumerateObject().ToList() : new List<JsonProperty>()).Select(field => (field.Name, field.Value)));
                var pairs = given.Select(field => JsonSerializer.Serialize(field.Name, ReadableJson) + ": " + (field.Value.ValueKind == JsonValueKind.String
                    ? field.Name.EndsWith("_id", StringComparison.Ordinal) && Regex.IsMatch(field.Value.GetString() ?? "", "^[1-9][0-9]{0,18}$") ? field.Value.GetString() : JsonSerializer.Serialize(Unmarked(field.Value.GetString() ?? ""), ReadableJson)
                    : field.Value.GetRawText())).ToList();
                if (operation == "create_project")
                {
                    // n8n's defaults for a project's billing, which its export leaves out and Harvest asks of every new project.
                    foreach (var (name, value) in new[] { ("is_billable", "true"), ("bill_by", "\"none\""), ("budget_by", "\"none\"") })
                    {
                        if (given.All(field => field.Name != name))
                        {
                            pairs.Add(JsonSerializer.Serialize(name, ReadableJson) + ": " + value);
                        }
                    }
                }

                var marked = given.Any(field => field.Value.ValueKind == JsonValueKind.String && (field.Value.GetString() ?? "").StartsWith('='));
                lines.Add(("fields", pairs.Count == 0 ? "" : (marked ? "=" : "") + "{" + string.Join(", ", pairs) + "}"));
            }

            if (Text(p, "accountId") is { Length: > 0 } account)
            {
                todo.Add($"n8n acted in Harvest account {account} - here the connection names its account: set it there (Account).");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(listed ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(HarvestConnection);
        }

        private const string StrapiConnection = "choose its connection - n8n's credentials stay in n8n: add a Strapi connection under Admin > Connections (its address, an API token from Settings > API Tokens, and its version) and pick it here.";

        // n8n's Strapi node: the content type and the entry; its Get Many's where (Strapi's filters), sort, publication state and
        // n8n's limit of 50; a create's or an update's columns written from the record that reaches it, as n8n took them from the
        // item, and an update's entry from the item's update key; n8n's sign-in with an e-mail and password said.
        private static void Strapi(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var options = Find(p, "options");
            var columns = Text(p, "columns").Split(',', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries);
            var lines = new List<(string Name, string Value)>
            {
                ("content_type", Text(p, "contentType")),
                ("id", operation == "update_entry" ? "{{ " + (Text(p, "updateKey") is { Length: > 0 } key ? key : "id") + " }}" : Text(p, "entryId")),
                ("filters", Text(options, "where")),
                ("sort", Find(options, "sort") is { ValueKind: JsonValueKind.Array } sorts ? string.Join(",", sorts.EnumerateArray().Select(item => Text(item))) : Text(options, "sort")),
                ("status", Text(options, "publicationState") switch { "live" => "published", "preview" => "draft", _ => "" }),
                ("max", operation == "entries" ? Most(p, 50) : ""),
                ("fields", columns.Length == 0 ? "" : "{" + string.Join(", ", columns.Select(column => JsonSerializer.Serialize(column, ReadableJson) + ": \"{{ " + column + " }}\"")) + "}"),
            };
            if (columns.Length > 0)
            {
                todo.Add("n8n wrote the item's own " + string.Join(", ", columns) + " - here each is the record's, written as text: put it in a For Each over the records, and give a number or a list as JSON in the fields.");
            }

            if (Text(p, "authentication") != "token")
            {
                todo.Add("n8n signed in to Strapi with an e-mail and a password - here a Strapi connection uses an API token: make one in Strapi under Settings > API Tokens.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation == "entries" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(StrapiConnection);
        }

        private const string ContentfulConnection = "choose its connection - n8n's credentials stay in n8n: add a Contentful connection under Admin > Connections (the space's id, a Content Delivery or Preview API token, and which API) and pick it here.";

        // n8n's Contentful node: the entry, asset or content type and the environment; its Get Many's content type, its Equal, Not
        // Equal, Include, Exclude and Exist - each attribute=value, split at the first = - as Contentful's search parameters (an
        // expression among them making them one), the fields, order and query, n8n's limit of 100 and its RAW Data; its Preview
        // API said.
        private static void Contentful(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "additionalFields");
            var filters = new[] { "equal", "notEqual", "include", "exclude", "exist" }
                .Select(name => Text(more, name))
                .Where(value => value.Length > 0)
                .Select(value => (Expression: value.StartsWith('='), Pair: Unmarked(value).Split('=', 2)))
                .Where(item => item.Pair.Length == 2 && item.Pair[0].Trim().Length > 0)
                .ToList();
            var lines = new List<(string Name, string Value)>();
            if (operation is "entry" or "asset" or "content_type")
            {
                lines.Add(("id", Text(p, operation switch { "entry" => "entryId", "asset" => "assetId", _ => "contentTypeId" })));
            }

            lines.Add(("content_type", Text(more, "content_type")));
            lines.Add(("filters", filters.Count == 0 ? "" : (filters.Any(item => item.Expression) ? "=" : "") + "{" + string.Join(", ", filters.Select(item =>
                JsonSerializer.Serialize(item.Pair[0].Trim(), ReadableJson) + ": " + JsonSerializer.Serialize(item.Pair[1], ReadableJson))) + "}"));
            lines.Add(("select", Text(more, "select")));
            lines.Add(("order", Text(more, "order")));
            lines.Add(("query", Text(more, "query")));
            lines.Add(("raw", Bool(more, "rawData") ? "true" : ""));
            lines.Add(("max", operation is "entries" or "assets" or "locales" ? Most(p, 100) : ""));
            lines.Add(("environment", Text(p, "environmentId")));
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (Text(p, "source") == "previewApi")
            {
                todo.Add("n8n read Contentful's Preview API - here a connection reads the API it is set to: choose one set to preview, with a Content Preview API token.");
            }

            todo.Add(operation is "entries" or "assets" or "locales" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(ContentfulConnection);
        }

        private const string ElasticsearchConnection = "choose its connection - n8n's credentials stay in n8n: add an Elasticsearch connection under Admin > Connections (the cluster's address, a user's name and password - or an API key with no user) and pick it here.";

        private static readonly string[] ElasticsearchSearchOptions = { "query", "queryParameters", "sort", "_source_includes", "_source_excludes", "routing" };

        // n8n's Elasticsearch node: the index and the document; its Get Many's search body, sort, source fields, routing, n8n's
        // limit of 50 - or its Return All's 10,000 - and Simplify; a create's or an update's Fields to Send (an expression among
        // them making them one), a create's id, routing and pipeline, the refresh; an index's settings, mappings and aliases; what
        // has no counterpart said - its query parameters, its other search options, its bulk, its Auto-Map Input Data.
        private static void Elasticsearch(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var options = Find(p, "options");
            var more = Find(p, "additionalFields");
            static string Json(string value) => value.Length == 0 || value.StartsWith('=') ? value : Minified(value);
            var lines = new List<(string Name, string Value)>
            {
                ("index", Text(p, "indexId")),
                ("id", operation is "get" or "update" or "delete" ? Text(p, "documentId") : operation == "create" ? Text(more, "documentId") : ""),
            };
            if (operation == "search")
            {
                lines.Add(("query", Json(Text(options, "query"))));
                lines.Add(("sort", Text(options, "sort")));
            }

            if (operation is "search" or "get")
            {
                lines.Add(("includes", Text(options, "_source_includes")));
                lines.Add(("excludes", Text(options, "_source_excludes")));
            }

            lines.Add(("routing", operation == "search" ? Text(options, "routing") : operation == "create" ? Text(more, "routing") : ""));
            if (operation is "create" or "update")
            {
                if (Text(p, "dataToSend") == "autoMapInputData")
                {
                    todo.Add("n8n wrote each item's own fields as the document (its Auto-Map Input Data) - here give the fields, a JSON object of the record's fields in a For Each: 'fields = {\"title\": \"{{ title }}\"}'.");
                }
                else
                {
                    var pairs = Items(p, "fieldsUi", "fieldValues").Select(item => (Name: Text(item, "fieldId"), Value: Text(item, "fieldValue"))).Where(pair => pair.Name.Length > 0).ToList();
                    lines.Add(("fields", pairs.Count == 0 ? "" : (pairs.Any(pair => pair.Value.StartsWith('=')) ? "=" : "") + "{" + string.Join(", ", pairs.Select(pair =>
                        JsonSerializer.Serialize(pair.Name, ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(pair.Value), ReadableJson))) + "}"));
                }

                lines.Add(("pipeline", operation == "create" ? Text(options, "pipeline") : ""));
                lines.Add(("refresh", Text(options, "refresh")));
            }

            if (operation == "create_index")
            {
                foreach (var part in new[] { "settings", "mappings", "aliases" })
                {
                    lines.Add((part, Json(Text(more, part))));
                }
            }

            lines.Add(("raw", operation is "search" or "get" && Text(p, "simple") == "false" ? "true" : ""));
            lines.Add(("max", operation == "search" ? Bool(p, "returnAll") ? "10000" : Most(p, 50) : operation == "indices" ? Most(p, 50) : ""));
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (operation == "search")
            {
                if (Text(options, "queryParameters").Length > 0)
                {
                    todo.Add("n8n filled its search's $1, $2 from its query parameters - here write each value into the search, from the record: {\"term\": {\"level\": \"{{ level }}\"}}.");
                }

                var others = options.ValueKind == JsonValueKind.Object ? options.EnumerateObject().Select(option => option.Name).Where(name => !ElasticsearchSearchOptions.Contains(name)).ToList() : new List<string>();
                if (others.Count > 0)
                {
                    todo.Add("n8n's other search options - " + string.Join(", ", others) + " - have no counterpart here: give them in the search body where Elasticsearch takes them there.");
                }
            }

            if (Bool(options, "bulkOperation"))
            {
                todo.Add("n8n sent it through Elasticsearch's bulk API, fifty items at a time - here it runs for one document: put it in a For Each over the records.");
            }

            todo.Add(operation is "search" or "indices" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(ElasticsearchConnection);
        }

        private const string DeepLConnection = "choose its connection - n8n's credentials stay in n8n: add a DeepL connection under Admin > Connections (its authentication key - a Free API key ends in :fx) and pick it here.";

        // n8n's DeepL node: its text - one holding a line break written as a list of one, a parameter being a line - and the
        // language into it; its source language (DeepL reads it without a variant), sentence splitting, formatting and
        // formality, which n8n's node offers and never sends - said.
        private static void DeepL(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            Set(step, "Operation", "translate");
            var more = Find(p, "additionalFields");
            var text = Text(p, "text");
            var broken = !text.StartsWith('=') && (text.Contains('\n') || text.Contains('\r'));
            var split = Text(more, "splitSentences") is { Length: > 0 } splitting && splitting != "1" ? splitting : "";
            var keep = Text(more, "preserveFormatting") == "1" ? "true" : "";
            var formality = Text(more, "formality") is { Length: > 0 } formal && formal != "default" ? formal : "";
            Set(step, "Parameters", FtpParameters(new (string Name, string Value)[]
            {
                (broken ? "texts" : "text", broken ? "[" + JsonSerializer.Serialize(text, ReadableJson) + "]" : text),
                ("target", Text(p, "translateTo")),
                ("source", Text(more, "sourceLang")),
                ("split_sentences", split),
                ("preserve_formatting", keep),
                ("formality", formality),
            }.Where(line => line.Value.Length > 0).ToArray()));
            if (split.Length + keep.Length + formality.Length > 0)
            {
                todo.Add("n8n's DeepL node offered its sentence splitting, formatting and formality but never sent them - here they are sent: check the translation reads as you meant.");
            }

            todo.Add(PerItem);
            todo.Add(DeepLConnection);
        }

        private const string PagerDutyConnection = "choose its connection - n8n's credentials stay in n8n: add a PagerDuty connection under Admin > Connections (an API token, and the e-mail of the PagerDuty user its changes come from) and pick it here.";

        // n8n's PagerDuty node: the incident, log entry or user; a new incident's title, service, sender and additional fields,
        // its conference bridge; an update's fields; a note and its sender; Get Many's options - its lists, its times, every
        // time (n8n's date range), its sort, what to include as PagerDuty names it, its time zone - and n8n's limit of 100.
        private static void PagerDuty(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, operation == "update_incident" ? "updateFields" : "additionalFields");
            var options = Find(p, "options");
            var bridge = Find(p, "conferenceBridgeUi", "conferenceBridgeValues");
            var list = operation is "incidents" or "log_entries";
            static string Joined(JsonElement holder, string name, bool snake = false) => Find(holder, name) is { ValueKind: JsonValueKind.Array } items
                ? string.Join(",", items.EnumerateArray().Select(item => snake ? Regex.Replace(Text(item), "(?<=[a-z])([A-Z])", "_$1").ToLowerInvariant() : Text(item)))
                : Text(holder, name);
            var lines = new List<(string Name, string Value)>
            {
                ("id", operation switch
                {
                    "incident" or "update_incident" or "notes" or "create_note" => Text(p, "incidentId"),
                    "log_entry" => Text(p, "logEntryId"),
                    "user" => Text(p, "userId"),
                    _ => "",
                }),
                ("title", operation == "create_incident" ? Text(p, "title") : Text(more, "title")),
                ("service", Text(p, "serviceId")),
                ("from", Text(p, "email")),
                ("status", Text(more, "status")),
                ("resolution", Text(more, "resolution")),
                ("urgency", Text(more, "urgency")),
                ("escalation_level", Text(more, "escalationLevel") is var level && level != "0" ? level : ""),
                ("incident_key", list ? Text(options, "incidentKey") : Text(more, "incidentKey")),
                ("details", Text(more, "details")),
                ("priority", Text(more, "priorityId")),
                ("escalation_policy", Text(more, "escalationPolicyId")),
                ("conference_number", Text(bridge, "conferenceNumber")),
                ("conference_url", Text(bridge, "conferenceUrl")),
                ("content", Text(p, "content")),
                ("statuses", Joined(options, "statuses")),
                ("urgencies", Joined(options, "urgencies")),
                ("services", Joined(options, "serviceIds")),
                ("teams", Joined(options, "teamIds")),
                ("users", Joined(options, "userIds")),
                ("all", Text(options, "dateRange") == "all" ? "true" : ""),
                ("since", Text(options, "since")),
                ("until", Text(options, "until")),
                ("sort", Text(options, "sortBy")),
                ("include", Joined(options, "include", snake: true)),
                ("overview", Bool(options, "isOverview") ? "true" : ""),
                ("time_zone", Text(options, "timeZone")),
                ("max", list ? Most(p, 100) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(list ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(PagerDutyConnection);
        }

        private const string BitlyConnection = "choose its connection - n8n's credentials stay in n8n: add a Bitly connection under Admin > Connections (an access token from Settings > Developer settings > API) and pick it here.";

        // n8n's Bitly node: the long address and the link; a create's domain, group, title and tags, an update's title, tags,
        // archived and address; its deep links as Bitly names their fields - on which n8n's node fails; an update's
        // group, which a link keeps here, said.
        private static void Bitly(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, operation == "update" ? "updateFields" : "additionalFields");
            static string Joined(JsonElement holder, string name) => Find(holder, name) is { ValueKind: JsonValueKind.Array } items ? string.Join(",", items.EnumerateArray().Select(item => Text(item))) : Text(holder, name);
            var deeplinks = Items(p, "deeplink", "deeplinkUi").Select(item => new[] { ("app_id", Text(item, "appId")), ("app_uri_path", Text(item, "appUriPath")), ("install_url", Text(item, "installUrl")), ("install_type", Text(item, "installType")) }
                .Where(field => field.Item2.Length > 0).ToList()).Where(fields => fields.Count > 0).ToList();
            var lines = new List<(string Name, string Value)>
            {
                ("link", Text(p, "id")),
                ("long_url", operation == "update" ? Text(more, "longUrl") : Text(p, "longUrl")),
                ("domain", operation == "create" && Text(more, "domain") is { Length: > 0 } domain && domain != "bit.ly" ? domain : ""),
                ("group", operation == "create" ? Text(more, "group") : ""),
                ("title", Text(more, "title")),
                ("tags", Joined(more, "tags")),
                ("archived", operation == "update" ? Text(more, "archived") : ""),
                ("deeplinks", deeplinks.Count == 0 ? "" : "[" + string.Join(", ", deeplinks.Select(fields => "{" + string.Join(", ", fields.Select(field => JsonSerializer.Serialize(field.Item1, ReadableJson) + ": " + JsonSerializer.Serialize(field.Item2, ReadableJson))) + "}")) + "]"),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (operation == "update" && Text(more, "group").Length > 0)
            {
                todo.Add("n8n moved the link to another group - here a link keeps its group: move it in Bitly.");
            }

            todo.Add(PerItem);
            todo.Add(BitlyConnection);
        }

        private const string FacebookGraphConnection = "choose its connection - n8n's credentials stay in n8n: add a Facebook Graph API connection under Admin > Connections (a Page's or a user's access token, and the Graph version) and pick it here.";

        // n8n's Facebook Graph API node: the node, the edge and the Graph version; a GET's fields and its query parameters - the
        // pairs and the JSON merged - as the Graph's parameters, a POST's as what it posts (the Graph reads them the same); its
        // video host and its file upload said.
        private static void FacebookGraph(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var options = Find(p, "options");
            var pairs = Items(options, "queryParameters", "parameter").Select(item => (Name: Text(item, "name"), Value: Text(item, "value"))).Where(pair => pair.Name.Length > 0).ToList();
            var json = Text(options, "queryParametersJson");
            var parameters = new JsonObject();
            foreach (var (name, value) in pairs)
            {
                parameters[name] = Unmarked(value);
            }

            if (json.Length > 0 && !json.StartsWith('='))
            {
                JsonObject? extra = null;
                try
                {
                    extra = JsonNode.Parse(json) as JsonObject;
                }
                catch (JsonException)
                {
                }

                if (extra is null)
                {
                    todo.Add("n8n's query parameters' JSON does not read as a JSON object - give them as JSON in the step.");
                }

                foreach (var (name, value) in extra?.ToList() ?? new List<KeyValuePair<string, JsonNode?>>())
                {
                    extra!.Remove(name);
                    parameters[name] = value;
                }
            }

            var merged = parameters.Count == 0 ? "" : (pairs.Any(pair => pair.Value.StartsWith('=')) ? "=" : "") + parameters.ToJsonString(ReadableJson);

            var lines = new List<(string Name, string Value)>
            {
                ("node", Text(p, "node")),
                ("edge", Text(p, "edge")),
                ("fields", operation == "get" ? string.Join(",", Items(options, "fields", "field").Select(item => Text(item, "name")).Where(name => name.Length > 0)) : merged),
                ("query", operation == "get" ? merged : ""),
                ("version", Text(p, "graphApiVersion")),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (Text(p, "hostUrl") == "graph-video.facebook.com")
            {
                todo.Add("n8n sent it to graph-video.facebook.com - here the connection's address is the host: give it https://graph-video.facebook.com.");
            }

            if (Bool(p, "sendBinaryData"))
            {
                todo.Add("n8n uploaded a file - here a post sends JSON: post the file's address instead (url, file_url).");
            }

            if (json.StartsWith('='))
            {
                todo.Add("n8n read its query parameters' JSON from the item - here give them as JSON in the step, from the record.");
            }

            todo.Add(PerItem);
            todo.Add(FacebookGraphConnection);
        }

        private const string ZulipConnection = "choose its connection - n8n's credentials stay in n8n: add a Zulip connection under Admin > Connections (the organization's address, the bot's e-mail and its API key) and pick it here.";

        private static readonly Dictionary<string, string> ZulipRoles = new(StringComparer.Ordinal) { ["100"] = "owner", ["200"] = "administrator", ["300"] = "moderator", ["400"] = "member", ["600"] = "guest" };

        // n8n's Zulip node: a message's people, stream, topic and text, its id and what an update changes (its move as Zulip
        // names it); a stream's - the first of n8n's subscriptions - with its privacy, subscribers and announcement, an update's
        // name, description and privacy; a user's e-mail, name, password and role by name; what has no counterpart said.
        private static void Zulip(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, operation is "update_message" ? "updateFields" : operation is "update_user" ? "updateFields" : "additionalFields");
            static string Joined(JsonElement holder, string name) => Find(holder, name) is { ValueKind: JsonValueKind.Array } items ? string.Join(",", items.EnumerateArray().Select(item => Text(item))) : Text(holder, name);
            var subscriptions = Items(p, "subscriptions", "properties").ToList();
            var principals = Items(more, "principals", "properties").Select(item => Text(item, "email")).Where(email => email.Length > 0).ToList();
            var lines = new List<(string Name, string Value)>
            {
                ("id", operation switch
                {
                    "message" or "update_message" or "delete_message" => Text(p, "messageId"),
                    "update_stream" or "delete_stream" => Text(p, "streamId"),
                    "user" or "update_user" or "deactivate_user" => Text(p, "userId"),
                    _ => "",
                }),
                ("to", operation == "send_direct" ? Joined(p, "to") : ""),
                ("stream", operation == "send_stream" ? Text(p, "stream") : ""),
                ("topic", operation == "send_stream" ? Text(p, "topic") : operation == "update_message" ? Text(more, "topic") : ""),
                ("content", operation is "send_stream" or "send_direct" ? Text(p, "content") : operation == "update_message" ? Text(more, "content") : ""),
                ("propagate_mode", operation == "update_message" ? Text(more, "propagateMode") switch { "changeLater" => "change_later", "changeAll" => "change_all", _ => "" } : ""),
                ("subscribers", operation == "subscriptions" && Text(more, "includeSubscribers") != "false" ? "true" : ""),
                ("name", operation == "create_stream" && subscriptions.Count > 0 ? Text(subscriptions[0], "name") : ""),
                ("description", operation == "create_stream" && subscriptions.Count > 0 ? Text(subscriptions[0], "description") : operation == "update_stream" ? Unquoted(Text(more, "description")) : ""),
                ("new_name", operation == "update_stream" ? Unquoted(Text(more, "newName")) : ""),
                ("private", operation == "create_stream" ? Text(more, "inviteOnly") : operation == "update_stream" ? Text(more, "isPrivate") : ""),
                ("principals", string.Join(",", principals)),
                ("announce", operation == "create_stream" ? Text(more, "announce") : ""),
                ("email", operation == "create_user" ? Text(p, "email") : ""),
                ("full_name", operation == "create_user" ? Text(p, "fullName") : operation == "update_user" ? Unquoted(Text(more, "fullName")) : ""),
                ("password", operation == "create_user" ? Text(p, "password") : ""),
                ("role", operation == "update_user" && ZulipRoles.TryGetValue(Text(more, "role"), out var role) ? role : ""),
                ("max", operation is "streams" or "users" ? Most(p, 100) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (subscriptions.Count > 1)
            {
                todo.Add("n8n subscribed to " + subscriptions.Count + " streams in one go - here a step makes one: the first is here, add a step for each other.");
            }

            if (Bool(p, "jsonParameters"))
            {
                todo.Add("n8n took this stream's fields as JSON - here give them as the step's own: its name, description, privacy, subscribers.");
            }

            if (operation == "update_user" && (Text(more, "isAdmin").Length > 0 || Text(more, "isGuest").Length > 0 || Find(more, "profileData").ValueKind != JsonValueKind.Undefined))
            {
                todo.Add("n8n set this user's admin or guest flags or profile fields - here a user's role is one of owner, administrator, moderator, member or guest: give the role.");
            }

            todo.Add(operation is "streams" or "subscriptions" or "users" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(ZulipConnection);
        }

        // n8n sent a Zulip update's names JSON-quoted - "\"Kafé\"" - as Zulip once asked; here a name is its text.
        private static string Unquoted(string value) => value.Length > 1 && value.StartsWith('"') && value.EndsWith('"') ? value[1..^1] : value;

        private const string MailerLiteConnection = "choose its connection - n8n's credentials stay in n8n: add a MailerLite connection under Admin > Connections (an API token from Integrations > MailerLite API) and pick it here.";

        // n8n's MailerLite node, both its versions: the subscriber's e-mail or id; its custom fields - the classic API's name
        // among them - as their JSON; its status (the classic API's type), its times and addresses as MailerLite names them
        // now, a resubscribe as the status active; Get Many's status and n8n's limit of 50; a resend of the autoresponders,
        // which has no counterpart, said.
        private static void MailerLite(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "updateFields") is { ValueKind: JsonValueKind.Object } update ? update : Find(p, "additionalFields");
            var filters = Find(p, "filters");
            var fields = new JsonObject();
            var expression = false;
            if (Text(more, "name") is { Length: > 0 } name)
            {
                expression = name.StartsWith('=');
                fields["name"] = Unmarked(name);
            }

            foreach (var item in Items(more, "customFieldsUi", "customFieldsValues"))
            {
                if (Text(item, "fieldId") is { Length: > 0 } key)
                {
                    expression |= Text(item, "value").StartsWith('=');
                    fields[key] = Unmarked(Text(item, "value"));
                }
            }

            static string Either(JsonElement holder, string now, string classic) => Text(holder, now) is { Length: > 0 } value ? value : Text(holder, classic);
            var lines = new List<(string Name, string Value)>
            {
                ("subscriber", operation is "subscriber" or "update_subscriber" ? Text(p, "subscriberId") : ""),
                ("email", operation == "create_subscriber" ? Text(p, "email") : ""),
                ("fields", fields.Count == 0 ? "" : (expression ? "=" : "") + fields.ToJsonString(ReadableJson)),
                ("status", operation == "subscribers" ? Either(filters, "status", "type") : Either(more, "status", "type") is { Length: > 0 } status ? status : Bool(more, "resubscribe") ? "active" : ""),
                ("subscribed_at", Either(more, "subscribed_at", "signup_timestamp")),
                ("ip_address", Either(more, "ip_address", "signup_ip")),
                ("opted_in_at", Either(more, "opted_in_at", "confirmation_timestamp")),
                ("optin_ip", Either(more, "optin_ip", "confirmation_ip")),
                ("unsubscribed_at", Text(more, "unsubscribed_at")),
                ("max", operation == "subscribers" ? Most(p, 50) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (Bool(more, "resend_autoresponders"))
            {
                todo.Add("n8n asked MailerLite's classic API to resend the autoresponders - here nothing does: MailerLite's automations run as they are set there.");
            }

            todo.Add(operation == "subscribers" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(MailerLiteConnection);
        }

        private const string MauticConnection = "choose its connection - n8n's credentials stay in n8n: add a Mautic connection under Admin > Connections (the instance's address, and a user's name and password with the API and its basic authentication on) and pick it here.";

        // n8n's Mautic node: the contact, company, segment, campaign and email; a contact's own fields as their parameters, its
        // address, social profiles, custom fields and the rest as its other fields by Mautic's aliases - its JSON body when
        // n8n took one - its tags, owner, stage, address and last activity; a company's name and fields as Mautic names them;
        // n8n's raw data (its default) or its simplified fields; Get Many's search, order and n8n's limit of 30; points added
        // or taken; a do-not-contact's channel, reason and comments; a minimal list said.
        private static void Mautic(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var contact = operation is "contacts" or "contact" or "create_contact" or "update_contact" or "delete_contact" or "add_do_not_contact" or "remove_do_not_contact";
            var company = operation is "companies" or "company" or "create_company" or "update_company" or "delete_company";
            var more = Find(p, operation is "update_contact" or "update_company" ? "updateFields" : "additionalFields");
            var options = Find(p, "options");
            var fields = new JsonObject();
            var expression = false;
            void Put(string key, JsonElement value)
            {
                switch (value.ValueKind)
                {
                    case JsonValueKind.String when value.GetString() is { Length: > 0 } text:
                        expression |= text.StartsWith('=');
                        fields[key] = Unmarked(text);
                        break;
                    case JsonValueKind.Number:
                        fields[key] = JsonNode.Parse(value.GetRawText());
                        break;
                    case JsonValueKind.True or JsonValueKind.False:
                        fields[key] = value.GetBoolean();
                        break;
                }
            }

            var address = Find(more, "addressUi", "addressValues");
            foreach (var (n8n, alias) in new[] { ("address1", "address1"), ("address2", "address2"), ("city", "city"), ("state", "state"), ("country", "country"), ("zipCode", "zipcode") })
            {
                Put(company ? "company" + alias : alias, Find(address, n8n));
            }

            var social = Find(more, "socialMediaUi", "socialMediaValues");
            foreach (var (n8n, alias) in new[] { ("facebook", "facebook"), ("foursquare", "foursquare"), ("instagram", "instagram"), ("linkedIn", "linkedin"), ("skype", "skype"), ("twitter", "twitter") })
            {
                Put(alias, Find(social, n8n));
            }

            var named = company
                ? new[] { ("companyEmail", "companyemail"), ("fax", "companyfax"), ("industry", "companyindustry"), ("numberOfEmpoyees", "companynumber_of_employees"), ("phone", "companyphone"), ("website", "companywebsite"), ("annualRevenue", "companyannual_revenue"), ("description", "companydescription"), ("isPublished", "isPublished") }
                : new[] { ("b2bOrb2c", "b2b_or_b2c"), ("crmId", "crm_id"), ("fax", "fax"), ("hasPurchased", "haspurchased"), ("prospectOrCustomer", "prospect_or_customer"), ("sandbox", "sandbox"), ("website", "website") };
            foreach (var (n8n, alias) in named)
            {
                Put(alias, Find(more, n8n));
            }

            foreach (var item in Items(more, "customFieldsUi", "customFieldValues"))
            {
                if (Text(item, "fieldId") is { Length: > 0 } key)
                {
                    Put(key, Find(item, "fieldValue"));
                }
            }

            // n8n's JSON body: the contact's fields by Mautic's aliases, as they are.
            var json = operation == "create_contact" ? Text(p, "bodyJson") : operation == "update_contact" ? Text(more, "bodyJson") : "";
            var other = fields.Count > 0 ? (expression ? "=" : "") + fields.ToJsonString(ReadableJson) : json.Length > 0 && (operation == "create_contact" ? Bool(p, "jsonParameters") : true) ? (json.StartsWith('=') ? json : Minified(json)) : "";
            if (fields.Count > 0 && json.Length > 0)
            {
                todo.Add("n8n took this contact's fields as JSON as well - here give them as the step's other fields, its JSON beside those.");
            }

            var people = operation == "create_contact" ? p : more;
            static string Joined(JsonElement holder, string name) => Find(holder, name) is { ValueKind: JsonValueKind.Array } items ? string.Join(",", items.EnumerateArray().Select(item => Text(item))) : Text(holder, name);
            var points = Text(p, "points");
            var lines = new List<(string Name, string Value)>
            {
                ("contact", contact || operation is "points" or "send_email" or "add_to_company" or "remove_from_company" or "add_to_segment" or "remove_from_segment" or "add_to_campaign" or "remove_from_campaign" ? Text(p, "contactId") : ""),
                ("company", company || operation is "add_to_company" or "remove_from_company" ? Text(p, "companyId") : ""),
                ("segment", Text(p, "segmentId")),
                ("campaign", Text(p, "campaignId")),
                ("email_id", operation == "send_email" ? Text(p, "campaignEmailId") : operation == "send_segment_email" ? Text(p, "segmentEmailId") : ""),
                ("name", operation == "create_company" ? Text(p, "name") : operation == "update_company" ? Text(more, "name") : ""),
                ("email", operation is "create_contact" or "update_contact" ? Text(people, "email") : ""),
                ("firstname", operation is "create_contact" or "update_contact" ? Text(people, "firstName") : ""),
                ("lastname", operation is "create_contact" or "update_contact" ? Text(people, "lastName") : ""),
                ("company", operation is "create_contact" or "update_contact" ? Text(people, "company") : ""),
                ("position", operation is "create_contact" or "update_contact" ? Text(people, "position") : ""),
                ("title", operation is "create_contact" or "update_contact" ? Text(people, "title") : ""),
                ("phone", company ? "" : Text(more, "phone")),
                ("mobile", Text(more, "mobile")),
                ("tags", Joined(more, "tags")),
                ("owner", Text(more, "ownerId")),
                ("stage", Text(more, "stage")),
                ("ip_address", Text(more, "ipAddress")),
                ("last_active", Text(more, "lastActive")),
                ("fields", other),
                ("overwrite_with_blank", Bool(more, "overwriteWithBlank") ? "true" : ""),
                ("points", operation == "points" && points.Length > 0 ? Text(p, "action") == "remove" ? points.StartsWith('=') ? "=-" + points[1..] : "-" + points : points : ""),
                ("channel", operation is "add_do_not_contact" or "remove_do_not_contact" ? Text(p, "channel") : ""),
                ("reason", operation == "add_do_not_contact" ? Text(more, "reason") switch { "1" => "unsubscribed", "2" => "bounced", "3" => "manual", _ => "" } : ""),
                ("comments", operation == "add_do_not_contact" ? Text(more, "comments") : ""),
                ("search", operation == "contacts" ? Text(options, "search") : operation == "companies" ? Text(more, "search") : ""),
                ("order_by", operation == "contacts" ? Regex.Replace(Text(options, "orderBy"), "(?<=[a-z0-9])([A-Z])", "_$1").ToLowerInvariant() : operation == "companies" ? Text(more, "orderBy") : ""),
                ("order_dir", operation == "contacts" ? Text(options, "orderByDir") : operation == "companies" ? Text(more, "orderByDir") : ""),
                ("published_only", operation == "contacts" && Bool(options, "publishedOnly") ? "true" : ""),
                ("raw", contact ? Text(options, "rawData") != "false" ? "true" : "" : company && Text(p, "simple") == "false" ? "true" : ""),
                ("max", operation is "contacts" or "companies" ? Most(p, 30) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (operation == "contacts" && Bool(options, "minimal"))
            {
                todo.Add("n8n asked Mautic for minimal contacts - here a contact is its fields: set raw for the whole of it.");
            }

            todo.Add(operation is "contacts" or "companies" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(MauticConnection);
        }

        private const string NetlifyConnection = "choose its connection - n8n's credentials stay in n8n: add a Netlify connection under Admin > Connections (a personal access token from User settings > Applications) and pick it here.";

        // n8n's Netlify node: the site and the deploy - a deploy found by its id alone here; a new deploy's title and branch;
        // Get Many's n8n limit of 50.
        private static void Netlify(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "additionalFields");
            var lines = new List<(string Name, string Value)>
            {
                ("site", operation is "deploy" or "cancel_deploy" or "sites" ? "" : Text(p, "siteId")),
                ("deploy", operation is "deploy" or "cancel_deploy" ? Text(p, "deployId") : ""),
                ("title", operation == "create_deploy" ? Text(more, "title") : ""),
                ("branch", operation == "create_deploy" ? Text(more, "branch") : ""),
                ("max", operation is "sites" or "deploys" ? Most(p, 50) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "sites" or "deploys" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(NetlifyConnection);
