        private const string RocketChatConnection = "choose its connection - n8n's credentials stay in n8n: add a Rocket.Chat connection under Admin > Connections (the server's address, a user's id and a personal access token from My Account > Personal Access Tokens) and pick it here.";

        // A Rocket.Chat attachment's fields as its API names them - n8n's own names turned.
        private static readonly (string N8n, string Api)[] RocketChatAttachment =
        {
            ("color", "color"), ("text", "text"), ("ts", "ts"), ("thumbUrl", "thumb_url"), ("messageLink", "message_link"), ("collapsed", "collapsed"),
            ("authorName", "author_name"), ("authorLink", "author_link"), ("authorIcon", "author_icon"), ("title", "title"), ("titleLink", "title_link"),
            ("titleLinkDownload", "title_link_download"), ("imageUrl", "image_url"), ("audioUrl", "audio_url"), ("videoUrl", "video_url"),
        };

        // n8n's Rocket.Chat node: the channel, the text, an alias, an emoji, an avatar; its attachments as the API names their
        // fields - its message link too, which n8n's node drops - or its attachments' JSON; the room; a direct conversation's
        // messages with n8n's limit of 50.
        private static void RocketChat(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var options = Find(p, "options");
            var expression = false;
            JsonNode? Value(JsonElement value)
            {
                switch (value.ValueKind)
                {
                    case JsonValueKind.String:
                        var text = value.GetString() ?? "";
                        expression |= text.StartsWith('=');
                        return Unmarked(text);
                    case JsonValueKind.True or JsonValueKind.False:
                        return value.GetBoolean();
                    case JsonValueKind.Number:
                        return JsonNode.Parse(value.GetRawText());
                    default:
                        return null;
                }
            }

            var attachments = new JsonArray();
            if (operation == "post_message" && !Bool(p, "jsonParameters") && Find(p, "attachments") is { ValueKind: JsonValueKind.Array } given)
            {
                foreach (var item in given.EnumerateArray().Where(item => item.ValueKind == JsonValueKind.Object))
                {
                    var attachment = new JsonObject();
                    foreach (var (n8n, api) in RocketChatAttachment)
                    {
                        if (Find(item, n8n) is { ValueKind: not JsonValueKind.Undefined } value && Value(value) is { } node && !(node is JsonValue text && text.TryGetValue<string>(out var s) && s.Length == 0))
                        {
                            attachment[api] = node;
                        }
                    }

                    var fields = new JsonArray(Items(item, "fields", "fieldsValues").Select(field => (JsonNode?)new JsonObject { ["short"] = Bool(field, "short"), ["title"] = Value(Find(field, "title")), ["value"] = Value(Find(field, "value")) }).ToArray());
                    if (fields.Count > 0)
                    {
                        attachment["fields"] = fields;
                    }

                    if (attachment.Count > 0)
                    {
                        attachments.Add(attachment);
                    }
                }
            }

            var json = Text(p, "attachmentsJson");
            var lines = new List<(string Name, string Value)>
            {
                ("channel", operation == "post_message" ? Text(p, "channel") : ""),
                ("text", operation == "post_message" ? Text(p, "text") : ""),
                ("alias", operation == "post_message" ? Text(options, "alias") : ""),
                ("emoji", operation == "post_message" ? Text(options, "emoji") : ""),
                ("avatar", operation == "post_message" ? Text(options, "avatar") : ""),
                ("attachments", attachments.Count > 0 ? (expression ? "=" : "") + attachments.ToJsonString(ReadableJson) : operation == "post_message" && Bool(p, "jsonParameters") && json.Length > 0 ? json.StartsWith('=') ? json : Minified(json) : ""),
                ("room", operation is "messages" or "mark_read" ? Text(p, "roomId") : ""),
                ("kind", operation == "messages" ? "dm" : ""),
                ("max", operation == "messages" ? Most(p, 50) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "messages" or "subscriptions" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(RocketChatConnection);
        }

        private const string JenkinsConnection = "choose its connection - n8n's credentials stay in n8n: add a Jenkins connection under Admin > Connections (the server's address, a user's name and an API token from the user's Security page) and pick it here.";

        // n8n's Jenkins node: the job; a Trigger with Parameters' names and values as a JSON object; a copy's new name; a new
        // job's name and its config.xml on one line - its line breaks as the character reference XML reads the same, unless a
        // CDATA section holds one, which is said; a quiet-down's reason; Get Many's n8n limit of 50.
        private static void Jenkins(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var parameters = new JsonObject();
            var expression = false;
            if (Text(p, "operation") == "triggerParams")
            {
                foreach (var item in Items(p, "param", "params"))
                {
                    if (Text(item, "name") is { Length: > 0 } name)
                    {
                        expression |= Text(item, "value").StartsWith('=');
                        parameters[name] = Unmarked(Text(item, "value"));
                    }
                }
            }

            var xml = operation == "create_job" ? Text(p, "xml") : "";
            var cdata = xml.Contains("<![CDATA[", StringComparison.Ordinal) && xml.Contains('\n');
            var lines = new List<(string Name, string Value)>
            {
                ("job", operation is "build" or "copy_job" or "builds" ? Text(p, "job") : ""),
                ("parameters", parameters.Count == 0 ? "" : (expression ? "=" : "") + parameters.ToJsonString(ReadableJson)),
                ("new_job", operation is "copy_job" or "create_job" ? Text(p, "newJob") : ""),
                ("config", xml.Length == 0 || cdata ? "" : xml.StartsWith('=') ? xml : xml.Trim().Replace("\r\n", "\n").Replace("\n", "&#10;")),
                ("reason", operation == "quiet_down" ? Text(p, "reason") : ""),
                ("max", operation == "builds" ? Most(p, 50) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (cdata)
            {
                todo.Add("n8n created this job from a config.xml with a CDATA section across lines - here a step's config is one line: paste it with its line breaks as &#10; outside the CDATA, or keep the job's script in a file.");
            }

            todo.Add(operation == "builds" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(JenkinsConnection);
        }

        private const string KitConnection = "choose its connection - n8n's credentials stay in n8n: add a Kit connection under Admin > Connections (a V4 API key from Settings > Developer - Kit's API v4, not ConvertKit's v3 secret) and pick it here.";

        // n8n's ConvertKit node, Kit's API v4 now: the form, sequence, tag and custom field; the subscriber's e-mail; a tag's
        // name - the first of n8n's comma-separated ones, the others said; a custom field's label; Get Subscriptions' state;
        // n8n's limit of 100. A subscriber n8n created as it added them - with a first name, fields or tags - must exist first
        // in Kit's v4: said; a custom field's Get read as the list, said.
        private static void Kit(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "additionalFields");
            var names = Text(p, "name").Split(',', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries);
            var lines = new List<(string Name, string Value)>
            {
                ("form", operation is "add_to_form" or "form_subscribers" ? Text(p, "id") : ""),
                ("sequence", operation is "add_to_sequence" or "sequence_subscribers" ? Text(p, "id") : ""),
                ("tag", operation is "tag_subscriber" or "tag_subscribers" or "untag_subscriber" ? Text(p, "tagId") : ""),
                ("custom_field", operation is "update_custom_field" or "delete_custom_field" ? Text(p, "id") : ""),
                ("email", operation is "add_to_form" or "add_to_sequence" or "tag_subscriber" or "untag_subscriber" ? Text(p, "email") : ""),
                ("name", operation == "create_tag" && names.Length > 0 ? names[0] : ""),
                ("label", operation is "create_custom_field" or "update_custom_field" ? Text(p, "label") : ""),
                ("status", operation is "form_subscribers" or "sequence_subscribers" or "tag_subscribers" ? Text(more, "subscriberState") : ""),
                ("max", operation is "forms" or "form_subscribers" or "sequences" or "sequence_subscribers" or "tags" or "tag_subscribers" or "custom_fields" ? Most(p, 100) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (operation is "add_to_form" or "add_to_sequence" or "tag_subscriber"
                && (Text(more, "firstName").Length > 0 || Items(more, "fieldsUi", "fieldsValues").Any() || Items(more, "fields", "field").Any() || Find(more, "tags").ValueKind == JsonValueKind.Array))
            {
                todo.Add("n8n created the subscriber with a first name, fields or tags as it added them - in Kit's API v4 a subscriber must exist first: put a Create a subscriber step before this one with them, and a Tag a subscriber step for each tag.");
            }

            if (names.Length > 1)
            {
                todo.Add("n8n created " + names.Length + " tags in one go - here a step creates one: the first is here, add a step for each other.");
            }

            if (operation == "custom_fields" && Text(p, "operation") == "get")
            {
                todo.Add("n8n got one custom field - here the custom fields are read: pick it by its id from them.");
            }

            todo.Add(operation is "forms" or "form_subscribers" or "sequences" or "sequence_subscribers" or "tags" or "tag_subscribers" or "custom_fields" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(KitConnection);
        }

        private const string MatrixConnection = "choose its connection - n8n's credentials stay in n8n: add a Matrix connection under Admin > Connections (the homeserver's address and an access token - Element: Settings > Help & About) and pick it here.";

        // n8n's Matrix node: the room - an alias for a join; a message's text and type, its HTML with the fallback text as its
        // plain text - a line break a space on the one line a parameter takes, said; Get Many's filter and n8n's limit of 100;
        // a new room's name, n8n's preset - public unless it says private - and alias; the user invited or kicked and a kick's
        // reason; the event; the members' membership and the one left out.
        private static void Matrix(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var html = operation == "send_message" && Text(p, "messageFormat") == "org.matrix.custom.html";
            var text = operation == "send_message" ? html && Text(p, "fallbackText") is { Length: > 0 } fallback ? fallback : Text(p, "text") : "";
            var broken = false;
            string Line(string value)
            {
                if (value.StartsWith('=') || !(value.Contains('\n') || value.Contains('\r')))
                {
                    return value;
                }

                broken = true;
                return string.Join(" ", value.Split(new[] { "\r\n", "\n", "\r" }, StringSplitOptions.None));
            }

            var filter = operation == "messages" ? Text(Find(p, "otherOptions"), "filter") : "";
            var filters = Find(p, "filters");
            var lines = new List<(string Name, string Value)>
            {
                ("room", operation switch { "join_room" => Text(p, "roomIdOrAlias"), "me" or "create_room" => "", _ => Text(p, "roomId") }),
                ("text", Line(text)),
                ("html", html ? Line(Text(p, "text")) : ""),
                ("type", operation == "send_message" && Text(p, "messageType") is { Length: > 0 } type && type != "m.text" ? type : ""),
                ("filter", filter.Length == 0 || filter.StartsWith('=') ? filter : Minified(filter)),
                ("max", operation == "messages" ? Most(p, 100) : ""),
                ("name", operation == "create_room" ? Text(p, "roomName") : ""),
                ("preset", operation == "create_room" ? Text(p, "preset") is { Length: > 0 } preset ? preset : "public_chat" : ""),
                ("alias", operation == "create_room" ? Text(p, "roomAlias") : ""),
                ("user", operation is "invite" or "kick" ? Text(p, "userId") : ""),
                ("reason", operation == "kick" ? Text(p, "reason") : ""),
                ("event", operation == "event" ? Text(p, "eventId") : ""),
                ("membership", operation == "members" ? Text(filters, "membership") : ""),
                ("not_membership", operation == "members" ? Text(filters, "notMembership") : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (broken)
            {
                todo.Add("n8n's message has line breaks - a step's parameter is one line: here each is a space; read the text from the record ({{ $json.text }}) to keep them.");
            }

            if (html && Text(p, "fallbackText").Length == 0)
            {
                todo.Add("n8n sent its HTML with no fallback text - here the HTML is the plain text too: give the text as plain text.");
            }

            todo.Add(operation is "messages" or "members" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(MatrixConnection);
        }

        private const string SentryConnection = "choose its connection - n8n's credentials stay in n8n: add a Sentry connection under Admin > Connections (sentry.io's address - a region's or a self-hosted server's - and an auth token from User Settings > Personal Tokens) and pick it here.";

        // n8n's Sentry.io node: the organization, project, team, issue, event and version; Get Many's filters and n8n's limit of
        // 100 - an event's Full on unless n8n says off; an issue's update fields; a project's, an organization's and a team's
        // name and slug; a release's address, projects, date, commits - their patch sets too, which n8n's node drops - and
        // refs. A project moved to another team has no counterpart: said.
        private static void Sentry(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "additionalFields");
            var update = Find(p, "updateFields");
            var fields = operation is "update_organization" or "update_project" or "update_team" or "update_release" ? update : more;
            var expression = false;
            string Value(string value)
            {
                expression |= value.StartsWith('=');
                return Unmarked(value);
            }

            JsonArray Commits() => new(Items(fields, "commits", "commitProperties").Select(commit =>
            {
                var item = new JsonObject();
                foreach (var (n8n, api) in new[] { ("id", "id"), ("repository", "repository"), ("message", "message"), ("authorName", "author_name"), ("authorEmail", "author_email"), ("timestamp", "timestamp") })
                {
                    if (Text(commit, n8n) is { Length: > 0 } value)
                    {
                        item[api] = Value(value);
                    }
                }

                var patches = new JsonArray(Items(commit, "patchSet", "patchSetProperties").Where(patch => Text(patch, "path").Length > 0).Select(patch =>
                    (JsonNode?)new JsonObject { ["path"] = Value(Text(patch, "path")), ["type"] = Text(patch, "type") switch { "delete" => "D", "modify" => "M", _ => "A" } }).ToArray());
                if (patches.Count > 0)
                {
                    item["patch_set"] = patches;
                }

                return (JsonNode?)item;
            }).ToArray());
            JsonArray Refs() => new(Items(fields, "refs", "refProperties").Select(reference =>
            {
                var item = new JsonObject();
                foreach (var name in new[] { "repository", "commit", "previousCommit" })
                {
                    if (Text(reference, name) is { Length: > 0 } value)
                    {
                        item[name] = Value(value);
                    }
                }

                return (JsonNode?)item;
            }).ToArray());
            var release = operation is "create_release" or "update_release";
            var commits = release ? Commits() : new JsonArray();
            var refs = release ? Refs() : new JsonArray();
            var projects = Find(p, "projects") is { ValueKind: JsonValueKind.Array } chosen ? string.Join(",", chosen.EnumerateArray().Select(project => project.ValueKind == JsonValueKind.String ? project.GetString() : project.GetRawText())) : Text(p, "projects");
            var lines = new List<(string Name, string Value)>
            {
                ("organization", operation is "issue" or "update_issue" or "delete_issue" or "organizations" or "projects" ? "" : operation == "update_organization" ? Text(p, "organization_slug") : Text(p, "organizationSlug")),
                ("project", operation is "event" or "events" or "issues" or "project" or "update_project" or "delete_project" ? Text(p, "projectSlug") : ""),
                ("team", operation is "create_project" or "team" or "update_team" or "delete_team" ? Text(p, "teamSlug") : ""),
                ("issue", operation is "issue" or "update_issue" or "delete_issue" ? Text(p, "issueId") : ""),
                ("event", operation == "event" ? Text(p, "eventId") : ""),
                ("version", operation is "release" or "create_release" or "update_release" or "delete_release" ? Text(p, "version") : ""),
                ("full", operation == "events" ? Text(p, "full") is { Length: > 0 } full ? full : "true" : ""),
                ("query", operation is "issues" or "releases" ? Text(more, "query") : ""),
                ("stats_period", operation == "issues" ? Text(more, "statsPeriod") : ""),
                ("short_id_lookup", operation == "issues" ? Text(more, "shortIdLookUp") : ""),
                ("member", operation == "organizations" ? Text(more, "member") : ""),
                ("owner", operation == "organizations" ? Text(more, "owner") : ""),
                ("status", operation == "update_issue" ? Text(more, "status") : ""),
                ("assigned_to", operation == "update_issue" ? Text(more, "assignedTo") : ""),
                ("has_seen", operation == "update_issue" ? Text(more, "hasSeen") : ""),
                ("is_bookmarked", operation is "update_issue" or "update_project" ? Text(fields, "isBookmarked") : ""),
                ("is_subscribed", operation == "update_issue" ? Text(more, "isSubscribed") : ""),
                ("is_public", operation == "update_issue" ? Text(more, "isPublic") : ""),
                ("name", operation is "create_project" or "create_team" ? Text(p, "name") : operation is "update_organization" or "update_project" or "update_team" ? Text(update, "name") : ""),
                ("slug", operation is "create_project" or "create_team" ? Text(more, "slug") : operation is "update_organization" or "update_project" or "update_team" ? Text(update, "slug") : ""),
                ("platform", operation == "update_project" ? Text(update, "platform") : ""),
                ("digests_min_delay", operation == "update_project" ? Text(update, "digestsMinDelay") : ""),
                ("digests_max_delay", operation == "update_project" ? Text(update, "digestsMaxDelay") : ""),
                ("projects", operation == "create_release" ? projects : ""),
                ("url", operation == "create_release" ? Text(p, "url") : operation == "update_release" ? Text(update, "url") : ""),
                ("date_released", release ? Text(fields, "dateReleased") : ""),
                ("ref", operation == "update_release" ? Text(update, "ref") : ""),
                ("commits", commits.Count == 0 ? "" : (expression ? "=" : "") + commits.ToJsonString(ReadableJson)),
                ("refs", refs.Count == 0 ? "" : (expression ? "=" : "") + refs.ToJsonString(ReadableJson)),
                ("max", operation is "events" or "issues" or "organizations" or "projects" or "releases" or "teams" ? Most(p, 100) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (operation == "update_project" && Text(update, "team").Length > 0)
            {
                todo.Add("n8n moved the project to another team - Sentry's API no longer does: move it in Sentry's project settings.");
            }

            todo.Add(operation is "events" or "issues" or "organizations" or "projects" or "releases" or "teams" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(SentryConnection);
        }

        private const string DiscourseConnection = "choose its connection - n8n's credentials stay in n8n: add a Discourse connection under Admin > Connections (the forum's address, the API username and an API key from Admin > Advanced > API keys) and pick it here.";

        // n8n's Discourse node: a post's content, title, category, topic and the post it replies to; a post's id and an edit's
        // reason; a category's name and colours - n8n's 0000FF when it names none; a group's name and id; a user by name or
        // SSO external id, a new user's name, e-mail, user name and flags - a password written in the workflow left out, said;
        // the users' list's flag, order and switches; the user names a group gains or loses; n8n's limit of 50.
        private static void Discourse(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "additionalFields");
            var update = Find(p, "updateFields");
            var options = Find(p, "options");
            var password = operation == "create_user" ? Text(p, "password") : "";
            var byExternal = operation == "user" && Text(p, "by") == "externalId";
            string Colour(JsonElement holder, string name, bool create) => Text(holder, name) is { Length: > 0 } colour ? colour : create ? "0000FF" : "";
            var lines = new List<(string Name, string Value)>
            {
                ("post", operation is "post" or "update_post" ? Text(p, "postId") : ""),
                ("content", operation is "create_post" or "update_post" ? Text(p, "content") : ""),
                ("title", operation == "create_post" ? Text(p, "title") : ""),
                ("category", operation == "create_post" ? Text(more, "category") : operation == "update_category" ? Text(p, "categoryId") : ""),
                ("topic", operation == "create_post" ? Text(more, "topic_id") : ""),
                ("reply_to", operation == "create_post" ? Text(more, "reply_to_post_number") : ""),
                ("edit_reason", operation == "update_post" ? Text(update, "edit_reason") : ""),
                ("group", operation is "update_group" or "add_to_group" or "remove_from_group" ? Text(p, "groupId") : ""),
                ("name", operation is "create_category" or "update_category" or "group" or "create_group" or "update_group" or "create_user" ? Text(p, "name") : ""),
                ("color", operation == "create_category" ? Colour(p, "color", true) : operation == "update_category" ? Colour(update, "color", false) : ""),
                ("text_color", operation == "create_category" ? Colour(p, "textColor", true) : operation == "update_category" ? Colour(update, "textColor", false) : ""),
                ("usernames", operation is "add_to_group" or "remove_from_group" ? Text(p, "usernames") : ""),
                ("email", operation == "create_user" ? Text(p, "email") : ""),
                ("username", operation == "create_user" || (operation == "user" && !byExternal) ? Text(p, "username") : ""),
                ("external_id", byExternal ? Text(p, "externalId") : ""),
                ("password", password.StartsWith('=') ? password : ""),
                ("active", operation == "create_user" ? Text(more, "active") : ""),
                ("approved", operation == "create_user" ? Text(more, "approved") : ""),
                ("flag", operation == "users" ? Text(p, "flag") : ""),
                ("order", operation == "users" ? Text(options, "order") : ""),
                ("ascending", operation == "users" ? Text(options, "asc") : ""),
                ("show_emails", operation == "users" ? Text(options, "showEmails") : ""),
                ("stats", operation == "users" ? Text(options, "stats") : ""),
                ("max", operation is "posts" or "categories" or "groups" or "users" ? Most(p, 50) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (password.Length > 0 && !password.StartsWith('='))
            {
                todo.Add("n8n's workflow held the new user's password in plain text - it is left out here: read it from the record ({{ $json.password }}) in the step's parameters.");
            }

            if (operation == "update_post" && Text(update, "cooked") == "true")
            {
                todo.Add("n8n's Cooked asked Discourse to keep the content as written HTML - Discourse renders a post from its content itself: give it as Markdown.");
            }

            todo.Add(operation is "posts" or "categories" or "groups" or "users" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(DiscourseConnection);
        }

        private const string ZammadConnection = "choose its connection - n8n's credentials stay in n8n: add a Zammad connection under Admin > Connections (the help desk's address and an access token from Profile > Token Access - a user's name and password are not used) and pick it here.";

        // n8n's Zammad node: the id; a user's, an organization's and a group's fields - a user's address as its own fields; a
        // ticket's title, group and customer, its first article's subject, body, type, sender and addresses, internal unless
        // n8n says external; an update's title, group, state, priority, owner, customer, pending time and note; custom fields
        // as a JSON object of names and values; the users' search and sort; n8n's limit of 50.
        private static void Zammad(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var create = operation.StartsWith("create_", StringComparison.Ordinal);
            var fields = create ? Find(p, "additionalFields") : Find(p, "updateFields");
            var article = Find(Find(p, "article"), "articleDetails");
            var filters = Find(p, "filters");
            static JsonElement One(JsonElement holder, params string[] path) => Find(holder, path) is { ValueKind: JsonValueKind.Array } list ? list.EnumerateArray().FirstOrDefault() : Find(holder, path);
            var sort = One(filters, "sortUi", "sortDetails");
            var address = One(fields, "addressUi", "addressDetails");
            var expression = false;
            var custom = new JsonObject();
            foreach (var pair in Items(fields, "customFieldsUi", "customFieldPairs"))
            {
                if (Text(pair, "name") is { Length: > 0 } name)
                {
                    expression |= Text(pair, "value").StartsWith('=');
                    custom[name] = Unmarked(Text(pair, "value"));
                }
            }

            var kind = operation[(operation.IndexOf('_') + 1)..];
            var lines = new List<(string Name, string Value)>
            {
                ("id", operation is "ticket" or "user" or "organization" or "group" || operation.StartsWith("update_", StringComparison.Ordinal) || operation.StartsWith("delete_", StringComparison.Ordinal) ? Text(p, "id") : ""),
                ("query", operation == "users" ? Text(filters, "query") : ""),
                ("sort_by", operation == "users" && sort.ValueKind == JsonValueKind.Object ? Text(sort, "sort_by") : ""),
                ("order_by", operation == "users" && sort.ValueKind == JsonValueKind.Object ? Text(sort, "order_by") : ""),
                ("title", operation == "create_ticket" ? Text(p, "title") : operation == "update_ticket" ? Text(fields, "title") : ""),
                ("group", operation == "create_ticket" ? Text(p, "group") : operation == "update_ticket" ? Text(fields, "group") : ""),
                ("customer", operation == "create_ticket" ? Text(p, "customer") : operation == "update_ticket" ? Text(fields, "customer_id") : ""),
                ("state", operation == "update_ticket" ? Text(fields, "state_id") : ""),
                ("priority", operation == "update_ticket" ? Text(fields, "priority_id") : ""),
                ("owner", operation == "update_ticket" ? Text(fields, "owner_id") : ""),
                ("pending_time", operation == "update_ticket" ? Text(fields, "pending_time") : ""),
                ("note", operation == "update_ticket" ? Text(fields, "note") : ""),
                ("subject", operation == "create_ticket" ? Text(article, "subject") : ""),
                ("body", operation == "create_ticket" ? Text(article, "body") : ""),
                ("type", operation == "create_ticket" && Text(article, "type") is { Length: > 0 } type && type != "note" ? type : ""),
                ("internal", operation == "create_ticket" && Text(article, "visibility") == "external" ? "false" : ""),
                ("sender", operation == "create_ticket" && Text(article, "sender") is { Length: > 0 } sender && sender != "Agent" ? sender : ""),
                ("to", operation == "create_ticket" ? Text(article, "to") : ""),
                ("cc", operation == "create_ticket" ? Text(article, "cc") : ""),
                ("reply_to", operation == "create_ticket" ? Text(article, "reply_to") : ""),
            };
            if (kind is "user" or "organization" or "group" && (create || operation.StartsWith("update_", StringComparison.Ordinal)))
            {
                string[] names = kind switch
                {
                    "user" => new[] { "firstname", "lastname", "email", "organization", "phone", "mobile", "fax", "department", "web", "note", "active", "verified", "vip" },
                    "organization" => new[] { "name", "domain", "note", "shared", "domain_assignment", "active", "vip" },
                    _ => new[] { "name", "note", "active" },
                };
                foreach (var name in names)
                {
                    var holder = create && name is "firstname" or "lastname" && kind == "user" || create && name == "name" ? p : fields;
                    lines.Add((name, Text(holder, name)));
                }

                if (kind == "user" && address.ValueKind == JsonValueKind.Object)
                {
                    lines.Add(("street", Text(address, "address")));
                    lines.Add(("zip", Text(address, "zip")));
                    lines.Add(("city", Text(address, "city")));
                    lines.Add(("country", Text(address, "country")));
                }
            }

            lines.Add(("fields", custom.Count == 0 ? "" : (expression ? "=" : "") + custom.ToJsonString(ReadableJson)));
            lines.Add(("max", operation is "tickets" or "users" or "organizations" or "groups" ? Most(p, 50) : ""));
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "tickets" or "users" or "organizations" or "groups" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(ZammadConnection);
        }

        private const string PushoverConnection = "choose its connection - n8n's credentials stay in n8n: add a Pushover connection under Admin > Connections (an application's API token from Your Applications) and pick it here.";

        // n8n's Pushover node: the user key, the message, n8n's priority - its lowest, -2, when the export names none - an
        // emergency's retry and expire (n8n's 30 seconds each when it names none), the title, address and its title, device,
        // sound, HTML, time and time to live. An attachment has no counterpart here: said.
        private static void Pushover(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            Set(step, "Operation", "push");
            var more = Find(p, "additionalFields");
            var priority = Text(p, "priority") is { Length: > 0 } given ? given : "-2";
            var emergency = priority == "2";
            Set(step, "Parameters", FtpParameters(new (string Name, string Value)[]
            {
                ("user", Text(p, "userKey")),
                ("message", Text(p, "message")),
                ("title", Text(more, "title")),
                ("priority", priority),
                ("retry", emergency ? Text(p, "retry") is { Length: > 0 } retry ? retry : "30" : ""),
                ("expire", emergency ? Text(p, "expire") is { Length: > 0 } expire ? expire : "30" : ""),
                ("url", Text(more, "url")),
                ("url_title", Text(more, "url_title")),
                ("device", Text(more, "device")),
                ("sound", Text(more, "sound")),
                ("html", Text(more, "html") == "true" ? "true" : ""),
                ("timestamp", Text(more, "timestamp")),
                ("ttl", Text(more, "ttl")),
            }.Where(line => line.Value.Length > 0).ToArray()));
            if (Find(more, "attachmentsUi").ValueKind == JsonValueKind.Object)
            {
                todo.Add("n8n attached a file to the message - a step here sends text: put the file where an address reaches it and give that address.");
            }

            todo.Add(PerItem);
            todo.Add(PushoverConnection);
        }

        private const string GotifyConnection = "choose its connection - n8n's credentials stay in n8n: add a Gotify connection under Admin > Connections (the server's address, an application's token to send and a client's token to read and delete) and pick it here.";

        // n8n's Gotify node: a message's text, title, priority, content type, click address, big image and Android intent; the
        // message deleted; Get Many with n8n's limit of 20.
        private static void Gotify(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "additionalFields");
            var options = Find(p, "options");
            var create = operation == "create_message";
            Set(step, "Parameters", FtpParameters(new (string Name, string Value)[]
            {
                ("message", create ? Text(p, "message") : ""),
                ("title", create ? Text(more, "title") : ""),
                ("priority", create ? Text(more, "priority") : ""),
                ("content_type", create && Text(options, "contentType") is { Length: > 0 } type && type != "text/plain" ? type : ""),
                ("click_url", create ? Text(options, "clickUrl") : ""),
                ("big_image_url", create ? Text(options, "bigImageUrl") : ""),
                ("intent_url", create ? Text(options, "intentUrl") : ""),
                ("id", operation == "delete_message" ? Text(p, "messageId") : ""),
                ("max", operation == "messages" ? Most(p, 20) : ""),
            }.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation == "messages" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(GotifyConnection);
        }

        private const string UptimeRobotConnection = "choose its connection - n8n's credentials stay in n8n: add an UptimeRobot connection under Admin > Connections (the main API key from Integrations & API > API) and pick it here.";

        // n8n's UptimeRobot node: the id; Get Many's filters - ids, a search, statuses and types by UptimeRobot's numbers, the
        // switches - and n8n's limit of 50; a monitor's name, address, type and update fields; an alert contact's name, type and
        // value; a maintenance window's name, type, duration, days and start - a once window's moment, another's time of day as
        // n8n wrote it; a status page's name, monitors, domain and sort. A password - a monitored site's, a status page's - is
        // never a step's parameter: left out, said.
        private static void UptimeRobot(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var filters = Find(p, "filters");
            var update = Find(p, "updateFields");
            var more = Find(p, "additionalFields");
            string Joined(JsonElement holder, string name) => Find(holder, name) is { ValueKind: JsonValueKind.Array } list ? string.Join(",", list.EnumerateArray().Select(item => item.ValueKind == JsonValueKind.String ? item.GetString() : item.GetRawText())) : Text(holder, name);
            string Flag(JsonElement holder, string name) => Text(holder, name) == "true" ? "true" : "";
            var window = operation is "create_maintenance_window" or "update_maintenance_window";
            var fields = operation == "create_maintenance_window" ? p : update;
            var windowType = window ? Text(fields, "type") : "";
            var start = window ? Text(fields, "start_time") : "";
            var lines = new List<(string Name, string Value)>
            {
                ("id", operation is "monitor" or "update_monitor" or "reset_monitor" or "delete_monitor" or "alert_contact" or "update_alert_contact" or "delete_alert_contact"
                    or "maintenance_window" or "update_maintenance_window" or "delete_maintenance_window" or "status_page" or "delete_status_page" ? Text(p, "id") : ""),
                ("ids", operation switch { "monitors" => Text(filters, "monitors"), "alert_contacts" => Text(filters, "alert_contacts"), "maintenance_windows" => Text(filters, "mwindow"), "status_pages" => Text(filters, "psps"), _ => "" }),
                ("search", operation == "monitors" ? Text(filters, "search") : ""),
                ("statuses", operation == "monitors" ? Joined(filters, "statuses") : ""),
                ("types", operation == "monitors" ? Joined(filters, "types") : ""),
                ("logs", operation == "monitors" ? Flag(filters, "logs") : ""),
                ("response_times", operation == "monitors" ? Flag(filters, "response_times") : ""),
                ("alert_contacts", operation == "monitors" ? Flag(filters, "alert_contacts") : ""),
                ("mwindows", operation == "monitors" ? Flag(filters, "mwindow") : ""),
                ("duration", window ? Text(p, "duration") is { Length: > 0 } duration ? duration : operation == "create_maintenance_window" ? "1" : "" : ""),
                ("friendly_name", operation is "create_monitor" or "create_alert_contact" or "create_maintenance_window" or "create_status_page" ? Text(p, "friendlyName")
                    : operation is "update_monitor" or "update_alert_contact" or "update_maintenance_window" ? Text(update, "friendly_name") : ""),
                ("url", operation == "create_monitor" ? Text(p, "url") : operation == "update_monitor" ? Text(update, "url") : ""),
                ("type", operation is "create_monitor" or "create_alert_contact" ? Text(p, "type") : window ? windowType : ""),
                ("sub_type", operation == "update_monitor" ? Text(update, "sub_type") : ""),
                ("port", operation == "update_monitor" ? Text(update, "port") : ""),
                ("interval", operation == "update_monitor" ? Text(update, "interval") : ""),
                ("http_method", operation == "update_monitor" ? Text(update, "http_method") : ""),
                ("status", operation == "update_monitor" ? Text(update, "status") switch { "0" => "paused", "1" => "active", _ => "" } : ""),
                ("value", operation == "create_alert_contact" ? Text(p, "value") : operation == "update_alert_contact" ? Text(update, "value")
                    : window ? windowType switch { "3" => Text(fields, "weekDay"), "4" => Text(fields, "monthDay") is { Length: > 0 } day ? day : "1", _ => "" } : ""),
                ("start_time", start.Length == 0 || windowType == "1" || start.StartsWith('=') ? start : start.Contains('T') && start.Length >= start.IndexOf('T') + 6 ? start.Substring(start.IndexOf('T') + 1, 5) : start),
                ("monitors", operation == "create_status_page" ? Text(p, "monitors") : ""),
                ("custom_domain", operation == "create_status_page" ? Text(more, "custom_domain") : ""),
                ("sort", operation == "create_status_page" ? Text(more, "sort") : ""),
                ("max", operation is "monitors" or "alert_contacts" or "maintenance_windows" or "status_pages" ? Most(p, 50) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if ((operation == "update_monitor" && (Text(update, "http_password").Length > 0 || Text(update, "http_username").Length > 0 || Text(update, "http_auth_type").Length > 0))
                || (operation == "create_status_page" && Text(more, "password").Length > 0))
            {
                todo.Add("n8n set a password - a monitored site's or a status page's - in the workflow: a password is never a step's parameter here, so it is left out: set it in UptimeRobot.");
            }

            if (window && windowType is not "" and not "1" && start.Length > 0 && !start.StartsWith('='))
            {
                todo.Add("n8n turned the start into a time of day in the workflow's time zone - here it is the time as n8n wrote it, which UptimeRobot reads in the account's: check it.");
            }

            todo.Add(operation is "monitors" or "alert_contacts" or "maintenance_windows" or "status_pages" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(UptimeRobotConnection);
        }

        private const string GrafanaConnection = "choose its connection - n8n's credentials stay in n8n: add a Grafana connection under Admin > Connections (the server's address and a service account's token from Administration > Service accounts) and pick it here.";

        // n8n's Grafana node: a dashboard's uid or address and title - a folder n8n chose by its id said, a folder here being its
        // uid - and Get Many's search; a team's id, name and e-mail and Get Many's name; a member's team and user; a user's id, a
        // role (n8n's Admin when it names none on an update) and a login or e-mail; n8n's limit of 50. n8n's dashboard update
        // replaced the dashboard with its title alone, dropping its panels; here they are kept: said.
        private static void Grafana(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "additionalFields");
            var update = Find(p, "updateFields");
            var filters = Find(p, "filters");
            var lines = new List<(string Name, string Value)>
            {
                ("dashboard", operation is "dashboard" or "update_dashboard" or "delete_dashboard" ? Text(p, "dashboardUidOrUrl") : ""),
                ("title", operation == "create_dashboard" ? Text(p, "title") : operation == "update_dashboard" ? Text(update, "title") : ""),
                ("query", operation == "dashboards" ? Text(filters, "query") : ""),
                ("team", operation is "team" or "update_team" or "delete_team" or "team_members" or "add_team_member" or "remove_team_member" ? Text(p, "teamId") : ""),
                ("name", operation == "create_team" ? Text(p, "name") : operation == "update_team" ? Text(update, "name") : operation == "teams" ? Text(filters, "name") : ""),
                ("email", operation == "create_team" ? Text(more, "email") : operation == "update_team" ? Text(update, "email") : ""),
                ("user", operation switch { "add_team_member" => Text(p, "userId"), "remove_team_member" => Text(p, "memberId"), "update_user" or "remove_user" => Text(p, "userId"), _ => "" }),
                ("login", operation == "add_user" ? Text(p, "loginOrEmail") : ""),
                ("role", operation == "add_user" ? Text(p, "role") : operation == "update_user" ? Find(update, "role").ValueKind == JsonValueKind.Undefined ? "" : Text(update, "role") is { Length: > 0 } role ? role : "Admin" : ""),
                ("max", operation is "dashboards" or "teams" or "team_members" or "users" ? Most(p, 50) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (Text(operation == "create_dashboard" ? more : update, "folderId").Length > 0 && operation is "create_dashboard" or "update_dashboard")
            {
                todo.Add("n8n chose the dashboard's folder by its id - here a folder is its uid: give it (folder), from the folder's address.");
            }

            if (operation == "update_dashboard")
            {
                todo.Add("n8n's update replaced the dashboard with its title alone, dropping its panels - here the dashboard is read and kept, its title changed: check that is what was meant.");
            }

            todo.Add(operation is "dashboards" or "teams" or "team_members" or "users" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(GrafanaConnection);
        }

        private const string OktaConnection = "choose its connection - n8n's credentials stay in n8n: add an Okta connection under Admin > Connections (the org's address and an API token from Security > API > Tokens) and pick it here.";

        // n8n's Okta attributes by its names and the connector's.
        private static readonly (string N8n, string Name)[] OktaAttributes =
        {
            ("firstName", "first_name"), ("lastName", "last_name"), ("email", "email"), ("login", "login"), ("secondEmail", "second_email"), ("middleName", "middle_name"),
            ("honorificPrefix", "honorific_prefix"), ("honorificSuffix", "honorific_suffix"), ("title", "title"), ("displayName", "display_name"), ("nickName", "nick_name"),
            ("profileUrl", "profile_url"), ("mobilePhone", "mobile_phone"), ("primaryPhone", "primary_phone"), ("streetAddress", "street_address"), ("city", "city"),
            ("state", "state"), ("zipCode", "zip_code"), ("countryCode", "country_code"), ("postalAddress", "postal_address"), ("preferredLanguage", "preferred_language"),
            ("locale", "locale"), ("timezone", "timezone"), ("userType", "user_type"), ("employeeNumber", "employee_number"), ("costCenter", "cost_center"),
            ("organization", "organization"), ("division", "division"), ("department", "department"), ("managerId", "manager_id"), ("manager", "manager"),
        };

        // n8n's Okta node: a user's id or login (n8n's From List, By username or ID); a new user's name, e-mail and login and the
        // attributes n8n offers beside them, unactivated when n8n said so; an update's fields; Get Many's search and n8n's limit
        // of 20; a deletion's e-mail. A password and a recovery question are never a step's parameters: left out, said. n8n's
        // Simplify cut a user to a few fields - here a record is the whole user: said.
        private static void Okta(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var fields = Find(p, operation == "create_user" ? "getCreateFields" : "getUpdateFields");
            var lines = new List<(string Name, string Value)>
            {
                ("user", operation is "user" or "update_user" or "delete_user" ? Locator(p, "userId") : ""),
                ("search", operation == "users" ? Text(p, "searchQuery") : ""),
            };
            if (operation is "create_user" or "update_user")
            {
                lines.AddRange(OktaAttributes.Select(attribute => (attribute.Name, operation == "create_user" && attribute.N8n is "firstName" or "lastName" or "email" or "login" ? Text(p, attribute.N8n) : Text(fields, attribute.N8n))));
            }

            lines.Add(("activate", operation == "create_user" && Text(p, "activate") == "false" ? "false" : ""));
            lines.Add(("send_email", operation == "delete_user" && Bool(p, "sendEmail") ? "true" : ""));
            lines.Add(("max", operation == "users" ? Most(p, 20) : ""));
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (operation is "create_user" or "update_user" && new[] { "password", "recoveryQuestionQuestion", "recoveryQuestionAnswer" }.Any(name => Text(fields, name).Length > 0))
            {
                todo.Add("n8n set a password or a recovery question in the workflow: neither is ever a step's parameter here, so they are left out: Okta e-mails an activated user to set them.");
            }

            if (operation is "users" or "user" && Text(p, "simplify") != "false")
            {
                todo.Add("n8n simplified each user to a few fields - here a record is the whole user, its profile's attributes beside its id and status.");
            }

            todo.Add(operation == "users" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(OktaConnection);
        }

        private const string SplunkConnection = "choose its connection - n8n's credentials stay in n8n: add a Splunk connection under Admin > Connections (the server's management address and an authentication token from Settings > Tokens) and pick it here.";

        private static readonly Regex OffsetMoment = new("(Z|[+\\-]\\d{2}:?\\d{2})$", RegexOptions.CultureInvariant);

        // n8n's Splunk node: a search's SPL and n8n's job settings - its times as n8n wrote them, a moment without its offset said,
        // One Shot made a blocking job, said; a job's id; Get Result's field and value and its summary; Get Many's sort and n8n's
        // limit of 50; a report's name made from a job, a report's id; the fired alerts and metric alerts; a user's id and an
        // update's e-mail, full name and roles - a password left out, said. n8n's user Create has no step here: Splunk needs a
        // password for one, so it stays a placeholder.
        private static void Splunk(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "additionalFields");
            var update = Find(p, "updateFields");
            var lines = new List<(string Name, string Value)>
            {
                ("search", operation == "create_search" ? Text(p, "search") : ""),
                ("job", operation is "search_job" or "search_results" or "delete_search_job" or "create_report" ? Locator(p, "searchJobId") : ""),
                ("name", operation == "create_report" ? Text(p, "name") : ""),
                ("report", operation is "report" or "delete_report" ? Locator(p, "reportId") : ""),
                ("user", operation is "user" or "update_user" or "delete_user" ? Locator(p, "userId") : ""),
            };
            var times = new List<string>();
            if (operation == "create_search")
            {
                foreach (var name in new[] { "earliest_time", "latest_time", "index_earliest", "index_latest" })
                {
                    if (Text(more, name) is { Length: > 0 } time)
                    {
                        lines.Add((name, time));
                        if (!time.StartsWith('=') && !OffsetMoment.IsMatch(time))
                        {
                            times.Add(name);
                        }
                    }
                }

                lines.Add(("exec_mode", Text(more, "exec_mode") is "normal" ? "normal" : ""));
                foreach (var name in new[] { "adhoc_search_level", "search_mode", "namespace", "remote_server_list", "rf", "workload_pool", "auto_cancel", "auto_finalize_ec", "auto_pause", "max_time", "reduce_freq", "reuse_max_seconds_ago", "status_buckets", "timeout", "indexedRealtimeOffset" })
                {
                    lines.Add((name, Text(more, name)));
                }
            }

            var pair = Find(p, "filters", "keyValueMatch", "keyValuePair");
            lines.Add(("field", operation == "search_results" && Text(pair, "value").Length > 0 ? Text(pair, "key") : ""));
            lines.Add(("value", operation == "search_results" && Text(pair, "key").Length > 0 ? Text(pair, "value") : ""));
            lines.Add(("summary", operation == "search_results" && Bool(p, "options", "add_summary_to_metadata") ? "true" : ""));
            lines.Add(("sort_key", operation == "search_jobs" ? Text(p, "sort", "values", "sort_key") : ""));
            lines.Add(("sort_dir", operation == "search_jobs" ? Text(p, "sort", "values", "sort_dir") : ""));
            lines.Add(("sort_mode", operation == "search_jobs" ? Text(p, "sort", "values", "sort_mode") : ""));
            lines.Add(("add_orphan_field", operation == "reports" && Bool(p, "options", "add_orphan_field") ? "true" : ""));
            lines.Add(("list_default_action_args", operation == "reports" && Bool(p, "options", "listDefaultActionArgs") ? "true" : ""));
            lines.Add(("email", operation == "update_user" ? Text(update, "email") : ""));
            lines.Add(("realname", operation == "update_user" ? Text(update, "realname") : ""));
            lines.Add(("roles", operation == "update_user" ? Find(update, "roles") is { ValueKind: JsonValueKind.Array } roles ? string.Join(",", roles.EnumerateArray().Select(role => role.GetString())) : Text(update, "roles") : ""));
            lines.Add(("max", operation is "search_jobs" or "search_results" or "reports" or "users" ? Most(p, 50) : ""));
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (times.Count > 0)
            {
                todo.Add("n8n read " + string.Join(" and ", times) + " in the workflow's time zone - here a moment needs its offset (2026-10-13T08:00:00Z or +02:00): give it.");
            }

            if (operation == "create_search" && Text(more, "exec_mode") == "oneshot")
            {
                todo.Add("n8n's One Shot gave the results without a job - here the search makes a job, run blocking: read its results with Get search results after it.");
            }

            if (operation == "update_user" && Text(update, "password").Length > 0)
            {
                todo.Add("n8n set a password in the workflow: a password is never a step's parameter here, so it is left out: set it in Splunk.");
            }

            todo.Add(operation is "search_jobs" or "search_results" or "reports" or "fired_alerts" or "metric_alerts" or "users" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(SplunkConnection);
        }

        private const string BitwardenConnection = "choose its connection - n8n's credentials stay in n8n: add a Bitwarden connection under Admin > Connections (the organization API key's client id and secret from Admin Console > Settings > Organization info, and your server's address if it is your own) and pick it here.";

        // n8n's Bitwarden node: a collection's, group's or member's id; Get Many's limit of 10; a group's name, all collections,
        // collections and external id; a member's e-mail and role by n8n's number, and the same; an update's fields - n8n's
        // update sent only what it named and Bitwarden dropped the rest, here read and kept: said; the event filters' member,
        // item and moments - one without its offset said; a group's members and a member's groups.
        private static void Bitwarden(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var update = Find(p, "updateFields");
            var filters = Find(p, "filters");
            var fields = operation.StartsWith("update_", StringComparison.Ordinal) ? update : Find(p, "additionalFields");
            string Ids(JsonElement holder, string name) => Find(holder, name) is { ValueKind: JsonValueKind.Array } list ? string.Join(",", list.EnumerateArray().Select(item => item.ValueKind == JsonValueKind.String ? item.GetString() : item.GetRawText())) : Text(holder, name);
            static string Role(string number) => number switch { "0" => "owner", "1" => "admin", "2" => "user", "3" => "manager", "4" => "custom", _ => number };
            var times = new List<string>();
            string Moment(string name)
            {
                var value = operation == "events" ? Text(filters, name) : "";
                if (value.Length > 0 && !value.StartsWith('=') && !OffsetMoment.IsMatch(value))
                {
                    times.Add(name);
                }

                return value;
            }

            var lines = new List<(string Name, string Value)>
            {
                ("id", operation switch
                {
                    "collection" or "update_collection" or "delete_collection" => Text(p, "collectionId"),
                    "group" or "update_group" or "delete_group" or "group_members" or "set_group_members" => Text(p, "groupId"),
                    "member" or "update_member" or "delete_member" or "member_groups" or "set_member_groups" => Text(p, "memberId"),
                    _ => "",
                }),
                ("name", operation == "create_group" ? Text(p, "name") : operation == "update_group" ? Text(update, "name") : ""),
                ("email", operation == "invite_member" ? Text(p, "email") : ""),
                ("role", operation == "invite_member" ? Role(Text(p, "type") is { Length: > 0 } type ? type : "2")
                    : operation == "update_member" && Find(update, "type").ValueKind is JsonValueKind.Number or JsonValueKind.String ? Role(Text(update, "type")) : ""),
                ("access_all", operation is "create_group" or "invite_member" ? Bool(p, "accessAll") ? "true" : ""
                    : operation is "update_group" or "update_member" && Find(update, "accessAll").ValueKind is JsonValueKind.True or JsonValueKind.False ? Text(update, "accessAll") : ""),
                ("collections", operation is "create_group" or "invite_member" or "update_group" or "update_member" ? Ids(fields, "collections") : ""),
                ("groups", operation == "update_collection" ? Ids(update, "groups") : operation == "set_member_groups" ? Text(p, "groupIds") : ""),
                ("members", operation == "set_group_members" ? Text(p, "memberIds") : ""),
                ("external_id", operation is "create_group" or "invite_member" or "update_group" or "update_member" or "update_collection" ? Text(fields, "externalId") : ""),
                ("start", Moment("start")),
                ("end", Moment("end")),
                ("member", operation == "events" ? Text(filters, "actingUserId") : ""),
                ("item", operation == "events" ? Text(filters, "itemID") : ""),
                ("max", operation is "collections" or "groups" or "members" or "events" ? Most(p, 10) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (times.Count > 0)
            {
                todo.Add("n8n read " + string.Join(" and ", times) + " in the workflow's time zone - here a moment needs its offset (2026-10-01T00:00:00Z or +02:00): give it.");
            }

            if (operation is "update_collection" or "update_group" or "update_member")
            {
                todo.Add("n8n's update sent only what it named and Bitwarden dropped the rest - here the rest is read first and kept: check that is what was meant.");
            }

            todo.Add(operation is "collections" or "groups" or "members" or "events" or "group_members" or "member_groups" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(BitwardenConnection);
        }

        private const string GoogleWorkspaceAdminConnection = "choose its connection - n8n's credentials stay in n8n: add a Google Workspace Admin connection under Admin > Connections (an OAuth client's id and secret and an administrator's refresh token granted the directory scopes) and pick it here.";

        // n8n's G Suite Admin node: a user's, group's or device's id (n8n's From List, By E-mail or By ID); Get Many's filters, sort
        // and n8n's limit of 100; a projection (n8n's custom one made full, said); an update's fields - a password, phones, e-mails,
        // roles and custom fields left out, said; a group's e-mail, name and description; a device's annotations and unit and its
        // status. n8n's Simplify cut each user to a few fields - here a record is the whole user: said. A user's Create has no step
        // here: Google takes one only with a password, so it stays a placeholder.
        private static void GoogleWorkspaceAdmin(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var filter = Find(p, "filter");
            var sort = Find(p, "sort", "sortRules");
            var update = Find(p, "updateFields");
            var device = Find(p, "updateOptions");
            var projection = Text(p, "projection");
            var lines = new List<(string Name, string Value)>
            {
                ("user", operation is "user" or "update_user" or "delete_user" or "add_to_group" or "remove_from_group" ? Locator(p, "userId") : ""),
                ("group", operation is "group" or "update_group" or "delete_group" or "add_to_group" or "remove_from_group" ? Locator(p, "groupId") : ""),
                ("device", operation is "device" or "update_device" or "device_action" ? Locator(p, "deviceId") : ""),
                ("customer", operation is "users" or "groups" ? Text(filter, "customer") : ""),
                ("domain", operation is "users" or "groups" ? Text(filter, "domain") : ""),
                ("member", operation == "groups" ? Text(filter, "userId") : ""),
                ("query", operation is "users" or "groups" or "devices" ? Text(filter, "query") : ""),
                ("show_deleted", operation == "users" && Bool(filter, "showDeleted") ? "true" : ""),
                ("org_unit_path", operation == "devices" ? Text(filter, "orgUnitPath") : operation == "update_device" ? Text(device, "orgUnitPath") : operation == "update_user" ? Text(update, "orgUnitPath") : ""),
                ("include_child_units", operation == "devices" && Bool(p, "includeChildOrgunits") ? "true" : ""),
                ("order_by", operation is "users" or "devices" ? Text(sort, "orderBy") : ""),
                ("sort_order", operation is "users" or "groups" ? Text(sort, "sortOrder").ToLowerInvariant() : operation == "devices" ? Text(sort, "sortBy") : ""),
                ("projection", operation is "users" or "user" or "devices" or "device" && projection.Length > 0 ? projection == "custom" ? "full" : projection : ""),
                ("first_name", operation == "update_user" ? Text(update, "firstName") : ""),
                ("last_name", operation == "update_user" ? Text(update, "lastName") : ""),
                ("primary_email", operation == "update_user" ? Text(update, "primaryEmail") : ""),
                ("suspended", operation == "update_user" ? Text(update, "suspendUi") : ""),
                ("archived", operation == "update_user" ? Text(update, "archived") : ""),
                ("change_password_at_next_login", operation == "update_user" ? Text(update, "changePasswordAtNextLogin") : ""),
                ("email", operation == "create_group" ? Text(p, "email") : operation == "update_group" ? Text(update, "email") : ""),
                ("name", operation == "create_group" ? Text(p, "name") : operation == "update_group" ? Text(update, "name") : ""),
                ("description", operation == "create_group" ? Text(p, "additionalFields", "description") : operation == "update_group" ? Text(update, "description") : ""),
                ("annotated_user", operation == "update_device" ? Text(device, "annotatedUser") : ""),
                ("annotated_location", operation == "update_device" ? Text(device, "annotatedLocation") : ""),
                ("annotated_asset_id", operation == "update_device" ? Text(device, "annotatedAssetId") : ""),
                ("notes", operation == "update_device" ? Text(device, "notes") : ""),
                ("action", operation == "device_action" ? Text(p, "action") : ""),
                ("max", operation is "users" or "groups" or "devices" ? Most(p, 100) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (projection == "custom" && operation is "users" or "user")
            {
                todo.Add("n8n read a custom schema's fields alone - here the projection is full, every custom field with it: check that is what was meant.");
            }

            if (operation == "update_user" && Text(update, "password").Length > 0)
            {
                todo.Add("n8n set a password in the workflow: a password is never a step's parameter here, so it is left out - ask for a new one at next sign-in instead (change_password_at_next_login).");
            }

            if (operation == "update_user" && new[] { "phoneUi", "emailUi", "roles", "customFields" }.Any(name => Find(update, name).ValueKind is not JsonValueKind.Undefined and not JsonValueKind.Null))
            {
                todo.Add("n8n set phones, e-mails, roles or custom fields - here they are not a step's parameters: set them in the Admin console.");
            }

            if (operation is "users" or "user" && Text(p, "output") != "raw")
            {
                todo.Add("n8n gave a few of each user's fields - here a record is the whole user.");
            }

            todo.Add(operation is "users" or "groups" or "devices" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(GoogleWorkspaceAdminConnection);
        }

        private const string MailjetConnection = "choose its connection - n8n's credentials stay in n8n: add a Mailjet connection under Admin > Connections (the API key and secret key from Account settings > REST API) and pick it here.";

        private const string MailjetSmsConnection = "choose its connection - n8n's credentials stay in n8n: add a Mailjet SMS connection under Admin > Connections (the SMS token from Account settings > SMS) and pick it here.";

        // n8n's Mailjet node: an e-mail's sender (its name beside its address), recipients, copies, reply-to, subject and body - or
        // a template's number and language - its variables (n8n's JSON or its name and value pairs, an expression among them said),
        // tracking, priority and campaign; an SMS's sender, number and text, on a Mailjet SMS connection.
        private static void Mailjet(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            if (operation == "send_sms")
            {
                Set(step, "Parameters", FtpParameters(new (string Name, string Value)[] { ("from", Text(p, "from")), ("to", Text(p, "to")), ("text", Text(p, "text")) }.Where(line => line.Value.Length > 0).ToArray()));
                todo.Add(PerItem);
                todo.Add(MailjetSmsConnection);
                return;
            }

            var more = Find(p, "additionalFields");
            var template = operation == "send_template";
            var email = Text(p, "fromEmail");
            var name = Text(more, "fromName");
            var from = name.Length > 0 && !name.StartsWith('=') && !email.StartsWith('=') ? name + " <" + email + ">" : email;
            if (name.Length > 0 && from == email)
            {
                todo.Add("n8n named the sender in an expression - here a sender is named with its address in from: Kafé <kafe@example.com>.");
            }

            var variables = "";
            if (Bool(p, "jsonParameters"))
            {
                variables = Text(p, "variablesJson") is { } json && !json.StartsWith('=') ? Minified(json) : Text(p, "variablesJson");
            }
            else if (Items(p, "variablesUi", "variablesValues").ToList() is { Count: > 0 } pairs)
            {
                var given = new JsonObject();
                foreach (var pair in pairs)
                {
                    if (Text(pair, "name") is not { Length: > 0 } key)
                    {
                        continue;
                    }

                    if (key.StartsWith('=') || Text(pair, "value").StartsWith('='))
                    {
                        todo.Add("n8n made the variable '" + key + "' from an expression - here the variables are a JSON object: give it there.");
                        continue;
                    }

                    given[key] = Text(pair, "value");
                }

                variables = given.Count == 0 ? "" : given.ToJsonString(ReadableJson);
            }

            var lines = new List<(string Name, string Value)>
            {
                ("from", from),
                ("to", Text(p, "toEmail")),
                ("cc", Text(more, template ? "ccEmail" : "ccAddresses")),
                ("bcc", Text(more, "bccEmail")),
                ("reply_to", Text(more, "replyTo")),
                ("subject", Text(p, "subject")),
                ("text", template ? "" : Text(p, "text")),
                ("html", template ? "" : Text(p, "html")),
                ("template", template ? Text(p, "templateId") : ""),
                ("template_language", Bool(more, "templateLanguage") ? "true" : ""),
                ("variables", variables),
                ("track_opens", Text(more, "trackOpens")),
                ("track_clicks", Text(more, "trackClicks")),
                ("priority", Text(more, "priority")),
                ("campaign", Text(more, "customCampaign")),
                ("deduplicate", Bool(more, "deduplicateCampaign") ? "true" : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(PerItem);
            todo.Add(MailjetConnection);
        }

        private const string MicrosoftGraphSecurityConnection = "choose its connection - n8n's credentials stay in n8n: add a Microsoft Graph Security connection under Admin > Connections (an app registration's client id and secret with the SecurityEvents application permission, and the tenant's token endpoint) and pick it here.";

        // n8n's Microsoft Graph Security node: a secure score's or a control profile's id; Get Many's OData filter, a score's
