        private const string ServiceNowConnection = "choose its connection - n8n's credentials stay in n8n: add a ServiceNow connection under Admin > Connections (the instance's address - https://{instance}.service-now.com - and an integration user's name and password) and pick it here.";

        // An incident's own fields, as the ServiceNow connector names them (ServiceNow's column names - n8n's).
        private static readonly string[] ServiceNowIncidentFields =
        {
            "short_description", "description", "caller_id", "urgency", "impact", "state", "category", "subcategory", "assignment_group", "assigned_to",
            "contact_type", "business_service", "cmdb_ci", "hold_reason", "work_notes", "close_code", "close_notes",
        };

        // n8n's ServiceNow node: the table each resource stands for (a table record's own name); a record's sys_id; Get Many's
        // filter, fields, display values and limit (50 when the export leaves it out); a user got by name as that table read
        // for the name, one at most; an incident's short description and n8n's additional or update fields by ServiceNow's
        // names, one the connector does not name by itself among the values; a table record's columns - n8n's pairs, a JSON
        // object (an expression among them making the line one) - or, as n8n's Auto-Map wrote the item's own, said to be given;
        // a user's fields as values, its password left out and said. A list among n8n's fields is written comma-separated, as
        // ServiceNow takes a list. n8n signed in by OAuth2 unless told otherwise: said.
        private static void ServiceNow(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            var resource = Text(p, "resource") is { Length: > 0 } named ? named : "user";
            var table = resource switch
            {
                "incident" => "incident",
                "user" => "sys_user",
                "businessService" => "cmdb_ci_service",
                "configurationItems" => "cmdb_ci",
                "department" => "cmn_department",
                "dictionary" => "sys_dictionary",
                "userGroup" => "sys_user_group",
                "userRole" => "sys_user_role",
                _ => Text(p, "tableName"),
            };
            var options = Find(p, "options");
            var byName = resource == "user" && operation == "record" && Text(p, "getOption") == "user_name";
            if (byName)
            {
                operation = "table";
            }

            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            if (operation is not ("create_incident" or "update_incident"))
            {
                lines.Add(("table", table));
            }

            // A field's value as ServiceNow takes it: a list comma-separated, anything else as its text.
            static string Value(JsonElement value) =>
                value.ValueKind == JsonValueKind.Array ? string.Join(",", value.EnumerateArray().Select(item => Value(item))) : value.ValueKind == JsonValueKind.String ? value.GetString() ?? "" : value.GetRawText();
            static IEnumerable<(string Name, string Value)> Fields(JsonElement holder) =>
                holder.ValueKind == JsonValueKind.Object ? holder.EnumerateObject().Select(field => (field.Name, Value(field.Value))).Where(field => field.Item2.Length > 0) : Enumerable.Empty<(string, string)>();
            static string Pairs(List<(string Name, string Value)> pairs) =>
                pairs.Count == 0 ? "" : (pairs.Any(pair => pair.Value.StartsWith('=')) ? "=" : "") + "{" + string.Join(", ", pairs.Select(pair =>
                    JsonSerializer.Serialize(pair.Name, ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(pair.Value), ReadableJson))) + "}";
            var columns = options.ValueKind == JsonValueKind.Object && options.TryGetProperty("sysparm_fields", out var listed) ? Value(listed) : "";
            switch (operation)
            {
                case "table":
                    var name = Text(p, "user_name");
                    lines.Add(("query", byName ? (name.StartsWith('=') ? "=user_name=" + name[1..] : "user_name=" + name) : Text(options, "sysparm_query")));
                    lines.Add(("fields", columns));
                    lines.Add(("display_value", Text(options, "sysparm_display_value")));
                    lines.Add(("max", byName ? "1" : Most(p, 50)));
                    break;
                case "record":
                    lines.Add(("id", Text(p, "id")));
                    lines.Add(("fields", columns));
                    lines.Add(("display_value", Text(options, "sysparm_display_value")));
                    break;
                case "delete_record":
                    lines.Add(("id", Text(p, "id")));
                    break;
                case "create_incident":
                case "update_incident":
                    {
                        lines.Add(operation == "create_incident" ? ("short_description", Text(p, "short_description")) : ("id", Text(p, "id")));
                        var fields = Fields(Find(p, operation == "create_incident" ? "additionalFields" : "updateFields")).ToList();
                        lines.AddRange(fields.Where(field => ServiceNowIncidentFields.Contains(field.Name, StringComparer.Ordinal)));
                        lines.Add(("values", Pairs(fields.Where(field => !ServiceNowIncidentFields.Contains(field.Name, StringComparer.Ordinal)).ToList())));
                        break;
                    }

                default:
                    {
                        if (operation == "update_record")
                        {
                            lines.Add(("id", Text(p, "id")));
                        }

                        if (resource == "user")
                        {
                            var fields = Fields(Find(p, operation == "create_record" ? "additionalFields" : "updateFields")).ToList();
                            if (fields.Any(field => field.Name == "user_password"))
                            {
                                todo.Add("n8n set the user's password - a password is never a step's parameter here: set it in ServiceNow.");
                            }

                            lines.Add(("values", Pairs(fields.Where(field => field.Name != "user_password").ToList())));
                            break;
                        }

                        var data = Text(p, "dataToSend") is { Length: > 0 } given ? given : "columns";
                        if (data == "mapInput")
                        {
                            todo.Add("n8n wrote each item's own fields as the record (its Auto-Map Input Data) - here give the values, a JSON object of the record's columns in a For Each: 'values = {\"short_description\": \"{{ short_description }}\"}'.");
                        }
                        else if (data == "columns")
                        {
                            lines.Add(("values", Pairs(Items(p, "fieldsToSend", "field").Select(item => (Name: Text(item, "column"), Value: Text(item, "value"))).Where(pair => pair.Name.Length > 0).ToList())));
                        }

                        break;
                    }
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (Text(p, "authentication") != "basicAuth")
            {
                todo.Add("n8n signed in by OAuth2 - here the connection is an integration user's name and password, with the roles its steps need.");
            }

            todo.Add(operation == "table" && !byName ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(ServiceNowConnection);
        }

        private const string MicrosoftEntraConnection = "choose its connection - n8n's credentials stay in n8n: add a Microsoft Entra ID connection under Admin > Connections (an app registration's client id and secret with the User.ReadWrite.All, Group.ReadWrite.All and GroupMember.ReadWrite.All application permissions its steps need, granted by an administrator, and the tenant's token endpoint) and pick it here.";

        // n8n's Microsoft Entra ID node: a user's and a group's id (n8n's From List or By ID); Get Many's filter and n8n's limit of
        // 50; n8n's Selected Fields as the columns (its Simplified the connector's own, its Raw said); a group's members; a group's
        // kind, membership, name, mail nickname and the rest of its fields; a user's update as a JSON object of Graph's properties
        // - its phones a list, as n8n sends them - a password, its policies and a forced change left out, said. n8n signed in as a
        // user; here the app's own permissions: said. A user's Create has no step here: Entra takes one only with a password, so it
        // stays a placeholder.
        private static void MicrosoftEntra(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var update = Find(p, "updateFields");
            var more = Find(p, "additionalFields");
            var create = operation == "create_group";
            var unified = create && Text(p, "groupType") == "Unified";
            var lines = new List<(string Name, string Value)>
            {
                ("user", operation is "user" or "update_user" or "delete_user" or "add_to_group" or "remove_from_group" ? Locator(p, "user") : ""),
                ("group", operation is "group" or "update_group" or "delete_group" or "add_to_group" or "remove_from_group" ? Locator(p, "group") : ""),
                ("filter", operation is "users" or "groups" ? Text(p, "filter") : ""),
                ("select", operation is "users" or "user" or "groups" or "group" && Text(p, "output") == "fields" && Find(p, "fields") is { ValueKind: JsonValueKind.Array } fields
                    ? string.Join(",", fields.EnumerateArray().Select(field => field.GetString() ?? "").Where(field => field.Length > 0).Append("id").Distinct(StringComparer.Ordinal)) : ""),
                ("include_members", operation == "group" && Bool(p, "options", "includeMembers") ? "true" : ""),
                ("kind", unified ? "microsoft365" : ""),
                ("membership", create && Text(p, "membershipType") == "DynamicMembership" ? "dynamic" : ""),
                ("display_name", create ? Text(p, "displayName") : operation == "update_group" ? Text(update, "displayName") : ""),
                ("mail_nickname", create ? Text(p, "mailNickname") : operation == "update_group" ? Text(update, "mailNickname") : ""),
                ("description", create ? Text(more, "description") : operation == "update_group" ? Text(update, "description") : ""),
                ("membership_rule", create ? Text(more, "membershipRule") : operation == "update_group" ? Text(update, "membershipRule") : ""),
                ("rule_processing", create ? Text(more, "membershipRuleProcessingState") : operation == "update_group" ? Text(update, "membershipRuleProcessingState") : ""),
                ("visibility", create ? Text(more, "visibility") : operation == "update_group" ? Text(update, "visibility") : ""),
                ("mail_enabled", unified ? Text(p, "mailEnabled") : ""),
                ("security_enabled", unified ? Text(p, "securityEnabled") is { Length: > 0 } security ? security : "true" : operation == "update_group" ? Text(update, "securityEnabled") : ""),
                ("assignable_to_role", create && Bool(more, "isAssignableToRole") ? "true" : ""),
                ("values", operation == "update_user" ? EntraUserValues(update) : ""),
                ("max", operation is "users" or "groups" ? Most(p, 50) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (operation == "update_user" && new[] { "password", "passwordPolicies", "forceChangePassword" }.Any(name => Find(update, name).ValueKind is not JsonValueKind.Undefined and not JsonValueKind.Null))
            {
                todo.Add("n8n set a password, its policies or a forced change in the workflow: a password is never a step's parameter here, so they are left out - set them in Entra ID.");
            }

            if ((create ? more : update) is { ValueKind: JsonValueKind.Object } holder && new[] { "uniqueName", "preferredDataLocation", "allowExternalSenders", "autoSubscribeNewMembers" }.Any(name => holder.TryGetProperty(name, out _)))
            {
                todo.Add("n8n set a unique name, a preferred data location or a Microsoft 365 group's mail settings - here they are not a step's parameters: set them in Entra ID (the mail settings take a signed-in user's permission).");
            }

            if (operation is "users" or "user" or "groups" or "group" && Text(p, "output") == "raw")
            {
                todo.Add("n8n read every property (its Raw) - here a record has the columns named, the connector's own when none are: name more in select.");
            }

            todo.Add("n8n signed in as a user - here the connection is an app with the application permissions its steps need, granted by an administrator.");
            todo.Add(operation is "users" or "groups" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(MicrosoftEntraConnection);
        }

        // n8n's user update fields as a JSON object of Graph's user properties: phones and other e-mails a list, as n8n sends them,
        // an object's fields kept; a password, its policies and a forced change left out. An expression among them makes the line
        // one.
        private static string EntraUserValues(JsonElement update)
        {
            if (update.ValueKind != JsonValueKind.Object)
            {
                return "";
            }

            var expression = false;
            string Node(JsonElement value)
            {
                switch (value.ValueKind)
                {
                    case JsonValueKind.String:
                        var text = value.GetString() ?? "";
                        expression |= text.StartsWith('=');
                        return JsonSerializer.Serialize(Unmarked(text), ReadableJson);
                    case JsonValueKind.Object:
                        return "{" + string.Join(", ", value.EnumerateObject().Select(field => JsonSerializer.Serialize(field.Name, ReadableJson) + ": " + Node(field.Value))) + "}";
                    case JsonValueKind.Array:
                        return "[" + string.Join(", ", value.EnumerateArray().Select(Node)) + "]";
                    default:
                        return value.GetRawText();
                }
            }

            var fields = update.EnumerateObject().Where(field => field.Name is not ("password" or "passwordPolicies" or "forceChangePassword")).Select(field =>
                JsonSerializer.Serialize(field.Name, ReadableJson) + ": " + (field.Name is "businessPhones" or "otherMails" && field.Value.ValueKind == JsonValueKind.String ? "[" + Node(field.Value) + "]" : Node(field.Value))).ToList();
            return fields.Count == 0 ? "" : (expression ? "=" : "") + "{" + string.Join(", ", fields) + "}";
        }

        private const string MicrosoftDynamicsConnection = "choose its connection - n8n's credentials stay in n8n: add a Microsoft Dynamics 365 connection under Admin > Connections (the environment's address, an app registration's client id and secret - an application user of the environment with the security role its steps need - and the tenant's token endpoint) and pick it here.";

        // n8n's Microsoft Dynamics CRM node: an account by its id; Get Many's filter, its columns and related records and n8n's
        // limit of 5; a Create's name and fields and an Update's fields as the account's columns - n8n's addresses as its
        // address1_ and address2_ columns, an expression among them making the line one; the columns n8n returned from a write, its
        // own id with them (that id alone when none were named). n8n signed in as a user; here an application user: said.
        private static void MicrosoftDynamics(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var options = Find(p, "options");
            static string Joined(JsonElement holder, string name) =>
                holder.ValueKind == JsonValueKind.Object && holder.TryGetProperty(name, out var list)
                    ? list.ValueKind == JsonValueKind.Array ? string.Join(",", list.EnumerateArray().Select(item => item.GetString() ?? "").Where(item => item.Length > 0)) : list.ValueKind == JsonValueKind.String ? list.GetString() ?? "" : ""
                    : "";
            var returned = Joined(options, "returnFields");
            var lines = new List<(string Name, string Value)>
            {
                ("table", "accounts"),
                ("id", operation is "record" or "update_record" or "delete_record" ? Text(p, "accountId") : ""),
                ("filter", operation == "records" ? Text(p, "filters", "query") : ""),
                ("select", operation is "records" or "record" ? returned
                    : operation is "create_record" or "update_record" ? string.Join(",", returned.Split(',', StringSplitOptions.RemoveEmptyEntries).Append("accountid").Distinct(StringComparer.Ordinal)) : ""),
                ("expand", operation is "records" or "record" ? Joined(options, "expandFields") : ""),
                ("values", operation == "create_record" ? DynamicsValues(Text(p, "name"), Find(p, "additionalFields")) : operation == "update_record" ? DynamicsValues("", Find(p, "updateFields")) : ""),
                ("max", operation == "records" ? Most(p, 5) : ""),
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add("n8n signed in as a user - here the connection is an application user of the environment, with the security role its steps need.");
            todo.Add(operation == "records" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(MicrosoftDynamicsConnection);
        }

        // n8n's account fields as a JSON object of the account's columns: a Create's name first, n8n's addresses as address1_ and
        // address2_ columns (an empty one left out, as n8n does), numbers and flags as JSON writes them. An expression among them
        // makes the line one.
        private static string DynamicsValues(string name, JsonElement fields)
        {
            var expression = false;
            string Node(JsonElement value)
            {
                if (value.ValueKind == JsonValueKind.String)
                {
                    var text = value.GetString() ?? "";
                    expression |= text.StartsWith('=');
                    return JsonSerializer.Serialize(Unmarked(text), ReadableJson);
                }

                return value.GetRawText();
            }

            var pairs = new List<string>();
            if (name.Length > 0)
            {
                expression |= name.StartsWith('=');
                pairs.Add("\"name\": " + JsonSerializer.Serialize(Unmarked(name), ReadableJson));
            }

            if (fields.ValueKind == JsonValueKind.Object)
            {
                foreach (var field in fields.EnumerateObject().Where(field => field.Name != "addresses"))
                {
                    pairs.Add(JsonSerializer.Serialize(field.Name, ReadableJson) + ": " + Node(field.Value));
                }

                var addresses = Items(fields, "addresses", "address").ToList();
                for (var index = 0; index < addresses.Count; index++)
                {
                    foreach (var part in addresses[index].ValueKind == JsonValueKind.Object ? addresses[index].EnumerateObject().ToList() : new List<JsonProperty>())
                    {
                        if (part.Value.ValueKind != JsonValueKind.String || part.Value.GetString() is { Length: > 0 })
                        {
                            pairs.Add(JsonSerializer.Serialize($"address{index + 1}_{part.Name}", ReadableJson) + ": " + Node(part.Value));
                        }
                    }
                }
            }

            return pairs.Count == 0 ? "" : (expression ? "=" : "") + "{" + string.Join(", ", pairs) + "}";
        }

        private const string GoogleBigQueryConnection = "choose its connection - n8n's credentials stay in n8n: add a Google BigQuery connection under Admin > Connections (an OAuth client's id and secret and a refresh token granted the BigQuery scope) and pick it here.";

        // n8n's Google BigQuery node (its second version): the project (n8n's From List or By ID); Execute Query's SQL as the step's
        // Query, its named parameters as '@name = value' lines - bound, as n8n bound them - its default dataset, location, legacy SQL
        // and n8n's 1,000 rows at most; a dry run, raw output, the schema, numbers as numbers, bytes billed and n8n's own wait said;
        // Insert's dataset, table and its columns as one row (n8n's Auto-Map said), invalid rows skipped and unknown columns
        // ignored when asked; its batch size, template suffix and trace id said.
        private static void GoogleBigQuery(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var options = Find(p, "options");
            var lines = new List<(string Name, string Value)> { ("project", Locator(p, "projectId")) };
            if (operation == "query")
            {
                var sql = Text(p, "sqlQuery");
                Set(step, "Query", sql.StartsWith('=') || !sql.Contains("{{", StringComparison.Ordinal) ? sql : "=" + sql);
                lines.AddRange(Items(options, "queryParameters", "namedParameters").Select(item => ("@" + Text(item, "name"), Text(item, "value"))).Where(pair => pair.Item1.Length > 1));
                lines.Add(("dataset", Text(options, "defaultDataset")));
                lines.Add(("location", Text(options, "location")));
                lines.Add(("legacy_sql", Bool(options, "useLegacySql") ? "true" : ""));
                lines.Add(("max", Text(options, "maxResults") is { Length: > 0 } most ? most : "1000"));
                if (new[] { "dryRun", "rawOutput", "includeSchema", "returnAsNumbers", "maximumBytesBilled", "timeoutMs" }.Any(name => options.ValueKind == JsonValueKind.Object && options.TryGetProperty(name, out _)))
                {
                    todo.Add("n8n was asked for a dry run, its raw output or schema, numbers as numbers, a cap on bytes billed or its own wait - here a query runs, its rows typed by the schema, and waits as long as 'wait' says: check the step does what was meant.");
                }

                todo.Add("n8n gave each row as an item - here they are the step's result, a list of records.");
            }
            else
            {
                lines.Add(("dataset", Locator(p, "datasetId")));
                lines.Add(("table", Locator(p, "tableId")));
                if (Text(p, "dataMode") == "define")
                {
                    var pairs = Items(p, "fieldsUi", "values").Select(item => (Name: Text(item, "fieldId"), Value: Text(item, "fieldValue"))).Where(pair => pair.Name.Length > 0).ToList();
                    lines.Add(("rows", pairs.Count == 0 ? "" : (pairs.Any(pair => pair.Value.StartsWith('=')) ? "=" : "") + "{" + string.Join(", ", pairs.Select(pair =>
                        JsonSerializer.Serialize(pair.Name, ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(pair.Value), ReadableJson))) + "}"));
                }
                else
                {
                    todo.Add("n8n wrote each item's own fields that match the table's columns (its Auto-Map) - here give the rows: the records themselves, or a JSON object of a record's columns in a For Each: 'rows = {\"name\": \"{{ name }}\"}'.");
                }

                lines.Add(("skip_invalid", Bool(options, "skipInvalidRows") ? "true" : ""));
                lines.Add(("ignore_unknown", Bool(options, "ignoreUnknownValues") ? "true" : ""));
                if (new[] { "batchSize", "templateSuffix", "traceId" }.Any(name => options.ValueKind == JsonValueKind.Object && options.TryGetProperty(name, out _)))
                {
                    todo.Add("n8n set a batch size, a template suffix or a trace id - here rows go in batches of 500, straight into the table: check that is what was meant.");
                }

                todo.Add(PerItem);
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(GoogleBigQueryConnection);
        }

        private const string FreshserviceConnection = "choose its connection - n8n's credentials stay in n8n: add a Freshservice connection under Admin > Connections (the desk's address - https://{domain}.freshservice.com - and an API key) and pick it here.";

        // n8n's Freshservice resources as the connector names them, with the parameter n8n names a record's id by.
        private static readonly Dictionary<string, (string Resource, string Id)> FreshserviceResources = new(StringComparer.Ordinal)
        {
            ["agent"] = ("agents", "agentId"), ["agentGroup"] = ("groups", "agentGroupId"), ["agentRole"] = ("roles", "agentRoleId"),
            ["announcement"] = ("announcements", "announcementId"), ["assetType"] = ("asset_types", "assetTypeId"), ["change"] = ("changes", "changeId"),
            ["department"] = ("departments", "departmentId"), ["location"] = ("locations", "locationId"), ["problem"] = ("problems", "problemId"),
            ["product"] = ("products", "productId"), ["release"] = ("releases", "releaseId"), ["requester"] = ("requesters", "requesterId"),
            ["requesterGroup"] = ("requester_groups", "requesterGroupId"), ["software"] = ("applications", "softwareId"), ["ticket"] = ("tickets", "ticketId"),
        };

        // A Create's own parameters - n8n's names, Freshservice's, and the value n8n sends when its export leaves one out.
        private static readonly Dictionary<string, (string N8n, string Freshservice, string? Default)[]> FreshserviceCreates = new(StringComparer.Ordinal)
        {
            ["agent"] = new[] { ("email", "email", (string?)null), ("firstName", "first_name", null) },
            ["agentGroup"] = new[] { ("name", "name", (string?)null) },
            ["announcement"] = new[] { ("title", "title", (string?)null), ("bodyHtml", "body_html", null), ("visibility", "visibility", null), ("visibleFrom", "visible_from", null) },
            ["assetType"] = new[] { ("name", "name", (string?)null) },
            ["change"] = new[] { ("requesterId", "requester_id", (string?)null), ("subject", "subject", null), ("plannedStartDate", "planned_start_date", null), ("plannedEndDate", "planned_end_date", null) },
            ["department"] = new[] { ("name", "name", (string?)null) },
            ["location"] = new[] { ("name", "name", (string?)null) },
            ["problem"] = new[] { ("subject", "subject", (string?)null), ("requesterId", "requester_id", null), ("dueBy", "due_by", null) },
            ["product"] = new[] { ("assetTypeId", "asset_type_id", (string?)null), ("name", "name", null) },
            ["release"] = new[] { ("subject", "subject", (string?)null), ("releaseType", "release_type", "1"), ("status", "status", "1"), ("priority", "priority", "1"), ("plannedStartDate", "planned_start_date", null), ("plannedEndDate", "planned_end_date", null) },
            ["requester"] = new[] { ("firstName", "first_name", (string?)null), ("primaryEmail", "primary_email", null) },
            ["requesterGroup"] = new[] { ("name", "name", (string?)null) },
            ["software"] = new[] { ("applicationType", "application_type", (string?)null), ("name", "name", null) },
            ["ticket"] = new[] { ("email", "email", (string?)null), ("subject", "subject", null), ("description", "description", null), ("priority", "priority", "1"), ("status", "status", "2") },
        };

        // n8n's Freshservice node: each resource as the connector's, its record's id; Get Many's ticket filters as Freshservice's
        // query (a date among them said) and n8n's limit of 50; a Create's own parameters by Freshservice's names, n8n's own
        // values when its export leaves them out (a change's and a problem's status, priority, impact and the rest it fixes at
        // 1), and its additional and update fields - comma-separated e-mails and domains as lists, an agent's roles as
        // Freshservice's, a location's address as an object; an expression among them making the line one. n8n's filters for the
        // other resources said.
        private static void Freshservice(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var resource = Text(p, "resource") is { Length: > 0 } named ? named : "agent";
            var (table, idName) = FreshserviceResources.TryGetValue(resource, out var known) ? known : ("", "");
            var lines = new List<(string Name, string Value)> { ("resource", table) };
            if (operation is "record" or "update_record" or "delete_record")
            {
                lines.Add(("id", Text(p, idName)));
            }

            if (operation == "records")
            {
                var filters = Find(p, "filters");
                if (resource == "ticket" && filters.ValueKind == JsonValueKind.Object)
                {
                    var terms = filters.EnumerateObject().Where(filter => filter.Name is "agent_id" or "group_id" or "priority" or "status" or "impact").Select(filter => filter.Name + ":" + Text(filter.Value)).ToList();
                    lines.Add(("query", string.Join(" AND ", terms)));
                    if (filters.EnumerateObject().Any(filter => filter.Name is "created_at" or "due_by"))
                    {
                        todo.Add("n8n filtered the tickets by a date - give it in the query: created_at:>'2026-10-01' or due_by:<'2026-10-31'.");
                    }
                }
                else if (filters.ValueKind == JsonValueKind.Object && filters.EnumerateObject().Any())
                {
                    todo.Add("n8n filtered them - here tickets, agents and requesters take Freshservice's query (email:'ada@kafe.example.com'); the other resources are read whole.");
                }

                lines.Add(("max", Most(p, 50)));
            }
            else if (operation is "create_record" or "update_record")
            {
                var expression = false;
                string Json(JsonElement value, bool list = false)
                {
                    if (value.ValueKind == JsonValueKind.String)
                    {
                        var text = value.GetString() ?? "";
                        expression |= text.StartsWith('=');
                        return list && !text.StartsWith('=')
                            ? "[" + string.Join(", ", text.Split(',').Select(item => item.Trim()).Where(item => item.Length > 0).Select(item => JsonSerializer.Serialize(item, ReadableJson))) + "]"
                            : JsonSerializer.Serialize(Unmarked(text), ReadableJson);
                    }

                    return value.ValueKind == JsonValueKind.Object
                        ? "{" + string.Join(", ", value.EnumerateObject().Select(field => JsonSerializer.Serialize(field.Name, ReadableJson) + ": " + Json(field.Value))) + "}"
                        : value.ValueKind == JsonValueKind.Array ? "[" + string.Join(", ", value.EnumerateArray().Select(item => Json(item))) + "]" : value.GetRawText();
                }

                var pairs = new List<string>();
                void Add(string name, string json) => pairs.Add(JsonSerializer.Serialize(name, ReadableJson) + ": " + json);
                if (operation == "create_record")
                {
                    foreach (var (n8n, freshservice, fallback) in FreshserviceCreates.TryGetValue(resource, out var own) ? own : Array.Empty<(string, string, string?)>())
                    {
                        if (Find(p, n8n) is { ValueKind: not JsonValueKind.Undefined } given)
                        {
                            Add(freshservice, Json(given));
                        }
                        else if (fallback is not null)
                        {
                            Add(freshservice, fallback);
                        }
                    }

                    if (resource is "change" or "problem")
                    {
                        foreach (var fixedAt in resource == "change" ? new[] { "status", "priority", "impact", "risk", "change_type" } : new[] { "status", "priority", "impact" })
                        {
                            Add(fixedAt, "1");
                        }
                    }

                    if (resource == "agent")
                    {
                        var roles = Items(p, "roles", "roleProperties").Select(role => "{\"role_id\": " + Json(Find(role, "role")) + ", \"assignment_scope\": " + Json(Find(role, "assignment_scope"))
                            + (Find(role, "groups") is { ValueKind: JsonValueKind.Array } groups ? ", \"groups\": " + Json(groups) : "") + "}").ToList();
                        if (roles.Count > 0)
                        {
                            Add("roles", "[" + string.Join(", ", roles) + "]");
                        }
                        else
                        {
                            todo.Add("n8n gave the agent roles - here give them in the values: \"roles\": [{\"role_id\": 1, \"assignment_scope\": \"entire_helpdesk\"}].");
                        }
                    }
                }

                var more = Find(p, operation == "create_record" ? "additionalFields" : "updateFields");
                if (more.ValueKind == JsonValueKind.Object)
                {
                    foreach (var field in more.EnumerateObject())
                    {
                        if (field.Name == "address" && field.Value.ValueKind == JsonValueKind.Object)
                        {
                            Add("address", Json(field.Value.TryGetProperty("addressFields", out var inner) ? inner : field.Value));
                        }
                        else
                        {
                            Add(field.Name, Json(field.Value, list: field.Name is "cc_emails" or "secondary_emails" or "additional_emails" or "domains"));
                        }
                    }
                }

                lines.Add(("values", pairs.Count == 0 ? "" : (expression ? "=" : "") + "{" + string.Join(", ", pairs) + "}"));
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation == "records" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(FreshserviceConnection);
        }

        private const string MicrosoftSharePointConnection = "choose its connection - n8n's credentials stay in n8n: add a Microsoft SharePoint connection under Admin > Connections (an app registration's client id and secret with the Sites.ReadWrite.All application permission - or Sites.Selected granted on the site - and the tenant's token endpoint) and pick it here.";

        // n8n's Microsoft SharePoint node: the site and the list (n8n's From List or By ID) and an item's id; Get Many's filter and
        // n8n's limit of 50 (its Simplify said - here an item is all its columns); the columns its mapper wrote - an Update's id among
        // them as the item's, an Upsert's matching column as the one to match on - as a JSON object, an expression among them making
        // the line one; its Auto-Map said. A file by its id (its folder only a picker's), downloaded into the site's pipeline folder
        // under its own name; an upload's folder and name, its binary said - the file read from the pipeline folder by that name, a
        // guess; an update's new name, new content said. n8n signed in as a user; here the app's own permission: said.
        private static void MicrosoftSharePoint(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)> { ("site", Locator(p, "site")) };
            switch (operation)
            {
                case "lists":
                    break;
                case "download_file":
                    lines.Add(("item", Locator(p, "file")));
                    lines.Add(("file", "downloads/"));
                    todo.Add("n8n kept the file in the item's binary 'data' - here it is written into the site's pipeline folder (downloads/, under its own name), for the file steps to read.");
                    break;
                case "upload_file":
                    lines.Add(("folder", Locator(p, "folder")));
                    lines.Add(("name", Text(p, "fileName")));
                    lines.Add(("file", Text(p, "fileName")));
                    todo.Add($"n8n sent the item's binary '{(Text(p, "fileContents") is { Length: > 0 } binary ? binary : "data")}' - here the file is read from the site's pipeline folder: 'file =' is {(Text(p, "fileName").Length > 0 ? "its name, as a guess" : "to be named")}.");
                    break;
                case "update_file":
                    lines.Add(("item", Locator(p, "file")));
                    lines.Add(("name", Text(p, "fileName")));
                    if (Bool(p, "changeFileContent"))
                    {
                        todo.Add($"n8n sent the item's binary '{(Text(p, "fileContents") is { Length: > 0 } property ? property : "data")}' as the new content - here give its file in the site's pipeline folder ('file =') or text.");
                    }

                    break;
                default:
                    lines.Add(("list", Locator(p, "list")));
                    break;
            }

            var columns = Find(p, "columns", "value");
            var mapped = columns.ValueKind == JsonValueKind.Object ? columns.EnumerateObject().ToList() : new List<JsonProperty>();
            if (operation is "item" or "delete_item")
            {
                lines.Add(("id", Locator(p, "item")));
            }
            else if (operation == "update_item")
            {
                lines.Add(("id", mapped.Any(field => field.Name == "id") ? Text(mapped.First(field => field.Name == "id").Value) : Locator(p, "item")));
            }
            else if (operation == "upsert_item")
            {
                lines.Add(("match", Find(p, "columns", "matchingColumns") is { ValueKind: JsonValueKind.Array } matching && matching.GetArrayLength() > 0 ? matching[0].GetString() ?? "" : ""));
            }

            if (operation == "items")
            {
                lines.Add(("filter", Text(p, "filter")));
                lines.Add(("max", Most(p, 50)));
                if (Text(p, "simplify") != "false")
                {
                    todo.Add("n8n gave a few of each item's fields (its Simplify) - here an item is all its columns, its id, address and times.");
                }
            }

            if (operation is "create_item" or "update_item" or "upsert_item")
            {
                if (Text(p, "columns", "mappingMode") == "autoMapInputData")
                {
                    todo.Add("n8n wrote each item's own fields as the columns (its Auto-Map) - here give the values, a JSON object of a record's columns in a For Each: 'values = {\"Title\": \"{{ Title }}\"}'.");
                }
                else
                {
                    var expression = false;
                    var pairs = mapped.Where(field => !(operation == "update_item" && field.Name == "id")).Select(field =>
                    {
                        var text = field.Value.ValueKind == JsonValueKind.String ? field.Value.GetString() ?? "" : null;
                        expression |= text?.StartsWith('=') ?? false;
                        return JsonSerializer.Serialize(field.Name, ReadableJson) + ": " + (text is null ? field.Value.GetRawText() : JsonSerializer.Serialize(Unmarked(text), ReadableJson));
                    }).ToList();
                    lines.Add(("values", pairs.Count == 0 ? "" : (expression ? "=" : "") + "{" + string.Join(", ", pairs) + "}"));
                }
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add("n8n signed in as a user - here the connection is an app with the Sites.ReadWrite.All application permission (or Sites.Selected on the site), granted by an administrator.");
            todo.Add(operation is "items" or "lists" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(MicrosoftSharePointConnection);
        }

        private const string MongoDbConnection = "choose its connection - n8n's credentials stay in n8n: add a MongoDB connection under Admin > Connections (one server's address - mongodb://db.example.com:27017/kassa?authSource=admin; for Atlas its primary's host with tls=true - a user and its password) and pick it here.";

        // n8n's MongoDB node: Find (its default) - its query, sort, projection, skip and limit (none: Return All); Insert,
        // Update, Find And Update and Find And Replace - the item's fields they wrote said, a document being this step's own JSON,
        // and the key (n8n's Update Key, 'id' its default) and Upsert; Delete - its query, an empty one (every document) said
        // and not carried over; Aggregate - its pipeline. JSON over several lines written on one; Query Parameters, date
        // fields and dot notation said.
        private static void MongoDb(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var options = Find(p, "options");
            var lines = new List<(string Name, string Value)> { ("collection", Text(p, "collection")) };
            static string Json(string value) => value.Length == 0 || value.StartsWith('=') ? value : Minified(value);
            static string Given(string value) => value is "{}" or "[]" ? "" : value;
            var fields = Text(p, "fields").Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            switch (operation)
            {
                case "find":
                    lines.Add(("query", Given(Json(Text(p, "query")))));
                    lines.Add(("sort", Given(Json(Text(options, "sort")))));
                    lines.Add(("projection", Given(Json(Text(options, "projection")))));
                    lines.Add(("skip", Text(options, "skip") is "0" ? "" : Text(options, "skip")));
                    lines.Add(("max", Text(options, "limit") is { Length: > 0 } and not "0" ? Text(options, "limit") : EveryRecord));
                    break;
                case "insert":
                    todo.Add($"n8n inserted each item's fields{(fields.Length > 0 ? " (" + string.Join(", ", fields) + ")" : "")} - here give the documents, a JSON object - or an array of them - in a For Each over the records: 'documents = {{\"{(fields.Length > 0 ? fields[0] : "kund")}\": \"{{{{ {(fields.Length > 0 ? fields[0] : "kund")} }}}}\"}}'.");
                    break;
                case "delete":
                    if (Given(Json(Text(p, "query"))) is { Length: > 0 } query)
                    {
                        lines.Add(("query", query));
                    }
                    else
                    {
                        todo.Add("its query was empty - it deleted every document of the collection; here an empty query is refused: give one, or all = true to mean every document.");
                    }

                    break;
                case "aggregate":
                    lines.Add(("pipeline", Json(Text(p, "query"))));
                    break;
                default:
                    {
                        var key = Text(p, "updateKey") is { Length: > 0 } named ? named : "id";
                        lines.Add(("key", key == "_id" ? "" : key));
                        lines.Add(("upsert", Bool(p, "upsert") ? "true" : ""));
                        todo.Add($"n8n wrote each item's fields{(fields.Length > 0 ? " (" + string.Join(", ", fields) + ")" : "")} on the document its '{key}' matches - here give the document, a JSON object of them with the '{key}' it is found by, in a For Each over the records: 'document = {{\"{key}\": \"{{{{ {key} }}}}\"}}'.");
                        break;
                    }
            }

            if (Text(p, "queryParameters") is { Length: > 0 } values && values != "=[]")
            {
                todo.Add("its query read $1, $2 from its Query Parameters - here write those values into the query, with expressions.");
            }

            if (Text(options, "dateFields").Length > 0)
            {
                todo.Add($"it read {Text(options, "dateFields")} as dates - here a date is MongoDB's extended JSON: {{\"$date\": \"2026-10-17T08:00:00Z\"}}.");
            }

            if (Bool(options, "useDotNotation"))
            {
                todo.Add("it read its fields' names in dot notation - here a nested field is a nested object.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "find" or "aggregate" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(MongoDbConnection);
        }

        private const string RedisConnection ="choose its connection - n8n's credentials stay in n8n: add a Redis connection under Admin > Connections (the server's address - cache.example.com:6379, with ssl=true for TLS - its password, and a user where the server has ACL users) and pick it here.";

        // n8n's Redis node: each operation as the connector's - a key, a list, a channel; Get's and Set's key type (n8n's 'sets'
        // a set); Set's value and its time to live (n8n's Expire and TTL), a hash's value as JSON (its 'field value' pairs said);
        // Increment's time to live; Keys' pattern and whether to read values; Push's and Pop's end (n8n's Tail); Publish's
        // message. A JSON value over several lines written on one; other text over several lines said. Where n8n wrote a value
        // into the item (Get's and Pop's Name), here it is the record's value: said.
        private static void Redis(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            var type = Text(p, "keyType") switch { "" or "automatic" => "", "sets" => "set", var named => named };
            string OneLine(string name, string value)
            {
                if (!value.Contains('\n') && !value.Contains('\r'))
                {
                    return value;
                }

                try
                {
                    return value.StartsWith('=') ? throw new JsonException() : JsonNode.Parse(value)?.ToJsonString() ?? "";
                }
                catch (JsonException)
                {
                    todo.Add($"its {name} runs over several lines - here write it on one, or read it from a record with an expression.");
                    return "";
                }
            }

            void Named(string property)
            {
                if (property.Length > 0 && property != "propertyName")
                {
                    todo.Add($"n8n wrote the value into the item's '{property}' - here it is the record's 'value'.");
                }
            }

            string Ttl() => Bool(p, "expire") ? (Text(p, "ttl") is { Length: > 0 } seconds ? seconds : "60") : "";
            switch (operation)
            {
                case "get":
                    lines.Add(("key", Text(p, "key")));
                    lines.Add(("type", type));
                    Named(Text(p, "propertyName"));
                    break;
                case "set":
                    lines.Add(("key", Text(p, "key")));
                    lines.Add(("value", OneLine("value", Text(p, "value"))));
                    lines.Add(("type", type));
                    lines.Add(("ttl", Ttl()));
                    if (type == "hash" && Text(p, "valueIsJSON") == "false")
                    {
                        todo.Add("n8n wrote the hash from 'field value' pairs - here a hash's value is a JSON object: {\"field\": \"value\"}.");
                    }

                    if (type is "list" or "set")
                    {
                        todo.Add($"n8n set the {type}'s members into it - here a {type}'s value, a JSON array, replaces it whole.");
                    }

                    break;
                case "delete":
                    lines.Add(("key", Text(p, "key")));
                    break;
                case "incr":
                    lines.Add(("key", Text(p, "key")));
                    lines.Add(("ttl", Ttl()));
                    break;
                case "keys":
                    lines.Add(("pattern", Text(p, "keyPattern")));
                    lines.Add(("values", Text(p, "getValues") == "false" ? "false" : ""));
                    todo.Add("n8n gave the keys as one item - here each key is a record, its value and type beside it.");
                    break;
                case "llen":
                    lines.Add(("list", Text(p, "list")));
                    break;
                case "push":
                    lines.Add(("list", Text(p, "list")));
                    lines.Add(("value", OneLine("data", Text(p, "messageData"))));
                    lines.Add(("end", Bool(p, "tail") ? "tail" : ""));
                    break;
                case "pop":
                    lines.Add(("list", Text(p, "list")));
                    lines.Add(("end", Bool(p, "tail") ? "tail" : ""));
                    Named(Text(p, "propertyName"));
                    break;
                case "publish":
                    lines.Add(("channel", Text(p, "channel")));
                    lines.Add(("message", OneLine("data", Text(p, "messageData"))));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "keys" or "info" ? "n8n ran it once for each item that reached it - here it runs once." : PerItem);
            todo.Add(RedisConnection);
        }

        private const string MicrosoftOneDriveConnection ="choose its connection - n8n's credentials stay in n8n: add a Microsoft OneDrive connection under Admin > Connections (an app registration's client id and secret with the Files.ReadWrite.All application permission, the tenant's token endpoint, and whose drive - a user's address or a drive's id) and pick it here.";

        // n8n's Microsoft OneDrive node: each resource and operation as the connector's - a Rename an Update of the name; a file
        // and a folder by their ids; a search's query, files or folders as the resource asks; a folder's items; a download into
        // the site's pipeline folder under its own name; an upload into its parent folder from the pipeline folder by its name
        // (n8n's binary said) or a text; a copy's new name and parent, Graph's background copy said; a move's folder and new
        // name; a share's link; a folder's name - a path of them - and its parent. n8n read the signed-in user's drive; here the
        // connection names whose: said.
        private static void MicrosoftOneDrive(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var folders = Text(p, "resource") == "folder";
            var additional = Find(p, "additionalFields");
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "search":
                    lines.Add(("query", Text(p, "query")));
                    lines.Add(("what", folders ? "folders" : "files"));
                    break;
                case "children":
                    lines.Add(("folder", Text(p, "folderId")));
                    break;
                case "get":
                case "delete":
                case "share":
                    lines.Add(("item", Text(p, folders ? "folderId" : "fileId")));
                    lines.Add(("type", operation == "share" ? Text(p, "type") : ""));
                    lines.Add(("scope", operation == "share" ? Text(p, "scope") : ""));
                    break;
                case "download":
                    lines.Add(("item", Text(p, "fileId")));
                    lines.Add(("file", "downloads/"));
                    todo.Add($"n8n kept the file in the item's binary '{(Text(p, "binaryPropertyName") is { Length: > 0 } property ? property : "data")}' - here it is written into the site's pipeline folder (downloads/, under its own name), for the file steps to read.");
                    break;
                case "upload":
                    lines.Add(("name", Text(p, "fileName")));
                    lines.Add(("folder", Text(p, "parentId")));
                    if (Bool(p, "binaryData"))
                    {
                        lines.Add(("file", Text(p, "fileName")));
                        todo.Add($"n8n sent the item's binary '{(Text(p, "binaryPropertyName") is { Length: > 0 } binary ? binary : "data")}' - here the file is read from the site's pipeline folder: 'file =' is {(Text(p, "fileName").Length > 0 ? "its name, as a guess" : "to be named")}.");
                    }
                    else
                    {
                        var content = Text(p, "fileContent");
                        if (content.Contains('\n') || content.Contains('\r'))
                        {
                            todo.Add("its text runs over several lines - here write it to a file with Write text file and give that file.");
                        }
                        else
                        {
                            lines.Add(("text", content));
                        }
                    }

                    break;
                case "update":
                    lines.Add(("item", Text(p, "itemId")));
                    lines.Add(("name", Text(p, "newName")));
                    break;
                case "copy":
                    {
                        var parent = Find(p, "parentReference");
                        lines.Add(("item", Text(p, "fileId")));
                        lines.Add(("name", Text(additional, "name")));
                        lines.Add(("folder", Text(parent, "id")));
                        lines.Add(("drive", Text(parent, "driveId")));
                        if (new[] { "path", "name", "siteId", "listId", "shareId", "driveType" }.Any(field => Text(parent, field).Length > 0))
                        {
                            todo.Add("it named the copy's parent by more than its id and drive (its path, name, site, list, share or drive type) - here give the folder's id and the drive's.");
                        }

                        todo.Add("Graph copies in the background - here the step's record is the copy's status and the address that reports on it; the copy is not waited for.");
                        break;
                    }

                case "move":
                    lines.Add(("item", Text(p, folders ? "folderId" : "fileId")));
                    lines.Add(("folder", Text(p, "destinationFolderId")));
                    lines.Add(("name", Text(additional, "name")));
                    break;
                case "create_folder":
                    lines.Add(("name", Text(p, "name")));
                    lines.Add(("folder", Text(Find(p, "options"), "parentFolderId")));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add("n8n read the signed-in user's own drive - here the connection is an app with the Files.ReadWrite.All application permission, granted by an administrator, and names whose drive: a user's address or a drive's id.");
            todo.Add(operation is "search" or "children" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(MicrosoftOneDriveConnection);
        }

        private const string DropboxConnection = "choose its connection - n8n's credentials stay in n8n: add a Dropbox connection under Admin > Connections (an app's key and secret, from Dropbox's App Console, and a refresh token of an offline grant; Root team for a team's whole space, as n8n's Full Dropbox access) and pick it here.";

        // n8n's Dropbox node: each resource and operation as the connector's - a folder listed with its filters and limit; a search
        // by name, in a folder, by category and extension; a download into the site's pipeline folder under its own name; an
        // upload to its path from the pipeline folder (n8n's binary said) or of its text, overwriting as n8n's did; a folder made;
        // a copy and a move from its path to another; a delete.
        private static void Dropbox(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var path = Text(p, "path");
            var filters = Find(p, "filters");
            var binary = Text(p, "binaryPropertyName") is { Length: > 0 } property ? property : "data";
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "list":
                    lines.Add(("path", path));
                    foreach (var (n8n, ours) in new[] { ("recursive", "recursive"), ("include_deleted", "deleted"), ("include_has_explicit_shared_members", "shared_members") })
                    {
                        if (Bool(filters, n8n))
                        {
                            lines.Add((ours, "true"));
                        }
                    }

                    foreach (var (n8n, ours) in new[] { ("include_mounted_folders", "mounted"), ("include_non_downloadable_files", "non_downloadable") })
                    {
                        if (Text(filters, n8n) == "false")
                        {
                            lines.Add((ours, "false"));
                        }
                    }

                    lines.Add(("max", Most(p, 100)));
                    break;
                case "search":
                    lines.Add(("query", Text(p, "query")));
                    lines.Add(("path", Text(filters, "path")));
                    var categories = Find(filters, "file_categories");
                    lines.Add(("categories", categories.ValueKind == JsonValueKind.Array ? string.Join(", ", categories.EnumerateArray().Select(category => Text(category)).Where(category => category.Length > 0)) : ""));
                    lines.Add(("extensions", Text(filters, "file_extensions")));
                    lines.Add(("max", Most(p, 100)));
                    todo.Add("n8n answered each match" + (Text(p, "simple") == "false" ? " as Dropbox gave it" : ", simplified") + " - here each is its file's or folder's fields, named as n8n's folder List names them (pathDisplay, contentSize...).");
                    break;
                case "download":
                    lines.Add(("path", path));
                    lines.Add(("file", "downloads/"));
                    todo.Add($"n8n kept the file in the item's binary '{binary}' - here it is written into the site's pipeline folder (downloads/, under its own name), for the file steps to read.");
                    break;
                case "upload":
                    lines.Add(("path", path));
                    if (Bool(p, "binaryData"))
                    {
                        lines.Add(("file", path.StartsWith('=') ? path : path.TrimEnd('/')[(path.TrimEnd('/').LastIndexOf('/') + 1)..]));
                        todo.Add($"n8n sent the item's binary '{binary}' - here the file is read from the site's pipeline folder: 'file =' is its name, as a guess.");
                    }
                    else
                    {
                        // A parameter is one line: text over several is a file's.
                        var content = Text(p, "fileContent");
                        if (content.Contains('\n') || content.Contains('\r'))
                        {
                            todo.Add("its text runs over several lines - here write it to a file with Write text file and give that file.");
                        }
                        else
                        {
                            lines.Add(("text", content));
                        }
                    }

                    break;
                case "copy":
                case "move":
                    lines.Add(("from", path));
                    lines.Add(("to", Text(p, "toPath")));
                    break;
                default: // create_folder, delete
                    lines.Add(("path", path));
                    break;
            }

            if (operation is "copy" or "move" or "delete" or "create_folder")
            {
                todo.Add("n8n answered Dropbox's reply as it came, {metadata: ...} - here the step's record is that metadata's fields themselves (name, path_display...).");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "list" or "search" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(DropboxConnection);
        }

        private const string BaserowConnection = "choose its connection - n8n's credentials stay in n8n: add a Baserow connection under Admin > Connections (its address - https://api.baserow.io, or your Baserow's own - and a database token, Settings > Database tokens) and pick it here.";

        // n8n's Baserow row operations as the Baserow connector's: the table by its id (n8n's database needs no input here); a
        // row's id; its fields by n8n's field ids (field_123 - the connector reads them by their names through the table's fields),
        // or, as n8n's Auto-Map wrote the item's own, said to be given; Get Many's filters - each field by its id, n8n's operator
        // Baserow's own, a date's time zone before its value as n8n sends it - match, search and sort, and its limit (50 when the
        // export leaves it out); a batch's rows and ids. A user's password n8n signed in by said: here a database token.
        private static void Baserow(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var additional = Find(p, "additionalOptions");
            var lines = new List<(string Name, string Value)> { ("table", Text(p, "tableId")) };

            // A field n8n names by its id - a number, or digits - as the connector reads one: field_123.
            static string FieldKey(string id) => id.Length > 0 && id.All(char.IsAsciiDigit) ? "field_" + id : id;

            // n8n's field and value pairs (its fieldsUi) as a JSON object - an expression among them making the line one.
            string? Object(JsonElement parent)
            {
                var pairs = Items(parent, "fieldsUi", "fieldValues").Select(pair => (Name: FieldKey(Text(pair, "fieldId")), Value: Text(pair, "fieldValue"))).Where(pair => pair.Name.Length > 0).ToList();
                return pairs.Count == 0 ? null : "{" + string.Join(", ", pairs.Select(pair => JsonSerializer.Serialize(pair.Name, ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(pair.Value), ReadableJson))) + "}";
            }

            bool Expression(JsonElement parent) => Items(parent, "fieldsUi", "fieldValues").Any(pair => Text(pair, "fieldValue").StartsWith('='));

            var autoMap = Text(p, "dataToSend") == "autoMapInputData";
            switch (operation)
            {
                case "rows":
                    {
                        var expression = false;
                        var conditions = Items(additional, "filters", "fields").Where(filter => Text(filter, "field").Length > 0).Select(filter =>
                        {
                            var field = Text(filter, "field");
                            var type = Text(filter, "operator") is { Length: > 0 } named ? named : "equal";
                            var value = Text(filter, "value");
                            expression |= value.StartsWith('=');
                            value = Unmarked(value);
                            if (type.StartsWith("date", StringComparison.Ordinal) && !value.Contains('?', StringComparison.Ordinal))
                            {
                                value = (Text(filter, "timezone") is { Length: > 0 } zone ? zone : "UTC") + "?" + value; // as n8n sends a date's
                            }

                            return "{\"field\": " + (field.All(char.IsAsciiDigit) ? field : JsonSerializer.Serialize(field, ReadableJson)) + ", \"type\": " + JsonSerializer.Serialize(type, ReadableJson) + ", \"value\": " + JsonSerializer.Serialize(value, ReadableJson) + "}";
                        }).ToList();
                        lines.Add(("filters", conditions.Count == 0 ? "" : (expression ? "=" : "") + "[" + string.Join(", ", conditions) + "]"));
                        lines.Add(("filter_type", Text(additional, "filterType") is "OR" ? "OR" : ""));
                        lines.Add(("search", Text(additional, "search")));
                        var order = Items(additional, "order", "fields").Where(item => Text(item, "field").Length > 0).Select(item => (Text(item, "direction") == "-" ? "-" : "") + FieldKey(Text(item, "field")));
                        lines.Add(("order_by", string.Join(",", order)));
                        lines.Add(("max", Most(p, 50)));
                        break;
                    }

                case "get_row":
                case "delete_row":
                    lines.Add(("row", Text(p, "rowId")));
                    break;
                case "create_row":
                case "update_row":
                    lines.Add(("row", operation == "update_row" ? Text(p, "rowId") : ""));
                    if (autoMap)
                    {
                        todo.Add("n8n wrote each item's own fields as the row (its Auto-Map Input Data) - here give the fields, a JSON object of the row's fields in a For Each: 'fields = {\"Name\": \"{{ name }}\"}'.");
                        break;
                    }

                    lines.Add(("fields", Object(p) is { } written ? (Expression(p) ? "=" : "") + written : ""));
                    break;
                case "create_rows":
                case "update_rows":
                    {
                        if (autoMap)
                        {
                            todo.Add("n8n wrote the items' own fields as the rows (its Auto-Map Input Data) - here give the rows, a JSON list of their fields: 'rows = [{\"Name\": \"Ada\"}]'.");
                            break;
                        }

                        var rows = Items(p, "rowsUi", "rowValues").Select(row =>
                        {
                            var written = Object(row) ?? "{}";
                            return operation == "update_rows" && Text(row, "id") is { Length: > 0 } id
                                ? "{\"id\": " + (id.All(char.IsAsciiDigit) ? id : JsonSerializer.Serialize(Unmarked(id), ReadableJson)) + (written == "{}" ? "}" : ", " + written[1..])
                                : written;
                        }).ToList();
                        var expression = Items(p, "rowsUi", "rowValues").Any(row => Expression(row) || Text(row, "id").StartsWith('='));
                        lines.Add(("rows", rows.Count == 0 ? "" : (expression ? "=" : "") + "[" + string.Join(", ", rows) + "]"));
                        break;
                    }

                case "delete_rows":
                    {
                        if (autoMap)
                        {
                            todo.Add($"n8n deleted the rows whose ids the items' '{Text(p, "rowIdProperty")}' held - here give the rows' ids: 'rows = 7, 8'.");
                            break;
                        }

                        var ids = Find(p, "rowIds");
                        lines.Add(("rows", ids.ValueKind == JsonValueKind.Array ? string.Join(", ", ids.EnumerateArray().Select(id => Text(id)).Where(id => id.Length > 0)) : Text(ids)));
                        break;
                    }
            }

            if (Text(p, "authentication") != "databaseToken")
            {
                todo.Add("n8n signed in as a Baserow user, by a password - here the connection is a database token, which Baserow scopes to a workspace's tables.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "rows" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(BaserowConnection);
        }

        private const string RabbitMqConnection = "choose its connection - n8n's credentials stay in n8n: add a RabbitMQ connection under Admin > Connections (its broker's address - amqp://rabbit.example.com:5672/vhost, amqps:// for TLS - and a user and password) and pick it here.";

        // n8n's RabbitMQ Send a Message as the RabbitMQ connector's publish: to its queue, or to its exchange - its type and routing
        // key - its message (one over several lines in the step's Query box), its durability and headers; the item's JSON n8n
        // sent by default said to be given; a queue's or exchange's arguments, auto-delete, exclusive and alternate exchange said.
        private static void RabbitMq(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            Set(step, "Operation", "publish");
            var options = Find(p, "options");
            var lines = new List<(string Name, string Value)>();
            if (Text(p, "mode") == "exchange")
            {
                lines.Add(("exchange", Text(p, "exchange")));
                lines.Add(("exchange_type", Text(p, "exchangeType") is { Length: > 0 } type ? type : "fanout"));
                lines.Add(("routing_key", Text(p, "routingKey")));
            }
            else
            {
                lines.Add(("queue", Text(p, "queue")));
            }

            if (Text(p, "sendInputData") != "false")
            {
                todo.Add("n8n sent each item's own JSON as the message (its Send Input Data) - here give the message: the record as JSON in a For Each, 'message = {{ record }}'.");
            }
            else
            {
                var message = Text(p, "message");
                if (message.Contains('\n') || message.Contains('\r'))
                {
                    Set(step, "Query", message); // a message over several lines: the step's Query box
                }
                else
                {
                    lines.Add(("message", message));
                }
            }

            if (Text(options, "durable") == "false")
            {
                lines.Add(("durable", "false"));
            }

            var headers = Items(options, "headers", "header").Where(header => Text(header, "key").Length > 0).ToList();
            if (headers.Count > 0)
            {
                lines.Add(("headers", (headers.Any(header => Text(header, "value").StartsWith('=')) ? "=" : "") + "{" + string.Join(", ", headers.Select(header =>
                    JsonSerializer.Serialize(Text(header, "key"), ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(Text(header, "value")), ReadableJson))) + "}"));
            }

            if (Items(options, "arguments", "argument").Any() || Bool(options, "autoDelete") || Bool(options, "exclusive") || Text(options, "alternateExchange").Length > 0)
            {
                todo.Add("its queue's or exchange's arguments, auto-delete, exclusive or alternate exchange are not declared here - declare the queue or exchange so on the broker, and set 'declare = false'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(PerItem);
            todo.Add(RabbitMqConnection);
        }

        private const string MqttConnection = "choose its connection - n8n's credentials stay in n8n: add an MQTT connection under Admin > Connections (its broker's address - mqtt://broker.example.com:1883, mqtts:// for TLS - and a user and password when it asks for one) and pick it here.";

        // n8n's MQTT Send a Message as the MQTT connector's publish: its topic, its message (one over several lines in the step's
        // Query box), its QoS and retain; the item's JSON n8n sent by default said to be given.
        private static void Mqtt(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            Set(step, "Operation", "publish");
            var options = Find(p, "options");
            var lines = new List<(string Name, string Value)> { ("topic", Text(p, "topic")) };
            if (Text(p, "sendInputData") != "false")
            {
                todo.Add("n8n sent each item's own JSON as the message (its Send Input Data) - here give the message: the record as JSON in a For Each, 'message = {{ record }}'.");
            }
            else
            {
                var message = Text(p, "message");
                if (message.Contains('\n') || message.Contains('\r'))
                {
                    Set(step, "Query", message); // a message over several lines: the step's Query box
                }
                else
                {
                    lines.Add(("message", message));
                }
            }

            if (Text(options, "qos") is "1" or "2")
            {
                lines.Add(("qos", Text(options, "qos")));
            }

            if (Bool(options, "retain"))
            {
                lines.Add(("retain", "true"));
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(PerItem);
            todo.Add(MqttConnection);
        }

        private const string NextcloudConnection = "choose its connection - n8n's credentials stay in n8n: add a Nextcloud connection under Admin > Connections (the server's address - https://cloud.example.com; n8n's WebDAV URL is read as it - and a user with an app password, from Personal settings > Security) and pick it here.";

        // n8n's Nextcloud share types by number, as the connector names them.
        private static readonly Dictionary<string, (string Type, string With)> NextcloudShares = new(StringComparer.Ordinal)
        {
            ["0"] = ("user", "user"), ["1"] = ("group", "groupId"), ["3"] = ("link", ""), ["4"] = ("email", "email"), ["7"] = ("team", "circleId"), ["200"] = ("internal", ""),
        };

        // n8n's Nextcloud node: each resource and operation as the connector's - a file's or folder's path and its new one; a
        // download into the site's pipeline folder under its own name; an upload of its text (one over several lines in the step's
        // Query box) or from the pipeline folder (n8n's binary said); a share's type, whom with and permissions (a link's password
        // said: it is set in Nextcloud, never a step's parameter); a user's id, address and display name; Get Many's search, offset
        // and limit; an update's field (a password said).
        private static void Nextcloud(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var path = Text(p, "path");
            var options = Find(p, "options");
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "download":
                    lines.Add(("path", path));
                    lines.Add(("file", "downloads/"));
                    todo.Add($"n8n kept the file in the item's binary '{(Text(p, "binaryPropertyName") is { Length: > 0 } property ? property : "data")}' - here it is written into the site's pipeline folder (downloads/, under its own name), for the file steps to read.");
                    break;
                case "upload":
                    lines.Add(("path", path));
                    if (Bool(p, "binaryDataUpload"))
                    {
                        lines.Add(("file", path.StartsWith('=') ? path : path.TrimEnd('/')[(path.TrimEnd('/').LastIndexOf('/') + 1)..]));
                        todo.Add($"n8n sent the item's binary '{(Text(p, "binaryPropertyName") is { Length: > 0 } binary ? binary : "data")}' - here the file is read from the site's pipeline folder: 'file =' is its name, as a guess.");
                    }
                    else
                    {
                        var content = Text(p, "fileContent");
                        if (content.Contains('\n') || content.Contains('\r'))
                        {
                            Set(step, "Query", content); // text over several lines: the step's Query box
                        }
                        else
                        {
                            lines.Add(("text", content));
                        }
                    }

                    break;
                case "copy":
                case "move":
                    lines.Add(("from", path));
                    lines.Add(("to", Text(p, "toPath")));
                    break;
                case "share":
                    {
                        lines.Add(("path", path));
                        var (type, with) = NextcloudShares.TryGetValue(Text(p, "shareType") is { Length: > 0 } number ? number : "0", out var known) ? known : (Text(p, "shareType"), "");
                        lines.Add(("type", type));
                        if (with.Length > 0)
                        {
                            lines.Add(("with", Text(p, with)));
                        }

                        lines.Add(("permissions", Text(options, "permissions")));
                        if (Text(options, "password").Length > 0)
                        {
                            todo.Add("n8n set the link's password - a password is never a step's parameter here: set it on the share in Nextcloud.");
                        }

                        break;
                    }

                case "users":
                    lines.Add(("search", Text(options, "search")));
                    lines.Add(("offset", Text(options, "offset")));
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "user_create":
                    lines.Add(("user", Text(p, "userId")));
                    lines.Add(("email", Text(p, "email")));
                    lines.Add(("display_name", Text(p, "additionalFields", "displayName")));
                    break;
                case "user_get":
                case "user_delete":
                    lines.Add(("user", Text(p, "userId")));
                    break;
                case "user_update":
                    {
                        lines.Add(("user", Text(p, "userId")));
                        var field = Find(p, "updateFields", "field");
                        foreach (var entry in field.ValueKind == JsonValueKind.Array ? field.EnumerateArray().ToList() : new List<JsonElement> { field })
                        {
                            switch (Text(entry, "key") is { Length: > 0 } given ? given : "email")
                            {
                                case "password":
                                    todo.Add("n8n set the user's password - a password is never a step's parameter here: the user sets their own in Nextcloud.");
                                    break;
                                case var key when entry.ValueKind == JsonValueKind.Object:
                                    lines.Add((key == "displayname" ? "display_name" : key, Text(entry, "value")));
                                    break;
                            }
                        }

                        break;
                    }

                default: // list, create_folder, delete
                    lines.Add(("path", path));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "list" or "users" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(NextcloudConnection);
        }

        private const string AzureStorageConnection = "choose its connection - n8n's credentials stay in n8n: add an Azure Storage connection under Admin > Connections (the account's address - https://{account}.blob.core.windows.net - and its account key, from the account's Access keys) and pick it here.";

        // A fixed collection of n8n's name and value pairs as a JSON object - an expression among them making the whole one.
        private static string JsonPairs(IEnumerable<JsonElement> items, string name, string value)
        {
            var pairs = items.Where(item => Text(item, name).Length > 0).ToList();
            return pairs.Count == 0 ? "" : (pairs.Any(item => Text(item, value).StartsWith('=')) ? "=" : "") + "{" + string.Join(", ", pairs.Select(item =>
                JsonSerializer.Serialize(Text(item, name), ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(Text(item, value)), ReadableJson))) + "}";
        }

        // n8n's Azure Storage node: each resource and operation as the connector's - a container by its name (n8n's list or by
        // name alike); Get Many's filter and limit, and the fields it includes; a container made public or not, with its metadata;
        // a blob downloaded into the site's pipeline folder; one created from the pipeline folder (n8n's binary said) or from a URL,
        // its tier, type, metadata and tags; one deleted. What n8n set that has no counterpart here - a lease, an expiry, a cache
        // control, encryption, a legal hold - said.
        private static void AzureStorage(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var options = Find(p, "options");
            var lines = new List<(string Name, string Value)>();
            if (operation != "containers")
            {
                lines.Add(("container", operation == "container_create" ? Text(p, "containerCreate") : Locator(p, "container")));
            }

            var fields = Find(options, "fields");
            var include = fields.ValueKind == JsonValueKind.Array ? fields.EnumerateArray().Select(field => Text(field)).Where(field => field.Length > 0).ToList() : new List<string>();
            switch (operation)
            {
                case "containers":
                    lines.Add(("prefix", Text(options, "filter")));
                    if (include.Contains("metadata"))
                    {
                        lines.Add(("metadata", "true"));
                    }

                    lines.Add(("max", Most(p, 50)));
                    break;
                case "container_create":
                    lines.Add(("access", Text(options, "accessLevel")));
                    lines.Add(("metadata", JsonPairs(Items(options, "metadata", "metadataValues"), "fieldName", "fieldValue")));
                    break;
                case "blobs":
                    lines.Add(("include", string.Join(", ", include)));
                    lines.Add(("max", Most(p, 50)));
                    if (Find(options, "filter").ValueKind == JsonValueKind.Array && Find(options, "filter").GetArrayLength() > 0)
                    {
                        todo.Add("n8n's filter (only deleted, files or directories) has no counterpart here - every blob is listed; give a prefix for a folder's.");
                    }

                    break;
                case "download":
                    lines.Add(("blob", Locator(p, "blob")));
                    lines.Add(("file", "downloads/"));
                    todo.Add("n8n kept the blob in the item's binary 'data' - here it is written into the site's pipeline folder (downloads/, under its own name), for the file steps to read.");
                    break;
                case "upload":
                    {
                        var blob = Text(p, "blobCreate");
                        lines.Add(("blob", blob));
                        if (Text(p, "from") == "url")
                        {
                            lines.Add(("url", Text(p, "url")));
                        }
                        else
                        {
                            lines.Add(("file", blob.StartsWith('=') ? blob : blob.TrimEnd('/')[(blob.TrimEnd('/').LastIndexOf('/') + 1)..]));
                            todo.Add($"n8n sent the item's binary '{(Text(p, "binaryPropertyName") is { Length: > 0 } binary ? binary : "data")}' - here the file is read from the site's pipeline folder: 'file =' is its name, as a guess.");
                        }

                        lines.Add(("content_type", Text(options, "contentType")));
                        lines.Add(("tier", Text(options, "accessTier")));
                        lines.Add(("metadata", JsonPairs(Items(options, "metadata", "metadataValues"), "fieldName", "fieldValue")));
                        lines.Add(("tags", JsonPairs(Items(options, "tags", "tagValues"), "tagName", "tagValue")));
                        var unset = new[] { "blobType", "cacheControl", "contentCrc64", "contentEncoding", "contentLanguage", "contentMd5", "encryptionContext", "encryptionScope", "expiryOption", "expiryTime", "filename", "immutabilityPolicyUntilDate", "immutabilityPolicyMode", "leaseId", "legalHold", "origin" }
                            .Where(name => Text(options, name).Length > 0 && !(name == "blobType" && Text(options, name) == "BlockBlob")).ToList();
                        if (unset.Count > 0)
                        {
                            todo.Add($"n8n set {string.Join(", ", unset)} - not set here: a block blob with its type, tier, metadata and tags; set the rest on the blob in Azure.");
                        }

                        break;
                    }

                case "delete":
                    lines.Add(("blob", Locator(p, "blob")));
                    break;
            }

            if (Text(options, "leaseId").Length > 0 && operation != "upload")
            {
                todo.Add("n8n named a lease - not taken here: a blob under a lease is refused until it is released.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "containers" or "blobs" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            if (Text(p, "authentication") == "oAuth2")
            {
                todo.Add("n8n signed in through OAuth2 - here the connection signs with the account's key (Shared Key).");
            }

            todo.Add(AzureStorageConnection);
        }

        private const string GoogleCloudStorageConnection = "choose its connection - n8n's credentials stay in n8n: add a Google Cloud Storage connection under Admin > Connections (an OAuth client's id and secret, from the Google Cloud console, and a refresh token granted the devstorage scope) and pick it here.";

        // A JSON value n8n kept as text (its json fields): the object as one line, or nothing when it is empty or not an object.
        private static string JsonObjectText(JsonElement parent, string name)
        {
            var text = Text(parent, name);
            if (text.StartsWith('='))
            {
                return text;
            }

            try
            {
                using var parsed = JsonDocument.Parse(text.Length > 0 ? text : "{}");
                return parsed.RootElement.ValueKind == JsonValueKind.Object && parsed.RootElement.EnumerateObject().Any() ? JsonSerializer.Serialize(parsed.RootElement, ReadableJson) : "";
            }
            catch (JsonException)
            {
                return "";
            }
        }

        // n8n's Google Cloud Storage node: each resource and operation as the connector's - a project by its id (n8n's locator or
        // its text alike), a bucket and an object by name; a bucket's location, storage class, labels and versioning; Get Many's
        // prefix, delimiter, versions and limit (every one when n8n returned all); an object's Get as its metadata, or - its data -
        // a download into the site's pipeline folder; Create from the pipeline folder (n8n's binary said) or its text, its type,
        // storage class and metadata, refused when it exists where n8n asked ifGenerationMatch 0; Update's metadata and headers.
        // What has no counterpart here - ACLs, a bucket's other settings, a metageneration condition, encryption keys - said.
        private static void GoogleCloudStorage(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            var bucket = Text(p, "bucketName");
            var objectName = Text(p, "objectName");
            var unset = new List<string>();
            void Unset(JsonElement collection, params string[] handled)
            {
                if (collection.ValueKind == JsonValueKind.Object)
                {
                    unset.AddRange(collection.EnumerateObject().Select(field => field.Name).Where(name => !handled.Contains(name) && Text(collection, name) is { Length: > 0 } value && value is not ("[]" or "{}" or "-1" or "0" or "false")));
                }
            }

            switch (operation)
            {
                case "buckets":
                    lines.Add(("project", Locator(p, "projectRLC") is { Length: > 0 } listed ? listed : Text(p, "projectId")));
                    lines.Add(("prefix", Text(p, "prefix")));
                    lines.Add(("max", Bool(p, "returnAll") ? EveryRecord : Text(p, "projection") == "full" ? "200" : "1000"));
                    break;
                case "bucket_create":
                    {
                        lines.Add(("project", Locator(p, "projectRLC") is { Length: > 0 } project ? project : Text(p, "projectId")));
                        lines.Add(("bucket", bucket));
                        var body = Find(p, "createBody");
                        lines.Add(("location", Text(body, "location")));
                        lines.Add(("storage_class", Text(body, "storageClass")));
                        lines.Add(("labels", JsonObjectText(body, "labels")));
                        if (JsonObjectText(body, "versioning").Replace(" ", "").Contains("\"enabled\":true", StringComparison.Ordinal))
                        {
                            lines.Add(("versioning", "true"));
                        }

                        Unset(body, "location", "storageClass", "labels", "versioning");
                        Unset(Find(p, "createAcl"));
                        break;
                    }

                case "bucket_get":
                case "bucket_delete":
                    lines.Add(("bucket", bucket));
                    Unset(Find(p, "getFilters"));
                    break;
                case "objects":
                    {
                        var filters = Find(p, "listFilters");
                        lines.Add(("bucket", bucket));
                        lines.Add(("prefix", Text(filters, "prefix")));
                        lines.Add(("delimiter", Text(filters, "delimiter")));
                        if (Bool(filters, "versions"))
                        {
                            lines.Add(("versions", "true"));
                        }

                        lines.Add(("max", Bool(p, "returnAll") ? EveryRecord : Text(p, "maxResults") is { Length: > 0 } most ? most : "100"));
                        Unset(filters, "prefix", "delimiter", "versions");
                        break;
                    }

                case "get":
                case "delete":
                    lines.Add(("bucket", bucket));
                    lines.Add(("object", objectName));
                    Unset(Find(p, "getParameters"));
                    break;
                case "download":
                    lines.Add(("bucket", bucket));
                    lines.Add(("object", objectName));
                    lines.Add(("file", "downloads/"));
                    todo.Add($"n8n kept the object in the item's binary '{(Text(p, "binaryPropertyName") is { Length: > 0 } property ? property : "data")}' - here it is written into the site's pipeline folder (downloads/, under its own name), for the file steps to read.");
                    Unset(Find(p, "getParameters"));
                    break;
                case "upload":
                    {
                        lines.Add(("bucket", bucket));
                        lines.Add(("object", objectName));
                        if (Text(p, "createFromBinary") != "false")
                        {
                            lines.Add(("file", objectName.StartsWith('=') ? objectName : objectName.TrimEnd('/')[(objectName.TrimEnd('/').LastIndexOf('/') + 1)..]));
                            todo.Add($"n8n sent the item's binary '{(Text(p, "createBinaryPropertyName") is { Length: > 0 } binary ? binary : "data")}' - here the file is read from the site's pipeline folder: 'file =' is its name, as a guess.");
                        }
                        else
                        {
                            var content = Text(p, "createContent");
                            if (content.Contains('\n') || content.Contains('\r'))
                            {
                                Set(step, "Query", content); // text over several lines: the step's Query box
                            }
                            else
                            {
                                lines.Add(("text", content));
                            }
                        }

                        var data = Find(p, "createData");
                        lines.Add(("content_type", Text(data, "contentType")));
                        lines.Add(("storage_class", Text(data, "storageClass")));
                        lines.Add(("metadata", JsonObjectText(data, "metadata")));
                        var query = Find(p, "createQuery");
                        if (Text(query, "ifGenerationMatch") == "0")
                        {
                            lines.Add(("overwrite", "false"));
                        }

                        Unset(data, "contentType", "storageClass", "metadata");
                        Unset(query, "ifGenerationMatch");
                        break;
                    }

                case "update":
                    {
                        lines.Add(("bucket", bucket));
                        lines.Add(("object", objectName));
                        var data = Find(p, "updateData");
                        lines.Add(("metadata", JsonObjectText(data, "metadata")));
                        lines.Add(("content_type", Text(data, "contentType")));
                        lines.Add(("cache_control", Text(data, "cacheControl")));
                        lines.Add(("content_disposition", Text(data, "contentDisposition")));
                        Unset(data, "metadata", "contentType", "cacheControl", "contentDisposition");
                        Unset(Find(p, "metagenAndAclQuery"));
                        break;
                    }
            }

            if (Find(p, "encryptionHeaders").ValueKind == JsonValueKind.Object && Text(Find(p, "encryptionHeaders"), "X-Goog-Encryption-Key").Length > 0)
            {
                unset.Add("an encryption key");
            }

            if (unset.Count > 0)
            {
                todo.Add($"n8n set {string.Join(", ", unset.Distinct())} - not set here: set it in Google Cloud.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "buckets" or "objects" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            if (Text(p, "authentication") == "serviceAccount")
            {
                todo.Add("n8n signed in as a service account - here the connection is an OAuth client and a refresh token granted the devstorage scope.");
            }

            todo.Add(GoogleCloudStorageConnection);
        }

        private const string BoxConnection = "choose its connection - n8n's credentials stay in n8n: add a Box connection under Admin > Connections (a server app's client id and secret - Client Credentials Grant, from Box's Developer Console - and the enterprise's id it acts as) and pick it here.";

        // n8n's Box node: each resource and operation as the connector's - a file or folder by its id; an upload of its text (one
        // over several lines in the step's Query box) or from the pipeline folder (n8n's binary said), into its folder; a download
        // into the pipeline folder; a copy with its name; a search of files or folders with its limit and filters; a share with a
        // user by address or id, or a group, as its role; a folder made, got, updated (its name, description and parent) and
        // deleted. What has no counterpart - a fields selection, a version, date and size ranges, a folder's shared link and its
        // collaborator settings - said; n8n's user OAuth2 said: here a server app.
        private static void Box(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var resource = Text(p, "resource") is { Length: > 0 } named ? named : "file";
            var lines = new List<(string Name, string Value)>();
            var unset = new List<string>();
            void Unset(JsonElement collection, params string[] handled)
            {
                if (collection.ValueKind == JsonValueKind.Object)
                {
                    unset.AddRange(collection.EnumerateObject().Select(field => field.Name).Where(name => !handled.Contains(name) && Text(collection, name) is { Length: > 0 } value && value is not ("false" or "{}" or "[]")));
                }
            }

            switch (operation)
            {
                case "upload":
                    {
                        var name = Text(p, "fileName");
                        lines.Add(("name", name));
                        lines.Add(("parent", Text(p, "parentId")));
                        if (Bool(p, "binaryData"))
                        {
                            lines.Add(("file", name.Length > 0 ? name : "upload"));
                            todo.Add($"n8n sent the item's binary '{(Text(p, "binaryPropertyName") is { Length: > 0 } binary ? binary : "data")}' - here the file is read from the site's pipeline folder: 'file =' is its name, as a guess.");
                        }
                        else
                        {
                            var content = Text(p, "fileContent");
                            if (content.Contains('\n') || content.Contains('\r'))
                            {
                                Set(step, "Query", content); // text over several lines: the step's Query box
                            }
                            else
                            {
                                lines.Add(("text", content));
                            }
                        }

                        break;
                    }

                case "download":
                    lines.Add(("file_id", Text(p, "fileId")));
                    lines.Add(("file", "downloads/"));
                    todo.Add($"n8n kept the file in the item's binary '{(Text(p, "binaryPropertyName") is { Length: > 0 } property ? property : "data")}' - here it is written into the site's pipeline folder (downloads/, under its own name), for the file steps to read.");
                    break;
                case "get":
                case "delete":
                    lines.Add(("file_id", Text(p, "fileId")));
                    Unset(Find(p, "additionalFields"));
                    break;
                case "copy":
                    {
                        var additional = Find(p, "additionalFields");
                        lines.Add(("file_id", Text(p, "fileId")));
                        lines.Add(("parent", Text(p, "parentId")));
                        lines.Add(("name", Text(additional, "name")));
                        Unset(additional, "name");
                        break;
                    }

                case "search":
                    {
                        var additional = Find(p, "additionalFields");
                        lines.Add(("query", Text(p, "query")));
                        lines.Add(("type", resource));
                        lines.Add(("folders", Text(additional, "ancestor_folder_ids")));
                        lines.Add(("extensions", Text(additional, "file_extensions")));
                        lines.Add(("content_types", Text(additional, "contet_types")));
                        if (Text(additional, "trash_content") == "trashed_only")
                        {
                            lines.Add(("trash", "true"));
                        }

                        lines.Add(("max", Most(p, 100)));
                        Unset(additional, "ancestor_folder_ids", "file_extensions", "contet_types", "trash_content", "sort");
                        if (Text(additional, "sort") is "modified_at")
                        {
                            unset.Add("sort");
                        }

                        break;
                    }

                case "share":
                    {
                        lines.Add(("item_type", resource));
                        lines.Add(("item_id", Text(p, resource == "folder" ? "folderId" : "fileId")));
                        if (Text(p, "accessibleBy") == "group")
                        {
                            lines.Add(("group_id", Text(p, "groupId")));
                        }
                        else if (Text(p, "useEmail") == "false")
                        {
                            lines.Add(("user_id", Text(p, "userId")));
                        }
                        else
                        {
                            lines.Add(("email", Text(p, "email")));
                        }

                        lines.Add(("role", Text(p, "role") is { Length: > 0 } role ? role : "editor"));
                        var options = Find(p, "options");
                        if (Bool(options, "can_view_path"))
                        {
                            lines.Add(("can_view_path", "true"));
                        }

                        lines.Add(("expires", Text(options, "expires_at")));
                        if (Bool(options, "notify"))
                        {
                            lines.Add(("notify", "true"));
                        }

                        Unset(options, "can_view_path", "expires_at", "notify");
                        break;
                    }

                case "folder_create":
                    {
                        var options = Find(p, "options");
                        lines.Add(("name", Text(p, "name")));
                        lines.Add(("parent", Text(p, "parentId")));
                        lines.Add(("access", Text(options, "access")));
                        Unset(options, "access");
                        break;
                    }

                case "folder_get":
                    lines.Add(("folder_id", Text(p, "folderId")));
                    break;
                case "folder_delete":
                    lines.Add(("folder_id", Text(p, "folderId")));
                    if (Bool(p, "recursive"))
                    {
                        lines.Add(("recursive", "true"));
                    }

                    break;
                case "folder_update":
                    {
                        var fields = Find(p, "updateFields");
                        lines.Add(("folder_id", Text(p, "folderId")));
                        lines.Add(("name", Text(fields, "name")));
                        lines.Add(("description", Text(fields, "description")));
                        lines.Add(("parent", Text(fields, "parentId")));
                        Unset(fields, "name", "description", "parentId", "shared_link");
                        if (Find(fields, "shared_link").ValueKind == JsonValueKind.Object && Find(fields, "shared_link").EnumerateObject().Any())
                        {
                            todo.Add("n8n set the folder's shared link - here make it with Make a shared link (link), its access and expiry; its password is set in Box.");
                        }

                        break;
                    }
            }

            if (unset.Count > 0)
            {
                todo.Add($"n8n set {string.Join(", ", unset.Distinct())} - not set here.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "search" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add("n8n signed in through OAuth2 as a Box user - here the connection is a server app, Box's Client Credentials Grant, acting as its enterprise or a managed user.");
            todo.Add(BoxConnection);
        }

        // n8n's AWS Textract, Rekognition and Comprehend nodes as their connectors' operations: a document or an image read from
        // the pipeline folder where n8n read an item's binary (said: here its file is named), or from S3 - its bucket, object and
        // version; Rekognition's analysis by n8n's type, its labels' limit and least confidence, its faces' attributes, its words
        // as well as its lines as n8n gave them; Comprehend's text (one over several lines in the step's Query box) and language.
        // What has no counterpart - regions of interest, a box size filter, a custom entity recognizer - said.
        private static void AwsAi(JsonElement p, PipelineGraphStep step, Todo todo, string service, string operation)
        {
            Set(step, "Operation", operation);
            var additional = Find(p, "additionalFields");
            var lines = new List<(string Name, string Value)>();
            var binary = Text(p, "binaryPropertyName") is { Length: > 0 } property ? property : "data";
            switch (service)
            {
                case "textract":
                    todo.Add($"n8n read the document from the item's binary '{binary}' - here name its file in the site's pipeline folder (file =), or an S3 object (bucket =, object =).");
                    if (Text(p, "simple") == "false")
                    {
                        todo.Add("n8n answered Textract's response as it came - here each document is a record of its fields (VENDOR_NAME, TOTAL...) and its line items.");
                    }

                    break;
                case "rekognition":
                    if (Bool(p, "binaryData"))
                    {
                        todo.Add($"n8n read the image from the item's binary '{binary}' - here name its file in the site's pipeline folder (file =), or an S3 object.");
                    }
                    else
                    {
                        lines.Add(("bucket", Text(p, "bucket")));
                        lines.Add(("object", Text(p, "name")));
                        lines.Add(("version", Text(additional, "version")));
                    }

                    if (Number(additional, "maxLabels") is int most && most > 0)
                    {
                        lines.Add(("max", most.ToString(CultureInfo.InvariantCulture)));
                    }

                    // n8n's numbers may carry decimals: the least confidence rounded to the whole percent the connector takes.
                    double? Positive(params string[] path) => double.TryParse(Text(additional, path), NumberStyles.Float, CultureInfo.InvariantCulture, out var value) && value > 0 ? value : null;
                    if ((Positive("minConfidence") ?? Positive("wordFilterUi", "MinConfidence")) is { } least)
                    {
                        lines.Add(("min_confidence", ((int)Math.Round(least)).ToString(CultureInfo.InvariantCulture)));
                    }

                    if (operation == "detect_text")
                    {
                        lines.Add(("words", "true")); // n8n gave each word as well as each line
                    }

                    if (operation == "detect_faces")
                    {
                        var attributes = Find(additional, "attributes");
                        lines.Add(("details", attributes.ValueKind == JsonValueKind.Array && attributes.EnumerateArray().Any(attribute => Text(attribute) == "all") ? "true" : "false"));
                    }

                    if (Items(additional, "regionsOfInterestUi", "regionsOfInterestValues").Any() || Positive("wordFilterUi", "MinBoundingBoxHeight") is not null || Positive("wordFilterUi", "MinBoundingBoxWidth") is not null)
                    {
                        todo.Add("n8n named regions of interest or a box size for the text - not taken here: every region, any size.");
                    }

                    break;
                default: // comprehend
                    {
                        var text = Text(p, "text");
                        if (text.Contains('\n') || text.Contains('\r'))
                        {
                            Set(step, "Query", text); // text over several lines: the step's Query box
                        }
                        else
                        {
                            lines.Add(("text", text));
                        }

                        if (operation != "detect_language")
                        {
                            lines.Add(("language", Text(p, "languageCode")));
                        }
                        else if (Text(p, "simple") != "false")
                        {
                            todo.Add("n8n answered one object of language codes and scores - here each language is a record (languageCode, score).");
                        }

                        if (Text(additional, "endpointArn").Length > 0)
                        {
                            todo.Add("n8n read the entities through a custom recognizer's endpoint - here Comprehend's own entities.");
                        }

                        break;
                    }
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(PerItem);
            todo.Add($"choose its connection - n8n's credentials stay in n8n: add an Amazon {(service == "textract" ? "Textract" : service == "rekognition" ? "Rekognition" : "Comprehend")} connection under Admin > Connections (an IAM user's access key and secret, allowed {service}, and its region) and pick it here.");
        }

        // n8n's AWS Transcribe node: a job's name; a start's recording, its language - n8n's en-US when none was picked - or its
        // detection, and its options; a Get's transcript and Simplify; Get Many's filters and limit.
        private static void AwsTranscribe(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var options = Find(p, "options");
            var lines = new List<(string Name, string Value)>();
            if (operation != "jobs")
            {
                lines.Add(("job", Text(p, "transcriptionJobName")));
            }

            switch (operation)
            {
                case "start_job":
                    lines.Add(("media", Text(p, "mediaFileUri")));
                    lines.Add(("language", Bool(p, "detectLanguage") ? "" : Text(p, "languageCode") is { Length: > 0 } language ? language : "en-US"));
                    lines.Add(("channels", Bool(options, "channelIdentification") ? "true" : ""));
                    lines.Add(("alternatives", Text(options, "maxAlternatives")));
                    lines.Add(("speakers", Text(options, "maxSpeakerLabels")));
                    lines.Add(("vocabulary", Text(options, "vocabularyName")));
                    lines.Add(("vocabulary_filter", Text(options, "vocabularyFilterName")));
                    lines.Add(("filter_method", Text(options, "vocabularyFilterName").Length > 0 ? Text(options, "vocabularyFilterMethod") : ""));
                    break;
                case "job":
                    lines.Add(("transcript", Text(p, "returnTranscript") == "false" ? "false" : ""));
                    lines.Add(("simple", Text(p, "simple") == "false" ? "false" : ""));
                    break;
                case "jobs":
                    lines.Add(("status", Text(p, "filters", "status")));
                    lines.Add(("name_contains", Text(p, "filters", "jobNameContains")));
                    lines.Add(("max", Most(p, 20)));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation == "jobs" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add an Amazon Transcribe connection under Admin > Connections (an IAM user's access key and secret, allowed transcribe and to read the recordings' bucket, and its region) and pick it here.");
        }

        // n8n's AWS Cognito node: each resource and operation as the Amazon Cognito connector's - its user pool, user and group by
        // their value (n8n's list or by id alike); a user's attributes, standard or custom (custom: as n8n wrote it, never twice), as
        // a JSON object; a create's invitation and alias - its temporary password never carried, said; Get Many's filter (n8n's
        // starts-with, on the email by default) and limit; Simplify; a group's description, precedence and role, its users if asked.
        private static void AwsCognito(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "additionalFields");
            var lines = new List<(string Name, string Value)> { ("user_pool", Locator(p, "userPool")) };
            if (operation is "user" or "user_update" or "user_delete" or "user_add_to_group" or "user_remove_from_group")
            {
                lines.Add(("user", Locator(p, "user")));
            }

            if (operation is "user_add_to_group" or "user_remove_from_group" or "group" or "group_update" or "group_delete")
            {
                lines.Add(("group", Locator(p, "group")));
            }

            switch (operation)
            {
                case "users":
                    if (Find(p, "filters", "filter").ValueKind == JsonValueKind.Object && Text(p, "filters", "filter", "value") is { Length: > 0 } value)
                    {
                        lines.Add(("filter_attribute", Text(p, "filters", "filter", "attribute") is { Length: > 0 } attribute ? attribute : "email"));
                        lines.Add(("filter_value", value));
                    }

                    lines.Add(("simple", Text(p, "simple") == "false" ? "false" : ""));
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "user" or "user_pool":
                    lines.Add(("simple", Text(p, "simple") == "false" ? "false" : ""));
                    break;
                case "user_create":
                    lines.Add(("username", Text(p, "newUserName")));
                    lines.Add(("attributes", CognitoAttributes(Items(more, "userAttributes", "attributes"))));
                    lines.Add(("delivery", Find(more, "desiredDeliveryMediums") is { ValueKind: JsonValueKind.Array } mediums
                        ? string.Join(",", mediums.EnumerateArray().Select(medium => (medium.ValueKind == JsonValueKind.String ? medium.GetString() ?? "" : "").ToLowerInvariant()).Where(medium => medium.Length > 0))
                        : ""));
                    lines.Add(("message_action", Text(more, "messageAction").ToLowerInvariant()));
                    lines.Add(("force_alias", Bool(more, "forceAliasCreation") ? "true" : ""));
                    if (Text(more, "temporaryPasswordOptions").Length > 0)
                    {
                        todo.Add("n8n set the user's temporary password - a password is never a step's parameter here: Cognito makes one and sends it with the invitation (delivery).");
                    }

                    break;
                case "user_update":
                    lines.Add(("attributes", CognitoAttributes(Items(p, "userAttributes", "attributes"))));
                    break;
                case "groups":
                    lines.Add(("include_users", Bool(p, "includeUsers") ? "true" : ""));
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "group":
                    lines.Add(("include_users", Bool(p, "includeUsers") ? "true" : ""));
                    break;
                case "group_create" or "group_update":
                    if (operation == "group_create")
                    {
                        lines.Add(("group", Text(p, "newGroupName")));
                    }

                    lines.Add(("description", Text(more, "description")));
                    lines.Add(("precedence", Text(more, "precedence")));
                    lines.Add(("role_arn", Text(more, "arn")));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "users" or "groups" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add an Amazon Cognito connection under Admin > Connections (an IAM user's access key and secret, allowed cognito-idp, and its region - its user pool too, if the steps share one) and pick it here.");
        }

        // n8n's user attributes, a fixed collection of standard ones by name and custom ones by theirs, as one JSON object - n8n's
        // custom: prefix added once; an expression among the values makes the whole an expression.
        private static string CognitoAttributes(IEnumerable<JsonElement> items)
        {
            var pairs = items.Select(item => (Name: Text(item, "attributeType") == "custom"
                    ? Text(item, "customName") is var custom && custom.StartsWith("custom:", StringComparison.Ordinal) ? custom : "custom:" + custom
                    : Text(item, "standardName") is { Length: > 0 } standard ? standard : "address", Value: Text(item, "value")))
                .Where(pair => pair.Name != "custom:")
                .ToList();
            return pairs.Count == 0 ? "" : (pairs.Any(pair => pair.Value.StartsWith('=')) ? "=" : "") + "{" + string.Join(", ", pairs.Select(pair =>
                JsonSerializer.Serialize(pair.Name, ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(pair.Value), ReadableJson))) + "}";
        }

        // n8n's Google Translate node: its text - over several lines, the step's Query box - into its language; Google's answer a
        // record as n8n's item was, the text and the language beside it.
        private static void GoogleTranslate(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            Set(step, "Operation", "translate");
            var lines = new List<(string Name, string Value)>();
            var text = Text(p, "text");
            if (text.Contains('\n') || text.Contains('\r'))
            {
                Set(step, "Query", text); // text over several lines: the step's Query box
            }
            else
            {
                lines.Add(("text", text));
            }

            lines.Add(("to", Text(p, "translateTo")));
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a Google Translate connection under Admin > Connections (an OAuth client's id and secret and a refresh token granted cloud-translation - a service account is not taken) and pick it here.");
        }

        // n8n's AWS Certificate Manager node: a certificate by its ARN; Get Many's statuses and what they include, n8n's lists as
        // the connector's, and its limit - its Return All sent none of its filters, which here filter, said.
        private static void AwsCertificateManager(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            if (operation == "certificates")
            {
                var options = Find(p, "options");
                string List(string name) => Find(options, name) is { ValueKind: JsonValueKind.Array } values
                    ? string.Join(",", values.EnumerateArray().Where(value => value.ValueKind == JsonValueKind.String).Select(value => value.GetString()))
                    : "";
                lines.Add(("statuses", List("certificateStatuses")));
                lines.Add(("key_types", List("keyTypes")));
                lines.Add(("key_usage", List("keyUsage")));
                lines.Add(("extended_key_usage", List("extendedKeyUsage")));
                lines.Add(("max", Most(p, 100)));
                if (Bool(p, "returnAll") && lines.Take(4).Any(line => line.Value.Length > 0))
                {
                    todo.Add("n8n's Return All sent none of its filters - here they filter the certificates.");
                }
            }
            else
            {
                lines.Add(("certificate", Text(p, "certificateArn")));
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation == "certificates" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add an AWS Certificate Manager connection under Admin > Connections (an IAM user's access key and secret, allowed acm, and its region) and pick it here.");
        }

        // n8n's Google Slides node: a presentation and a page by their ids; Get Slides' limit; Replace Text's texts as one JSON
        // object - {{placeholders}} by their names - their case and slides the first's, said where the others differ, and its
        // revision (which n8n read and never sent); a thumbnail downloaded into the run's folder, where n8n kept it in the item's binary, said.
        private static void GoogleSlides(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            if (operation == "create")
            {
                lines.Add(("title", Text(p, "title")));
            }
            else
            {
                lines.Add(("presentation", Text(p, "presentationId")));
            }

            switch (operation)
            {
                case "slides":
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "replace_text":
                    {
                        var texts = Items(p, "textUi", "textValues").Where(item => Text(item, "text").Length > 0).ToList();

                        // n8n's {{placeholders}} to find go by their names, the connector adding the braces - so none meet an
                        // expression, which would read them as variables.
                        static bool IsPlaceholder(string text) => text.Length > 4 && text.StartsWith("{{", StringComparison.Ordinal) && text.EndsWith("}}", StringComparison.Ordinal) && text[2..^2].IndexOfAny(new[] { '{', '}' }) < 0;
                        var placeholders = texts.Count > 0 && texts.All(item => IsPlaceholder(Text(item, "text")));
                        var found = texts.Select(item => (Find: placeholders ? Text(item, "text")[2..^2] : Text(item, "text"), Put: Text(item, "replaceText"))).ToList();
                        var expression = found.Any(pair => pair.Find.StartsWith('=') || pair.Put.StartsWith('='));
                        lines.Add(("texts", found.Count == 0 ? "" : (expression ? "=" : "") + "{" + string.Join(", ", found.Select(pair =>
                            JsonSerializer.Serialize(Unmarked(pair.Find), ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(pair.Put), ReadableJson))) + "}"));
                        lines.Add(("placeholders", placeholders ? "true" : ""));
                        if (expression && !placeholders && found.Any(pair => pair.Find.Contains("{{", StringComparison.Ordinal)))
                        {
                            todo.Add("a text to find written with {{ }} reads as a variable once a value is an expression - put the placeholders in a step of their own, named alone (placeholders = true).");
                        }

                        string Pages(JsonElement item) => Find(item, "pageObjectIds") is { ValueKind: JsonValueKind.Array } ids
                            ? string.Join(", ", ids.EnumerateArray().Where(id => id.ValueKind == JsonValueKind.String).Select(id => id.GetString()))
                            : "";
                        if (texts.Count > 0)
                        {
                            lines.Add(("match_case", Bool(texts[0], "matchCase") ? "true" : ""));
                            lines.Add(("pages", Pages(texts[0])));
                            if (texts.Skip(1).Any(item => Bool(item, "matchCase") != Bool(texts[0], "matchCase") || Pages(item) != Pages(texts[0])))
                            {
                                todo.Add("n8n matched each text by its own case and on its own slides - here every text takes the first's; split it over steps where they differ.");
                            }
                        }

                        lines.Add(("revision", Text(p, "options", "revisionId")));
                        break;
                    }

                case "page" or "thumbnail":
                    lines.Add(("page", Text(p, "pageObjectId")));
                    if (operation == "thumbnail" && Bool(p, "download"))
                    {
                        lines.Add(("file", "thumbnails/"));
                        todo.Add($"n8n kept the thumbnail in the item's binary '{(Text(p, "binaryProperty") is { Length: > 0 } binary ? binary : "data")}' - here it is saved in the run's pipeline folder (file =, thumbnails/<slide>.png).");
                    }

                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation == "slides" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a Google Slides connection under Admin > Connections (an OAuth client's id and secret and a refresh token granted presentations - a service account is not taken) and pick it here.");
        }

        // n8n's Metabase node: a question, a database, a metric and an alert by their numbers; a question's result as JSON rows, or as
        // CSV or XLSX into the run's folder where n8n kept it in the item's binary, said; the databases' Simplify.
        private static void Metabase(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "question" or "question_result":
                    lines.Add(("question", Text(p, "questionId")));
                    if (operation == "question_result")
                    {
                        var format = Text(p, "format") is { Length: > 0 } given ? given : "csv"; // n8n's default
                        lines.Add(("format", format));
                        if (format != "json")
                        {
                            lines.Add(("file", "metabase/"));
                            todo.Add($"n8n kept the {format} in the item's binary 'data' - here it is saved in the run's pipeline folder (file =, metabase/question-<n>.{format}).");
                        }
                    }

                    break;
                case "databases":
                    lines.Add(("simple", Text(p, "simple") == "false" ? "false" : ""));
                    break;
                case "database_fields":
                    lines.Add(("database", Text(p, "databaseId")));
                    break;
                case "metric":
                    lines.Add(("metric", Text(p, "metricId")));
                    break;
                case "alert":
                    lines.Add(("alert", Text(p, "alertId")));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "questions" or "databases" or "database_fields" or "metrics" or "alerts" || (operation == "question_result" && lines.Any(line => line == ("format", "json")))
                ? "n8n gave each as an item - here they are the step's result, a list of records."
                : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a Metabase connection under Admin > Connections (its address, and an API key - or a user's e-mail and password) and pick it here.");
        }

        // n8n's PostHog node: an event's name, a person's distinct id and an alias; the properties n8n listed as one JSON object and
        // its time; a page's and a screen's name - a page a $pageview, PostHog's own, where n8n sent $page, said. What has no
        // counterpart here - a context, a category, a message id - said.
        private static void PostHog(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "additionalFields");
            var lines = new List<(string Name, string Value)>();
            if (operation == "event")
            {
                lines.Add(("event", Text(p, "eventName")));
            }

            lines.Add(("distinct_id", Text(p, "distinctId")));
            switch (operation)
            {
                case "alias":
                    lines.Add(("alias", Text(p, "alias")));
                    break;
                case "page" or "screen":
                    lines.Add(("name", Text(p, "name")));
                    if (operation == "page")
                    {
                        todo.Add("n8n sent PostHog a $page event - here it is a $pageview, PostHog's own, its name the page's title; give its address too (url =).");
                    }

                    break;
            }

            if (operation != "alias")
            {
                lines.Add(("properties", JsonPairs(Items(more, "propertiesUi", "propertyValues"), "key", "value")));
            }

            lines.Add(("timestamp", Text(more, "timestamp")));
            if (Items(more, "contextUi", "contextValues").Any() || Text(more, "category").Length > 0 || Text(more, "messageId").Length > 0)
            {
                todo.Add("n8n sent a context, a category or a message id - PostHog keeps an event's properties alone here: put what matters among them.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation == "event" ? "n8n sent every item's event in one call - here it sends one, once: put it in a For Each over the records, or give several as one (operation events)." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a PostHog connection under Admin > Connections (its ingestion host - https://eu.i.posthog.com or https://us.i.posthog.com - and the project's API key) and pick it here.");
        }

        // n8n's AWS IAM node: a user and a group by their name (n8n's list or by name alike); a new one's name, path, permissions
        // boundary and tags as one JSON object; an update's new name and path; Get Many's path prefix and limit, and a group's users.
        private static void AwsIam(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "additionalFields");
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "users" or "groups":
                    lines.Add(("path_prefix", Text(more, "pathPrefix")));
                    if (operation == "groups")
                    {
                        lines.Add(("include_users", Bool(p, "includeUsers") ? "true" : ""));
                    }

                    lines.Add(("max", Most(p, 100)));
                    break;
                case "user_create":
                    lines.Add(("user", Text(p, "userName")));
                    lines.Add(("path", Text(more, "path")));
                    lines.Add(("permissions_boundary", Text(more, "permissionsBoundary")));
                    lines.Add(("tags", JsonPairs(Items(more, "tags", "tags"), "key", "value")));
                    break;
                case "group_create":
                    lines.Add(("group", Text(p, "groupName")));
                    lines.Add(("path", Text(more, "path")));
                    break;
                case "user_update" or "group_update":
                    lines.Add(operation == "user_update" ? ("user", Locator(p, "user")) : ("group", Locator(p, "group")));
                    lines.Add(("new_name", Text(p, operation == "user_update" ? "userName" : "groupName")));
                    lines.Add(("new_path", Text(more, "path")));
                    break;
                case "user" or "user_delete":
                    lines.Add(("user", Locator(p, "user")));
                    break;
                case "user_add_to_group" or "user_remove_from_group":
                    lines.Add(("user", Locator(p, "user")));
                    lines.Add(("group", Locator(p, "group")));
                    break;
                default: // a group, its deletion
                    lines.Add(("group", Locator(p, "group")));
                    lines.Add(("include_users", operation == "group" && Bool(p, "includeUsers") ? "true" : ""));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "users" or "groups" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add an AWS IAM connection under Admin > Connections (an IAM user's access key and secret, allowed what the steps do in iam) and pick it here.");
        }

        // n8n's AWS ELB node: a load balancer by its ARN (n8n's Load Balancer ID held it); a new one's name, type, scheme (n8n's
        // Schema), IP addresses, subnets and security groups (n8n's lists made comma-separated) and tags as one JSON object; Get
        // Many's names and limit; a listener's certificates by the listener's ARN and the certificate's (n8n's IDs held them).
        private static void AwsElb(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "load_balancers":
                    lines.Add(("names", Joined(Find(p, "filters"), "names")));
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "load_balancer" or "load_balancer_delete":
                    lines.Add(("load_balancer", Text(p, "loadBalancerId")));
                    break;
                case "load_balancer_create":
                    {
                        var more = Find(p, "additionalFields");
                        lines.Add(("name", Text(p, "name")));
                        lines.Add(("subnets", Joined(p, "subnets")));
                        lines.Add(("type", Text(p, "type")));
                        lines.Add(("scheme", Text(p, "schema")));
                        lines.Add(("ip_address_type", Text(p, "ipAddressType")));
                        lines.Add(("security_groups", Joined(more, "securityGroups")));
                        lines.Add(("tags", JsonPairs(Items(more, "tagsUi", "tagValues"), "key", "value")));
                        break;
                    }

                case "certificates":
                    lines.Add(("listener", Text(p, "listenerId")));
                    lines.Add(("max", Most(p, 10)));
                    break;
                default: // a certificate added to or removed from a listener
                    lines.Add(("listener", Text(p, "listenerId")));
                    lines.Add(("certificate", Text(p, "certificateId")));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "load_balancers" or "certificates" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add an AWS Elastic Load Balancing connection under Admin > Connections (its region, and an IAM user's access key and secret, allowed what the steps do in elasticloadbalancing) and pick it here.");
        }

        // n8n's Google Analytics node, its GA4 report: the property (n8n's list, its id, or the id in its GA4 address), n8n's date
        // range - a custom one's start and end as their days - its metrics and dimensions (n8n's own names, or the one it names for
        // "other"), its filters made GA4's filter expressions as n8n makes them (a string filter case-sensitive and exact unless
        // said otherwise, an in-list filter's values split at their commas, a numeric or between filter's values typed), its
        // ordering, empty rows, currency and limit. A custom metric's expression is said, not taken.
        private static void GoogleAnalytics(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            Set(step, "Operation", "report");
            var more = Find(p, "additionalFields");
            var property = Locator(p, "propertyId");
            var lines = new List<(string Name, string Value)>
            {
                ("property", Regex.Match(property, "/p([0-9]+)(?:/|$)") is { Success: true } inAddress && !property.StartsWith('=') ? inAddress.Groups[1].Value : property),
            };
            static string Day(string given) => given.Length >= 10 && !given.StartsWith('=') && DateOnly.TryParseExact(given[..10], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out _) ? given[..10] : given;
            if (Text(p, "dateRange") is "custom")
            {
                lines.Add(("start", Day(Text(p, "startDate"))));
                lines.Add(("end", Day(Text(p, "endDate"))));
            }
            else
            {
                lines.Add(("range", Text(p, "dateRange")));
            }

            static string Named(JsonElement item) => Text(item, "listName") is "other" or "custom" ? Text(item, "name") : Text(item, "listName");
            var metrics = Items(p, "metricsGA4", "metricValues").ToList();
            foreach (var custom in metrics.Where(item => Text(item, "listName") == "custom"))
            {
                todo.Add($"n8n's custom metric '{Text(custom, "name")}' was GA4's expression {Text(custom, "expression")} - expressions are not taken here: report the metrics it is made of and work it out in a step after.");
            }

            lines.Add(("metrics", string.Join(", ", metrics.Where(item => Text(item, "listName") != "custom").Select(Named).Where(name => name.Length > 0))));
            lines.Add(("dimensions", string.Join(", ", Items(p, "dimensionsGA4", "dimensionValues").Select(Named).Where(name => name.Length > 0))));
            var orders = Items(more, "orderByUI", "metricOrderBy").Select(order => (Bool(order, "desc") ? "-" : "") + Text(order, "metricName"))
                .Concat(Items(more, "orderByUI", "dimmensionOrderBy").Select(order => (Bool(order, "desc") ? "-" : "") + Text(order, "dimensionName")));
            lines.Add(("order_by", string.Join(", ", orders.Where(order => order.TrimStart('-').Length > 0))));
            foreach (var typed in Items(more, "orderByUI", "dimmensionOrderBy").Where(order => Text(order, "orderType") is { Length: > 0 } type && type != "ORDER_TYPE_UNSPECIFIED"))
            {
                todo.Add($"n8n ordered {Text(typed, "dimensionName")} {Text(typed, "orderType")} - here by GA4's own order for it.");
            }

            lines.Add(("dimension_filter", Ga4Filter(Find(more, "dimensionFiltersUI"))));
            lines.Add(("metric_filter", Ga4Filter(Find(more, "metricsFiltersUI"))));
            lines.Add(("keep_empty_rows", Bool(more, "keepEmptyRows") ? "true" : ""));
            lines.Add(("currency", Text(more, "currencyCode")));
            lines.Add(("max", Most(p, 50)));
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (p.ValueKind == JsonValueKind.Object && p.TryGetProperty("simple", out var simple) && simple.ValueKind == JsonValueKind.False)
            {
                todo.Add("n8n gave GA4's whole answer (its Simplify Output off) - here each row is a record of its dimensions and metrics, the aggregations and the property's quota not among them.");
            }

            todo.Add("n8n gave each row as an item - here they are the step's result, a list of records.");
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a Google Analytics connection under Admin > Connections (an OAuth client's id and secret, and a refresh token granted analytics.readonly) and pick it here.");
        }

        // n8n's GA4 filter collection as GA4's own filter expression, as n8n builds it: an and- or or-group of each filter, its
        // field n8n's listed name or the one named for "other"; empty when no filter was given.
        private static string Ga4Filter(JsonElement ui)
        {
            var filters = Find(ui, "filterExpressions");
            var expressions = new JsonArray();
            static string Field(JsonElement item) => Text(item, "listName") is "other" or "custom" ? Text(item, "name") : Text(item, "listName");
            static string Or(string text, string fallback) => text.Length > 0 ? text : fallback;
            static bool CaseSensitive(JsonElement item) => !(item.TryGetProperty("caseSensitive", out var said) && said.ValueKind == JsonValueKind.False);
            static JsonObject Typed(JsonElement item, string value) => new() { [Or(Text(item, "valueType"), "doubleValue")] = value };
            foreach (var item in Items(filters, "expression", "stringFilter"))
            {
                expressions.Add(new JsonObject { ["filter"] = new JsonObject { ["fieldName"] = Field(item), ["stringFilter"] = new JsonObject { ["value"] = Text(item, "value"), ["caseSensitive"] = CaseSensitive(item), ["matchType"] = Or(Text(item, "matchType"), "EXACT") } } });
            }

            foreach (var item in Items(filters, "expression", "inListFilter"))
            {
                var values = new JsonArray(Text(item, "values").Split(',').Select(value => (JsonNode?)value).ToArray());
                expressions.Add(new JsonObject { ["filter"] = new JsonObject { ["fieldName"] = Field(item), ["inListFilter"] = new JsonObject { ["values"] = values, ["caseSensitive"] = CaseSensitive(item) } } });
            }

            foreach (var item in Items(filters, "expression", "numericFilter"))
            {
                expressions.Add(new JsonObject { ["filter"] = new JsonObject { ["fieldName"] = Field(item), ["numericFilter"] = new JsonObject { ["operation"] = Or(Text(item, "operation"), "EQUAL"), ["value"] = Typed(item, Text(item, "value")) } } });
            }

            foreach (var item in Items(filters, "expression", "betweenFilter"))
            {
                expressions.Add(new JsonObject { ["filter"] = new JsonObject { ["fieldName"] = Field(item), ["betweenFilter"] = new JsonObject { ["fromValue"] = Typed(item, Text(item, "fromValue")), ["toValue"] = Typed(item, Text(item, "toValue")) } } });
            }

            return expressions.Count == 0 ? string.Empty : new JsonObject { [Or(Text(filters, "filterExpressionType"), "andGroup")] = new JsonObject { ["expressions"] = expressions } }.ToJsonString();
        }

        // n8n's Hunter node: a domain search's domain, its Only Emails (on by default, as the connector's), its type, seniority and
        // department (n8n's lists made comma-separated) and limit; an email finder's domain and names; an email verifier's address.
        private static void Hunter(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var filters = Find(p, "filters");
            var lines = operation switch
            {
                "domain_search" => new List<(string Name, string Value)>
                {
                    ("domain", Text(p, "domain")),
                    ("only_emails", p.ValueKind == JsonValueKind.Object && p.TryGetProperty("onlyEmails", out var only) && only.ValueKind == JsonValueKind.False ? "false" : ""),
                    ("type", Text(filters, "type")),
                    ("seniority", Joined(filters, "seniority")),
                    ("department", Joined(filters, "department")),
                    ("max", Most(p, 100)),
                },
                "email_finder" => new List<(string Name, string Value)> { ("domain", Text(p, "domain")), ("first_name", Text(p, "firstname")), ("last_name", Text(p, "lastname")) },
                _ => new List<(string Name, string Value)> { ("email", Text(p, "email")) },
            };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation == "domain_search" ? "n8n gave each address as an item - here they are the step's result, a list of records (with only_emails = false, the domain's one record)." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a Hunter connection under Admin > Connections (its API key, from Hunter's API page) and pick it here.");
        }

        // n8n's HighLevel node, its second version: each operation as the connector's - a contact's email, phone and fields (its
        // time zone n8n's list or id, its custom fields one JSON object of their ids and values, its notes the upsert's note); an
        // opportunity's contact, name, pipeline, stage, status, value and owner; a task's title, due time, body and whether it is
        // done; a calendar's free slots between two times and an appointment; Get Many's filters and limit. A time without its
        // offset, which n8n read in its instance's time zone, is said.
        private static void HighLevel(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var update = operation.EndsWith("_update", StringComparison.Ordinal);
            var more = Find(p, update ? "updateFields" : "additionalFields");
            var lines = new List<(string Name, string Value)>();
            void Add(string name, string value) => lines.Add((name, value));
            static string Day(string given) => given.Length >= 10 && !given.StartsWith('=') && DateOnly.TryParseExact(given[..10], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out _) ? given[..10] : given;
            var times = new List<string>();
            string Time(string given)
            {
                if (given.Length > 0 && !given.StartsWith('=') && !Regex.IsMatch(given, "(Z|[+-][0-9]{2}:?[0-9]{2})$") && !Regex.IsMatch(given, "^[0-9]+$"))
                {
                    times.Add(given);
                }

                return given;
            }

            switch (operation)
            {
                case "contacts":
                    Add("query", Text(Find(p, "filters"), "query"));
                    Add("order", Text(Find(p, "options"), "order"));
                    Add("sort_by", Text(Find(p, "options"), "sortBy"));
                    Add("max", Most(p, 50));
                    break;
                case "contact" or "contact_delete":
                    Add("contact", Text(p, "contactId"));
                    break;
                case "contact_upsert" or "contact_update":
                    {
                        if (update)
                        {
                            Add("contact", Text(p, "contactId"));
                        }

                        Add("email", update ? Text(more, "email") : Text(p, "email"));
                        Add("phone", update ? Text(more, "phone") : Text(p, "phone"));
                        foreach (var (n8n, ours) in new[] { ("firstName", "first_name"), ("lastName", "last_name"), ("name", "name"), ("address1", "address1"), ("city", "city"), ("state", "state"), ("postalCode", "postal_code"), ("website", "website") })
                        {
                            Add(ours, Text(more, n8n));
                        }

                        Add("timezone", Locator(more, "timezone"));
                        Add("dnd", Text(more, "dnd"));
                        Add("tags", Text(more, "tags"));
                        var custom = new JsonObject();
                        foreach (var field in Items(more, "customFields", "values"))
                        {
                            if (Locator(field, "fieldId") is { Length: > 0 } id)
                            {
                                custom[id] = Text(field, "fieldValue");
                            }
                        }

                        Add("custom_fields", custom.Count > 0 ? custom.ToJsonString() : string.Empty);
                        if (!update)
                        {
                            Add("source", Text(more, "source"));
                            Add("note", Text(more, "notes"));
                        }

                        break;
                    }

                case "opportunities":
                    {
                        var filters = Find(p, "filters");
                        Add("query", Text(filters, "query"));
                        Add("pipeline", Text(filters, "pipelineId"));
                        Add("stage", Text(filters, "stageId"));
                        Add("status", Text(filters, "status"));
                        Add("assigned_to", Text(filters, "assignedTo"));
                        Add("campaign", Text(filters, "campaignId"));
                        Add("start", Day(Text(filters, "startDate")));
                        Add("end", Day(Text(filters, "endDate")));
                        Add("max", Most(p, 20));
                        break;
                    }

                case "opportunity" or "opportunity_delete":
                    Add("opportunity", Text(p, "opportunityId"));
                    break;
                case "opportunity_create" or "opportunity_update":
                    {
                        if (update)
                        {
                            Add("opportunity", Text(p, "opportunityId"));
                        }
                        else
                        {
                            Add("contact", Text(p, "contactId"));
                        }

                        var holder = update ? more : p;
                        Add("name", Text(holder, "name"));
                        Add("pipeline", Text(holder, "pipelineId"));
                        Add("status", Text(holder, "status"));
                        Add("stage", Text(more, "stageId"));
                        Add("monetary_value", Text(more, "monetaryValue"));
                        Add("assigned_to", Text(more, "assignedTo"));
                        if (!update)
                        {
                            Add("company_name", Text(more, "companyName"));
                            Add("tags", Text(more, "tags"));
                        }

                        break;
                    }

                case "tasks":
                    Add("contact", Text(p, "contactId"));
                    Add("max", Most(p, 20));
                    break;
                case "task" or "task_delete":
                    Add("contact", Text(p, "contactId"));
                    Add("task", Text(p, "taskId"));
                    break;
                case "task_create" or "task_update":
                    {
                        Add("contact", Text(p, "contactId"));
                        if (update)
                        {
                            Add("task", Text(p, "taskId"));
                        }

                        var holder = update ? more : p;
                        Add("title", Text(holder, "title"));
                        Add("due", Time(Text(holder, "dueDate")));
                        Add("body", Text(more, "body"));
                        Add("completed", Text(holder, "completed"));
                        Add("assigned_to", Text(more, "assignedTo"));
                        break;
                    }

                case "free_slots":
                    Add("calendar", Text(p, "calendarId"));
                    Add("start", Text(p, "startDate"));
                    Add("end", Text(p, "endDate"));
                    Add("timezone", Text(more, "timezone"));
                    Add("user", Text(more, "userId"));
                    Add("users", Text(Find(more, "userIds"), "userIds"));
                    break;
                default: // appointment_book
                    Add("calendar", Text(p, "calendarId"));
                    Add("contact", Text(p, "contactId"));
                    Add("start", Time(Text(p, "startTime")));
                    Add("end", Time(Text(more, "endTime")));
                    Add("title", Text(more, "title"));
                    Add("appointment_status", Text(more, "appointmentStatus"));
                    Add("assigned_user", Text(more, "assignedUserId"));
                    Add("address", Text(more, "address"));
                    Add("ignore_date_range", Text(more, "ignoreDateRange"));
                    Add("notify", Text(more, "toNotify"));
                    if (Text(p, "locationId") is { Length: > 0 } location)
                    {
                        todo.Add($"n8n booked it in location {location} - here the connection's location is used: make the connection for that one.");
                    }

                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (times.Count > 0)
            {
                todo.Add($"{string.Join(", ", times)} carries no offset - n8n read it in its instance's time zone, here it is UTC: give the offset (+02:00).");
            }

            todo.Add(operation is "contacts" or "opportunities" or "tasks" or "free_slots" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a HighLevel connection under Admin > Connections (the sub-account's location id, and a Private Integration token - Settings > Private Integrations - with the scopes the steps need; n8n's OAuth2 app is not used) and pick it here.");
        }

        // n8n's OpenWeatherMap node: its place as the one it selected - a city's name (its default), a city id (n8n's own default
        // id when none is given), coordinates or a postal code - its units (n8n's Format, metric by default) and language.
        private static void OpenWeatherMap(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            switch (Text(p, "locationSelection"))
            {
                case "cityId":
                    lines.Add(("city_id", Text(p, "cityId") is { Length: > 0 } id ? id : "160001123"));
                    break;
                case "coordinates":
                    lines.Add(("latitude", Text(p, "latitude")));
                    lines.Add(("longitude", Text(p, "longitude")));
                    break;
                case "zipCode":
                    lines.Add(("zip", Text(p, "zipCode")));
                    break;
                default:
                    lines.Add(("city", Text(p, "cityName")));
                    break;
            }

            lines.Add(("units", Text(p, "format")));
            lines.Add(("language", Text(p, "language")));
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (operation == "forecast")
            {
                todo.Add("n8n gave the whole forecast as one item - here each three hours is a record, its city and country beside it.");
            }

            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add an OpenWeatherMap connection under Admin > Connections (its API key, from openweathermap.org's API keys page) and pick it here.");
        }

        // n8n's Google Business Profile node: its account, location, post and review as n8n held them (their names, or a review's
        // id); a new post's type, and a post's text, title, times or days, call to action and offer - a new one's at the node's
        // top and in its options, a change's in its options alone; Get Many's limit; a reply. An event's time without its
        // offset, which n8n read in its instance's time zone, is said.
        private static void GoogleBusinessProfile(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, "additionalOptions");
            var lines = new List<(string Name, string Value)> { ("account", Locator(p, "account")), ("location", Locator(p, "location")) };
            switch (operation)
            {
                case "posts" or "reviews":
                    lines.Add(("max", Most(p, 20)));
                    break;
                case "post" or "post_delete":
                    lines.Add(("post", Locator(p, "post")));
                    break;
                case "review" or "review_reply_delete":
                    lines.Add(("review", Locator(p, "review")));
                    break;
                case "review_reply":
                    lines.Add(("review", Locator(p, "review")));
                    lines.Add(("reply", Text(p, "reply")));
                    break;
                default: // a post made, or changed
                    {
                        var update = operation == "post_update";
                        lines.Add(update ? ("post", Locator(p, "post")) : ("type", Text(p, "postType")));
                        var holder = update ? more : p;
                        lines.Add(("summary", Text(holder, "summary")));
                        lines.Add(("title", Text(holder, "title")));
                        foreach (var (name, time, day) in new[] { ("start", "startDateTime", "startDate"), ("end", "endDateTime", "endDate") })
                        {
                            var moment = Text(holder, time);
                            if (moment.Length > 0 && !moment.StartsWith('=') && !Regex.IsMatch(moment, "(Z|[+-][0-9]{2}:?[0-9]{2})$"))
                            {
                                todo.Add($"{moment} carries no offset - n8n read it in its instance's time zone, here it is UTC: give the offset (+02:00).");
                            }

                            lines.Add((name, moment.Length > 0 ? moment : Text(holder, day)));
                        }

                        lines.Add(("call_to_action", Text(more, "callToActionType") is "ACTION_TYPE_UNSPECIFIED" ? string.Empty : Text(more, "callToActionType")));
                        lines.Add(("url", Text(more, "url")));
                        lines.Add(("coupon_code", Text(more, "couponCode")));
                        lines.Add(("redeem_url", Text(more, "redeemOnlineUrl")));
                        lines.Add(("terms", Text(more, "termsConditions")));
                        lines.Add(("language", Text(more, "languageCode")));
                        break;
                    }
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "posts" or "reviews" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a Google Business Profile connection under Admin > Connections (an OAuth client's id and secret, and a refresh token granted business.manage; its account and location, if the steps name none) and pick it here.");
        }

        // n8n's Vonage node: its SMS as n8n sent it - from, to and the message, a message over several lines in the Query box -
        // and the additional fields it took, its time to live in minutes as here. n8n sent every text as GSM-7; one that needs
        // Unicode now goes as Unicode, which is said.
        private static void Vonage(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            Set(step, "Operation", "send");
            var more = Find(p, "additionalFields");
            var lines = new List<(string Name, string Value)> { ("to", Text(p, "to")), ("from", Text(p, "from")) };
            var message = Text(p, "message");
            if (message.Contains('\n') || message.Contains('\r'))
            {
                Set(step, "Query", message); // a message over several lines: the step's Query box
            }
            else
            {
                lines.Add(("text", message));
            }

            lines.Add(("account_ref", Text(more, "account-ref")));
            lines.Add(("callback", Text(more, "callback")));
            lines.Add(("client_ref", Text(more, "client-ref")));
            lines.Add(("message_class", Text(more, "message-class")));
            lines.Add(("protocol_id", Text(more, "protocol-id")));
            lines.Add(("status_report", Text(more, "status-report-req")));
            lines.Add(("ttl", Text(more, "ttl")));
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add("n8n sent every text as GSM-7, which garbles what it cannot carry - here a text that needs it goes as Unicode, 70 characters to a part rather than 160.");
            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a Vonage connection under Admin > Connections (the account's API key and secret, from the Vonage dashboard's API settings) and pick it here.");
        }

        // n8n's CircleCI node: its provider and project slug as n8n took them - the slug's org/repo under the provider; a
        // pipeline's number, n8n's 1 when the export leaves it out; Get Many's branch and limit; a trigger's branch or tag. A
        // provider left unset, which n8n then sent as nothing, is said.
        private static void CircleCi(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)> { ("project", Text(p, "projectSlug")), ("vcs", Text(p, "vcs")) };
            switch (operation)
            {
                case "pipeline":
                    lines.Add(("number", Text(p, "pipelineNumber") is { Length: > 0 } number ? number : "1"));
                    break;
                case "pipelines":
                    lines.Add(("branch", Text(p, "filters", "branch")));
                    lines.Add(("max", Most(p, 100)));
                    break;
                default:
                    lines.Add(("branch", Text(p, "additionalFields", "branch")));
                    lines.Add(("tag", Text(p, "additionalFields", "tag")));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (Text(p, "vcs").Length == 0)
            {
                todo.Add("n8n's node named no provider - here the project is taken as GitHub's: give 'vcs = bitbucket' if it is on Bitbucket.");
            }

            if (operation == "pipeline_trigger")
            {
                todo.Add("n8n's node could not wait on the build it started - here List a pipeline's workflows, its 'pipeline =' the id this step answers, says how each went.");
            }

            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a CircleCI connection under Admin > Connections (a personal API token, from CircleCI's User Settings > Personal API Tokens) and pick it here.");
        }

        // n8n's MISP node: its event, attribute and tag ids, an event's info, its additional or update fields (distribution,
        // threat level, analysis, sharing group, organisation), an attribute's type and value, a tag's name and colour, Get Many's
        // limit, and a search's value and its additional fields - or the JSON it took instead, in the Query box. An organisation
        // given to a new event is said: MISP owns an event by the key's own organisation and takes another only as its creator.
        private static void Misp(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var more = Find(p, operation.EndsWith("_update", StringComparison.Ordinal) ? "updateFields" : "additionalFields");
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "events" or "attributes" or "tags":
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "event" or "event_delete" or "event_publish" or "event_unpublish":
                    lines.Add(("event", Text(p, "eventId")));
                    break;
                case "event_create" or "event_update":
                    if (operation == "event_update")
                    {
                        lines.Add(("event", Text(p, "eventId")));
                    }

                    lines.Add(("info", operation == "event_create" ? Text(p, "information") : Text(more, "information")));
                    lines.Add(("distribution", Text(more, "distribution")));
                    lines.Add(("threat_level", Text(more, "threat_level_id")));
                    lines.Add(("analysis", Text(more, "analysis")));
                    lines.Add(("sharing_group", Text(more, "sharing_group_id")));
                    if (operation == "event_create" && Text(p, "org_id") is { Length: > 0 } org)
                    {
                        lines.Add(("organisation", org));
                        todo.Add("n8n's node named the event's organisation - MISP owns an event by the key's own organisation, and takes this one as the event's creator only from a site administrator or a sync user.");
                    }

                    break;
                case "event_tag_add" or "event_tag_remove":
                    lines.Add(("event", Text(p, "eventId")));
                    lines.Add(("tag", Text(p, "tagId")));
                    break;
                case "attribute" or "attribute_delete":
                    lines.Add(("attribute", Text(p, "attributeId")));
                    break;
                case "attribute_create":
                    lines.Add(("event", Text(p, "eventId")));
                    lines.Add(("type", Text(p, "type") is { Length: > 0 } type ? type : "text"));
                    lines.Add(("value", Text(p, "value")));
                    lines.Add(("distribution", Text(more, "distribution")));
                    lines.Add(("sharing_group", Text(more, "sharing_group_id")));
                    break;
                case "attribute_update":
                    lines.Add(("attribute", Text(p, "attributeId")));
                    lines.Add(("distribution", Text(more, "distribution")));
                    lines.Add(("sharing_group", Text(more, "sharing_group_id")));
                    break;
                case "event_search" or "attribute_search":
                    if (Bool(p, "useJson"))
                    {
                        Set(step, "Query", Text(p, "jsonOutput")); // MISP's own JSON: the step's Query box
                    }
                    else
                    {
                        lines.Add(("value", Text(p, "value")));
                        foreach (var name in new[] { "type", "category", "tags", "searchall" })
                        {
                            lines.Add((name, Text(more, name)));
                        }

                        foreach (var name in new[] { "published", "deleted" })
                        {
                            lines.Add((name, Bool(more, name) ? "true" : string.Empty));
                        }
                    }

                    lines.Add(("max", Most(p, 50)));
                    break;
                case "tag_create":
                    lines.Add(("name", Text(p, "name")));
                    lines.Add(("colour", Text(more, "colour")));
                    break;
                default:
                    lines.Add(("tag", Text(p, "tagId")));
                    if (operation == "tag_update")
                    {
                        lines.Add(("name", Text(more, "name")));
                        lines.Add(("colour", Text(more, "colour")));
                    }

                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (operation is "event_search" && !Bool(p, "useJson") && Text(more, "searchall") is { Length: > 0 } anywhere && !anywhere.Contains('%'))
            {
                todo.Add("n8n sent 'searchall' as it was, which MISP finds only between its own %s - here it is looked for anywhere, as if %" + anywhere + "%.");
            }

            todo.Add(operation is "events" or "attributes" or "tags" or "event_search" or "attribute_search" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a MISP connection under Admin > Connections (its address and an authentication key, from My Profile > Auth keys) and pick it here.");
        }

        // n8n's urlscan.io node: a scan's URL and its additional fields (visibility, tags, user agent, referer, override safety),
        // a scan's id, Get Many's query and limit. A scan whose visibility n8n left unset - urlscan.io then used the account's
        // default, public unless changed - is said: here it is private unless the step says otherwise.
        private static void UrlScanIo(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "scan":
                    {
                        var more = Find(p, "additionalFields");
                        lines.Add(("url", Text(p, "url")));
                        lines.Add(("visibility", Text(more, "visibility")));
                        lines.Add(("tags", Text(more, "tags")));
                        lines.Add(("custom_agent", Text(more, "customAgent")));
                        lines.Add(("referer", Text(more, "referer")));
                        lines.Add(("override_safety", Text(more, "overrideSafety")));
                        if (Text(more, "visibility").Length == 0)
                        {
                            todo.Add("n8n's node set no visibility, so urlscan.io used the account's default - public, unless changed; here the scan is private unless 'visibility = public' says otherwise.");
                        }

                        todo.Add("n8n's node only submitted the scan - here 'wait = true' has the step wait for its result and verdict, without a Wait step.");
                        break;
                    }

                case "result":
                    lines.Add(("scan", Text(p, "scanId")));
                    break;
                default:
                    lines.Add(("query", Text(p, "filters", "query")));
                    lines.Add(("max", Most(p, 50)));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation == "search" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a urlscan.io connection under Admin > Connections (its API key, from urlscan.io's Settings & API) and pick it here.");
        }

        // n8n's Elastic Security node: a case's title and its additional fields (description, owner, alert sync), Get Many's
        // status, tags, sort and limit, an update's fields, a comment's text - over several lines in the Query box - and a tag.
        // A new case's external connector, which n8n's node required, is said: here a case is made without one.
        private static void ElasticSecurity(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            if (operation is not ("cases" or "case_create" or "case_status"))
            {
                lines.Add(("case", Text(p, "caseId")));
            }

            void Multiline(string name, string text)
            {
                if (text.Contains('\n') || text.Contains('\r'))
                {
                    Set(step, "Query", text); // over several lines: the step's Query box
                }
                else
                {
                    lines.Add((name, text));
                }
            }

            switch (operation)
            {
                case "cases":
                    {
                        var filters = Find(p, "filters");
                        lines.Add(("status", Text(filters, "status")));
                        lines.Add(("tags", Find(filters, "tags") is { ValueKind: JsonValueKind.Array } tags ? string.Join(", ", tags.EnumerateArray().Select(tag => tag.GetString())) : Text(filters, "tags")));
                        lines.Add(("sort", Text(p, "sortOptions", "sortOptionsProperties", "sortField")));
                        lines.Add(("order", Text(p, "sortOptions", "sortOptionsProperties", "sortOrder")));
                        lines.Add(("max", Most(p, 50)));
                        break;
                    }

                case "case_create":
                    {
                        var more = Find(p, "additionalFields");
                        lines.Add(("title", Text(p, "title")));
                        Multiline("description", Text(more, "description"));
                        if (Text(more, "description").Length == 0)
                        {
                            todo.Add("n8n's node sent the case an empty description, which Kibana refuses - give it one: 'description =', or the Query box.");
                        }

                        lines.Add(("owner", Text(more, "owner")));
                        lines.Add(("sync_alerts", Bool(more, "syncAlerts") ? "true" : string.Empty));
                        if (Text(p, "connectorId").Length > 0)
                        {
                            todo.Add("n8n's node made the case with an external connector (" + Text(p, "connectorType") + ") - here the case has none: push it from Kibana, where its connector and that connector's secrets stay.");
                        }

                        break;
                    }

                case "case_update":
                    {
                        var changes = Find(p, "updateFields");
                        lines.Add(("title", Text(changes, "title")));
                        Multiline("description", Text(changes, "description"));
                        lines.Add(("status", Text(changes, "status")));
                        lines.Add(("sync_alerts", Text(changes, "syncAlerts")));
                        if (Text(changes, "version").Length > 0)
                        {
                            todo.Add("n8n's node changed the case at the version given it - here the step reads the case's own version first, as n8n's node did when none was given.");
                        }

                        break;
                    }

                case "case_comments":
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "case_comment" or "case_comment_delete":
                    lines.Add(("comment_id", Text(p, "commentId")));
                    break;
                case "case_comment_add":
                    Multiline("comment", Text(p, "comment"));
                    lines.Add(("owner", Text(p, "additionalFields", "owner")));
                    break;
                case "case_comment_update":
                    lines.Add(("comment_id", Text(p, "commentId")));
                    Multiline("comment", Text(p, "comment"));
                    break;
                case "case_tag_add" or "case_tag_remove":
                    lines.Add(("tag", Text(p, "tag")));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "cases" or "case_comments" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add an Elastic Security connection under Admin > Connections (Kibana's address, a Kibana user and password, and its space if not the default) and pick it here.");
        }

        // n8n's TheHive 5 node: its resource locators (alertId, caseId, taskId, commentId, observableId, and the id a comment or
        // an observable goes to), its fields as a mapper's "define below" values (an alert's, a case's, a task's, a log's, an
        // observable's - the id among an update's), an alert's status, a comment's message and a search's filters (title, status,
        // severity, tags, source, type and assignee by equality, a title by its like). A description or a message over several
        // lines goes to the Query box. What it cannot carry is said: fields mapped from the item, a file as an observable or an
        // attachment, a search's other filters, sorts and counts.
        private static void TheHive(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            var connectorOperation = operation == "alert_status" ? "alert_update" : operation;
            Set(step, "Operation", connectorOperation);
            var lines = new List<(string Name, string Value)>();

            void Multiline(string name, string text)
            {
                if (text.Contains('\n') || text.Contains('\r'))
                {
                    Set(step, "Query", text); // over several lines: the step's Query box
                }
                else
                {
                    lines.Add((name, text));
                }
            }

            // A mapper's "define below" values; the item's own fields (n8n's "map automatically") said, not guessed.
            JsonElement Fields(string mapper)
            {
                if (Text(p, mapper, "mappingMode") == "autoMapInputData")
                {
                    todo.Add("n8n mapped the item's fields onto the " + mapper.Replace("Fields", string.Empty, StringComparison.Ordinal).Replace("Update", string.Empty, StringComparison.Ordinal) + " - here name each in Parameters, its value reading the record (n8n's $json).");
                }

                return Find(p, mapper, "value") is { ValueKind: JsonValueKind.Object } value ? value : default;
            }

            void Marks(JsonElement fields, bool severity = true)
            {
                if (severity)
                {
                    lines.Add(("severity", Text(fields, "severity")));
                }

                lines.Add(("tlp", Text(fields, "tlp")));
                lines.Add(("pap", Text(fields, "pap")));
                lines.Add(("tags", Find(fields, "tags") is { ValueKind: JsonValueKind.Array } tags ? string.Join(", ", tags.EnumerateArray().Select(tag => tag.GetString())) : Text(fields, "tags")));
            }

            // Where a comment or an observable goes: n8n's addTo or createIn, and the id beside it.
            void On(string chooser, string n8nDefault)
            {
                var on = Text(p, chooser) is { Length: > 0 } given ? given : n8nDefault;
                lines.Add(("on", on));
                lines.Add(("id", Locator(p, "id")));
            }

            void Search(params (string N8nField, string Name)[] known)
            {
                foreach (var filter in Items(p, "filters", "values"))
                {
                    var field = Text(filter, "field");
                    var op = Text(filter, "operator") is { Length: > 0 } given ? given : "_eq";
                    var name = known.FirstOrDefault(pair => pair.N8nField == field).Name;
                    if (name is not null && (op == "_eq" || (op == "_like" && field == "title")))
                    {
                        lines.Add((name, Text(filter, "value")));
                    }
                    else
                    {
                        todo.Add($"n8n's search filtered {field} by {op} - here a search filters only {string.Join(", ", known.Select(pair => pair.N8nField))} (title by its like, the rest by equality): add it as a filter after the step.");
                    }
                }

                if (Items(p, "sort", "fields").Any())
                {
                    todo.Add("n8n's search sorted its own way - here the newest come first: sort after the step.");
                }

                if (Bool(p, "options", "returnCount"))
                {
                    todo.Add("n8n's search returned only a count - here it returns the records: count them after the step.");
                }

                lines.Add(("max", Most(p, 50)));
            }

            switch (operation)
            {
                case "alerts":
                    Search(("title", "title"), ("status", "status"), ("severity", "severity"), ("tags", "tag"), ("source", "source"), ("type", "type"));
                    break;
                case "alert" or "alert_promote" or "alert_delete":
                    lines.Add(("alert", Locator(p, "alertId")));
                    break;
                case "alert_merge":
                    lines.Add(("alert", Locator(p, "alertId")));
                    lines.Add(("case", Locator(p, "caseId")));
                    break;
                case "alert_status":
                    lines.Add(("alert", Locator(p, "alertId")));
                    lines.Add(("status", Text(p, "status")));
                    break;
                case "alert_create":
                    {
                        var fields = Fields("alertFields");
                        lines.Add(("title", Text(fields, "title")));
                        Multiline("description", Text(fields, "description"));
                        lines.Add(("type", Text(fields, "type")));
                        lines.Add(("source", Text(fields, "source")));
                        lines.Add(("source_ref", Text(fields, "sourceRef")));
                        Marks(fields);
                        lines.Add(("date", Text(fields, "date")));
                        if (Items(p, "observableUi", "values").Any())
                        {
                            todo.Add("n8n's node raised the alert with its observables - here add each with an Observable Create step on the alert, after this one.");
                        }

                        break;
                    }

                case "alert_update":
                    {
                        var fields = Fields("alertUpdateFields");
                        lines.Add(("alert", Text(fields, "id")));
                        lines.Add(("title", Text(fields, "title")));
                        Multiline("description", Text(fields, "description"));
                        lines.Add(("status", Text(fields, "status")));
                        Marks(fields);
                        if (Text(p, "alertUpdateFields", "matchingColumns") is { Length: > 0 } matching && !matching.Contains("\"id\"", StringComparison.Ordinal))
                        {
                            todo.Add("n8n's node changed every alert matching " + matching + " - here the step changes the one alert it names: search for them first and update each in a For Each.");
                        }

                        break;
                    }

                case "cases":
                    Search(("title", "title"), ("status", "status"), ("severity", "severity"), ("tags", "tag"), ("assignee", "assignee"));
                    break;
                case "case" or "case_delete" or "tasks":
                    lines.Add(("case", Locator(p, "caseId")));
                    if (operation == "tasks")
                    {
                        lines.Add(("max", Most(p, 50)));
                    }

                    break;
                case "case_create":
                    {
                        var fields = Fields("caseFields");
                        lines.Add(("title", Text(fields, "title")));
                        Multiline("description", Text(fields, "description"));
                        Marks(fields);
                        lines.Add(("assignee", Text(fields, "assignee") is { Length: > 0 } assignee ? assignee : Text(fields, "owner")));
                        lines.Add(("flag", Text(fields, "flag")));
                        break;
                    }

                case "case_update":
                    {
                        var fields = Fields("caseUpdateFields");
                        lines.Add(("case", Text(fields, "id")));
                        lines.Add(("title", Text(fields, "title")));
                        Multiline("description", Text(fields, "description"));
                        lines.Add(("status", Text(fields, "status")));
                        lines.Add(("summary", Text(fields, "summary")));
                        lines.Add(("impact_status", Text(fields, "impactStatus")));
                        Marks(fields);
                        lines.Add(("assignee", Text(fields, "assignee")));
                        lines.Add(("flag", Text(fields, "flag")));
                        break;
                    }

                case "comments":
                    {
                        var parent = Items(p, "filters", "values").FirstOrDefault(filter => Text(filter, "field") is "caseId" or "alertId" or "case" or "alert");
                        if (parent.ValueKind == JsonValueKind.Object)
                        {
                            lines.Add(("on", Text(parent, "field").StartsWith("alert", StringComparison.Ordinal) ? "alert" : "case"));
                            lines.Add(("id", Text(parent, "value")));
                        }
                        else
                        {
                            todo.Add("n8n's search read comments across TheHive - here the step reads one case's or one alert's: give it 'on' and its 'id'.");
                        }

                        lines.Add(("max", Most(p, 50)));
                        break;
                    }

                case "comment_add":
                    On("addTo", "alert");
                    Multiline("message", Text(p, "message"));
                    break;
                case "comment_update":
                    lines.Add(("comment", Locator(p, "commentId")));
                    Multiline("message", Text(p, "message"));
                    break;
                case "comment_delete":
                    lines.Add(("comment", Locator(p, "commentId")));
                    break;
                case "task" or "task_delete":
                    lines.Add(("task", Locator(p, "taskId")));
                    break;
                case "task_create":
                    {
                        lines.Add(("case", Locator(p, "caseId")));
                        var fields = Fields("taskFields");
                        lines.Add(("title", Text(fields, "title")));
                        Multiline("description", Text(fields, "description"));
                        lines.Add(("group", Text(fields, "group")));
                        lines.Add(("assignee", Text(fields, "assignee")));
                        lines.Add(("flag", Text(fields, "flag")));
                        lines.Add(("due", Text(fields, "dueDate")));
                        lines.Add(("mandatory", Text(fields, "mandatory")));
                        break;
                    }

                case "task_update":
                    {
                        var fields = Fields("taskUpdateFields");
                        lines.Add(("task", Text(fields, "id")));
                        lines.Add(("title", Text(fields, "title")));
                        Multiline("description", Text(fields, "description"));
                        lines.Add(("status", Text(fields, "status")));
                        lines.Add(("assignee", Text(fields, "assignee")));
                        lines.Add(("flag", Text(fields, "flag")));
                        lines.Add(("due", Text(fields, "dueDate")));
                        break;
                    }

                case "task_logs":
                    {
                        var parent = Items(p, "filters", "values").FirstOrDefault(filter => Text(filter, "field") is "taskId" or "task");
                        if (parent.ValueKind == JsonValueKind.Object)
                        {
                            lines.Add(("task", Text(parent, "value")));
                        }
                        else
                        {
                            todo.Add("n8n's search read logs across TheHive - here the step reads one task's: give it the 'task'.");
                        }

                        lines.Add(("max", Most(p, 50)));
                        break;
                    }

                case "task_log_add":
                    {
                        lines.Add(("task", Locator(p, "taskId")));
                        Multiline("message", Text(Fields("logFields"), "message"));
                        if (Items(p, "attachmentsUi", "values").Any())
                        {
                            todo.Add("n8n's node attached files to the log - here a log is its message: attach the files in TheHive.");
                        }

                        break;
                    }

                case "observables":
                    {
                        var parent = Items(p, "filters", "values").FirstOrDefault(filter => Text(filter, "field") is "caseId" or "alertId" or "case" or "alert");
                        if (parent.ValueKind == JsonValueKind.Object)
                        {
                            lines.Add(("on", Text(parent, "field").StartsWith("alert", StringComparison.Ordinal) ? "alert" : "case"));
                            lines.Add(("id", Text(parent, "value")));
                        }
                        else
                        {
                            todo.Add("n8n's search read observables across TheHive - here the step reads one case's or one alert's: give it 'on' and its 'id'.");
                        }

                        if (Items(p, "filters", "values").FirstOrDefault(filter => Text(filter, "field") == "dataType") is { ValueKind: JsonValueKind.Object } type)
                        {
                            lines.Add(("data_type", Text(type, "value")));
                        }

                        lines.Add(("max", Most(p, 50)));
                        break;
                    }

                case "observable" or "observable_delete":
                    lines.Add(("observable", Locator(p, "observableId")));
                    break;
                case "observable_create":
                    {
                        On("createIn", "case");
                        var dataType = Text(p, "dataType") is { Length: > 0 } given ? given : "file";
                        if (dataType == "file")
                        {
                            todo.Add("n8n's node added a file as the observable - here an observable is its data: add the file in TheHive, or give the step a data type and its data.");
                        }
                        else
                        {
                            lines.Add(("data_type", dataType));
                            lines.Add(("data", Text(p, "data")));
                        }

                        var fields = Fields("observableFields");
                        Multiline("message", Text(fields, "message"));
                        lines.Add(("ioc", Text(fields, "ioc")));
                        lines.Add(("sighted", Text(fields, "sighted")));
                        Marks(fields, severity: false);
                        break;
                    }

                case "observable_update":
                    {
                        var fields = Fields("observableUpdateFields");
                        lines.Add(("observable", Text(fields, "id")));
                        Multiline("message", Text(fields, "message"));
                        lines.Add(("ioc", Text(fields, "ioc")));
                        lines.Add(("sighted", Text(fields, "sighted")));
                        Marks(fields, severity: false);
                        break;
                    }
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "alerts" or "cases" or "comments" or "tasks" or "task_logs" or "observables" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a TheHive connection under Admin > Connections (TheHive's address and an API key from a user's settings).");
        }

        // n8n's YOURLS node: a URL to shorten with its additional keyword and title, or a short URL to expand or count. A URL
        // YOURLS already has is said: here it comes back as its existing short URL, where n8n's node failed.
        private static void Yourls(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = operation == "shorten"
                ? new List<(string Name, string Value)> { ("url", Text(p, "url")), ("keyword", Text(p, "additionalFields", "keyword")), ("title", Text(p, "additionalFields", "title")) }
                : new List<(string Name, string Value)> { ("short_url", Text(p, "shortUrl")) };
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (operation == "shorten")
            {
                todo.Add("a URL YOURLS already has comes back here as its existing short URL (its record's 'existing' true), where n8n's node failed - check it where a new link mattered.");
            }

            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a YOURLS connection under Admin > Connections (YOURLS's address and its signature token, from YOURLS's Tools page) and pick it here.");
        }

        // n8n's Wekan node: its ids (a board, a list, a swimlane, a card, a comment, a checklist, an item), titles and fields as the
        // Wekan connector's parameters - a description or a comment over several lines, and a checklist's items one a line, in
        // the Query box; a card's list or swimlane in n8n's update a move within the board. A card's or a comment's author is the
        // connection's user, whatever n8n chose: said where n8n named one.
        private static void Wekan(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();

            void Multiline(string name, string text)
            {
                if (text.Contains('\n') || text.Contains('\r'))
                {
                    Set(step, "Query", text); // over several lines: the step's Query box
                }
                else
                {
                    lines.Add((name, text));
                }
            }

            // n8n's multi-options (a JSON list) or a text of ids, as ids by commas.
            static string Ids(JsonElement fields, string name) =>
                Find(fields, name) is { ValueKind: JsonValueKind.Array } ids ? string.Join(",", ids.EnumerateArray().Select(id => id.ValueKind == JsonValueKind.String ? id.GetString() : id.GetRawText())) : Text(fields, name);

            void Author(JsonElement fields)
            {
                if (Text(fields, "authorId").Length > 0)
                {
                    todo.Add("its author is the connection's user here - Wekan takes it from the sign-in whatever n8n's node sent: sign in as the user it should be.");
                }
            }

            lines.Add(("board", Text(p, "boardId")));
            switch (operation)
            {
                case "boards":
                    lines.Clear();
                    lines.Add(("user", Text(p, "IdUser")));
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "board_create":
                    {
                        lines.Clear();
                        lines.Add(("title", Text(p, "title")));
                        lines.Add(("owner", Text(p, "owner")));
                        var fields = Find(p, "additionalFields");
                        lines.Add(("color", Text(fields, "color")));
                        lines.Add(("permission", Text(fields, "permission")));
                        foreach (var (n8n, name) in new[] { ("isAdmin", "is_admin"), ("isActive", "is_active"), ("isCommentOnly", "is_comment_only"), ("isNoComments", "is_no_comments"), ("isWorker", "is_worker") })
                        {
                            lines.Add((name, Text(fields, n8n)));
                        }

                        break;
                    }

                case "lists":
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "list":
                case "list_delete":
                    lines.Add(("list", Text(p, "listId")));
                    break;
                case "list_create":
                    lines.Add(("title", Text(p, "title")));
                    break;
                case "cards":
                    lines.Add(Text(p, "fromObject") == "swimlane" ? ("swimlane", Text(p, "swimlaneId")) : ("list", Text(p, "listId")));
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "card":
                case "card_delete":
                    lines.Add(("list", Text(p, "listId")));
                    lines.Add(("card", Text(p, "cardId")));
                    break;
                case "card_create":
                    {
                        var fields = Find(p, "additionalFields");
                        lines.Add(("list", Text(p, "listId")));
                        lines.Add(("title", Text(p, "title")));
                        lines.Add(("swimlane", Text(p, "swimlaneId")));
                        Multiline("description", Text(fields, "description"));
                        lines.Add(("assignees", Ids(fields, "assignees")));
                        lines.Add(("members", Ids(fields, "members")));
                        Author(p);
                        break;
                    }

                case "card_update":
                    {
                        var fields = Find(p, "updateFields");
                        lines.Add(("list", Text(p, "listId")));
                        lines.Add(("card", Text(p, "cardId")));
                        lines.Add(("title", Text(fields, "title")));
                        Multiline("description", Text(fields, "description"));
                        lines.Add(("color", Text(fields, "color")));
                        foreach (var (n8n, name) in new[] { ("dueAt", "due_at"), ("startAt", "start_at"), ("endAt", "end_at"), ("receivedAt", "received_at") })
                        {
                            lines.Add((name, Text(fields, n8n)));
                        }

                        lines.Add(("to_list", Text(fields, "listId")));
                        lines.Add(("to_swimlane", Text(fields, "swimlaneId")));
                        lines.Add(("parent", Text(fields, "parentId")));
                        lines.Add(("assignees", Ids(fields, "assignees")));
                        lines.Add(("members", Ids(fields, "members")));
                        lines.Add(("labels", Ids(fields, "labelIds")));
                        lines.Add(("sort", Text(fields, "sort")));
                        lines.Add(("spent_time", Text(fields, "spentTime")));
                        lines.Add(("is_over_time", Text(fields, "isOverTime")));
                        Author(fields);
                        break;
                    }

                case "comments":
                    lines.Add(("card", Text(p, "cardId")));
                    break;
                case "comment":
                case "comment_delete":
                    lines.Add(("card", Text(p, "cardId")));
                    lines.Add(("comment", Text(p, "commentId")));
                    break;
                case "comment_create":
                    lines.Add(("card", Text(p, "cardId")));
                    Multiline("comment", Text(p, "comment"));
                    Author(p);
                    break;
                case "checklists":
                    lines.Add(("card", Text(p, "cardId")));
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "checklist":
                case "checklist_delete":
                    lines.Add(("card", Text(p, "cardId")));
                    lines.Add(("checklist", Text(p, "checklistId")));
                    break;
                case "checklist_create":
                    lines.Add(("card", Text(p, "cardId")));
                    lines.Add(("title", Text(p, "title")));
                    if (Find(p, "items") is { ValueKind: JsonValueKind.Array } items && items.GetArrayLength() > 0)
                    {
                        Set(step, "Query", string.Join("\n", items.EnumerateArray().Select(item => item.ValueKind == JsonValueKind.String ? item.GetString() : item.GetRawText()))); // one item a line
                    }

                    break;
                default: // a checklist item
                    lines.Add(("card", Text(p, "cardId")));
                    lines.Add(("checklist", Text(p, "checklistId")));
                    lines.Add(("item", Text(p, "checklistItemId")));
                    if (operation == "checklist_item_update")
                    {
                        lines.Add(("title", Text(p, "updateFields", "title")));
                        lines.Add(("finished", Text(p, "updateFields", "isFinished")));
                    }

                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (operation == "comment_create")
            {
                todo.Add("the card is read on its board before the comment is added - Wekan 12 disables the account at a comment for a card that is not on it.");
            }

            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a Wekan connection under Admin > Connections (Wekan's address, a user's name and password) and pick it here.");
        }

        // n8n's Rundeck node: Execute as a run - its job, each argument an option.name parameter and its node filter - and Get
        // Metadata as a job's. n8n sent the arguments as one argString, which Rundeck splits on its own dashes: here each is its
        // own option, so a value holding " -" stays one value - said where one does.
        private static void Rundeck(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)> { ("job", Text(p, "jobid")) };
            if (operation == "run")
            {
                foreach (var argument in Items(p, "arguments", "arguments"))
                {
                    var value = Text(argument, "value");
                    lines.Add(("option." + Text(argument, "name"), value));
                    if (value.Contains(" -", StringComparison.Ordinal))
                    {
                        todo.Add($"n8n sent '{Text(argument, "name")}' inside one argString, where Rundeck read its \" -\" as another option - here it is one value, as written: check that is what the job should get.");
                    }
                }

                lines.Add(("filter", Text(p, "filter")));
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0 && line.Name != "option.").ToArray()));
            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a Rundeck connection under Admin > Connections (Rundeck's address and an API token from a user's profile) and pick it here.");
        }

        // n8n's Taiga node: its project, item ids, fields and filters as the Taiga connector's parameters - a description over
        // several lines in the Query box, tags by commas, n8n's numbers for a status, a priority or an assignee as they are (the
        // connector takes a name too). Two of n8n's filters never reached Taiga - Is Closed and a task's User Story went under
        // names Taiga ignores, so n8n's step returned everything - and here they filter: said where one is set. What has no
        // field here (a user story's type, which Taiga does not have; a list's owner and role filters) is named.
        private static void Taiga(JsonElement p, PipelineGraphStep step, Todo todo, string kind, string verb)
        {
            Set(step, "Operation", verb switch { "list" => kind == "user_story" ? "user_stories" : kind + "s", "get" => kind, _ => kind + "_" + verb });
            var n8nId = kind switch { "user_story" => "userStoryId", _ => kind + "Id" };
            var lines = new List<(string Name, string Value)>();

            static string Listed(JsonElement fields, string name) =>
                Find(fields, name) is { ValueKind: JsonValueKind.Array } list ? string.Join(", ", list.EnumerateArray().Select(item => item.ValueKind == JsonValueKind.String ? item.GetString() : item.GetRawText())) : Text(fields, name);

            void Fields(JsonElement fields)
            {
                foreach (var name in new[] { "subject", "assigned_to", "status", "tags", "is_blocked", "blocked_note", "priority", "severity", "type", "milestone", "user_story", "color", "us_order", "taskboard_order", "backlog_order", "kanban_order", "sprint_order" })
                {
                    var value = name == "tags" ? Listed(fields, name) : Text(fields, name);
                    if (value.Length == 0)
                    {
                        continue;
                    }

                    if (name == "type" && kind == "user_story")
                    {
                        todo.Add("n8n sent the user story a type, which Taiga's user stories do not have and ignored - left out here.");
                        continue;
                    }

                    lines.Add((name, value));
                }

                var description = Text(fields, "description");
                if (description.Contains('\n') || description.Contains('\r'))
                {
                    Set(step, "Query", description); // over several lines: the step's Query box
                }
                else if (description.Length > 0)
                {
                    lines.Add(("description", description));
                }
            }

            switch (verb)
            {
                case "create":
                    lines.Add(("project", Text(p, "projectId")));
                    lines.Add(("subject", Text(p, "subject")));
                    Fields(Find(p, "additionalFields"));
                    break;
                case "update":
                    lines.Add((kind, Text(p, n8nId)));
                    Fields(Find(p, "updateFields"));
                    break;
                case "list":
                    {
                        lines.Add(("project", Text(p, "projectId")));
                        var filters = Find(p, "filters");
                        foreach (var (n8n, name) in new[] { ("assigned_to", "assigned_to"), ("status", "status"), ("priority", "priority"), ("severity", "severity"), ("type", "type"), ("milestone", "milestone"), ("epic", "epic"), ("orderBy", "order_by") })
                        {
                            if (Text(filters, n8n) is { Length: > 0 } value && (name is "assigned_to" or "status" or "milestone" || (kind == "issue" && name is "priority" or "severity" or "type" or "order_by") || (kind == "user_story" && name == "epic")))
                            {
                                lines.Add((name, value));
                            }
                        }

                        lines.Add(("tags", Listed(filters, "tags")));
                        if (Text(filters, "statusIsClosed") is { Length: > 0 } closed)
                        {
                            lines.Add(("closed", closed));
                            todo.Add("n8n's Is Closed filter reached Taiga under a name it ignores, so n8n's step returned every item - here it filters: check what follows expects only those.");
                        }

                        if (kind == "task" && Text(filters, "userStory") is { Length: > 0 } story)
                        {
                            lines.Add(("user_story", story));
                            todo.Add("n8n's User Story filter reached Taiga under a name it ignores, so n8n's step returned every task - here it filters: check what follows expects only that story's.");
                        }

                        if (kind == "user_story" && Text(filters, "statusIsArchived") is { Length: > 0 } archived)
                        {
                            lines.Add(("archived", archived));
                        }

                        var left = new[] { "owner", "role" }.Where(name => Text(filters, name).Length > 0).ToArray();
                        if (left.Length > 0)
                        {
                            todo.Add($"n8n filtered by {string.Join(" and ", left)} - here a list filters by assignee, status, tags and closed: filter after the step.");
                        }

                        lines.Add(("max", Most(p, 50)));
                        break;
                    }

                default: // get, delete
                    lines.Add((kind, Text(p, n8nId)));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a Taiga connection under Admin > Connections (Taiga's address, a user's name and password) and pick it here.");
        }

        // n8n's QuickChart node: its chart type, labels (by hand, as a JSON list, or its labels array), data, one dataset's
        // options and the chart's, as the QuickChart connector's chart - saved as a file in the run's pipeline folder, where n8n
        // kept it in an item's binary property. n8n drew at quickchart.io whatever its node said; here the connection names the
        // server, quickchart.io or your own.
        private static void QuickChart(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            Set(step, "Operation", "chart");
            var lines = new List<(string Name, string Value)> { ("type", Text(p, "chartType")) };
            if (Text(p, "labelsMode") == "array")
            {
                lines.Add(("labels", Text(p, "labelsArray")));
            }
            else
            {
                var labels = Items(p, "labelsUi", "labelsValues").Select(label => Text(label, "label")).ToList();
                if (labels.Count > 0)
                {
                    lines.Add(("labels", JsonSerializer.Serialize(labels, ReadableJson))); // a JSON list: a label may hold a comma
                }
            }

            lines.Add(("data", Text(p, "data")));
            var dataset = Find(p, "datasetOptions");
            lines.Add(("label", Text(dataset, "label")));
            lines.Add(("background_color", Text(dataset, "backgroundColor")));
            lines.Add(("border_color", Text(dataset, "borderColor")));
            lines.Add(("fill", Text(dataset, "fill")));
            lines.Add(("point_style", Text(dataset, "pointStyle")));
            var chart = Find(p, "chartOptions");
            lines.Add(("horizontal", Text(chart, "horizontal")));
            lines.Add(("width", Text(chart, "width")));
            lines.Add(("height", Text(chart, "height")));
            lines.Add(("pixel_ratio", Text(chart, "devicePixelRatio")));
            lines.Add(("background", Text(chart, "backgroundColor")));
            var format = Text(chart, "format");
            lines.Add(("format", format));
            var output = Text(p, "output") is { Length: > 0 } property ? property : "data";
            lines.Add(("file", $"{output}.{(format.Length > 0 ? format : "png")}"));
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add($"n8n kept the chart in the item's '{output}' binary property - here it is a file in the run's pipeline folder, named in its record: read it with the file steps.");
            todo.Add("n8n drew one chart of every item's data together - here a step draws one chart: give it every number, or put it in a For Each for a chart each.");
            todo.Add("choose its connection - add a QuickChart connection under Admin > Connections (https://quickchart.io, or your own QuickChart's address; no sign-in) and pick it here.");
        }

        // n8n's Monica CRM node: its resource and operation as the Monica connector's operation, its parameters - top level and
        // in its additional and update fields - under the connector's names, a date-time cut to its day, a list of tags by commas.
        // Two of n8n's operations failed against Monica 4 and work here: Contact - Update (n8n read back only the first name, and
        // Monica requires the birthdate and deceased flags) and Contact Field - Get Many (n8n calls a route Monica has not got).
        private static readonly Dictionary<string, string> MonicaNames = new(StringComparer.Ordinal)
        {
            ["firstName"] = "first_name", ["genderId"] = "gender", ["gender_id"] = "gender", ["contactId"] = "contact", ["contact_id"] = "contact",
            ["activityTypeId"] = "activity_type", ["activity_type_id"] = "activity_type", ["contactFieldTypeId"] = "contact_field_type", ["contact_field_type_id"] = "contact_field_type",
            ["happenedAt"] = "happened_at", ["calledAt"] = "called_at", ["initialDate"] = "initial_date", ["frequencyType"] = "frequency_type", ["frequencyNumber"] = "frequency_number",
            ["writtenAt"] = "written_at", ["writtenByMe"] = "written_by_me", ["isFavorited"] = "is_favorited", ["isDeceased"] = "deceased", ["is_deceased"] = "deceased",
            ["is_deaceased"] = "deceased", ["deceasedDate"] = "deceased_date", ["tagsToAdd"] = "tags", ["tagsToRemove"] = "tags",
        };

        private static readonly HashSet<string> MonicaDates = new(StringComparer.Ordinal) { "happened_at", "called_at", "initial_date", "written_at", "birthdate", "deceased_date" };

        private static void MonicaCrm(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            var resource = Text(p, "resource") is { Length: > 0 } given ? given : "contact";
            var operation = Text(p, "operation") is { Length: > 0 } chosen ? chosen : "create";
            var name = resource switch { "contactField" => "contact_field", "journalEntry" => "journal_entry", "conversationMessage" => "message", "contactTag" => "contact_tags", var other => other };
            var plural = name switch { "activity" => "activities", "journal_entry" => "journal_entries", _ => name + "s" };
            var connectorOperation = (name, operation) switch
            {
                ("contact_tags", "add") => "contact_tags_add",
                ("contact_tags", "remove") => "contact_tags_remove",
                ("message", "add") => "message_create",
                ("message", _) => "message_" + operation,
                (_, "getAll") => plural,
                (_, "get") => name,
                _ => name + "_" + operation,
            };
            Set(step, "Operation", connectorOperation);

            var lines = new List<(string Name, string Value)>();
            void Add(string key, JsonElement value)
            {
                var target = MonicaNames.TryGetValue(key, out var known) ? known
                    : key.EndsWith("Id", StringComparison.Ordinal) ? key[..^2] switch { "journal" => "journal_entry", "contactField" => "contact_field", var item => item } // an item's own id: its name
                    : key;
                if (target is "returnAll" or "limit" or "filters" or "additionalFields" or "updateFields" or "resource" or "operation")
                {
                    return;
                }

                var text = value.ValueKind == JsonValueKind.Array
                    ? string.Join(", ", value.EnumerateArray().Select(item => item.ValueKind == JsonValueKind.String ? item.GetString() : item.GetRawText()))
                    : value.ValueKind == JsonValueKind.String ? value.GetString() ?? "" : value.GetRawText();
                if (MonicaDates.Contains(target) && !text.StartsWith('=') && text.Length > 10 && text[10] == 'T')
                {
                    text = text[..10]; // n8n's date-time: here a day, as Monica keeps it
                }

                if (text.Contains('\n') || text.Contains('\r'))
                {
                    Set(step, "Query", text); // over several lines: the step's Query box
                    return;
                }

                lines.Add((target, text));
            }

            if (p.ValueKind == JsonValueKind.Object)
            {
                foreach (var property in p.EnumerateObject())
                {
                    Add(property.Name, property.Value);
                }

                foreach (var holder in new[] { "additionalFields", "updateFields", "filters" })
                {
                    if (Find(p, holder) is { ValueKind: JsonValueKind.Object } fields)
                    {
                        foreach (var property in fields.EnumerateObject())
                        {
                            Add(property.Name, property.Value);
                        }
                    }
                }
            }

            if (operation == "getAll")
            {
                lines.Add(("max", Most(p, 50)));
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (connectorOperation == "contact_update")
            {
                todo.Add("n8n's Contact - Update failed against Monica 4 (it sent back only the first name, and Monica requires the birthdate and deceased flags) - here the contact is read and sent back whole: check what follows did not count on the failure.");
            }

            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a Monica CRM connection under Admin > Connections (Monica's address and an API token from its settings) and pick it here.");
        }

        // n8n's Invoice Ninja node: its resource and operation as the Invoice Ninja connector's operation, its parameters - top level,
        // in its additional fields and options, its addresses, contacts, lines and time logs - under the connector's names (version
        // 5's), a date-time cut to its day where Invoice Ninja keeps a day. Measured against Invoice Ninja 5.13: n8n's invoice and
        // quote date and expense date went under version 4's names, which version 5 ignores (the item dated today); its e-mail
        // answered 400; its "is deleted" filtered nothing - each said where an imported step counted on it.
        private static readonly Dictionary<string, string> InvoiceNinjaNames = new(StringComparer.Ordinal)
        {
            ["clientId"] = "client", ["invoiceId"] = "invoice", ["quoteId"] = "quote", ["taskId"] = "task", ["paymentId"] = "payment", ["expenseId"] = "expense",
            ["bankTransactionId"] = "bank_transaction", ["bankIntegrationId"] = "bank_integration", ["clientName"] = "name", ["idNumber"] = "id_number",
            ["privateNotes"] = "private_notes", ["publicNotes"] = "public_notes", ["vatNumber"] = "vat_number", ["workPhone"] = "work_phone", ["dueDate"] = "due_date",
            ["invoiceDate"] = "date", ["quoteDate"] = "date", ["expenseDate"] = "date", ["invoiceNumber"] = "number", ["quoteNumber"] = "number", ["poNumber"] = "po_number",
            ["isAmountDiscount"] = "is_amount_discount", ["partialDueDate"] = "partial_due_date", ["taxName1"] = "tax_name1", ["taxName2"] = "tax_name2",
            ["taxRate1"] = "tax_rate1", ["taxRate2"] = "tax_rate2", ["customValue1"] = "custom_value1", ["customValue2"] = "custom_value2", ["markSent"] = "mark_sent",
            ["emailInvoice"] = "send_email", ["paymentType"] = "payment_type", ["transferReference"] = "transaction_reference", ["transactionReference"] = "transaction_reference",
            ["paymentDate"] = "payment_date", ["baseType"] = "base_type", ["currencyId"] = "currency", ["createdAt"] = "created_since", ["updatedAt"] = "updated_since",
            ["clientStatus"] = "client_status",
        };

        private static readonly HashSet<string> InvoiceNinjaDays = new(StringComparer.Ordinal) { "date", "due_date", "partial_due_date", "payment_date" };

        private static void InvoiceNinja(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            var resource = Text(p, "resource") is { Length: > 0 } given ? given : "client";
            var operation = Text(p, "operation") is { Length: > 0 } chosen ? chosen : "create";
            var plural = resource + "s";
            var connectorOperation = operation switch
            {
                "getAll" => plural,
                "get" => resource,
                "matchPayment" => "bank_transaction_match",
                var other => resource + "_" + other,
            };
            Set(step, "Operation", connectorOperation);

            var lines = new List<(string Name, string Value)>();
            string Of(JsonElement value) =>
                value.ValueKind == JsonValueKind.String ? value.GetString() ?? "" : value.GetRawText();
            void Add(string key, JsonElement value)
            {
                var target = InvoiceNinjaNames.TryGetValue(key, out var known) ? known : key;
                if (resource == "payment" && key == "paymentType")
                {
                    target = "type"; // a payment's own type; an expense's is its payment_type
                }

                if (target == "isDeleted")
                {
                    if (value.ValueKind == JsonValueKind.True)
                    {
                        lines.Add(("status", "deleted")); // n8n's is_deleted filtered nothing on Invoice Ninja 5: the status does
                    }

                    return;
                }

                if (target is "returnAll" or "limit" or "options" or "additionalFields" or "resource" or "operation" or "apiVersion" or "email" or "autoBill"
                    or "invoiceStatus" or "quoteStatus" or "emailQuote" or "invoiceItemsUi" or "contactsUi" or "billingAddressUi" or "shippingAddressUi" or "timeLogsUi")
                {
                    return;
                }

                var text = Of(value);
                if (InvoiceNinjaDays.Contains(target) && !text.StartsWith('=') && text.Length > 10 && text[10] == 'T')
                {
                    text = text[..10]; // n8n's date-time: here a day, as Invoice Ninja keeps it
                }

                if (text.Contains('\n') || text.Contains('\r'))
                {
                    Set(step, "Query", text); // over several lines: the step's Query box
                    return;
                }

                lines.Add((target, text));
            }

            if (p.ValueKind == JsonValueKind.Object)
            {
                foreach (var property in p.EnumerateObject())
                {
                    Add(property.Name, property.Value);
                }

                foreach (var holder in new[] { "additionalFields", "options" })
                {
                    if (Find(p, holder) is { ValueKind: JsonValueKind.Object } fields)
                    {
                        foreach (var property in fields.EnumerateObject())
                        {
                            Add(property.Name, property.Value);
                        }
                    }
                }

                // A client's addresses and contacts, an invoice's or a quote's lines and a task's time: n8n's collections.
                foreach (var (holder, value, prefix) in new[] { ("billingAddressUi", "billingAddressValue", ""), ("shippingAddressUi", "shippingAddressValue", "shipping_") })
                {
                    if (Find(p, holder) is { ValueKind: JsonValueKind.Object } ui && ui.TryGetProperty(value, out var address) && address.ValueKind == JsonValueKind.Object)
                    {
                        foreach (var property in address.EnumerateObject())
                        {
                            var part = property.Name switch { "streetAddress" => "address1", "aptSuite" => "address2", "postalCode" => "postal_code", "countryCode" => "country", var other => other };
                            lines.Add((prefix + part, Of(property.Value)));
                        }
                    }
                }

                JsonElement[] Rows(string holder, string value) =>
                    Find(p, holder) is { ValueKind: JsonValueKind.Object } ui && ui.TryGetProperty(value, out var rows) && rows.ValueKind == JsonValueKind.Array ? rows.EnumerateArray().ToArray() : Array.Empty<JsonElement>();
                if (Rows("contactsUi", "contacstValues") is { Length: > 0 } contacts)
                {
                    lines.Add(("contacts", JsonSerializer.Serialize(contacts.Select(contact => contact.EnumerateObject().ToDictionary(
                        property => property.Name switch { "firstName" => "first_name", "lastName" => "last_name", var other => other }, property => Of(property.Value))), ReadableJson)));
                }

                if (Rows("invoiceItemsUi", "invoiceItemsValues") is { Length: > 0 } items)
                {
                    Set(step, "Query", JsonSerializer.Serialize(items.Select(item => item.EnumerateObject().ToDictionary(
                        property => property.Name switch { "service" => "product_key", "description" => "notes", "hours" => "quantity", "taxName1" => "tax_name1", "taxName2" => "tax_name2", "taxRate1" => "tax_rate1", "taxRate2" => "tax_rate2", var other => other },
                        property => property.Value.ValueKind == JsonValueKind.Number ? (object)property.Value.GetDecimal() : Of(property.Value))), ReadableJson));
                    if (items.Any(item => item.EnumerateObject().Any(property => Of(property.Value).StartsWith('='))))
                    {
                        todo.Add("its lines held n8n expressions, kept as their text - write them as {{ }} in the step's Query box.");
                    }
                }

                if (Rows("timeLogsUi", "timeLogsValues") is { Length: > 0 } logs)
                {
                    foreach (var property in logs[0].EnumerateObject())
                    {
                        lines.Add((property.Name switch { "startDate" => "start", "endDate" => "end", "duration" => "hours", var other => other }, Of(property.Value)));
                    }

                    if (logs.Length > 1)
                    {
                        todo.Add($"n8n logged {logs.Length} times on the task - here its first; add each other as a task of its own.");
                    }
                }
            }

            if (operation == "getAll")
            {
                lines.Add(("max", Most(p, 50)));
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (Text(p, "apiVersion") is "v4")
            {
                todo.Add("n8n spoke Invoice Ninja 4's API to it - the connector speaks version 5's: check the server is Invoice Ninja 5.");
            }

            if (operation == "email")
            {
                todo.Add("n8n's Email failed against Invoice Ninja 5 (a 400: the requested action email is not available) - here it goes by Invoice Ninja's own e-mail: check what follows did not count on the failure.");
            }

            if (Text(p, "additionalFields", "invoiceDate").Length > 0 || Text(p, "additionalFields", "quoteDate").Length > 0 || Text(p, "additionalFields", "expenseDate").Length > 0)
            {
                todo.Add("n8n sent its date under Invoice Ninja 4's name, which version 5 ignores - the item was dated the day it ran; here it takes the date given.");
            }

            if (Text(p, "additionalFields", "invoiceStatus").Length > 0 || Text(p, "additionalFields", "quoteStatus").Length > 0 || Text(p, "additionalFields", "autoBill").Length > 0 || Text(p, "additionalFields", "emailQuote").Length > 0)
            {
                todo.Add("n8n's status, auto bill and e-mail-the-quote fields were version 4's and did nothing on version 5 - left out: mark it sent with mark_sent, e-mail it with its Email operation.");
            }

            if (connectorOperation == "bank_transaction_create" && !lines.Any(line => line.Name == "bank_integration"))
            {
                todo.Add("give its bank_integration - Invoice Ninja refuses a bank transaction without its bank account, though n8n has it optional.");
            }

            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add an Invoice Ninja connection under Admin > Connections (Invoice Ninja's address and an API token from its settings) and pick it here.");
        }

        // n8n's Mattermost node beside its message posted: its resource and operation as the Mattermost connector's operation, its
        // parameters - top level and in its additional fields - under the connector's names. Measured against Mattermost 10.11: a
        // reaction is saved only as the token's own user, so n8n's reaction user is left out (another's was a 403); a password is
        // never a step's parameter here, so n8n's e-mail user's password is left out and the step says to invite instead.
        private static readonly Dictionary<string, string> MattermostNames = new(StringComparer.Ordinal)
        {
            ["channelId"] = "channel", ["userId"] = "user", ["postId"] = "post", ["teamId"] = "team", ["message"] = "text", ["displayName"] = "display_name",
            ["resolveData"] = "resolve", ["emojiName"] = "emoji", ["authService"] = "auth_service", ["authData"] = "auth_data", ["userIds"] = "users",
            ["inTeam"] = "in_team", ["notInTeam"] = "not_in_team", ["inChannel"] = "in_channel", ["notInChannel"] = "not_in_channel",
        };

        private static void MattermostRest(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            var resource = Text(p, "resource");
            var operation = Text(p, "operation");
            var connectorOperation = (resource, operation) switch
            {
                ("message", "postEphemeral") => "message_ephemeral",
                ("message", "delete") => "message_delete",
                ("channel", "addUser") => "channel_add_user",
                ("channel", var other) => "channel_" + other,
                ("reaction", "getAll") => "reactions",
                ("reaction", var other) => "reaction_" + other,
                ("user", "deactive") => "user_deactivate",
                ("user", "getAll") => "users",
                ("user", "getByEmail") => "user_by_email",
                ("user", "getById") => "users_by_id",
                ("user", var other) => "user_" + other,
                _ => resource + "_" + operation,
            };
            Set(step, "Operation", connectorOperation);

            var lines = new List<(string Name, string Value)>();
            void Add(string key, JsonElement value)
            {
                var target = connectorOperation == "channel_create" && key == "channel" ? "name" : MattermostNames.TryGetValue(key, out var known) ? known : key;
                if (target is "returnAll" or "limit" or "additionalFields" or "resource" or "operation" or "notificationUi" or "password"
                    || (connectorOperation == "channel_members" && target == "team") || (connectorOperation == "reaction_create" && target == "user"))
                {
                    return; // a reaction is the token's own user's; a password is no step's parameter
                }

                var text = value.ValueKind == JsonValueKind.String ? value.GetString() ?? "" : value.GetRawText();
                if (text.Contains('\n') || text.Contains('\r'))
                {
                    Set(step, "Query", text); // over several lines: the step's Query box
                    return;
                }

                lines.Add((target, text));
            }

            if (p.ValueKind == JsonValueKind.Object)
            {
                foreach (var property in p.EnumerateObject())
                {
                    Add(property.Name, property.Value);
                }

                if (Find(p, "additionalFields") is { ValueKind: JsonValueKind.Object } fields)
                {
                    foreach (var property in fields.EnumerateObject())
                    {
                        Add(property.Name, property.Value);
                    }
                }
            }

            if (connectorOperation is "channel_members" or "channel_search" or "reactions" or "users")
            {
                lines.Add(("max", Most(p, 100)));
            }


            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            if (connectorOperation == "reaction_create" && Text(p, "userId").Length > 0)
            {
                todo.Add("n8n named the reaction's user - Mattermost saves one only as the token's own (another's was a 403): here it is the token's user; check that is who it was.");
            }

            if (connectorOperation == "user_create" && Text(p, "authService") is "" or "email")
            {
                todo.Add("n8n made a user signing in by e-mail, its password a node parameter - a password is never a step's parameter here: this step refuses; invite them with the Mattermost connection's user_invite instead.");
            }

            if (Find(p, "additionalFields") is { ValueKind: JsonValueKind.Object } extra && extra.TryGetProperty("notificationUi", out _))
            {
                todo.Add("n8n set the new user's notifications - left out: the user sets them in Mattermost.");
            }

            todo.Add(PerItem);
            todo.Add(ChatCredential("Mattermost", "a bot account's or a personal access token (its endpoint the server's address)"));
        }

        // n8n's ERPNext node: its operation as the ERPNext connector's, its doctype and document, its properties as the fields'
        // JSON object and its filters as Frappe's [field, operator, value] - n8n's operator names as Frappe's (n8n's 'is' is '='; Frappe's own 'is' tests whether a field is set) - an
        // expression in either kept as one. Measured against ERPNext 16: n8n sent every property as text, so a child table (a
        // sales order's items) was a 500 - said where a property's value is a list.
        private static void ErpNext(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            var operation = Text(p, "operation") is { Length: > 0 } chosen ? chosen : "get";
            Set(step, "Operation", operation switch { "getAll" => "documents", "get" => "document", var other => "document_" + other });
            var lines = new List<(string Name, string Value)> { ("doctype", Text(p, "docType")) };
            if (operation is "get" or "update" or "delete")
            {
                lines.Add(("name", Text(p, "documentName")));
            }

            var expression = false;
            JsonNode? Value(string text)
            {
                if (text.StartsWith('='))
                {
                    expression = true;
                    return JsonValue.Create(text[1..]);
                }

                return JsonValue.Create(text);
            }

            JsonElement[] Rows(JsonElement holder) =>
                holder.ValueKind == JsonValueKind.Object && holder.TryGetProperty("customProperty", out var rows) && rows.ValueKind == JsonValueKind.Array ? rows.EnumerateArray().ToArray() : Array.Empty<JsonElement>();
            if (operation is "create" or "update" && Find(p, "properties") is { } properties)
            {
                var fields = new JsonObject();
                foreach (var property in Rows(properties))
                {
                    var value = Text(property, "value");
                    fields[Text(property, "field")] = Value(value);
                    if (value.TrimStart('=').TrimStart().StartsWith('['))
                    {
                        todo.Add($"its property {Text(property, "field")} is a list - n8n sent it as text, which ERPNext answered with a 500; here it goes as JSON: check it is the rows meant.");
                    }
                }

                lines.Add(("fields", fields.ToJsonString(ReadableJson)));
            }

            if (operation == "getAll")
            {
                if (Find(p, "options") is { ValueKind: JsonValueKind.Object } options)
                {
                    if (options.TryGetProperty("fields", out var fieldNames) && fieldNames.ValueKind == JsonValueKind.Array)
                    {
                        lines.Add(("fields", string.Join(", ", fieldNames.EnumerateArray().Select(field => field.GetString()))));
                    }

                    if (options.TryGetProperty("filters", out var filters) && Rows(filters) is { Length: > 0 } rows)
                    {
                        lines.Add(("filters", new JsonArray(rows.Select(row => (JsonNode?)new JsonArray(JsonValue.Create(Text(row, "field")), JsonValue.Create(Text(row, "operator") switch { "isNot" => "!=", "greater" => ">", "less" => "<", "equalsGreater" => ">=", "equalsLess" => "<=", _ => "=" }), Value(Text(row, "value")))).ToArray()).ToJsonString(ReadableJson)));
                    }
                }

                lines.Add(("max", Most(p, 50)));
            }

            var parameters = FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray());
            Set(step, "Parameters", expression && !parameters.StartsWith('=') ? "=" + parameters : parameters);
            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add an ERPNext connection under Admin > Connections (its address and an API key and secret from a user's settings) and pick it here.");
        }

        // n8n's AMQP Sender as the AMQP 1.0 connector's send: its queue or topic, its headers as application properties. n8n sent
        // each item's JSON - or one property of it - as the message, which here is given; and it returned without the broker's
        // outcome, so a message the broker refused was "sent" (measured against RabbitMQ 4.1) - here the step fails then.
        private static void Amqp(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            Set(step, "Operation", "send");
            var options = Find(p, "options");
            var lines = new List<(string Name, string Value)> { ("to", Text(p, "sink")) };
            var headers = Text(p, "headerParametersJson");
            if (headers.Length > 0 && headers != "{}")
            {
                lines.Add(("headers", headers.Replace("\r", string.Empty, StringComparison.Ordinal).Replace("\n", " ", StringComparison.Ordinal)));
            }

            todo.Add(Text(options, "sendOnlyProperty") is { Length: > 0 } property
                ? $"n8n sent each item's '{property}' as the message - here give the message: 'message = {{{{ record.{property} }}}}' in a For Each over the records."
                : "n8n sent each item's own JSON as the message - here give the message: the record as JSON in a For Each, 'message = {{ record }}'.");
            if (Bool(options, "dataAsObject"))
            {
                todo.Add("n8n sent the item as an AMQP map (its Data as Object) - here the message is text: JSON a receiver parses, or ask for it as bytes with 'body = data'.");
            }

            todo.Add("n8n's sender returned without the broker's answer, so a message to a queue it has not got, or one nothing routed, was 'sent' - here the step fails then: check what follows did not count on that.");
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add an AMQP 1.0 connection under Admin > Connections (amqp://broker:5672, or amqps:// for TLS, with its user and password) and pick it here.");
        }

        // n8n's SeaTable node as the SeaTable connector's operations: its table, view, row and link column by NAME (n8n keeps
        // name:::id, the connector looks the ids up), its columns' values as the fields' JSON object, its search's term and
        // options. Measured against SeaTable 6.2: n8n's search spliced its term into the SQL with backslash escapes SeaTable does
        // not read, so a term with a quote found nothing - said where an imported search runs.
        private static void SeaTable(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            var resource = Text(p, "resource") is { Length: > 0 } given ? given : "row";
            var operation = Text(p, "operation") is { Length: > 0 } chosen ? chosen : resource == "row" ? "create" : "metadata";
            string Name(string value) => value.Split(":::")[0];
            var connectorOperation = (resource, operation) switch
            {
                ("row", "getAll" or "list") => "rows",
                ("row", "get") => "row",
                ("row", "search") => "rows_search",
                ("row", "delete" or "remove") => "row_delete",
                ("row", var other) => "row_" + other,
                ("base", "collaborator") => "base_collaborators",
                ("base", var other) => "base_" + other,
                ("link", "list") => "links",
                ("link", var other) => "link_" + other,
                ("asset", "getPublicURL") => "asset_link",
                _ => "asset_upload",
            };
            Set(step, "Operation", connectorOperation);

            var lines = new List<(string Name, string Value)>();
            if (Text(p, "tableName") is { Length: > 0 } table)
            {
                lines.Add(("table", Name(table)));
            }

            var view = Text(p, "viewName") is { Length: > 0 } named ? named : Text(p, "filters", "view_name");
            if (connectorOperation == "rows" && view.Length > 0)
            {
                lines.Add(("view", Name(view)));
            }

            if (connectorOperation is "links" or "link_add" or "link_remove")
            {
                lines.Add(("column", Name(Text(p, "linkColumn"))));
                lines.Add(("row", Text(p, connectorOperation == "links" ? "rowId" : "linkColumnSourceId")));
                if (connectorOperation != "links")
                {
                    lines.Add(("other_rows", Text(p, "linkColumnTargetId")));
                }
            }
            else if (Text(p, "rowId") is { Length: > 0 } row)
            {
                lines.Add(("row", row));
            }

            if (connectorOperation == "rows_search")
            {
                lines.Add(("column", Name(Text(p, "searchColumn"))));
                lines.Add(("term", Text(p, "searchTerm")));
                if (Text(p, "options", "wildcard") == "false")
                {
                    lines.Add(("exact", "true"));
                }

                if (Bool(Find(p, "options"), "insensitive"))
                {
                    lines.Add(("ignore_case", "true"));
                }

                todo.Add("n8n's search spliced its term into the SQL with escapes SeaTable does not read - a term with a quote found nothing, one with a double quote failed; here the term is bound: check what follows did not count on that.");
            }

            if (connectorOperation is "row_create" or "row_update")
            {
                if (Text(p, "fieldsToSend") == "autoMapInputData")
                {
                    todo.Add("n8n sent each item's own fields as the row - here give them: 'fields = {{ record }}' in a For Each over the records, each a column of the table.");
                }
                else if (Find(p, "columnsUi") is { ValueKind: JsonValueKind.Object } columns && columns.TryGetProperty("columnValues", out var values) && values.ValueKind == JsonValueKind.Array)
                {
                    var fields = new JsonObject();
                    var expression = false;
                    foreach (var column in values.EnumerateArray())
                    {
                        var value = Text(column, "columnValue");
                        expression |= value.StartsWith('=');
                        fields[Name(Text(column, "columnName"))] = value.StartsWith('=') ? value[1..] : value;
                    }

                    lines.Add(("fields", (expression ? "=" : string.Empty) + fields.ToJsonString(ReadableJson)));
                }

                if (Bool(p, "bigdata"))
                {
                    todo.Add("n8n wrote the row to the base's big data storage - here it goes to the table: archive it in SeaTable if it belongs there.");
                }
            }

            if (connectorOperation == "base_collaborators" && Text(p, "searchString") is { Length: > 0 } search)
            {
                lines.Add(("search", search));
            }

            if (connectorOperation == "asset_link")
            {
                lines.Add(("path", Text(p, "assetPath")));
            }

            if (connectorOperation is "rows" or "rows_search" or "links" or "base_collaborators")
            {
                lines.Add(("max", Most(p, 50)));
            }

            if (connectorOperation == "asset_upload")
            {
                todo.Add("n8n uploaded a file to the row - the SeaTable connector uploads none: put the file in the base's assets and give its path, or keep n8n's step outside Stomme.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a SeaTable connection under Admin > Connections (SeaTable's address and the base's API token) and pick it here.");
        }

        private const string LdapConnection = "choose its connection - n8n's credentials stay in n8n: add an LDAP connection under Admin > Connections (the directory's address - ldap://dir.example.com:389, ldaps:// for TLS, StartTLS a setting - and its bind DN and password) and pick it here.";

        // n8n's LDAP node: each operation as the connector's - a search's base, its filter (n8n's custom one, or the one it built
        // from an object class, an attribute and the text searched, escaped as n8n escaped it), its attributes, scope and limit (its
        // page size the connection's, said); a compare's attribute and value; a create's attributes, a name given twice its values
        // (n8n kept the last); an update's values added, replaced and removed; a rename's new DN.
        private static void Ldap(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            if (operation != "search")
            {
                lines.Add(("dn", Text(p, "dn")));
            }

            switch (operation)
            {
                case "search":
                    {
                        lines.Add(("base", Text(p, "baseDN")));
                        var searchFor = Text(p, "searchFor");
                        var text = Text(p, "searchText");
                        var filter = searchFor == "custom"
                            ? Text(p, "customFilter") is { Length: > 0 } custom ? custom : "(objectclass=*)"
                            : $"(&{(searchFor.StartsWith('(') || searchFor.Length == 0 ? searchFor : $"(objectclass={searchFor})")}({Text(p, "attribute")}={(text.StartsWith('=') ? text : LdapFilterText(text))}))";
                        if (text.StartsWith('=') && searchFor != "custom")
                        {
                            filter = "=" + filter.Replace(text, Unmarked(text), StringComparison.Ordinal);
                            todo.Add("n8n escaped what the searched text's expression gave - here a value holding ( ) * or \\ changes the filter: keep it to plain text, or escape it.");
                        }

                        lines.Add(("filter", filter));
                        var options = Find(p, "options");
                        var attributes = Find(options, "attributes");
                        lines.Add(("attributes", attributes.ValueKind == JsonValueKind.Array ? string.Join(", ", attributes.EnumerateArray().Select(name => Text(name)).Where(name => name.Length > 0)) : Text(options, "attributes")));
                        lines.Add(("scope", Text(options, "scope") is "base" or "one" ? Text(options, "scope") : ""));
                        lines.Add(("max", Most(p, 50)));
                        if (Text(options, "pageSize") is { Length: > 0 } pageSize && pageSize != "1000")
                        {
                            todo.Add($"n8n paged its search {(pageSize == "0" ? "not at all" : "by " + pageSize)} - here a search's page size is its connection's (its Page size setting).");
                        }

                        break;
                    }

                case "compare":
                    lines.Add(("attribute", Text(p, "id")));
                    lines.Add(("value", Text(p, "value")));
                    break;
                case "create":
                    lines.Add(("attributes", LdapAttributes(Items(p, "attributes", "attribute"))));
                    break;
                case "update":
                    lines.Add(("add", LdapAttributes(Items(p, "attributes", "add"))));
                    lines.Add(("replace", LdapAttributes(Items(p, "attributes", "replace"))));
                    lines.Add(("remove", LdapAttributes(Items(p, "attributes", "delete"))));
                    break;
                case "rename":
                    lines.Add(("to", Text(p, "targetDn")));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation == "search" ? "n8n gave each entry as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(LdapConnection);
        }

        // n8n's attribute names and values as a JSON object: a name given once its value, several times a list of them - an
        // expression among them making the whole one.
        private static string LdapAttributes(IEnumerable<JsonElement> items)
        {
            var named = items.Where(item => Text(item, "id").Length > 0).GroupBy(item => Text(item, "id"), StringComparer.OrdinalIgnoreCase).ToList();
            string Value(JsonElement item) => JsonSerializer.Serialize(Unmarked(Text(item, "value")), ReadableJson);
            return named.Count == 0 ? "" : (named.Any(group => group.Any(item => Text(item, "value").StartsWith('='))) ? "=" : "") + "{" + string.Join(", ", named.Select(group =>
                JsonSerializer.Serialize(group.Key, ReadableJson) + ": " + (group.Count() == 1 ? Value(group.First()) : "[" + string.Join(", ", group.Select(Value)) + "]"))) + "}";
        }

        // The text an n8n LDAP search looks for, as n8n put it in its filter: a '*' a wildcard, an escaped \\ \* \( \) the
        // character itself, a bare ( or ) escaped - so no text breaks the filter around it.
        private static string LdapFilterText(string text)
        {
            var built = new StringBuilder();
            for (var i = 0; i < text.Length; i++)
            {
                if (text[i] == '\\' && i + 1 < text.Length && text[i + 1] is ('\\' or '*' or '(' or ')'))
                {
                    built.Append('\\').Append(((int)text[++i]).ToString("x2", CultureInfo.InvariantCulture));
                }
                else if (text[i] is '(' or ')')
                {
                    built.Append('\\').Append(((int)text[i]).ToString("x2", CultureInfo.InvariantCulture));
                }
                else
                {
                    built.Append(text[i]);
                }
            }

            return built.ToString();
        }

        private const string HomeAssistantConnection = "choose its connection - n8n's credentials stay in n8n: add a Home Assistant connection under Admin > Connections (its address - http://homeassistant.local:8123, n8n's host, port and SSL as one - and a long-lived access token, from your profile > Security) and pick it here.";

        // n8n's Home Assistant node: each resource and operation as the connector's - a list's limit; a service's domain, service
        // and attributes as its data; a state's entity, state and attributes; an event's type and attributes as its data; the
        // logbook's and history's start, end and entities; a template (over several lines in the step's Query box); a camera's
        // picture written into the site's pipeline folder.
        private static void HomeAssistant(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var additional = Find(p, "additionalFields");
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "services":
                case "states":
                case "events":
                case "history":
                    if (operation == "history")
                    {
                        lines.Add(("entities", Text(additional, "entityIds")));
                        lines.Add(("from", Text(additional, "startTime")));
                        lines.Add(("to", Text(additional, "endTime")));
                        lines.Add(("minimal", Bool(additional, "minimalResponse") ? "true" : ""));
                        lines.Add(("significant", Bool(additional, "significantChangesOnly") ? "true" : ""));
                    }

                    lines.Add(("max", Most(p, 50)));
                    break;
                case "call_service":
                    lines.Add(("domain", Text(p, "domain")));
                    lines.Add(("service", Text(p, "service")));
                    lines.Add(("data", JsonPairs(Items(p, "serviceAttributes", "attributes"), "name", "value")));
                    break;
                case "state":
                    lines.Add(("entity", Text(p, "entityId")));
                    break;
                case "set_state":
                    lines.Add(("entity", Text(p, "entityId")));
                    lines.Add(("state", Text(p, "state")));
                    lines.Add(("attributes", JsonPairs(Items(p, "stateAttributes", "attributes"), "name", "value")));
                    break;
                case "fire_event":
                    lines.Add(("event", Text(p, "eventType")));
                    lines.Add(("data", JsonPairs(Items(p, "eventAttributes", "attributes"), "name", "value")));
                    break;
                case "logbook":
                    lines.Add(("from", Text(additional, "startTime")));
                    lines.Add(("to", Text(additional, "endTime")));
                    lines.Add(("entity", Text(additional, "entityId")));
                    break;
                case "render_template":
                    {
                        var template = Text(p, "template");
                        if (template.Contains('\n') || template.Contains('\r'))
                        {
                            Set(step, "Query", template); // a template over several lines: the step's Query box
                        }
                        else
                        {
                            lines.Add(("template", template));
                        }

                        break;
                    }

                case "camera_snapshot":
                    lines.Add(("entity", Text(p, "cameraEntityId")));
                    lines.Add(("file", "homeassistant/"));
                    todo.Add($"n8n kept the picture in the item's binary '{(Text(p, "binaryPropertyName") is { Length: > 0 } property ? property : "data")}' - here it is written into the site's pipeline folder (homeassistant/, named after the camera), for the file steps to read.");
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "services" or "states" or "events" or "logbook" or "history" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(HomeAssistantConnection);
        }

        private const string AzureCosmosDbConnection = "choose its connection - n8n's credentials stay in n8n: add an Azure Cosmos DB connection under Admin > Connections (the account's address - https://{account}.documents.azure.com - its database as the connection's Database, and the account's key, from its Keys) and pick it here.";

        // n8n's Azure Cosmos DB node: each resource and operation as the connector's - a container by its id (n8n's list or by id
        // alike); a container's partition key paths, its indexing policy and throughput; an item by its id, its partition key; an
        // item's contents and an update's fields as one line of JSON; a query (over several lines in the step's Query box), n8n's
        // $1 kept for the connector to read as @Param1, its parameters by position; Get Many's limit and Simplify.
        private static void AzureCosmosDb(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var additional = Find(p, "additionalFields");
            var lines = new List<(string Name, string Value)>();
            if (operation != "containers")
            {
                lines.Add(("container", operation == "container_create" ? Text(p, "containerCreate") : Locator(p, "container")));
            }

            switch (operation)
            {
                case "container_create":
                    {
                        var key = Text(p, "partitionKey");
                        try
                        {
                            using var parsed = JsonDocument.Parse(key.Length == 0 ? "{}" : key);
                            if (parsed.RootElement.TryGetProperty("paths", out var paths) && paths.ValueKind == JsonValueKind.Array)
                            {
                                lines.Add(("partition_key", string.Join(",", paths.EnumerateArray().Select(path => Text(path)).Where(path => path.Length > 0))));
                            }
                        }
                        catch (JsonException)
                        {
                            todo.Add("n8n's partition key was not JSON - here the container is partitioned by /id: give its path (partition_key) where it is another.");
                        }

                        lines.Add(("throughput", Text(additional, "offerThroughput")));
                        lines.Add(("max_throughput", Text(additional, "maxThroughput")));
                        lines.Add(("indexing_policy", Text(additional, "indexingPolicy") is { Length: > 0 } policy ? OneLine(policy) : ""));
                        break;
                    }

                case "items":
                    lines.Add(("max", Most(p, 50)));
                    lines.Add(("simple", Text(p, "simple") == "false" ? "false" : ""));
                    break;
                case "item_get":
                case "item_delete":
                case "item_update":
                    lines.Add(("id", Locator(p, "item")));
                    lines.Add(("partition", Text(additional, "partitionKey")));
                    if (operation == "item_update")
                    {
                        lines.Add(("item", Text(p, "customProperties") is { Length: > 0 } fields ? OneLine(fields) : ""));
                    }

                    if (operation != "item_delete")
                    {
                        lines.Add(("simple", Text(p, "simple") == "false" ? "false" : ""));
                    }

                    break;
                case "item_create":
                    lines.Add(("item", Text(p, "customProperties") is { Length: > 0 } contents ? OneLine(contents) : ""));
                    break;
                case "query":
                    {
                        var sql = Text(p, "query");
                        if (sql.Contains('\n') || sql.Contains('\r'))
                        {
                            Set(step, "Query", sql); // a query over several lines: the step's Query box
                        }
                        else
                        {
                            lines.Add(("sql", sql));
                        }

                        // n8n's parameters by position, $1 the first: a comma list, or a JSON array of their values.
                        var options = Find(p, "options", "queryOptions");
                        var values = new List<string>();
                        if (Text(options, "queryParametersJson") is { Length: > 0 } json && !json.StartsWith('='))
                        {
                            try
                            {
                                using var parsed = JsonDocument.Parse(json);
                                values.AddRange(parsed.RootElement.ValueKind == JsonValueKind.Array ? parsed.RootElement.EnumerateArray().Select(value => value.GetRawText()) : Array.Empty<string>());
                            }
                            catch (JsonException)
                            {
                            }
                        }
                        else if (Text(options, "queryParameters") is { Length: > 0 } list && !list.StartsWith('='))
                        {
                            values.AddRange(list.Split(',', StringSplitOptions.TrimEntries).Select(value => JsonSerializer.Serialize(value, ReadableJson)));
                        }

                        if (Text(options, "queryParametersJson").StartsWith('=') || Text(options, "queryParameters").StartsWith('='))
                        {
                            todo.Add("n8n gave the query's parameters as an expression - here give them as a JSON object, {\"@Param1\": ...} (parameters).");
                        }

                        // Named as n8n names them: every @name in the query, in order, once its $1 is @Param1.
                        var names = Regex.Matches(Regex.Replace(sql, "\\$(\\d+)", "@Param$1"), "@\\w+").Select(match => match.Value).ToList();
                        if (values.Count > 0 && names.Count != values.Count)
                        {
                            todo.Add($"n8n's query names {names.Count} parameter{(names.Count == 1 ? "" : "s")} and gives {values.Count} value{(values.Count == 1 ? "" : "s")} - n8n refused it; here give each its value (parameters).");
                        }

                        lines.Add(("parameters", values.Count == 0 ? "" : "{" + string.Join(", ", names.Zip(values, (name, value) => $"{JsonSerializer.Serialize(name, ReadableJson)}: {value}")) + "}"));
                        lines.Add(("simple", Text(p, "simple") == "false" ? "false" : ""));
                        break;
                    }
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "containers" or "items" or "query" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(AzureCosmosDbConnection);
        }

        private const string GoogleFirestoreConnection = "choose its connection - n8n's credentials stay in n8n: add a Google Cloud Firestore connection under Admin > Connections (an OAuth client's id and secret and a refresh token granted the datastore scope, the project as its Project) and pick it here.";

        // n8n's Google Cloud Firestore node: each resource and operation as the connector's - a collection and a document's id; the
        // columns a create or an upsert takes from the item as fields reading it, an upsert's id from its update key; Get Many's
        // limit and Simplify; a query's JSON (over several lines in the step's Query box); the project and database n8n names on
        // each node the connection's own here, said.
        private static void GoogleFirestore(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            if (operation is not ("collections" or "query"))
            {
                lines.Add(("collection", Text(p, "collection")));
            }

            switch (operation)
            {
                case "collections":
                case "documents":
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "document_get":
                case "document_delete":
                    lines.Add(("id", Text(p, "documentId")));
                    break;
                case "document_create":
                case "document_upsert":
                    {
                        lines.Add(("id", operation == "document_create" ? Text(p, "documentId") : Text(p, "updateKey") is { Length: > 0 } key ? "={{ $json." + key + " }}" : ""));
                        var columns = Text(p, "columns").Split(',', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries);
                        if (columns.Length > 0)
                        {
                            lines.Add(("fields", "={" + string.Join(", ", columns.Select(column => JsonSerializer.Serialize(column, ReadableJson) + ": \"{{ $json." + column + " }}\"")) + "}"));
                            todo.Add("n8n took each column's value from the item, its type guessed - here each field reads the item's value as text: write a number, a boolean or a list without its quotes, {{ $json.total }}, where it is one.");
                        }

                        break;
                    }

                case "query":
                    {
                        var query = Text(p, "query");
                        if (query.Contains('\n') || query.Contains('\r'))
                        {
                            Set(step, "Query", query); // a query over several lines: the step's Query box
                        }
                        else
                        {
                            lines.Add(("structured_query", query));
                        }

                        if (Text(p, "queryParameters") is { Length: > 0 } parameters && parameters.Replace(" ", "") is not ("={{[]}}" or "[]"))
                        {
                            todo.Add("n8n filled the query's $1, $2 from its parameters - here write their values into the query itself.");
                        }

                        break;
                    }
            }

            if (operation is not ("collections" or "document_upsert" or "document_delete") && Text(p, "simple") == "false")
            {
                lines.Add(("simple", "false"));
            }

            if (Text(p, "projectId") is { Length: > 0 } project && !project.StartsWith('='))
            {
                todo.Add($"n8n named the project '{project}'{(Text(p, "database") is { Length: > 0 } database && database != "(default)" ? $" and its database '{database}'" : "")} on the node - here they are the connection's (its Project and Database).");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "collections" or "documents" or "query" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(GoogleFirestoreConnection);
        }

        // n8n's Google Chat node beyond a text message: a message's JSON with its request id, a message read, edited (its text or
        // its fields as JSON) and deleted by its resource name, spaces and a space's members with their limit.
        private static void GoogleChat(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "message_create":
                    lines.Add(("space", Text(p, "spaceId")));
                    lines.Add(("json", Text(p, "messageJson") is { Length: > 0 } json ? OneLine(json) : ""));
                    lines.Add(("request_id", Text(p, "additionalFields", "requestId")));
                    break;
                case "message_get":
                case "message_delete":
                    lines.Add(("message", Text(p, "messageId")));
                    break;
                case "message_update":
                    lines.Add(("message", Text(p, "messageId")));
                    if (Bool(p, "jsonParameters"))
                    {
                        lines.Add(("json", Text(p, "updateFieldsJson") is { Length: > 0 } fields ? OneLine(fields) : ""));
                    }
                    else
                    {
                        var text = Text(p, "updateFieldsUi", "text");
                        if (text.Contains('\n') || text.Contains('\r'))
                        {
                            Set(step, "Query", text); // a text over several lines: the step's Query box
                        }
                        else
                        {
                            lines.Add(("text", text));
                        }
                    }

                    break;
                case "space_get":
                    lines.Add(("space", Text(p, "spaceId")));
                    break;
                case "member_get":
                    lines.Add(("member", Text(p, "memberId")));
                    break;
                case "members":
                    lines.Add(("space", Text(p, "spaceId")));
                    lines.Add(("max", Most(p, 100)));
                    break;
                default: // spaces
                    lines.Add(("max", Most(p, 100)));
                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "spaces" or "members" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(ChatCredential("Google Chat", "an OAuth client's id and secret and a refresh token granted the chat.messages, chat.spaces.readonly and chat.memberships.readonly scopes"));
        }

        private const string HaloPsaConnection = "choose its connection - n8n's credentials stay in n8n: add a HaloPSA connection under Admin > Connections (Halo's address - https://{tenant}.halopsa.com - its token endpoint, /auth/token there, and an API application's client id and secret) and pick it here.";

        // n8n's HaloPSA resources as the connector names them, with the parameter n8n names a record's id by.
        private static readonly Dictionary<string, (string Resource, string Id)> HaloPsaResources = new(StringComparer.Ordinal)
        {
            ["client"] = ("clients", "clientId"), ["site"] = ("sites", "siteId"), ["ticket"] = ("tickets", "ticketId"), ["user"] = ("users", "userId"),
        };

        // A Create's own parameters - n8n's names and Halo's.
        private static readonly Dictionary<string, (string N8n, string Halo)[]> HaloPsaCreates = new(StringComparer.Ordinal)
        {
            ["client"] = new[] { ("clientName", "name") },
            ["site"] = new[] { ("siteName", "name"), ("clientId", "client_id") },
            ["ticket"] = new[] { ("ticketType", "tickettype_id"), ("summary", "summary"), ("details", "details") },
            ["user"] = new[] { ("userName", "name"), ("siteId", "site_id") },
        };

        // n8n's HaloPSA node: each resource as the connector's, its record's id; Get Many's search and active status and n8n's
        // limit of 50 (its Simplify said - here a record is all its fields); a Create's own parameters by Halo's names and its
        // additional and update fields - an id that is a number sent as one, as Halo keeps it, an expression among them making the
        // line one, a user's password left out and said (a password is never a step's value). n8n's default for a ticket is its
        // Delete: imported as it, and said.
        private static void HaloPsa(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var resource = Text(p, "resource") is { Length: > 0 } named ? named : "client";
            var (table, idName) = HaloPsaResources.TryGetValue(resource, out var known) ? known : ("", "");
            var lines = new List<(string Name, string Value)> { ("resource", table) };
            if (operation is "record" or "update_record" or "delete_record")
            {
                lines.Add(("id", Text(p, idName)));
            }

            if (operation == "delete_record" && Text(p, "operation") == "")
            {
                todo.Add("n8n's HaloPSA node deletes a ticket when no operation is chosen - this step deletes it too: make sure that is meant.");
            }

            if (operation == "records")
            {
                lines.Add(("search", Text(p, "filters", "search")));
                lines.Add(("status", Text(p, "filters", "activeStatus") is ("active" or "inactive") and var status ? status : ""));
                lines.Add(("max", Most(p, 50)));
            }

            if (operation is "records" or "record" && Text(p, "simplify") != "false")
            {
                todo.Add("n8n gave a few of each record's fields (its Simplify) - here a record is all its fields.");
            }

            if (operation is "create_record" or "update_record")
            {
                var expression = false;
                var pairs = new List<string>();
                void Add(string name, JsonElement value)
                {
                    var text = value.ValueKind == JsonValueKind.String ? value.GetString() ?? "" : null;
                    expression |= text?.StartsWith('=') ?? false;
                    pairs.Add(JsonSerializer.Serialize(name, ReadableJson) + ": " + (text is null ? value.GetRawText()
                        : name.EndsWith("_id", StringComparison.Ordinal) && text.Length is > 0 and <= 10 && text.All(char.IsAsciiDigit) ? text
                        : JsonSerializer.Serialize(Unmarked(text), ReadableJson)));
                }

                if (operation == "create_record")
                {
                    foreach (var (n8n, halo) in HaloPsaCreates.TryGetValue(resource, out var own) ? own : Array.Empty<(string, string)>())
                    {
                        if (Find(p, n8n) is { ValueKind: not JsonValueKind.Undefined } given)
                        {
                            Add(halo, given);
                        }
                    }
                }

                var more = Find(p, operation == "create_record" ? "additionalFields" : "updateFields");
                if (more.ValueKind == JsonValueKind.Object)
                {
                    foreach (var field in more.EnumerateObject())
                    {
                        if (field.Name == "password")
                        {
                            todo.Add("n8n set the user's password - here a password is never a step's value: set it in HaloPSA.");
                        }
                        else
                        {
                            Add(field.Name, field.Value);
                        }
                    }
                }

                lines.Add(("values", pairs.Count == 0 ? "" : (expression ? "=" : "") + "{" + string.Join(", ", pairs) + "}"));
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation == "records" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(HaloPsaConnection);
        }

        private const string SnowflakeConnection = "choose its connection - n8n's credentials stay in n8n: add a Snowflake connection under Admin > Connections (the account's address - https://{account}.snowflakecomputing.com - a programmatic access token, and the warehouse, database, schema and role n8n's credential named) and pick it here.";

        // n8n's Snowflake node: Execute Query's SQL as the step's Query - a value n8n spliced in staying an expression the editor
        // warns of - its Query Parameters as the values of its ? marks ('@1 = value', bound) and every row it returns; Insert's and
        // Update's table, columns and Update's key column, the rows n8n read from each item said (here a step's rows are given).
        // n8n signed in with a user's password; here a programmatic access token: said.
        private static void Snowflake(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            if (operation == "query")
            {
                var sql = Text(p, "query");
                Set(step, "Query", sql.StartsWith('=') || !sql.Contains("{{", StringComparison.Ordinal) ? sql : "=" + sql);
                var replacement = Text(p, "options", "queryReplacement");
                if (replacement.StartsWith('='))
                {
                    todo.Add("n8n bound the query's ? marks to values from each item - here give each as '@1 = value', '@2 = value' parameters.");
                }
                else if (replacement.Length > 0)
                {
                    lines.AddRange(replacement.Split(',').Select((value, index) => ("@" + (index + 1).ToString(CultureInfo.InvariantCulture), value.Trim())));
                }

                lines.Add(("max", EveryRecord));
                todo.Add("n8n gave each row as an item - here they are the step's result, a list of records.");
            }
            else
            {
                var columns = string.Join(", ", Text(p, "columns").Split(',').Select(column => column.Trim()).Where(column => column.Length > 0));
                lines.Add(("table", Text(p, "table")));
                if (operation == "update_rows")
                {
                    lines.Add(("key", Text(p, "updateKey") is { Length: > 0 } key ? key : "id"));
                }

                lines.Add(("columns", columns));
                var what = columns.Length > 0 ? $"the columns {columns} of each item" : "each item";
                todo.Add($"n8n wrote {what} that reached it as a row - here give the rows, a JSON object by column or a list of them, in a For Each when they are the records of an earlier step.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add("n8n signed in with a user's password - here the connection holds a programmatic access token.");
            todo.Add(SnowflakeConnection);
        }

        private const string HelpScoutConnection = "choose its connection - n8n's credentials stay in n8n: add a Help Scout connection under Admin > Connections (an app's ID and secret from Your Profile > My Apps) and pick it here.";

        // n8n's Help Scout resources as the connector names them, with the parameter n8n names a record's id by.
        private static readonly Dictionary<string, (string Resource, string Id)> HelpScoutResources = new(StringComparer.Ordinal)
        {
            ["conversation"] = ("conversations", "conversationId"), ["customer"] = ("customers", "customerId"), ["mailbox"] = ("mailboxes", "mailboxId"), ["thread"] = ("threads", "conversationId"),
        };

        // The fields Help Scout keeps as numbers - ids - which n8n's export may hold as text.
        private static readonly HashSet<string> HelpScoutNumbers = new(StringComparer.Ordinal) { "mailboxId", "assignTo", "user", "id", "mailbox" };

        // n8n's Help Scout node: each resource as the connector's, a record's id; Get Many's options as Help Scout's query
        // parameters (its tags as one, joined) and n8n's limit of 50, the customer properties whole; a conversation's Create - its
        // inbox, status, subject, type, its customer by id or e-mail, its threads with that customer on a customer's thread, its
        // additional fields - a customer's - its fields, e-mails, phones, chats, social profiles, websites and address as Help
        // Scout's lists - and a thread's - its type, text and customer - as the values, an id given as text a number, an
        // expression among them making the line one; a customer's Update replacing only the fields given (n8n's PUT overwrote the
        // customer whole: said); a thread's attachments said.
        private static void HelpScout(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var resource = Text(p, "resource") is { Length: > 0 } named ? named : "conversation";
            var properties = resource == "customer" && Text(p, "operation") == "properties";
            var (table, idName) = HelpScoutResources.TryGetValue(resource, out var known) ? known : ("", "");
            var lines = new List<(string Name, string Value)> { ("resource", properties ? "customer_properties" : table) };
            if (resource == "thread")
            {
                lines.Add(("conversation", Text(p, "conversationId")));
            }
            else if (operation is "record" or "update_record" or "delete_record")
            {
                lines.Add(("id", Text(p, idName)));
            }

            var expression = false;
            string Json(JsonElement value, string name)
            {
                if (value.ValueKind != JsonValueKind.String)
                {
                    return value.GetRawText();
                }

                var text = value.GetString() ?? "";
                expression |= text.StartsWith('=');
                return HelpScoutNumbers.Contains(name) && text.Length is > 0 and <= 12 && text.All(char.IsAsciiDigit) ? text : JsonSerializer.Serialize(Unmarked(text), ReadableJson);
            }

            static string Object(IEnumerable<(string Name, string Json)> pairs) => "{" + string.Join(", ", pairs.Select(pair => JsonSerializer.Serialize(pair.Name, ReadableJson) + ": " + pair.Json)) + "}";
            if (operation == "records")
            {
                var options = Find(p, "options");
                var filters = options.ValueKind == JsonValueKind.Object
                    ? options.EnumerateObject().Where(option => option.Value.ValueKind != JsonValueKind.Null && !(option.Value.ValueKind == JsonValueKind.String && option.Value.GetString() == "")).Select(option => option.Name == "tags" && option.Value.ValueKind == JsonValueKind.Array
                        ? ("tag", JsonSerializer.Serialize(string.Join(",", option.Value.EnumerateArray().Select(tag => Text(tag))), ReadableJson))
                        : (option.Name, Json(option.Value, option.Name))).ToList()
                    : new List<(string, string)>();
                lines.Add(("filters", filters.Count == 0 ? "" : (expression ? "=" : "") + Object(filters)));
                lines.Add(("max", properties ? EveryRecord : Most(p, 50)));
            }
            else if (operation is "create_record" or "update_record")
            {
                var pairs = new List<(string Name, string Json)>();
                var more = Find(p, operation == "update_record" ? "updateFields" : "additionalFields");
                var customer = more.ValueKind == JsonValueKind.Object && more.TryGetProperty("customerId", out var customerId) && Text(customerId) is { Length: > 0 } and not "0" ? "{\"id\": " + Json(customerId, "id") + "}"
                    : more.ValueKind == JsonValueKind.Object && more.TryGetProperty("customerEmail", out var customerEmail) && Text(customerEmail).Length > 0 ? "{\"email\": " + Json(customerEmail, "email") + "}"
                    : null;
                if (resource == "conversation")
                {
                    pairs.AddRange(new[] { "subject", "mailboxId", "type", "status" }.Where(name => Find(p, name).ValueKind != JsonValueKind.Undefined).Select(name => (name, Json(Find(p, name), name))));
                    if (customer is not null)
                    {
                        pairs.Add(("customer", customer));
                    }

                    var threads = Items(p, "threadsUi", "threadsValues").Select(thread => Object(new[] { ("type", Json(Find(thread, "type"), "type")), ("text", Json(Find(thread, "text"), "text")) }
                        .Concat(Text(thread, "type") == "customer" && customer is not null ? new[] { ("customer", customer) } : Array.Empty<(string, string)>())
                        .Concat(new[] { "cc", "bcc" }.Where(list => Find(thread, list) is { ValueKind: JsonValueKind.Array } items && items.GetArrayLength() > 0).Select(list => (list, Json(Find(thread, list), list)))))).ToList();
                    if (threads.Count > 0)
                    {
                        pairs.Add(("threads", "[" + string.Join(", ", threads) + "]"));
                    }
                }
                else if (resource == "thread")
                {
                    pairs.Add(("type", Json(Find(p, "type"), "type")));
                    pairs.Add(("text", Json(Find(p, "text"), "text")));
                    if (customer is not null)
                    {
                        pairs.Add(("customer", customer));
                    }

                    if (Find(p, "attachmentsUi").ValueKind == JsonValueKind.Object)
                    {
                        todo.Add("n8n attached files to the thread - here a thread is its text: attach them in Help Scout, or give them as 'attachments' among the values ([{\"fileName\": ..., \"mimeType\": ..., \"data\": base64}]).");
                    }
                }
                else if (resource == "customer" && operation == "create_record")
                {
                    foreach (var (collection, list, name, typed) in new[] { ("emailsUi", "emailsValues", "emails", true), ("phonesUi", "phonesValues", "phones", true), ("chatsUi", "chatsValues", "chats", true), ("socialProfilesUi", "socialProfilesValues", "socialProfiles", true), ("websitesUi", "websitesValues", "websites", false) })
                    {
                        var items = Items(p, collection, list).Select(item => Object((typed ? new[] { ("type", Json(Find(item, "type"), "type")) } : Array.Empty<(string, string)>()).Append(("value", Json(Find(item, "value"), "value"))))).ToList();
                        if (items.Count > 0)
                        {
                            pairs.Add((name, "[" + string.Join(", ", items) + "]"));
                        }
                    }

                    if (Find(p, "addressUi", "addressValue") is { ValueKind: JsonValueKind.Object } address)
                    {
                        var streets = new[] { "line1", "line2" }.Where(line => Text(address, line).Length > 0).Select(line => Json(Find(address, line), line)).ToList();
                        pairs.Add(("address", Object((streets.Count > 0 ? new[] { ("lines", "[" + string.Join(", ", streets) + "]") } : Array.Empty<(string, string)>())
                            .Concat(new[] { "city", "state", "country", "postalCode" }.Where(part => Text(address, part).Length > 0).Select(part => (part, Json(Find(address, part), part)))))));
                    }
                }

                if (more.ValueKind == JsonValueKind.Object)
                {
                    foreach (var field in more.EnumerateObject().Where(field => field.Name is not ("customerEmail" or "customerId")))
                    {
                        pairs.Add((field.Name, field.Name == "age" && field.Value.ValueKind == JsonValueKind.Number ? JsonSerializer.Serialize(field.Value.GetRawText(), ReadableJson) : Json(field.Value, field.Name)));
                    }
                }

                lines.Add(("values", pairs.Count == 0 ? "" : (expression ? "=" : "") + Object(pairs)));
                if (operation == "update_record")
                {
                    todo.Add("n8n wrote the customer whole (Help Scout's PUT: a field not given emptied) - here only the fields given change, the rest kept.");
                }
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation == "records" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(HelpScoutConnection);
        }

        private const string AwsS3Connection = "choose its connection - n8n's credentials stay in n8n: add an Amazon S3 connection under Admin > Connections (an access key and its secret and the region - for MinIO, R2 or another S3-compatible store its address too, buckets by path) and pick it here.";

        // n8n's canned ACLs and storage classes as S3 names them.
        private static readonly Dictionary<string, string> S3Acls = new(StringComparer.Ordinal)
        {
            ["private"] = "private", ["publicRead"] = "public-read", ["publicReadWrite"] = "public-read-write", ["authenticatedRead"] = "authenticated-read",
            ["awsExecRead"] = "aws-exec-read", ["bucketOwnerRead"] = "bucket-owner-read", ["bucketOwnerFullControl"] = "bucket-owner-full-control",
        };

        private static readonly Dictionary<string, string> S3StorageClasses = new(StringComparer.Ordinal)
        {
            ["standard"] = "STANDARD", ["standardIA"] = "STANDARD_IA", ["onezoneIA"] = "ONEZONE_IA", ["intelligentTiering"] = "INTELLIGENT_TIERING",
            ["glacier"] = "GLACIER", ["deepArchive"] = "DEEP_ARCHIVE", ["reducedRedundancy"] = "REDUCED_REDUNDANCY",
        };

        // n8n's AWS S3 and S3 nodes: each resource and operation as the connector's; a bucket's name, a file's key and a folder's
        // path (under its parent folder); a download written into the site's pipeline folder at the object's key and an upload
        // read from it by its name - n8n's binary property, said - or its text; a copy's /bucket/key paths apart; a search's prefix,
        // delimiter and start key, a file listing's folder, n8n's limit of 100; its ACL and storage class as S3's; what has no
        // parameter here - tags, encryption, grants, a version, object lock, requester pays - said.
        private static void AwsS3(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var resource = Text(p, "resource") is { Length: > 0 } named ? named : "file";
            var more = Find(p, "additionalFields");
            var options = Find(p, "options");
            var lines = new List<(string Name, string Value)>();
            static string Under(string folder, string name) =>
                folder.Length == 0 ? name : (folder.StartsWith('=') || name.StartsWith('=') ? "=" : "") + Unmarked(folder).TrimEnd('/') + "/" + Unmarked(name);
            void Said(JsonElement fields, params (string Field, string What)[] unsupported)
            {
                foreach (var (field, what) in unsupported)
                {
                    if (Text(fields, field) is { Length: > 0 } and not "false")
                    {
                        todo.Add(what);
                    }
                }
            }

            switch (operation)
            {
                case "buckets":
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "create_bucket":
                case "delete_bucket":
                    lines.Add(("bucket", Text(p, "name")));
                    if (Text(more, "region") is { Length: > 0 } region)
                    {
                        todo.Add($"it made the bucket in {Unmarked(region)} - here a bucket is made in the connection's region.");
                    }

                    Said(more, ("acl", "it set the bucket's access as it made it - set it in S3."), ("bucketObjectLockEnabled", "it turned object lock on as it made the bucket - turn it on in S3."),
                        ("grantFullControl", "it granted accounts access to the bucket - grant it in S3."), ("grantRead", "it granted accounts access to the bucket - grant it in S3."), ("grantWrite", "it granted accounts access to the bucket - grant it in S3."));
                    break;
                case "objects":
                    lines.Add(("bucket", Text(p, "bucketName")));
                    if (resource == "bucket")
                    {
                        lines.Add(("prefix", Text(more, "prefix")));
                        lines.Add(("delimiter", Text(more, "delimiter")));
                        lines.Add(("start_after", Text(more, "startAfter")));
                        Said(more, ("fetchOwner", "it read each object's owner - here an object's owner is not read."), ("requesterPays", "it paid as the requester - here the bucket's owner pays."));
                    }
                    else
                    {
                        lines.Add(("prefix", Text(options, "folderKey") is { Length: > 0 } folder ? (folder.StartsWith('=') ? folder : folder.TrimEnd('/') + "/") : ""));
                        todo.Add("n8n left its folders' own markers (keys ending with /) out - here they are among the records.");
                    }

                    lines.Add(("max", Most(p, 100)));
                    break;
                case "folders":
                    lines.Add(("bucket", Text(p, "bucketName")));
                    lines.Add(("folder", Text(options, "folderKey")));
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "create_folder":
                    lines.Add(("bucket", Text(p, "bucketName")));
                    lines.Add(("folder", Under(Text(more, "parentFolderKey"), Text(p, "folderName"))));
                    Said(more, ("storageClass", "it gave the folder a storage class - a folder here takes the bucket's."), ("requesterPays", "it paid as the requester - here the bucket's owner pays."));
                    break;
                case "delete_folder":
                    lines.Add(("bucket", Text(p, "bucketName")));
                    lines.Add(("folder", Text(p, "folderKey")));
                    break;
                case "download":
                    lines.Add(("bucket", Text(p, "bucketName")));
                    lines.Add(("key", Text(p, "fileKey")));
                    lines.Add(("file", Text(p, "fileKey")));
                    todo.Add($"n8n kept the file in the item's binary '{(Text(p, "binaryPropertyName") is { Length: > 0 } property ? property : "data")}' - here it is written into the site's pipeline folder at its key, for the file steps to read.");
                    break;
                case "upload":
                    lines.Add(("bucket", Text(p, "bucketName")));
                    lines.Add(("key", Under(Text(more, "parentFolderKey"), Text(p, "fileName"))));
                    if (Text(p, "binaryData") != "false")
                    {
                        lines.Add(("file", Text(p, "fileName")));
                        todo.Add($"n8n sent the item's binary '{(Text(p, "binaryPropertyName") is { Length: > 0 } binary ? binary : "data")}' - here the file is read from the site's pipeline folder: 'file =' is its name, as a guess.");
                    }
                    else
                    {
                        // A parameter is one line: text over several is a file's.
                        var content = Text(p, "fileContent");
                        if (content.Contains('\n') || content.Contains('\r'))
                        {
                            todo.Add("its text runs over several lines - here write it to a file with Write text file and give that file.");
                        }
                        else
                        {
                            lines.Add(("text", content));
                        }
                    }

                    if (Text(more, "acl") is { Length: > 0 } acl)
                    {
                        lines.Add(("acl", S3Acls.TryGetValue(acl, out var canned) ? canned : acl));
                    }

                    if (Text(more, "storageClass") is { Length: > 0 } storage)
                    {
                        lines.Add(("storage_class", S3StorageClasses.TryGetValue(storage, out var known) ? known : storage));
                    }

                    if (Items(p, "tagsUi", "tagsValues").Any())
                    {
                        todo.Add("it tagged the object - here set its tags in S3.");
                    }

                    Said(more, ("serverSideEncryption", "it chose the object's encryption - here it takes the bucket's."), ("lockMode", "it locked the object - lock it in S3."), ("lockLegalHold", "it held the object under legal hold - hold it in S3."),
                        ("grantFullControl", "it granted accounts access to the object - grant it in S3."), ("grantRead", "it granted accounts access to the object - grant it in S3."), ("requesterPays", "it paid as the requester - here the bucket's owner pays."));
                    break;
                case "copy":
                    {
                        var destination = Text(p, "destinationPath");
                        var trimmed = destination.TrimStart('/');
                        if (destination.StartsWith('='))
                        {
                            todo.Add($"its destination is an expression ({Unmarked(destination)}) - here give the copy's bucket and key apart.");
                        }
                        else if (trimmed.IndexOf('/') is var slash and > 0)
                        {
                            lines.Add(("bucket", trimmed[..slash]));
                            lines.Add(("key", trimmed[(slash + 1)..]));
                        }

                        var from = Text(p, "sourcePath");
                        lines.Add(("source", from.StartsWith('=') ? from : from.TrimStart('/')));
                        if (more.ValueKind == JsonValueKind.Object && more.EnumerateObject().Any())
                        {
                            todo.Add("it set the copy's access, class, metadata or tags - here a copy keeps the source's.");
                        }

                        break;
                    }

                case "delete":
                    lines.Add(("bucket", Text(p, "bucketName")));
                    lines.Add(("key", Text(p, "fileKey")));
                    if (Text(options, "versionId").Length > 0)
                    {
                        todo.Add("it deleted one version of the object - here the object's current version is deleted.");
                    }

                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "buckets" or "objects" or "folders" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(AwsS3Connection);
        }

        private const string GoogleDriveConnection = "choose its connection - n8n's credentials stay in n8n: add a Google Drive connection under Admin > Connections (an OAuth client's id and secret and a refresh token granted the drive scope) and pick it here.";

        // n8n's Google Drive node: each resource and operation as the connector's; a file, a folder and a shared drive by their
        // resource locators (My Drive and the root folder, n8n's defaults, left out); a search's name or query and its filter (a
        // folder, a drive, files or folders, types, the trash) and n8n's limit of 50; a download into the site's pipeline folder -
        // its own name in downloads/ unless n8n named it - converted as n8n's options say; an upload from the folder by its name
        // (n8n's binary property said) or a text, made a Google Doc when n8n's option asks; properties as JSON; a copy into another
        // folder; a delete to the trash or for good; a share's permission and options; a folder's and a shared drive's name; what
        // has no parameter here said.
        private static void GoogleDrive(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var n8n = Text(p, "operation");
            var resource = Text(p, "resource") is { Length: > 0 } named ? named : "file";
            var options = Find(p, "options");
            var lines = new List<(string Name, string Value)>();
            string Folder(JsonElement at) => Locator(at, "folderId") is var folder && folder != "root" ? folder : "";
            string Drive(JsonElement at) => Locator(at, "driveId") is var drive && drive != "My Drive" ? drive : "";
            void Properties()
            {
                foreach (var (collection, list, name) in new[] { ("propertiesUi", "propertyValues", "properties"), ("appPropertiesUi", "appPropertyValues", "app_properties") })
                {
                    var pairs = Items(options, collection, list).Where(pair => Text(pair, "key").Length > 0).ToList();
                    if (pairs.Count > 0)
                    {
                        var json = "{" + string.Join(", ", pairs.Select(pair => JsonSerializer.Serialize(Text(pair, "key"), ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(Text(pair, "value")), ReadableJson))) + "}";
                        lines.Add((name, (pairs.Any(pair => Text(pair, "value").StartsWith('=')) ? "=" : "") + json));
                    }
                }

                foreach (var (option, what) in new[] { ("keepRevisionForever", "it kept the revision for ever"), ("ocrLanguage", "it named the OCR language"), ("useContentAsIndexableText", "it made the content its indexable text") })
                {
                    if (Text(options, option) is { Length: > 0 } and not "false")
                    {
                        todo.Add(what + " - here Drive's default holds.");
                    }
                }
            }

            switch (operation)
            {
                case "search":
                    {
                        var filter = Find(p, "filter");
                        lines.Add((Text(p, "searchMethod") == "query" ? "query" : "name", Text(p, "queryString")));
                        lines.Add(("folder", Folder(filter)));
                        lines.Add(("drive", Drive(filter)));
                        lines.Add(("what", Text(filter, "whatToSearch") is { Length: > 0 } what and not "all" ? what : ""));
                        var types = filter.ValueKind == JsonValueKind.Object && filter.TryGetProperty("fileTypes", out var listed) && listed.ValueKind == JsonValueKind.Array
                            ? listed.EnumerateArray().Select(type => Text(type)).Where(type => type.Length > 0).ToList()
                            : new List<string>();
                        lines.Add(("types", types.Contains("*") ? "" : string.Join(", ", types)));
                        lines.Add(("trashed", Bool(filter, "includeTrashed") ? "true" : ""));
                        lines.Add(("max", Most(p, 50)));
                        if (options.ValueKind == JsonValueKind.Object && options.TryGetProperty("fields", out var fields) && fields.ValueKind == JsonValueKind.Array && fields.GetArrayLength() > 0)
                        {
                            todo.Add("it chose the fields read - here a file's usual fields are read.");
                        }

                        break;
                    }

                case "download":
                    {
                        lines.Add(("file_id", Locator(p, "fileId")));
                        lines.Add(("file", Text(options, "fileName") is { Length: > 0 } fileName ? fileName : "downloads/"));
                        var conversion = Find(options, "googleFileConversion", "conversion");
                        foreach (var (option, parameter) in new[] { ("docsToFormat", "docs_as"), ("sheetsToFormat", "sheets_as"), ("slidesToFormat", "slides_as"), ("drawingsToFormat", "drawings_as") })
                        {
                            lines.Add((parameter, Text(conversion, option)));
                        }

                        todo.Add($"n8n kept the file in the item's binary '{(Text(options, "binaryPropertyName") is { Length: > 0 } property ? property : "data")}' - here it is written into the site's pipeline folder ({(Text(options, "fileName") is { Length: > 0 } given ? given : "downloads/, under its own name")}), for the file steps to read.");
                        break;
                    }

                case "upload":
                    if (n8n == "createFromText")
                    {
                        lines.Add(("name", Text(p, "name") is { Length: > 0 } title ? title : "Untitled"));
                        var content = Text(p, "content");
                        if (content.Contains('\n') || content.Contains('\r'))
                        {
                            todo.Add("its text runs over several lines - here write it to a file with Write text file and give that file.");
                        }
                        else
                        {
                            lines.Add(("text", content));
                        }

                        lines.Add(("convert", Bool(options, "convertToGoogleDocument") ? "true" : ""));
                    }
                    else
                    {
                        lines.Add(("name", Text(p, "name")));
                        lines.Add(("file", Text(p, "name")));
                        todo.Add($"n8n sent the item's binary '{(Text(p, "inputDataFieldName") is { Length: > 0 } binary ? binary : "data")}' - here the file is read from the site's pipeline folder: 'file =' is {(Text(p, "name").Length > 0 ? "its name, as a guess" : "to be named")}.");
                    }

                    lines.Add(("folder", Folder(p)));
                    lines.Add(("drive", Drive(p)));
                    Properties();
                    break;
                case "update":
                    lines.Add(("file_id", Locator(p, "fileId")));
                    lines.Add(("name", Text(p, "newUpdatedFileName")));
                    if (Bool(p, "changeFileContent"))
                    {
                        todo.Add($"n8n sent the item's binary '{(Text(p, "inputDataFieldName") is { Length: > 0 } binary ? binary : "data")}' as the new content - here give its file in the site's pipeline folder ('file =') or text.");
                    }

                    if (Bool(options, "trashed"))
                    {
                        todo.Add("it moved the file to the trash - here Delete does, to the trash by default.");
                    }

                    Properties();
                    break;
                case "copy":
                    lines.Add(("file_id", Locator(p, "fileId")));
                    lines.Add(("name", Text(p, "name")));
                    if (Text(p, "sameFolder") == "false")
                    {
                        lines.Add(("folder", Folder(p) is { Length: > 0 } to ? to : "root"));
                        lines.Add(("drive", Drive(p)));
                    }

                    lines.Add(("description", Text(options, "description")));
                    if (Bool(options, "copyRequiresWriterPermission"))
                    {
                        todo.Add("it kept readers of the copy from copying it - set that in Drive.");
                    }

                    break;
                case "move":
                    lines.Add(("file_id", Locator(p, "fileId")));
                    lines.Add(("folder", Folder(p) is { Length: > 0 } into ? into : "root"));
                    lines.Add(("drive", Drive(p)));
                    break;
                case "delete":
                    lines.Add(("file_id", Locator(p, resource == "folder" ? "folderNoRootId" : "fileId")));
                    lines.Add(("permanently", Bool(options, "deletePermanently") ? "true" : ""));
                    break;
                case "share":
                    {
                        var permission = Find(p, "permissionsUi", "permissionsValues");
                        lines.Add(("file_id", Locator(p, resource == "folder" ? "folderNoRootId" : "fileId")));
                        lines.Add(("role", Text(permission, "role")));
                        lines.Add(("type", Text(permission, "type")));
                        lines.Add(("email", Text(permission, "emailAddress")));
                        lines.Add(("domain", Text(permission, "domain")));
                        lines.Add(("discoverable", Bool(permission, "allowFileDiscovery") ? "true" : ""));
                        lines.Add(("notify", Bool(options, "sendNotificationEmail") ? "true" : ""));
                        lines.Add(("message", Text(options, "emailMessage")));
                        lines.Add(("transfer_ownership", Bool(options, "transferOwnership") ? "true" : ""));
                        lines.Add(("domain_admin", Bool(options, "useDomainAdminAccess") ? "true" : ""));
                        if (Bool(options, "moveToNewOwnersRoot"))
                        {
                            todo.Add("it moved the file to its new owner's root - here it stays where it is.");
                        }

                        break;
                    }

                case "create_folder":
                    lines.Add(("name", Text(p, "name")));
                    lines.Add(("folder", Folder(p)));
                    lines.Add(("drive", Drive(p)));
                    if (Text(options, "folderColorRgb").Length > 0)
                    {
                        todo.Add("it coloured the folder - colour it in Drive.");
                    }

                    break;
                case "drives":
                    lines.Add(("query", Text(options, "q")));
                    lines.Add(("domain_admin", Bool(options, "useDomainAdminAccess") ? "true" : ""));
                    lines.Add(("max", Most(p, 100)));
                    break;
                case "create_drive":
                    lines.Add(("name", Text(p, "name")));
                    if (options.ValueKind == JsonValueKind.Object && options.EnumerateObject().Any())
                    {
                        todo.Add("it set the shared drive's colour, restrictions or capabilities - set them in Drive.");
                    }

                    break;
                case "get_drive":
                case "delete_drive":
                    lines.Add(("drive", Locator(p, "driveId")));
                    break;
                case "update_drive":
                    lines.Add(("drive", Locator(p, "driveId")));
                    lines.Add(("name", Text(options, "name")));
                    if (Text(options, "name").Length == 0)
                    {
                        todo.Add("it changed no name - here a shared drive's update is its new name: give it.");
                    }

                    if (Text(options, "colorRgb").Length > 0 || Find(options, "restrictions").ValueKind == JsonValueKind.Object)
                    {
                        todo.Add("it set the shared drive's colour or restrictions - set them in Drive.");
                    }

                    break;
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "search" or "drives" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(GoogleDriveConnection);
        }

        private const string GristConnection = "choose its connection - n8n's credentials stay in n8n: add a Grist connection under Admin > Connections (its address and an API key) and pick it here.";

        private static readonly Regex PlainNumber = new("^-?[0-9]+(\\.[0-9]+)?$", RegexOptions.CultureInvariant);

        // n8n's Grist node: its document and table; its Get Many Rows' filter (a column and a value each - a value that reads as a
        // number sent as one, as n8n does, and true or false as a flag, which n8n sends as text a Toggle column never equals - two
        // for one column both allowed), sort and limit; the columns and values its Create
        // Row, Update Row and Create or Update write (as text, as n8n sends them: Grist reads each by its column's type), the row
        // to update, the match and what to do when many match; the rows its Delete Row deletes.
        private static void Grist(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)> { ("doc", Text(p, "docId")), ("table", Text(p, "tableId")) };

            // n8n's pairs as a JSON object - an expression among the values making the whole one (its values read from the item).
            static string Pairs(List<(string Name, string Value)> pairs) =>
                pairs.Count == 0 ? "" : (pairs.Any(pair => pair.Value.StartsWith('=')) ? "=" : "") + "{" + string.Join(", ", pairs.Select(pair =>
                    JsonSerializer.Serialize(pair.Name, ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(pair.Value), ReadableJson))) + "}";
            static List<(string Name, string Value)> Columns(JsonElement holder, string collection) =>
                Items(holder, collection, "properties").Select(item => (Name: Text(item, "fieldId"), Value: Text(item, "fieldValue"))).Where(pair => pair.Name.Length > 0).ToList();
            switch (operation)
            {
                case "records":
                    {
                        var options = Find(p, "additionalOptions");
                        var filter = Items(options, "filter", "filterProperties").Select(item => (Field: Text(item, "field"), Value: Text(item, "values"))).Where(item => item.Field.Length > 0).ToList();
                        lines.Add(("filter", filter.Count == 0 ? "" : (filter.Any(item => item.Value.StartsWith('=')) ? "=" : "") + "{" + string.Join(", ", filter.GroupBy(item => item.Field, StringComparer.Ordinal).Select(group =>
                            JsonSerializer.Serialize(group.Key, ReadableJson) + ": [" + string.Join(", ", group.Select(item => item.Value.Trim() is var plain && (plain is "true" or "false" || PlainNumber.IsMatch(plain)) ? plain : JsonSerializer.Serialize(Unmarked(item.Value), ReadableJson))) + "]")) + "}"));
                        lines.Add(("sort", string.Join(",", Items(options, "sort", "sortProperties").Select(item => (Field: Text(item, "field"), Down: Text(item, "direction") == "desc")).Where(item => item.Field.Length > 0).Select(item => (item.Down ? "-" : "") + item.Field))));
                        lines.Add(("max", Most(p, 50)));
                        break;
                    }

                case "delete_records":
                    lines.Add(("ids", Text(p, "rowId")));
                    break;
                default:
                    {
                        if (operation == "update_record")
                        {
                            lines.Add(("id", Text(p, "rowId")));
                        }

                        if (operation == "upsert_record")
                        {
                            lines.Add(("match", Pairs(Columns(p, "upsertCriteria"))));
                            lines.Add(("on_many", Text(p, "onMany") is "all" or "none" ? Text(p, "onMany") : ""));
                        }

                        if (Text(p, "dataToSend") == "autoMapInputs")
                        {
                            todo.Add("n8n wrote each item's own fields as the row (its Auto-Map Input Data) - here give the fields, a JSON object of the record's fields in a For Each: 'fields = {\"Name\": \"{{ name }}\"}'.");
                            break;
                        }

                        lines.Add(("fields", Pairs(Columns(p, "fieldsToSend"))));
                        break;
                    }
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation is "records" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(GristConnection);
        }

        private const string NocoDbConnection = "choose its connection - n8n's credentials stay in n8n: add a NocoDB connection under Admin > Connections (its address and an API token) and pick it here.";

        // n8n's NocoDB row operations as Extract from connection's: the table by its id (n8n's base needs no input here - the
        // table's id names it); a row's id; its fields - n8n's newer column mapper or its older field and value pairs, a JSON
        // object (an expression among them making the line one), or, as n8n's Auto-Map wrote the item's own, said to be given;
        // Search's and Get Many's formula, sort, fields and view, and their limit (50 when the export leaves it out); Count's
        // formula. A primary key n8n named, a binary field and an attachment's download have no input here - said.
        private static void NocoDb(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var options = Find(p, "options");
            var lines = new List<(string Name, string Value)> { ("table", Locator(p, "table")) };
            switch (operation)
            {
                case "records":
                    {
                        lines.Add(("where", Text(options, "where")));
                        var sort = Items(options, "sort", "property").Select(item => (Field: Locator(item, "field"), Down: Text(item, "direction") == "desc")).Where(item => item.Field.Length > 0).Select(item => (item.Down ? "-" : "") + item.Field);
                        lines.Add(("sort", string.Join(",", sort)));
                        var fields = Find(options, "fields");
                        lines.Add(("columns", fields.ValueKind == JsonValueKind.Array ? string.Join(",", fields.EnumerateArray().Select(field => Text(field)).Where(field => field.Length > 0)) : Text(fields)));
                        lines.Add(("view", Locator(options, "viewId")));
                        lines.Add(("max", Most(p, 50)));
                        break;
                    }

                case "count_records":
                    lines.Add(("where", Text(options, "where")));
                    break;
                case "get_record":
                case "delete_record":
                    lines.Add(("id", Text(p, "id")));
                    break;
                default:
                    {
                        lines.Add(("id", Text(p, "id")));
                        if (Text(p, "dataToSend") == "autoMapInputData")
                        {
                            todo.Add("n8n wrote each item's own fields as the row (its Auto-Map Input Data) - here give the fields, a JSON object of the record's fields in a For Each: 'fields = {\"Name\": \"{{ name }}\"}'.");
                            break;
                        }

                        var pairs = new List<(string Name, string Value, bool Raw)>();
                        var mapped = Find(p, "fieldsMapper", "value");
                        if (mapped.ValueKind == JsonValueKind.Object)
                        {
                            pairs.AddRange(mapped.EnumerateObject().Select(field => (field.Name, field.Value.ValueKind == JsonValueKind.String ? field.Value.GetString() ?? "" : field.Value.GetRawText(), field.Value.ValueKind != JsonValueKind.String)));
                        }

                        foreach (var pair in Items(p, "fieldsUi", "fieldValues"))
                        {
                            if (Bool(pair, "binaryData"))
                            {
                                todo.Add($"n8n's field {Text(pair, "fieldName")} took a binary file - left out: a file has no input here.");
                                continue;
                            }

                            pairs.Add((Text(pair, "fieldName"), Text(pair, "fieldValue"), false));
                        }

                        pairs = pairs.Where(pair => pair.Name.Length > 0).ToList();
                        lines.Add(("fields", pairs.Count == 0 ? "" : (pairs.Any(pair => pair.Name.StartsWith('=') || pair.Value.StartsWith('=')) ? "=" : "") + "{" + string.Join(", ", pairs.Select(pair =>
                            JsonSerializer.Serialize(Unmarked(pair.Name).Trim(), ReadableJson) + ": " + (pair.Raw ? pair.Value : JsonSerializer.Serialize(Unmarked(pair.Value), ReadableJson)))) + "}"));
                        break;
                    }
            }

            if (Text(p, "primaryKey") is "custom" or "ncRecordId")
            {
                todo.Add($"n8n named the primary key {(Text(p, "primaryKey") == "custom" ? Text(p, "customPrimaryKey") : "ncRecordId")} - here it is the connection's: set it there (Primary key).");
            }

            if (Bool(p, "downloadAttachments"))
            {
                todo.Add("n8n downloaded the attachments - here an attachment is its JSON among the record's fields: fetch the file with an HTTP request.");
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "records" ? "n8n gave each as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(NocoDbConnection);
        }

        // n8n's update action as the Docs API request it sent: its object and action naming the request, its segment (the body's
        // empty), its location (the end of the segment, or an index), its table cell, range, header, footer, named range or object.
        private static JsonObject? DocsRequest(JsonElement action, Func<JsonElement, string, string, string> of)
        {
            JsonNode Value(string name, JsonNode fallback) =>
                action.ValueKind == JsonValueKind.Object && action.TryGetProperty(name, out var given)
                    ? given.ValueKind switch
                    {
                        JsonValueKind.String => JsonValue.Create(given.GetString() ?? "")!,
                        JsonValueKind.Number => JsonNode.Parse(given.GetRawText())!,
                        JsonValueKind.True => JsonValue.Create(true)!,
                        JsonValueKind.False => JsonValue.Create(false)!,
                        _ => fallback,
                    }
                    : fallback;
            var segment = of(action, "insertSegment", "body") == "body" ? "" : Text(action, "segmentId");
            JsonObject Location() => of(action, "locationChoice", "endOfSegmentLocation") == "location"
                ? new JsonObject { ["location"] = new JsonObject { ["segmentId"] = segment, ["index"] = Value("index", 1) } }
                : new JsonObject { ["endOfSegmentLocation"] = new JsonObject { ["segmentId"] = segment } };
            JsonObject With(JsonObject first, JsonObject rest)
            {
                foreach (var (key, value) in rest.ToList())
                {
                    rest.Remove(key);
                    first[key] = value;
                }

                return first;
            }

            JsonObject Cell() => new() { ["rowIndex"] = Value("rowIndex", 0), ["columnIndex"] = Value("columnIndex", 0), ["tableStartLocation"] = new JsonObject { ["segmentId"] = segment, ["index"] = Value("index", 1) } };
            JsonObject Range() => new() { ["segmentId"] = segment, ["startIndex"] = Value("startIndex", 0), ["endIndex"] = Value("endIndex", 0) };
            return (of(action, "object", "text"), of(action, "action", "insert")) switch
            {
                ("text", "insert") => new JsonObject { ["insertText"] = With(new JsonObject { ["text"] = Value("text", "") }, Location()) },
                ("text", "replaceAll") => new JsonObject { ["replaceAllText"] = new JsonObject { ["replaceText"] = Value("replaceText", ""), ["containsText"] = new JsonObject { ["text"] = Value("text", ""), ["matchCase"] = Value("matchCase", false) } } },
                ("pageBreak", "insert") => new JsonObject { ["insertPageBreak"] = Location() },
                ("table", "insert") => new JsonObject { ["insertTable"] = With(new JsonObject { ["rows"] = Value("rows", 0), ["columns"] = Value("columns", 0) }, Location()) },
                ("tableRow", "insert") => new JsonObject { ["insertTableRow"] = new JsonObject { ["insertBelow"] = Value("insertPosition", true), ["tableCellLocation"] = Cell() } },
                ("tableRow", "delete") => new JsonObject { ["deleteTableRow"] = new JsonObject { ["tableCellLocation"] = Cell() } },
                ("tableColumn", "insert") => new JsonObject { ["insertTableColumn"] = new JsonObject { ["insertRight"] = Value("insertPosition", true), ["tableCellLocation"] = Cell() } },
                ("tableColumn", "delete") => new JsonObject { ["deleteTableColumn"] = new JsonObject { ["tableCellLocation"] = Cell() } },
                ("header" or "footer", "create") => new JsonObject
                {
                    [of(action, "object", "text") == "header" ? "createHeader" : "createFooter"] = new JsonObject
                    {
                        ["type"] = "DEFAULT",
                        ["sectionBreakLocation"] = of(action, "locationChoice", "") == "location" || Text(action, "index").Length > 0 && Text(action, "index") != "0"
                            ? new JsonObject { ["segmentId"] = segment, ["index"] = Value("index", 0) } : new JsonObject { ["segmentId"] = segment },
                    },
                },
                ("header", "delete") => new JsonObject { ["deleteHeader"] = new JsonObject { ["headerId"] = Value("headerId", "") } },
                ("footer", "delete") => new JsonObject { ["deleteFooter"] = new JsonObject { ["footerId"] = Value("footerId", "") } },
                ("namedRange", "create") => new JsonObject { ["createNamedRange"] = new JsonObject { ["name"] = Value("name", ""), ["range"] = Range() } },
                ("namedRange", "delete") => new JsonObject { ["deleteNamedRange"] = new JsonObject { [of(action, "namedRangeReference", "namedRangeId")] = Value("value", "") } },
                ("paragraphBullets", "create") => new JsonObject { ["createParagraphBullets"] = new JsonObject { ["bulletPreset"] = Value("bulletPreset", "BULLET_DISC_CIRCLE_SQUARE"), ["range"] = Range() } },
                ("paragraphBullets", "delete") => new JsonObject { ["deleteParagraphBullets"] = new JsonObject { ["range"] = Range() } },
                ("positionedObject", "delete") => new JsonObject { ["deletePositionedObject"] = new JsonObject { ["objectId"] = Value("objectId", "") } },
                _ => null,
            };
        }

        private const string MicrosoftToDoConnection = "choose its connection - n8n's credentials stay in n8n: add a Microsoft To Do connection under Admin > Connections (an Entra ID app's id and secret, the tenant's token endpoint, the user whose To Do it acts on) and pick it here.";

        // n8n's Microsoft To Do task Create, Get, Get Many, Update and Delete and its list Create, Get, Get Many, Update and Delete
        // as Extract from connection's operations: the list, a task's id, its subject, content (HTML, as n8n sent it), due time,
        // reminder, importance and status; a list's name; n8n's limit (50 when its export leaves it out). A time with no offset -
        // n8n read it in the workflow's time zone - and an update that turned the reminder off in n8n are said.
        private static void MicrosoftToDo(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            var fields = p.ValueKind == JsonValueKind.Object && p.TryGetProperty(operation == "update_task" ? "updateFields" : "additionalFields", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            if (operation is "get_list" or "rename_list" or "delete_list")
            {
                lines.Add(("list", Text(p, "listId")));
            }
            else if (operation is not ("lists" or "create_list"))
            {
                lines.Add(("list", Text(p, "taskListId")));
            }

            switch (operation)
            {
                case "create_list":
                case "rename_list":
                    lines.Add(("name", Text(p, "displayName")));
                    break;
                case "lists":
                case "tasks":
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "create_task":
                case "update_task":
                    if (operation == "update_task")
                    {
                        lines.Add(("task", Text(p, "taskId")));
                    }

                    lines.Add(("title", operation == "create_task" ? Text(p, "title") : Text(fields, "title")));
                    if (Text(fields, "content") is { Length: > 0 } content)
                    {
                        lines.Add(("body", content));
                        lines.Add(("html", "true")); // n8n sent its content as HTML
                    }

                    var due = Text(fields, "dueDateTime");
                    var reminder = Text(fields, "reminderDateTime");
                    lines.Add(("due", due));
                    lines.Add(("reminder", reminder));
                    lines.Add(("importance", Text(fields, "importance")));
                    lines.Add(("status", Text(fields, "status")));
                    if (LocalTime.IsMatch(due) || LocalTime.IsMatch(reminder))
                    {
                        todo.Add("its times carry no offset - n8n read them in the workflow's time zone, here they are UTC: give an offset (2026-10-31T17:00:00+02:00).");
                    }

                    if (operation == "update_task" && reminder.Length == 0)
                    {
                        todo.Add("n8n turned the task's reminder off on an update that gave none - here the reminder is left as it is.");
                    }

                    break;
                default:
                    lines.Add(("task", Text(p, "taskId")));
                    break;
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "tasks" or "lists" ? "n8n gave each " + (operation == "tasks" ? "task" : "list") + " as an item - here they are the step's result, a list of records." : PerItem);
            todo.Add(MicrosoftToDoConnection);
        }

        private const string MicrosoftExcelConnection = "choose its connection - n8n's credentials stay in n8n: add a Microsoft Excel 365 connection under Admin > Connections (an Entra ID app's id and secret, the tenant's token endpoint, and the user whose OneDrive - or the library's drive - holds the workbook) and pick it here.";

        // n8n's Microsoft Excel 365 workbook, sheet and table operations - its first version's too - as Extract from connection's
        // operations: the workbook (its id), the sheet and the table (by name where n8n kept it beside the id), a range, the columns
        // a write sets (n8n's "map each column") as the record it writes, its raw rows as they are, the column to match on and its
        // value, n8n's limits (100 when its export leaves them out). Values mapped from the item by name, a header row other than
        // the range's first, raw output and kept columns are said.
        private static void MicrosoftExcel(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            JsonElement Part(string name) => p.ValueKind == JsonValueKind.Object && p.TryGetProperty(name, out var part) && part.ValueKind == JsonValueKind.Object ? part : default;
            string Named(string name) => Text(p, name, "cachedResultName") is { Length: > 0 } named ? named : Locator(p, name);
            var options = Part("options");
            var lines = new List<(string Name, string Value)>();
            if (operation != "workbooks")
            {
                lines.Add(("workbook", Locator(p, "workbook")));
            }

            if (operation is "delete_worksheet" or "read_rows" or "append_rows" or "update_rows" or "upsert_rows" or "clear" or "add_table")
            {
                lines.Add(("sheet", Named("worksheet")));
            }

            if (operation is "table_rows" or "append_table_rows" or "lookup" or "table_columns" or "delete_table" or "convert_table")
            {
                lines.Add(("table", Named("table")));
            }

            // What a write sets: n8n's mapped columns as a record (the match column's value first), its raw rows as they are.
            void Written(string? matchColumn)
            {
                var mode = Text(p, "dataMode");
                if (todo.Version < 2 || mode == "autoMap")
                {
                    todo.Add(matchColumn is null
                        ? "it wrote the item's fields under the columns by name - here give the record to write in Parameters, 'values = {{ record }}'."
                        : "it matched and wrote the item's fields by name - here give the record, its '" + matchColumn + "' among them, in Parameters, 'values = {{ record }}'.");
                    return;
                }

                if (mode == "raw")
                {
                    var data = Text(p, "data");
                    lines.Add(("values", data.StartsWith('=') ? data : Minified(data)));
                    return;
                }

                var fields = new List<(string Column, string Value)>();
                if (matchColumn is not null)
                {
                    fields.Add((matchColumn, Text(p, "valueToMatchOn")));
                }

                if (Part("fieldsUi") is { ValueKind: JsonValueKind.Object } ui && ui.TryGetProperty("values", out var list) && list.ValueKind == JsonValueKind.Array)
                {
                    fields.AddRange(list.EnumerateArray().Select(field => (Text(field, "column"), Text(field, "fieldValue"))).Where(field => field.Item1.Length > 0));
                }

                var record = "{" + string.Join(", ", fields.Select(field => JsonSerializer.Serialize(field.Column, ReadableJson) + ": " + JsonSerializer.Serialize(Unmarked(field.Value), ReadableJson))) + "}";
                lines.Add(("values", fields.Any(field => field.Value.StartsWith('=')) ? "=" + record : record));
            }

            switch (operation)
            {
                case "workbooks":
                case "table_rows":
                    lines.Add(("max", Most(p, 100)));
                    if (Part("filters") is { ValueKind: JsonValueKind.Object } filters && (Text(filters, "column").Length > 0 || filters.TryGetProperty("column", out var kept) && kept.ValueKind == JsonValueKind.Array && kept.GetArrayLength() > 0))
                    {
                        todo.Add("it kept only some of the table's columns - here every column is read: drop the others with Map fields.");
                    }

                    break;
                case "add_worksheet":
                    lines.Add(("name", Text(p, "additionalFields", "name")));
                    break;
                case "read_rows":
                    lines.Add(("range", todo.Version < 2 && Text(p, "range").Length == 0 ? "A1:C3" : Text(p, "range"))); // its first version's default
                    if (Text(p, "keyRow") is { Length: > 0 } keyRow && keyRow != "0" || Text(p, "dataStartRow") is { Length: > 0 } dataStartRow && dataStartRow != "1")
                    {
                        todo.Add("its headers were not the range's first row, or its data did not follow them - here the range's first row is the headers and every later row a record: start the range at the headers.");
                    }

                    break;
                case "append_rows":
                    Written(null);
                    break;
                case "update_rows":
                case "upsert_rows":
                    lines.Add(("range", Text(p, "range")));
                    lines.Add(("match_column", Text(p, "columnToMatchOn")));
                    Written(Text(p, "columnToMatchOn"));
                    lines.Add(("all_matches", Bool(options, "updateAll") ? "true" : ""));
                    break;
                case "clear":
                    lines.Add(("range", Bool(p, "useRange") ? Text(p, "range") : ""));
                    lines.Add(("apply_to", Text(p, "applyTo")));
                    break;
                case "append_table_rows":
                    Written(null);
                    var index = todo.Version < 2 ? Text(p, "additionalFields", "index") : Text(options, "index");
                    lines.Add(("index", index is "" or "0" ? "" : index)); // n8n never sent 0: its rows went at the end
                    break;
                case "lookup":
                    lines.Add(("column", Text(p, "lookupColumn")));
                    lines.Add(("value", Text(p, "lookupValue")));
                    lines.Add(("all_matches", Bool(options, "returnAllMatches") ? "true" : ""));
                    break;
                case "add_table":
                    lines.Add(("range", Text(p, "selectRange") == "manual" ? Text(p, "range") : "")); // n8n's Automatically: the used range
                    lines.Add(("has_headers", Text(p, "hasHeaders") == "false" ? "false" : ""));
                    break;
            }

            if (Bool(options, "rawData") || Bool(p, "rawData"))
            {
                todo.Add("it gave the raw answer under one field - here each row is a record of its own.");
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: its lines were joined; put longer text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation switch
            {
                "workbooks" => "n8n gave each workbook as an item - here they are the step's result, a list of records.",
                "worksheets" => "n8n gave each sheet as an item - here they are the step's result, a list of records.",
                "read_rows" or "table_rows" or "lookup" => "n8n gave each row as an item - here the rows are the step's result, a list of records, each its columns' fields.",
                "table_columns" => "n8n gave each column as an item - here they are the step's result, a list of records.",
                _ => PerItem,
            });
            todo.Add(MicrosoftExcelConnection);
        }

        private const string ZendeskConnection = "choose its connection - n8n's credentials stay in n8n: add a Zendesk connection under Admin > Connections (the account's address, an agent's email address and an API token) and pick it here.";

        // n8n's Zendesk ticket Create, Get, Get Many, Update and Delete, its user Create, Get, Search and Get Many and its organization
        // Create, Get and Get Many as Extract from connection's operations: a ticket's description, subject, status, type, tags (n8n's
        // list made comma-separated), group, external id and custom fields (its id and value pairs made Zendesk's JSON), an update's
        // public reply or internal note and assignee; a search's query, status, group and order; a user's name, address, role,
        // phone and organization; an organization's name, domains and tags. What it set that has no parameter here is said.
        private static void Zendesk(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            var said = new List<string>();
            var fields = p.ValueKind == JsonValueKind.Object && p.TryGetProperty(operation switch { "update_ticket" => "updateFields", "tickets" => "options", "users" => "filters", _ => "additionalFields" }, out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            void Unmapped(params string[] known)
            {
                if (fields.ValueKind == JsonValueKind.Object)
                {
                    said.AddRange(fields.EnumerateObject().Select(field => field.Name).Where(name => !known.Contains(name)));
                }
            }

            if (Bool(p, "jsonParameters"))
            {
                todo.Add("it gave its fields as JSON - here give each as a parameter, 'subject = ...'.");
            }

            if (Text(p, "ticketType") == "suspended")
            {
                todo.Add("it worked on suspended tickets - here a ticket is a regular one.");
            }

            switch (operation)
            {
                case "create_ticket":
                case "update_ticket":
                    if (operation == "update_ticket")
                    {
                        lines.Add(("ticket", Text(p, "id")));
                    }

                    lines.Add(("subject", Text(fields, "subject")));
                    lines.Add(("description", operation == "create_ticket" ? Text(p, "description") : ""));
                    lines.Add(("comment", Text(fields, "publicReply")));
                    lines.Add(("internal_note", Text(fields, "internalNote")));
                    lines.Add(("status", Text(fields, "status")));
                    lines.Add(("type", Text(fields, "type")));
                    lines.Add(("tags", Joined(fields, "tags")));
                    lines.Add(("group_id", Text(fields, "group")));
                    lines.Add(("assignee_email", Text(fields, "assigneeEmail")));
                    lines.Add(("external_id", Text(fields, "externalId")));
                    var custom = Items(fields, "customFieldsUi", "customFieldsValues").Select(pair => (Text(pair, "id"), Text(pair, "value"))).Where(pair => pair.Item1.Length > 0).ToList();
                    if (custom.Count > 0)
                    {
                        var list = new System.Text.Json.Nodes.JsonArray(custom.Select(pair => (System.Text.Json.Nodes.JsonNode)new System.Text.Json.Nodes.JsonObject
                        {
                            ["id"] = long.TryParse(pair.Item1, NumberStyles.Integer, CultureInfo.InvariantCulture, out var id) ? id : pair.Item1,
                            ["value"] = Unmarked(pair.Item2),
                        }).ToArray());
                        lines.Add(("custom_fields", (custom.Any(pair => pair.Item2.StartsWith('=')) ? "=" : "") + list.ToJsonString(ReadableJson)));
                    }

                    Unmapped("subject", "publicReply", "internalNote", "status", "type", "tags", "group", "assigneeEmail", "externalId", "customFieldsUi");
                    break;
                case "tickets":
                    lines.Add(("query", Text(fields, "query")));
                    lines.Add(("status", Text(fields, "status")));
                    lines.Add(("group_id", Text(fields, "group")));
                    lines.Add(("sort_by", Text(fields, "sortBy")));
                    lines.Add(("sort_order", Text(fields, "sortOrder")));
                    lines.Add(("max", Most(p, 100)));
                    Unmapped("query", "status", "group", "sortBy", "sortOrder");
                    break;
                case "users":
                    lines.Add(("query", Text(fields, "query") is { Length: > 0 } query ? query : Text(fields, "external_id") is { Length: > 0 } external ? "external_id:" + external : ""));
                    if (lines[^1].Value.Length == 0)
                    {
                        todo.Add("it read every user - here users are searched: give 'query = ...' (role:end-user, an address).");
                    }

                    lines.Add(("max", Most(p, 100)));
                    Unmapped("query", "external_id");
                    break;
                case "create_user":
                    lines.Add(("name", Text(p, "name")));
                    lines.Add(("email", Text(fields, "email")));
                    lines.Add(("role", Text(fields, "role")));
                    lines.Add(("phone", Text(fields, "phone")));
                    lines.Add(("organization_id", Text(fields, "organization_id")));
                    lines.Add(("external_id", Text(fields, "external_id")));
                    Unmapped("email", "role", "phone", "organization_id", "external_id");
                    break;
                case "create_organization":
                    lines.Add(("name", Text(p, "name")));
                    lines.Add(("domain_names", Joined(fields, "domain_names")));
                    lines.Add(("tags", Joined(fields, "tags")));
                    lines.Add(("external_id", Text(fields, "external_id")));
                    Unmapped("domain_names", "tags", "external_id");
                    break;
                case "organizations":
                    lines.Add(("max", Most(p, 100)));
                    break;
                default:
                    lines.Add((operation switch { "get_user" => "user", "get_organization" => "organization", _ => "ticket" }, Text(p, "id")));
                    break;
            }

            foreach (var name in said)
            {
                todo.Add($"it set its '{name}' - here it has no parameter: set it in Zendesk.");
            }

            if (lines.Any(line => line.Name is not ("description" or "comment" or "internal_note") && line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: put the text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "tickets" or "users" or "organizations" ? "n8n gave each record as an item - here the records are the step's result, a list, each its id, its name or subject and its fields." : PerItem);
            todo.Add(ZendeskConnection);
        }

        private const string PipedriveConnection = "choose its connection - n8n's credentials stay in n8n: add a Pipedrive connection under Admin > Connections (the account's API token) and pick it here.";

        // A Pipedrive field's value as JSON: a number or a yes/no as it is, an id, a value or a probability written as digits a
        // number, a list as JSON, anything else its text.
        private static System.Text.Json.Nodes.JsonNode? PipedriveValue(string name, JsonElement value)
        {
            if (value.ValueKind is JsonValueKind.Number or JsonValueKind.True or JsonValueKind.False or JsonValueKind.Array)
            {
                return System.Text.Json.Nodes.JsonNode.Parse(value.GetRawText());
            }

            var text = value.ValueKind == JsonValueKind.Object ? Text(value, "value") : Text(value);
            return (name.EndsWith("_id", StringComparison.Ordinal) || name is "value" or "probability" or "visible_to")
                && decimal.TryParse(text, NumberStyles.Number, CultureInfo.InvariantCulture, out var number)
                ? System.Text.Json.Nodes.JsonValue.Create(number)
                : text;
        }

        // n8n's Pipedrive Create, Get, Get Many, Search, Update and Delete of a deal, a person, an organization, an activity or a
        // product, and its note Create, as Extract from connection's operations: a record's fields as Pipedrive's JSON (its own
        // names; user_id made owner_id, a person's emails and phones its lists, an activity's person a participant, a date a
        // date), a Get Many's filters, a search's term. What it set that has no place here is said.
        private static void Pipedrive(JsonElement p, PipelineGraphStep step, Todo todo, string action)
        {
            var resource = Text(p, "resource") is { Length: > 0 } named ? named : "deal";
            var objectName = resource switch { "person" => "persons", "organization" => "organizations", "activity" => "activities", "product" => "products", _ => "deals" };
            Set(step, "Operation", action switch { "note" => "add_note", "getAll" => "list", _ => action });
            var lines = new List<(string Name, string Value)>();
            var said = new List<string>();
            var expression = false;
            if (action != "note")
            {
                lines.Add(("object", objectName));
            }

            if (action is "get" or "update" or "delete")
            {
                lines.Add(("id", Text(p, resource + "Id")));
            }

            if (action is "create" or "update")
            {
                var record = new System.Text.Json.Nodes.JsonObject();
                void Put(string name, JsonElement value)
                {
                    expression |= value.ValueKind == JsonValueKind.String && (value.GetString() ?? "").StartsWith('=');
                    var node = PipedriveValue(name, value);
                    record[name] = node is System.Text.Json.Nodes.JsonValue text && text.TryGetValue<string>(out var words) ? Unmarked(words) : node;
                }

                if (action == "create")
                {
                    foreach (var first in resource switch { "deal" => new[] { "title" }, "activity" => new[] { "subject", "type", "done" }, _ => new[] { "name" } })
                    {
                        if (p.ValueKind == JsonValueKind.Object && p.TryGetProperty(first, out var value))
                        {
                            Put(first, value);
                        }
                    }

                    foreach (var link in new[] { "org_id", "person_id" })
                    {
                        if (resource == "deal" && p.ValueKind == JsonValueKind.Object && p.TryGetProperty(link, out var value))
                        {
                            Put(link, value);
                        }
                    }
                }

                var fields = p.ValueKind == JsonValueKind.Object && p.TryGetProperty(action == "update" ? "updateFields" : "additionalFields", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
                if (fields.ValueKind == JsonValueKind.Object)
                {
                    foreach (var field in fields.EnumerateObject())
                    {
                        switch (field.Name)
                        {
                            case "user_id":
                                Put("owner_id", field.Value);
                                break;
                            case "emails" or "phones" when field.Value.ValueKind == JsonValueKind.Object:
                                record[field.Name] = new System.Text.Json.Nodes.JsonArray(Items(fields, field.Name, field.Name == "emails" ? "emailProperties" : "phoneProperties")
                                    .Select(entry => (System.Text.Json.Nodes.JsonNode)new System.Text.Json.Nodes.JsonObject { ["value"] = Text(entry, "value"), ["primary"] = Text(entry, "primary") != "false", ["label"] = Text(entry, "label") is { Length: > 0 } label ? label : field.Name == "emails" ? "work" : "mobile" }).ToArray());
                                break;
                            case "email" or "phone" when field.Value.ValueKind == JsonValueKind.Array: // n8n's v1 node: a list of text
                                record[field.Name + "s"] = new System.Text.Json.Nodes.JsonArray(field.Value.EnumerateArray().Select((entry, index) => (System.Text.Json.Nodes.JsonNode)new System.Text.Json.Nodes.JsonObject { ["value"] = Text(entry), ["primary"] = index == 0 }).ToArray());
                                break;
                            case "person_id" when resource == "activity":
                                record["participants"] = new System.Text.Json.Nodes.JsonArray(new System.Text.Json.Nodes.JsonObject { ["person_id"] = PipedriveValue("person_id", field.Value), ["primary"] = true });
                                break;
                            case "due_date" or "expected_close_date":
                                var day = Text(field.Value);
                                record[field.Name] = day.Length >= 10 && !day.StartsWith('=') ? day[..10] : Unmarked(day);
                                expression |= day.StartsWith('=');
                                break;
                            case "customFieldsCollection" or "customProperties":
                                todo.Add("it set custom fields - here give them in the fields' custom_fields, by their keys.");
                                break;
                            default:
                                Put(field.Name, field.Value);
                                break;
                        }
                    }
                }

                lines.Add(("fields", record.Count == 0 ? "" : (expression ? "=" : "") + record.ToJsonString(ReadableJson)));
            }
            else if (action == "getAll")
            {
                var filters = p.ValueKind == JsonValueKind.Object && p.TryGetProperty("filters", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
                if (filters.ValueKind == JsonValueKind.Object)
                {
                    foreach (var filter in filters.EnumerateObject())
                    {
                        switch (filter.Name)
                        {
                            case "user_id" or "owner_id":
                                lines.Add(("owner_id", Text(filter.Value)));
                                break;
                            case "filter_id" or "stage_id" or "pipeline_id" or "person_id" or "org_id" or "updated_since":
                                lines.Add((filter.Name, Text(filter.Value)));
                                break;
                            case "status":
                                lines.Add(("status", Text(filter.Value) is "all_not_deleted" ? "" : Text(filter.Value)));
                                break;
                            default:
                                said.Add($"its filter '{filter.Name}'");
                                break;
                        }
                    }
                }

                lines.Add(("max", Most(p, 100)));
            }
            else if (action == "search")
            {
                lines.Add(("term", Text(p, "term")));
                lines.Add(("exact_match", Bool(p, "exactMatch") || Bool(p, "exact_match") ? "true" : ""));
                if (p.ValueKind == JsonValueKind.Object && p.TryGetProperty("additionalFields", out var extra) && extra.ValueKind == JsonValueKind.Object)
                {
                    said.AddRange(extra.EnumerateObject().Select(field => $"its search option '{field.Name}'"));
                }

                lines.Add(("max", Most(p, 100)));
            }
            else if (action == "note")
            {
                lines.Add(("content", Text(p, "content")));
                var on = p.ValueKind == JsonValueKind.Object && p.TryGetProperty("additionalFields", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
                foreach (var field in new[] { "deal_id", "person_id", "org_id", "lead_id" })
                {
                    lines.Add((field, Text(on, field) is { Length: > 0 } id ? id : Text(on, field, "value")));
                }

                if (on.ValueKind == JsonValueKind.Object)
                {
                    said.AddRange(on.EnumerateObject().Where(field => field.Name.StartsWith("pinned", StringComparison.Ordinal)).Select(field => $"its '{field.Name}'"));
                }
            }

            foreach (var what in said)
            {
                todo.Add($"it set {what} - here it has no place: set it in Pipedrive.");
            }

            if (lines.Any(line => line.Name != "content" && line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: put the text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(action is "getAll" or "search" ? "n8n gave each record as an item - here the records are the step's result, a list, each its fields by Pipedrive's names." : PerItem);
            todo.Add(PipedriveConnection);
        }

        private const string ShopifyConnection = "choose its connection - n8n's credentials stay in n8n: add a Shopify connection under Admin > Connections (the shop's address and an app's Admin API access token, shpat_...) and pick it here.";

        // n8n's names for Shopify's statuses, as Shopify's search takes them; "any" is no filter.
        private static string ShopifyWord(string value) => value switch
        {
            "partiallyPaid" => "partially_paid",
            "partiallyRefunded" => "partially_refunded",
            "Cancelled" => "cancelled",
            "any" => "",
            _ => value,
        };

        // n8n's Shopify order and product Create, Get, Get Many, Update and Delete - over Shopify's REST API, its node's - as Extract
        // from connection's operations over its GraphQL one: an order's line items as JSON (a variant and a quantity, or a title, a
        // price and a quantity), its email, note, tags, test flag and receipts; a product's title, description, vendor, type, tags
        // and handle; a Get Many's statuses, vendor, type, title and times. What it set that has no parameter here is said.
        private static void Shopify(JsonElement p, PipelineGraphStep step, Todo todo, string action)
        {
            var order = Text(p, "resource") is "" or "order";
            var noun = order ? "order" : "product";
            var operation = action switch
            {
                "getAll" => order ? "orders" : "products",
                _ => action + "_" + noun,
            };
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            var fields = p.ValueKind == JsonValueKind.Object && p.TryGetProperty(action switch { "update" => "updateFields", "getAll" when order => "options", _ => "additionalFields" }, out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            var said = new List<string>();
            void Unmapped(params string[] names) => said.AddRange(names.Where(name => fields.ValueKind == JsonValueKind.Object && fields.TryGetProperty(name, out _)));
            if (action is "get" or "update" or "delete")
            {
                lines.Add((noun, Text(p, order ? "orderId" : "productId")));
            }

            if (action == "getAll")
            {
                if (order)
                {
                    var status = Text(fields, "status") is { Length: > 0 } chosen ? ShopifyWord(chosen) : "open"; // n8n read the open orders unless told
                    lines.Add(("status", status));
                    var financial = ShopifyWord(Text(fields, "financialStatus"));
                    if (financial == "unpaid")
                    {
                        todo.Add("it read the unpaid orders - here say which: 'financial_status = pending' or 'authorized'.");
                        financial = "";
                    }

                    lines.Add(("financial_status", financial));
                    lines.Add(("fulfillment_status", ShopifyWord(Text(fields, "fulfillmentStatus"))));
                    lines.Add(("created_after", Text(fields, "createdAtMin")));
                    lines.Add(("updated_after", Text(fields, "updatedAtMin")));
                    Unmapped("createdAtMax", "updatedAtMax", "processedAtMin", "processedAtMax", "ids", "sinceId", "attributionAppId");
                }
                else
                {
                    lines.Add(("vendor", Text(fields, "vendor")));
                    lines.Add(("product_type", Text(fields, "product_type")));
                    lines.Add(("title", Text(fields, "title")));
                    lines.Add(("created_after", Text(fields, "created_at_min")));
                    lines.Add(("updated_after", Text(fields, "updated_at_min")));
                    Unmapped("collection_id", "handle", "ids", "presentment_currencies", "published_status", "published_at_min", "published_at_max", "created_at_max", "updated_at_max");
                }

                lines.Add(("max", Most(p, 50)));
            }
            else if (action is "create" or "update" && order)
            {
                if (action == "create")
                {
                    var items = new System.Text.Json.Nodes.JsonArray();
                    var expression = false;
                    var custom = false;
                    foreach (var line in Items(p, "limeItemsUi", "lineItemValues"))
                    {
                        string Value(string name) => Unmarked(Text(line, name));
                        expression |= new[] { "variantId", "title", "price", "quantity" }.Any(name => Text(line, name).StartsWith('='));
                        var quantity = Text(line, "quantity") is { Length: > 0 } count ? Unmarked(count) : "1";
                        var item = new System.Text.Json.Nodes.JsonObject();
                        if (Value("variantId").Length > 0)
                        {
                            item["variant_id"] = Value("variantId");
                        }
                        else if (Value("title").Length > 0 && Value("price").Length > 0)
                        {
                            item["title"] = Value("title");
                            item["price"] = Value("price");
                            custom = true;
                        }
                        else
                        {
                            todo.Add("a line item of it names " + (Value("productId").Length > 0 ? "a product but not its variant" : "no variant") + " - here give its variant_id.");
                            continue;
                        }

                        item["quantity"] = int.TryParse(quantity, NumberStyles.Integer, CultureInfo.InvariantCulture, out var whole) ? whole : quantity;
                        items.Add(item);
                    }

                    lines.Add(("line_items", items.Count == 0 ? "" : (expression ? "=" : "") + items.ToJsonString(ReadableJson)));
                    if (custom)
                    {
                        todo.Add("an item of no product is priced in the order's currency - give 'currency = ...' (SEK).");
                    }
                }

                lines.Add(("email", Text(fields, "email")));
                lines.Add(("note", Text(fields, "note")));
                lines.Add(("tags", Text(fields, "tags")));
                if (action == "create")
                {
                    lines.Add(("test", Bool(fields, "test") ? "true" : ""));
                    lines.Add(("send_receipt", Bool(fields, "sendReceipt") ? "true" : ""));
                    lines.Add(("send_fulfillment_receipt", Bool(fields, "sendFulfillmentReceipt") ? "true" : ""));
                }

                Unmapped("fulfillmentStatus", "locationId", "sourceName", "discountCodesUi", "billingAddressUi", "shippingAddressUi", "inventoryBehaviour");
            }
            else if (action is "create" or "update")
            {
                lines.Add(("title", action == "create" ? Text(p, "title") : Text(fields, "title")));
                lines.Add(("description_html", Text(fields, "body_html")));
                lines.Add(("vendor", Text(fields, "vendor")));
                lines.Add(("product_type", Text(fields, "product_type")));
                lines.Add(("tags", Text(fields, "tags")));
                lines.Add(("handle", Text(fields, "handle")));
                Unmapped("images", "productOptions", "published_at", "published_scope", "template_suffix");
            }

            foreach (var name in said)
            {
                todo.Add($"it set its '{name}' - here it has no parameter: set it in Shopify, or search for it in Shopify's syntax ('query = ...').");
            }

            if (lines.Any(line => line.Name != "description_html" && line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: put the text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(action == "getAll" ? "n8n gave each " + noun + " as an item - here the " + noun + "s are the step's result, a list of records, each its id, name or title, statuses and prices." : PerItem);
            todo.Add(ShopifyConnection);
        }

        private const string SalesforceConnection = "choose its connection - n8n's credentials stay in n8n: add a Salesforce connection under Admin > Connections (a connected app's consumer key and secret and the org's token endpoint, by the client credentials flow) and pick it here.";

        private static readonly Dictionary<string, string> SalesforceObjects = new(StringComparer.Ordinal)
        {
            ["account"] = "Account", ["contact"] = "Contact", ["lead"] = "Lead", ["opportunity"] = "Opportunity", ["case"] = "Case", ["task"] = "Task", ["user"] = "User",
        };

        // The fields n8n's Get Many reads when its options name none, by object.
        private static readonly Dictionary<string, string> SalesforceDefaultFields = new(StringComparer.Ordinal)
        {
            ["Account"] = "id, name, type, LastModifiedDate",
            ["Lead"] = "id, company, firstname, lastname, street, postalCode, city, email, status, LastModifiedDate",
            ["Contact"] = "id, firstname, lastname, email, LastModifiedDate",
            ["Opportunity"] = "id, accountId, amount, probability, type, LastModifiedDate",
            ["Case"] = "id, accountId, contactId, priority, status, subject, type, LastModifiedDate",
            ["Task"] = "id, subject, status, priority, LastModifiedDate",
            ["User"] = "id, name, email, LastModifiedDate",
        };

        // A condition's value SOQL takes unquoted, as n8n leaves it: a date or a time, or a date literal.
        private static readonly Regex SoqlUnquoted = new(
            "^([0-9]{4}-[0-9]{2}-[0-9]{2}(T[0-9]{2}:[0-9]{2}(:[0-9]{2}(\\.[0-9]+)?)?(Z|[+-][0-9]{2}:?[0-9]{2})?)?|YESTERDAY|TODAY|TOMORROW|(LAST|THIS|NEXT)_(WEEK|MONTH|QUARTER|YEAR|FISCAL_QUARTER|FISCAL_YEAR)|(LAST|NEXT)_90_DAYS|(LAST|NEXT)_N_(DAYS|WEEKS|MONTHS|QUARTERS|YEARS|FISCAL_QUARTERS|FISCAL_YEARS):[0-9]+|N_(DAYS|WEEKS|MONTHS|QUARTERS|YEARS|FISCAL_QUARTERS|FISCAL_YEARS)_AGO:[0-9]+)$",
            RegexOptions.CultureInvariant);

        // JSON a parameter holds as a person reads it: <b>, & and é as written, not \u escapes - the same JSON either way.
        private static readonly JsonSerializerOptions ReadableJson = new() { Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping };

        // The API name Salesforce gives a field n8n names: its own name, its first letter capitalised - but for these.
        private static string SalesforceField(string name, string resource) => name.ToLowerInvariant() switch
        {
            "firstname" => "FirstName",
            "lastname" => "LastName",
            "owner" => "OwnerId",
            "acconuntid" => "AccountId", // n8n's contact names its account so
            "type" when resource == "task" => "TaskSubtype",
            _ => char.ToUpperInvariant(name[0]) + name[1..],
        };

        // A record's fields as Salesforce's JSON: those n8n named (its names made Salesforce's, an owner chosen from a list its id)
        // and its custom fields as given, a number or a yes/no as it is; an n8n expression among them making the parameters one.
        private static (string Fields, bool Expression) SalesforceFields(JsonElement p, string resource, string collection, IEnumerable<string> first)
        {
            var fields = new List<(string Name, JsonElement Value)>();
            foreach (var name in first)
            {
                if (p.ValueKind == JsonValueKind.Object && p.TryGetProperty(name, out var value))
                {
                    fields.Add((SalesforceField(name, resource), value));
                }
            }

            var holder = p.ValueKind == JsonValueKind.Object && p.TryGetProperty(collection, out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            if (holder.ValueKind == JsonValueKind.Object)
            {
                fields.AddRange(holder.EnumerateObject().Where(field => field.Name != "customFieldsUi" && field.Name.Length > 0).Select(field => (SalesforceField(field.Name, resource), field.Value)));
            }

            foreach (var custom in Items(holder, "customFieldsUi", "customFieldsValues").Concat(Items(p, "customFieldsUi", "customFieldsValues")))
            {
                if (Text(custom, "fieldId") is { Length: > 0 } id && custom.TryGetProperty("value", out var value))
                {
                    fields.Add((id, value));
                }
            }

            var record = new System.Text.Json.Nodes.JsonObject();
            var expression = false;
            foreach (var (name, value) in fields)
            {
                if (value.ValueKind is JsonValueKind.Number or JsonValueKind.True or JsonValueKind.False)
                {
                    record[name] = System.Text.Json.Nodes.JsonNode.Parse(value.GetRawText());
                    continue;
                }

                var text = value.ValueKind == JsonValueKind.Object ? Text(value, "value") : Text(value);
                if (text.Length > 0)
                {
                    expression |= text.StartsWith('=');
                    record[name] = Unmarked(text);
                }
            }

            return (record.ToJsonString(ReadableJson), expression);
        }

        // n8n's Get Many as the SOQL it would have sent: the fields its options name, or its defaults for the object, and its
        // conditions - equal as =, a number or a yes/no, a date, a time or a date literal unquoted, other text quoted.
        private static string SalesforceSoql(JsonElement p, string objectName)
        {
            var options = p.ValueKind == JsonValueKind.Object && p.TryGetProperty("options", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            var fields = Joined(options, "fields") is { Length: > 0 } named ? named : SalesforceDefaultFields.GetValueOrDefault(objectName, "id, LastModifiedDate");
            var expression = fields.StartsWith('=');
            var conditions = new List<string>();
            foreach (var condition in Items(options, "conditionsUi", "conditionValues"))
            {
                var field = Text(condition, "field");
                var operation = Text(condition, "operation") is { Length: > 0 } written && written != "equal" ? written : "=";
                condition.TryGetProperty("value", out var value);
                var text = Text(value);
                expression |= field.StartsWith('=') || text.StartsWith('=');
                var literal = value.ValueKind is JsonValueKind.Number or JsonValueKind.True or JsonValueKind.False ? value.GetRawText()
                    : text.StartsWith('=') ? "'" + Unmarked(text) + "'"
                    : SoqlUnquoted.IsMatch(text.Trim()) ? text.Trim()
                    : "'" + text.Trim().Replace("\\", "\\\\", StringComparison.Ordinal).Replace("'", "\\'", StringComparison.Ordinal) + "'";
                conditions.Add(Unmarked(field) + " " + operation + " " + literal);
            }

            var soql = "SELECT " + Unmarked(fields) + " FROM " + objectName + (conditions.Count > 0 ? " WHERE " + string.Join(" AND ", conditions) : "");
            return (expression ? "=" : "") + soql;
        }

        // n8n's Salesforce Create, Create or Update, Get, Get Many, Update and Delete of an account, a contact, a lead, an
        // opportunity, a case, a task or a custom object, a user's Get and Get Many, and its search by SOQL, as Extract from
        // connection's operations: the object, the record's id, its fields as Salesforce's JSON (n8n's names made Salesforce's, its
        // custom fields as given), an external id field and its value, a Get Many as the SOQL n8n would have sent.
        private static void Salesforce(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            var resource = Text(p, "resource") is { Length: > 0 } named ? named : "lead";
            var objectName = resource == "customObject" ? Text(p, "customObject") : SalesforceObjects.GetValueOrDefault(resource, resource);
            var id = Text(p, resource == "customObject" ? "recordId" : resource + "Id");
            var lines = new List<(string Name, string Value)>();
            switch (operation)
            {
                case "query":
                    lines.Add(("soql", Text(p, "query").ReplaceLineEndings(" ")));
                    break;
                case "getAll":
                    lines.Add(("soql", SalesforceSoql(p, objectName)));
                    lines.Add(("max", Most(p, 50)));
                    break;
                case "create":
                case "upsert":
                case "update":
                    lines.Add(("object", objectName));
                    lines.Add(("id", operation == "update" ? id : ""));
                    lines.Add(("external_id_field", operation == "upsert" ? Text(p, "externalId") : ""));
                    lines.Add(("external_id", operation == "upsert" ? Text(p, "externalIdValue") : ""));
                    var first = operation == "update" ? Array.Empty<string>() : resource switch
                    {
                        "lead" => new[] { "company", "lastname" },
                        "contact" => new[] { "lastname" },
                        "account" => new[] { "name" },
                        "opportunity" => new[] { "name", "closeDate", "stageName" },
                        "case" => new[] { "type" },
                        "task" => new[] { "status" },
                        _ => Array.Empty<string>(),
                    };
                    var (fields, expression) = SalesforceFields(p, resource, operation == "update" ? "updateFields" : "additionalFields", first);
                    lines.Add(("fields", (expression ? "=" : "") + fields));
                    break;
                default:
                    lines.Add(("object", objectName));
                    lines.Add(("id", id));
                    break;
            }

            if (lines.Any(line => line.Value.Contains('\n', StringComparison.Ordinal)))
            {
                todo.Add("a value of it spans lines - here a parameter is one line: put the text in a variable and give 'name = {{ variable }}'.");
            }

            Set(step, "Operation", operation == "getAll" ? "query" : operation);
            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).Select(line => (line.Name, line.Value.Replace("\n", " ", StringComparison.Ordinal))).ToArray()));
            todo.Add(operation is "query" or "getAll" ? "n8n gave each record as an item - here the records are the step's result, a list, each its fields, a related record's flattened (Account.Name)." : PerItem);
            todo.Add(SalesforceConnection);
        }

        private const string HubSpotConnection = "choose its connection - n8n's credentials stay in n8n: add a HubSpot connection under Admin > Connections (a private app's access token) and pick it here.";

        // n8n's names for a HubSpot record's fields and the properties HubSpot calls them.
        private static readonly Dictionary<string, string> HubSpotProperties = new(StringComparer.Ordinal)
        {
            ["firstName"] = "firstname", ["lastName"] = "lastname", ["jobTitle"] = "jobtitle", ["companyName"] = "company",
            ["lifeCycleStage"] = "lifecyclestage", ["phoneNumber"] = "phone", ["mobilePhoneNumber"] = "mobilephone", ["city"] = "city",
            ["country"] = "country", ["stateRegion"] = "state", ["postalCode"] = "zip", ["streetAddress"] = "address",
            ["websiteUrl"] = "website", ["industry"] = "industry", ["description"] = "description", ["domainName"] = "domain",
            ["dealName"] = "dealname", ["dealStage"] = "dealstage", ["amount"] = "amount", ["closeDate"] = "closedate", ["pipeline"] = "pipeline",
        };

        // A record's properties: the fields n8n named (its own names made HubSpot's), an n8n expression among them making the
        // parameters one; one it names that this does not know said.
        private static (string Record, bool Expression) HubSpotRecord(JsonElement p, Todo todo, IEnumerable<(string Property, string Value)> first)
        {
            var fields = first.Where(field => field.Value.Length > 0).ToList();
            if (p.ValueKind == JsonValueKind.Object && p.TryGetProperty("additionalFields", out var additional) && additional.ValueKind == JsonValueKind.Object)
            {
                foreach (var field in additional.EnumerateObject())
                {
                    if (HubSpotProperties.TryGetValue(field.Name, out var property) && Text(additional, field.Name) is { Length: > 0 } value)
                    {
                        fields.Add((property, value));
                    }
                    else
                    {
                        todo.Add($"it set its field '{field.Name}' - here name its HubSpot property in Parameters.");
                    }
                }
            }

            var record = "{" + string.Join(", ", fields.Select(field => JsonSerializer.Serialize(field.Property) + ": " + JsonSerializer.Serialize(Unmarked(field.Value)))) + "}";
            return (record, fields.Any(field => field.Value.StartsWith('=')));
        }

