        // n8n's Microsoft Outlook Get Many as Extract from connection's search: its search, or its unread filter, its first folder,
        // how many.
        private static void OutlookSearch(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            Set(step, "Operation", "search");
            var filters = p.ValueKind == JsonValueKind.Object && p.TryGetProperty("filters", out var given) && given.ValueKind == JsonValueKind.Object ? given : default;
            var lines = new List<(string Name, string Value)>();
            var folders = filters.ValueKind == JsonValueKind.Object && filters.TryGetProperty("foldersToInclude", out var included) && included.ValueKind == JsonValueKind.Array
                ? included.EnumerateArray().Select(folder => folder.GetString() ?? "").Where(folder => folder.Length > 0).ToList()
                : new List<string>();
            if (folders.Count > 0)
            {
                lines.Add(("folder", folders[0]));
            }

            if (Text(filters, "search") is { Length: > 0 } search)
            {
                lines.Add(("query", search));
                if (Text(filters, "readStatus") is "unread" or "read")
                {
                    todo.Add("it kept only " + Text(filters, "readStatus") + " messages as well as searching - Graph takes a search or a filter, so here it searches: put a Decision after it.");
                }
            }
            else if (Text(filters, "readStatus") is "unread" or "read")
            {
                lines.Add(("filter", "isRead eq " + (Text(filters, "readStatus") == "read" ? "true" : "false")));
            }

            if (Bool(p, "returnAll"))
            {
                lines.Add(("max", "500"));
                todo.Add("it read every message - here at most 500 are read; narrow the search to read fewer.");
            }
            else
            {
                lines.Add(("max", Most(p, 100)));
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add("n8n gave each message as an item - here the messages are the step's result, a list of records, each its id, conversation, headers and body.");
            todo.Add(OutlookConnection);
        }

        // A date as Gmail's search writes it (2026/10/01); an expression kept for the author to mend; anything else left out.
        private static string GmailDate(string value) =>
            value.StartsWith('=') ? value
            : DateTimeOffset.TryParse(value, CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal, out var date) ? date.ToString("yyyy/MM/dd", CultureInfo.InvariantCulture)
            : "";

        // n8n's Notion database pages, their filter and sorts, the properties it set (each by the name before its key's "|type",
        // the value its type keeps); an n8n expression among them making the parameters one. A Notion filter n8n built from its
        // conditions has no counterpart: the author gives Notion's own JSON.
        private static void Notion(JsonElement p, PipelineGraphStep step, Todo todo, string operation)
        {
            Set(step, "Operation", operation);
            var lines = new List<(string Name, string Value)>();
            if (operation != "update")
            {
                lines.Add(("database", Locator(p, "databaseId")));
            }

            if (operation == "query")
            {
                if (Text(p, "filterType") == "json" && OneLine(Text(p, "filterJson")) is { Length: > 0 } filter)
                {
                    lines.Add(("filter", filter));
                }
                else if (Text(p, "filterType") == "manual")
                {
                    todo.Add("it kept the pages its conditions matched - here give Notion's filter as JSON in Parameters, 'filter = {\"property\": \"Status\", \"status\": {\"equals\": \"Open\"}}'.");
                }

                // A sort by a property, or by when a page was made or last edited (n8n's "timestamp").
                var sorts = (p.ValueKind == JsonValueKind.Object && p.TryGetProperty("options", out var options) ? Items(options, "sort", "sortValue") : Enumerable.Empty<JsonElement>())
                    .Select(sort => "{" + (Bool(sort, "timestamp") ? "\"timestamp\": " + JsonSerializer.Serialize(Text(sort, "key")) : "\"property\": " + JsonSerializer.Serialize(NotionProperty(Text(sort, "key")).Name))
                        + ", \"direction\": " + JsonSerializer.Serialize(Text(sort, "direction") is { Length: > 0 } direction ? direction : "ascending") + "}")
                    .ToList();
                if (sorts.Count > 0)
                {
                    lines.Add(("sorts", "[" + string.Join(", ", sorts) + "]"));
                }
            }
            else
            {
                var fields = new List<(string Name, string Json, bool Expression)>();
                if (operation == "update")
                {
                    var page = Locator(p, "pageId");
                    fields.Add(("id", JsonSerializer.Serialize(Unmarked(page)), page.StartsWith('=')));
                }
                else if (Text(p, "title") is { Length: > 0 } title)
                {
                    fields.Add(("title", JsonSerializer.Serialize(Unmarked(title)), title.StartsWith('=')));
                }

                foreach (var property in Items(p, "propertiesUi", "propertyValues"))
                {
                    var (name, type) = NotionProperty(Text(property, "key"));
                    var field = type switch
                    {
                        "title" => "title",
                        "rich_text" => "textContent",
                        "number" => "numberValue",
                        "select" => "selectValue",
                        "status" => "statusValue",
                        "multi_select" => "multiSelectValue",
                        "checkbox" => "checkboxValue",
                        "url" => "urlValue",
                        "email" => "emailValue",
                        "phone_number" => "phoneValue",
                        "date" => "date",
                        "people" => "peopleValue",
                        "relation" => "relationValue",
                        _ => null,
                    };
                    if (field is null || !property.TryGetProperty(field, out var value))
                    {
                        todo.Add($"it set its property '{name}' ({type}) in a way not carried over - set it in Parameters.");
                        continue;
                    }

                    var text = value.ValueKind == JsonValueKind.String ? value.GetString() ?? "" : "";
                    fields.Add((name, value.ValueKind == JsonValueKind.String ? JsonSerializer.Serialize(Unmarked(text)) : value.GetRawText(), text.StartsWith('=')));
                }

                if (fields.Count > (operation == "update" ? 1 : 0))
                {
                    var record = "{" + string.Join(", ", fields.Select(field => JsonSerializer.Serialize(field.Name) + ": " + field.Json)) + "}";
                    lines.Add((operation == "create" ? "properties" : "pages", fields.Any(field => field.Expression) ? "=" + record : record));
                }
                else
                {
                    todo.Add(operation == "create"
                        ? "it set no properties - here give the page's properties in Parameters, 'properties = {\"Name\": \"...\"}'."
                        : "it changed no properties - here give the page's id and what to change in Parameters, 'pages = {\"id\": \"...\", \"Status\": \"Done\"}'.");
                }

                if (Items(p, "blockUi", "blockValues").Any())
                {
                    todo.Add("it also wrote blocks into the page's body - here only its properties are written.");
                }
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(operation == "query" ? "n8n gave each page as an item - here the pages are the step's result, a list of records, each its id, url, times and properties." : PerItem);
            todo.Add("choose its connection - n8n's credentials stay in n8n: add a Notion connection under Admin > Connections (an integration's secret, the database shared with it) and pick it here.");
        }

        // n8n names a property "Name|type".
        private static (string Name, string Type) NotionProperty(string key) =>
            key.LastIndexOf('|') is var bar and >= 0 ? (key[..bar], key[(bar + 1)..]) : (key, "");

        // A JSON parameter on the one line a parameter takes: compacted when it is JSON, its line breaks spaces when not.
        private static string OneLine(string value)
        {
            if (value.StartsWith('='))
            {
                return "=" + string.Join(" ", value[1..].Split('\n', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries));
            }

            try
            {
                using var json = JsonDocument.Parse(value);
                return JsonSerializer.Serialize(json.RootElement);
            }
            catch (JsonException)
            {
                return string.Join(" ", value.Split('\n', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries));
            }
        }

        // The base and the table (by the name n8n kept beside a chosen one), a search's formula; a create's mapped columns as the
        // record it creates, an n8n expression among them making the parameters one. Its older node named the base "application".
        private static void Airtable(JsonElement p, PipelineGraphStep step, Todo todo, bool create)
        {
            Set(step, "Operation", create ? "create" : "search");
            var table = Text(p, "table", "cachedResultName") is { Length: > 0 } named ? named : Locator(p, "table");
            var lines = new List<(string Name, string Value)>
            {
                ("base", Locator(p, "base") is { Length: > 0 } baseId ? baseId : Text(p, "application")),
                ("table", table),
            };
            if (!create && (Text(p, "filterByFormula") is { Length: > 0 } formula ? formula : Text(p, "additionalOptions", "filterByFormula")) is { Length: > 0 } filter)
            {
                lines.Add(("formula", filter));
            }

            if (create)
            {
                var columns = p.ValueKind == JsonValueKind.Object && p.TryGetProperty("columns", out var mapped) && mapped.ValueKind == JsonValueKind.Object
                    && Text(mapped, "mappingMode") != "autoMapInputData" && mapped.TryGetProperty("value", out var values) && values.ValueKind == JsonValueKind.Object
                    ? values.EnumerateObject().Select(column => (column.Name, Value: Text(values, column.Name))).ToList()
                    : new List<(string Name, string Value)>();
                if (columns.Count > 0)
                {
                    var record = "{" + string.Join(", ", columns.Select(column => JsonSerializer.Serialize(column.Name) + ": " + JsonSerializer.Serialize(Unmarked(column.Value)))) + "}";
                    lines.Add(("fields", columns.Any(column => column.Value.StartsWith('=')) ? "=" + record : record));
                }
                else
                {
                    todo.Add("it created a record from the item's fields by name - here give its fields in Parameters, 'fields = {{ record }}'.");
                }
            }

            Set(step, "Parameters", FtpParameters(lines.Where(line => line.Value.Length > 0).ToArray()));
            todo.Add(create ? PerItem : "n8n gave each record as an item - here the records are the step's result, a list, each its fields, id and created_time.");
            todo.Add("choose its connection - n8n's credentials stay in n8n: add an Airtable connection under Admin > Connections (a personal access token) and pick it here.");
        }

