        private static string ChatCredential(string service, string token) =>
            $"its account was n8n's {service} credential, which an export never carries - make a {service} connection (Admin > Connections) with {token} and choose it here.";

        // A resource locator n8n keeps as { "value": ... } (its newer nodes) or as text (its older ones).
        private static string Locator(JsonElement p, string name) =>
            (Text(p, name, "value") is { Length: > 0 } value ? value : p.ValueKind == JsonValueKind.Object && p.TryGetProperty(name, out var plain) && plain.ValueKind == JsonValueKind.String ? plain.GetString() ?? "" : "").Trim();

        // The columns a write sets and the value each takes: listed with their values (n8n's "Map each column manually"), or
        // listed by name to read from the item (its newer nodes' mapped columns, its older nodes' "a, b").
        private static List<(string Column, string Value)> SqlColumns(JsonElement p)
        {
            if (p.ValueKind == JsonValueKind.Object && p.TryGetProperty("columns", out var columns) && columns.ValueKind == JsonValueKind.Object)
            {
                if (Text(columns, "mappingMode") != "autoMapInputData" && columns.TryGetProperty("value", out var values) && values.ValueKind == JsonValueKind.Object)
                {
                    return values.EnumerateObject().Select(value => (value.Name, Text(values, value.Name))).ToList();
                }

                return columns.TryGetProperty("schema", out var schema) && schema.ValueKind == JsonValueKind.Array
                    ? schema.EnumerateArray().Where(column => Text(column, "removed") != "true" && Text(column, "id").Length > 0).Select(column => (Text(column, "id"), "={{ $json." + Text(column, "id") + " }}")).ToList()
                    : new List<(string, string)>();
            }

            // The older nodes' list - "id,name", a column perhaps cast as n8n allowed, "id:int": the column, its value the item's field
            // of its name (the database casts it to the column's own type).
            return Text(p, "columns").Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .Select(column => column.Split(':')[0].Trim()).Select(column => (column, "={{ $json." + column + " }}")).ToList();
        }

        // The columns an update, upsert or delete matches rows by.
        private static List<string> SqlKeys(JsonElement p, string operation, string? fallback = null)
        {
            if (p.ValueKind == JsonValueKind.Object && p.TryGetProperty("columns", out var columns) && columns.ValueKind == JsonValueKind.Object
                && columns.TryGetProperty("matchingColumns", out var matching) && matching.ValueKind == JsonValueKind.Array)
            {
                return matching.EnumerateArray().Select(key => key.GetString() ?? "").Where(key => key.Length > 0).ToList();
            }

            var named = Text(p, operation == "delete" ? "deleteKey" : "updateKey") is { Length: > 0 } given ? given : fallback ?? "";
            return named.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList();
        }

        // A list n8n writes with commas, each item perhaps an expression: the commas between {{ }}, not those inside one.
        private static List<string> CommasOutsidePlaceholders(string text)
        {
            var items = new List<string>();
            var depth = 0;
            var start = 0;
            for (var i = 0; i < text.Length; i++)
            {
                if (i + 1 < text.Length && text[i] == '{' && text[i + 1] == '{')
                {
                    depth++;
                    i++;
                }
                else if (i + 1 < text.Length && text[i] == '}' && text[i + 1] == '}' && depth > 0)
                {
                    depth--;
                    i++;
                }
                else if (text[i] == ',' && depth == 0)
                {
                    items.Add(text[start..i].Trim());
                    start = i + 1;
                }
            }

            items.Add(text[start..].Trim());
            return items.Where(item => item.Length > 0).ToList();
        }

        // The nodes the flow runs through: an end of a "main" connection. n8n's AI sub-nodes (a model, a memory, a tool, an
        // embeddings model, a document loader) join by ai_* connections only.
        private static HashSet<string> MainFlow(JsonElement root)
        {
            var names = new HashSet<string>(StringComparer.Ordinal);
            if (!root.TryGetProperty("connections", out var connections) || connections.ValueKind != JsonValueKind.Object)
            {
                return names;
            }

            foreach (var source in connections.EnumerateObject())
            {
                if (source.Value.ValueKind != JsonValueKind.Object || !source.Value.TryGetProperty("main", out var main) || main.ValueKind != JsonValueKind.Array)
                {
                    continue;
                }

                foreach (var output in main.EnumerateArray().Where(output => output.ValueKind == JsonValueKind.Array))
                {
                    foreach (var target in output.EnumerateArray().Select(target => Text(target, "node")).Where(target => target.Length > 0))
                    {
                        names.Add(source.Name);
                        names.Add(target);
                    }
                }
            }

            return names;
        }

        // n8n's vector stores in the flow: "Insert Documents" as Store passages, "Get Many" as Find passages - a data table of the
        // site's, its passages found by the words they share; another mode (a retriever, a tool) hangs off a chain or an agent.
        private static Mapping? VectorStore(string kind, JsonElement p)
        {
            var table = Text(p, "memoryKey") is { Length: > 0 } key && key != "vector_store_key" ? key : "Passages";
            void Where(PipelineGraphStep step, Todo todo)
            {
                Set(step, "Table", table);
                if (!kind.Equals("vectorStoreInMemory", StringComparison.OrdinalIgnoreCase))
                {
                    todo.Add("its vectors were kept in " + kind["vectorStore".Length..] + " - here the passages are kept in the site's data table '" + table + "' and found by the words they share; no embeddings model is needed.");
                }
            }

            return Text(p, "mode") switch
            {
                "insert" => new Mapping("Stomme.StorePassages", DoneFailed, (p, step, todo) =>
                {
                    Where(step, todo);
                    Set(step, "Source", "n8n");
                    todo.Add("it stored what n8n's document loader read - here the previous step's text, under the Source 'n8n': name what it is, as storing a source again replaces its passages.");
                }),
                "load" => new Mapping("Stomme.FindPassages", DoneFailed, (p, step, todo) =>
                {
                    Where(step, todo);
                    Set(step, "Question", Text(p, "prompt"));
                    Set(step, "Top", Number(p, "topK")?.ToString(CultureInfo.InvariantCulture));
                }),
                _ => null,
            };
        }

        // n8n's $('Node') and $node["Node"] - an earlier node's output read in an expression - as this site reads one: the node's
        // step saves its result to a variable named after it (the one it already saves to, else made here), and the expression
        // reads that variable. n8n read one item of the output (.item, .first(), .last()); the variable holds the step's whole
        // result, so a list reads [0] - said on the note. A node with no step here is left as written (its placeholder is named).
        private static readonly Regex NodeReference = new(
            @"\$\(\s*(?<q>['""])(?<name>.+?)\k<q>\s*\)(?:\.(?:item|first\(\)|last\(\)|all\(\)))?(?:\.json)?|\$node\[\s*(?<q2>['""])(?<name2>.+?)\k<q2>\s*\](?:\.json)?",
            RegexOptions.Compiled | RegexOptions.CultureInvariant);

        private static void NodeReferences(PipelineGraph graph, Dictionary<string, (PipelineGraphStep Step, Mapping Mapping, JsonElement Node)> byName, Todo todo)
        {
            var read = new Dictionary<string, PipelineGraphVariable>(StringComparer.Ordinal); // by node name
            string Rewrite(string text, PipelineGraphStep reader, HashSet<string> named) => string.IsNullOrEmpty(text) ? text : NodeReference.Replace(text, match =>
            {
                var name = match.Groups["name"].Success ? match.Groups["name"].Value : match.Groups["name2"].Value;
                if (!byName.TryGetValue(name, out var source) || source.Step.Type == PlaceholderType || ReferenceEquals(source.Step, reader))
                {
                    return match.Value;
                }

                if (!read.TryGetValue(name, out var variable))
                {
                    variable = source.Step.OutputVariables.TryGetValue("Result", out var id) ? graph.Variables.FirstOrDefault(known => known.Id == id) : null;
                    if (variable is null)
                    {
                        variable = new PipelineGraphVariable { Id = "var-n8n-" + (graph.Variables.Count + 1), Name = PipelineVariableNames.For(name, graph.Variables.Select(known => known.Name)), TypeName = "Object" };
                        graph.Variables.Add(variable);
                        source.Step.OutputVariables["Result"] = variable.Id;
                    }

                    read[name] = variable;
                }

                named.Add(name);
                return variable.Name;
            });

            foreach (var step in graph.Steps)
            {
                var named = new HashSet<string>(StringComparer.Ordinal);
                foreach (var input in step.InputExpressions.Keys.ToList())
                {
                    step.InputExpressions[input] = Rewrite(step.InputExpressions[input], step, named);
                }

                foreach (var rule in step.InputConditions.Values.SelectMany(condition => condition.Rules))
                {
                    rule.Left = Rewrite(rule.Left, step, named);
                    rule.Right = Rewrite(rule.Right, step, named);
                }

                if (named.Count > 0)
                {
                    todo.Node = step.Name;
                    todo.Add("it read " + string.Join(", ", named.Select(name => "'" + name + "'")) + " with $('...') in n8n - here "
                        + string.Join(", ", named.Select(name => read[name].Name)) + ", the variable" + (named.Count == 1 ? " its" : "s their") + " result is saved to; n8n read one item, here it is the whole result (a list reads [0]).");
                }
            }
        }

        // n8n's HTTP Request: its URL with its query, its method and headers (an Authorization header as the step's own), its body -
        // JSON, a form, raw - its timeout, and its pagination as the step's own where it is one of the step's three ways: a page
        // number in the query, a next URL in the body. What a step here does differently (n8n's binary data, a multipart form,
        // credentials, a paging expression) is named.
        private static void Http(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            var url = Text(p, "url");
            var query = new List<string>();
            if (Bool(p, "sendQuery"))
            {
                var unwritten = new List<string>();
                if (Text(p, "specifyQuery") == "json")
                {
                    unwritten.Add("JSON");
                }
                else
                {
                    foreach (var parameter in Items(p, "queryParameters", "parameters").Where(parameter => Text(parameter, "name").Length > 0))
                    {
                        var value = Text(parameter, "value");
                        if (value.StartsWith('='))
                        {
                            unwritten.Add(Text(parameter, "name"));
                        }
                        else
                        {
                            query.Add(Uri.EscapeDataString(Text(parameter, "name")) + "=" + Uri.EscapeDataString(value));
                        }
                    }
                }

                if (unwritten.Count > 0)
                {
                    todo.Add("its query's " + string.Join(", ", unwritten) + " - n8n's expressions - " + (unwritten.Count == 1 ? "is" : "are") + " not in its URL; add " + (unwritten.Count == 1 ? "it" : "them") + ".");
                }
            }

            Set(step, "Method", Text(p, "method") is { Length: > 0 } method ? method.ToUpperInvariant() : "GET");
            if (Bool(p, "sendHeaders"))
            {
                var headers = new List<(string Name, string Value)>();
                if (Text(p, "specifyHeaders") == "json")
                {
                    if (JsonObjectOf(Unmarked(Text(p, "jsonHeaders"))) is { } json)
                    {
                        headers.AddRange(json.EnumerateObject().Select(header => (header.Name, Text(header.Value))));
                    }
                    else
                    {
                        todo.Add("its headers were n8n's JSON expression - set them as 'Name: value' lines.");
                    }
                }
                else
                {
                    headers.AddRange(Items(p, "headerParameters", "parameters").Select(header => (Text(header, "name"), Text(header, "value"))));
                }

                var authorization = headers.FirstOrDefault(header => header.Name.Equals("Authorization", StringComparison.OrdinalIgnoreCase));
                Set(step, "Authorization", authorization.Value); // the step's own field, kept out of a run's data
                Set(step, "Headers", string.Join("\n", headers.Where(header => header.Name.Length > 0 && header != authorization).Select(header => header.Name + ": " + header.Value)));
            }

            if (Bool(p, "sendBody"))
            {
                switch (Text(p, "contentType") is { Length: > 0 } kind ? kind : "json")
                {
                    case "json" when Text(p, "specifyBody") == "json":
                        Set(step, "Body", Text(p, "jsonBody"));
                        Set(step, "ContentType", "application/json");
                        break;
                    case "json":
                        Set(step, "Body", JsonSerializer.Serialize(BodyFields(p).ToDictionary(field => field.Name, field => field.Value)));
                        Set(step, "ContentType", "application/json");
                        break;
                    case "form-urlencoded":
                        Set(step, "Body", Text(p, "specifyBody") == "string" ? Text(p, "body")
                            : string.Join("&", BodyFields(p).Select(field => Uri.EscapeDataString(field.Name) + "=" + Uri.EscapeDataString(field.Value))));
                        Set(step, "ContentType", "application/x-www-form-urlencoded");
                        break;
                    case "raw":
                        Set(step, "Body", Text(p, "body"));
                        Set(step, "ContentType", Text(p, "rawContentType"));
                        break;
                    case "multipart-form-data":
                        todo.Add("it sent a multipart form - here Send file and File field send a file as one; its other fields have no counterpart.");
                        break;
                    case "binaryData":
                        todo.Add("it sent n8n's binary data - here Send file sends a file from the pipeline folder; name it.");
                        break;
                }
            }

            if (Number(p, "options", "timeout") is { } milliseconds && milliseconds > 0)
            {
                Set(step, "TimeoutSeconds", ((milliseconds + 999) / 1000).ToString(CultureInfo.InvariantCulture));
            }

            if (Text(p, "options", "response", "response", "responseFormat") == "file")
            {
                todo.Add("it kept the response as n8n's binary data - here Save to writes it to a file in the pipeline folder; name it.");
            }

            Paging(Find(p, "options", "pagination", "pagination"), step, query, todo);
            Set(step, "Url", url.StartsWith('=') || query.Count == 0 ? url : url + (url.Contains('?') ? "&" : "?") + string.Join("&", query));
            if (url.StartsWith('=') && query.Count > 0)
            {
                todo.Add("its URL is an n8n expression, so its query " + string.Join("&", query) + " is not in it - add it.");
            }

            if (Text(p, "authentication") is { Length: > 0 } auth && auth != "none")
            {
                todo.Add("it signed in with n8n's " + auth + " - give it a connection, or the Authorization it needs.");
            }
        }

        // n8n's body fields, by name and value as written.
        private static IEnumerable<(string Name, string Value)> BodyFields(JsonElement p) =>
            Items(p, "bodyParameters", "parameters").Select(field => (Text(field, "name"), Text(field, "value"))).Where(field => field.Item1.Length > 0);

        // n8n's pagination, as the step's where it is one of its ways: a next URL in the body ({{ $response.body.links.next }}),
        // or a page number in the query ({{ $pageCount + 1 }} from 1, {{ $pageCount }} from 0 - a page=0 added to the URL).
        private static void Paging(JsonElement paging, PipelineGraphStep step, List<string> query, Todo todo)
        {
            if (paging.ValueKind != JsonValueKind.Object)
            {
                return;
            }

            var mode = Text(paging, "paginationMode") is { Length: > 0 } named ? named : "updateAParameterInEachRequest";
            if (mode == "responseContainsNextURL")
            {
                var next = Unmarked(Text(paging, "nextURL")).Trim();
                if (Regex.Match(next, @"^\{\{\s*\$response\.body((?:\.[A-Za-z_$][\w$]*)+)\s*\}\}$") is { Success: true } field)
                {
                    Set(step, "Pagination", "NextUrlInBody");
                    Set(step, "NextField", field.Groups[1].Value.TrimStart('.'));
                }
                else
                {
                    todo.Add("it found the next page by " + next + " - here say where the next page's URL is (Pagination).");
                }
            }
            else if (mode == "updateAParameterInEachRequest")
            {
                var parameters = Items(paging, "parameters", "parameters").ToList();
                var counted = parameters.Count == 1 && Text(parameters[0], "type") is "" or "qs"
                    ? Unmarked(Text(parameters[0], "value")).Replace(" ", "", StringComparison.Ordinal)
                    : "";
                if (counted is "{{$pageCount+1}}" or "{{$pageCount}}")
                {
                    Set(step, "Pagination", "PageNumber");
                    Set(step, "NextField", Text(parameters[0], "name"));
                    if (counted == "{{$pageCount}}")
                    {
                        query.Add(Uri.EscapeDataString(Text(parameters[0], "name")) + "=0"); // n8n counted from 0; here it counts on from the URL's
                    }
                }
                else
                {
                    todo.Add("it changed " + string.Join(", ", parameters.Select(parameter => Text(parameter, "name"))) + " from page to page by n8n's expressions - here a page number in the query, a next URL or the Link header page through (Pagination).");
                }
            }

            if (mode != "off")
            {
                if (Bool(paging, "limitPagesFetched"))
                {
                    Set(step, "MaxPages", (Number(paging, "maxRequests") ?? 100).ToString(CultureInfo.InvariantCulture));
                }

                todo.Add("its pages' records are gathered into one list here - when a page is not a list, say where its records are (Records field).");
            }
        }

        // n8n's Switch (rules): a case per rule, named as n8n's output was, its conditions as the case's; the fallback is Default.
        private static void Switch(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            var rules = Items(p, "rules", "values").ToList();
            var cases = new Todo { Node = todo.Node }; // what the cases leave to finish, each thing said once
            for (var index = 0; index < rules.Count; index++)
            {
                var label = Bool(rules[index], "renameOutput") || Text(rules[index], "outputKey").Length > 0 ? Text(rules[index], "outputKey") : "";
                step.Cases.Add(new PipelineGraphCase { Label = label.Length > 0 ? label : "Rule " + (index + 1), Condition = Condition(rules[index], records: false, cases) });
            }

            todo.Lines.AddRange(cases.Lines.Distinct().Select(line => line.Replace("set its condition", "set its cases' conditions")));
            if (rules.Count == 0)
            {
                todo.Add("set its cases - n8n's rules did not come over.");
            }
        }

        // n8n's Edit Fields (Set), every version's shape, as Map fields. A field copying one of the item's fields is a mapping; a
        // constant, a template over the item's top-level fields, or one JavaScript expression over them is a computed field -
        // each typed as n8n typed it. A field that cannot be written so is kept in Computed as a # line, which runs nothing, and
        // named. Whether the item's other fields come along is as n8n's version had it: from 3.3 only when it was told so, before
        // that unless it was told otherwise.
        private static void EditFields(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            var fields = new EditedFields();
            if (Text(p, "mode") == "raw")
            {
                var json = Unmarked(Text(p, "jsonOutput"));
                if (!json.Contains("{{", StringComparison.Ordinal) && JsonObjectOf(json) is { } constants)
                {
                    foreach (var property in constants.EnumerateObject())
                    {
                        fields.Assign(property.Name, KindOf(property.Value), property.Value.ValueKind == JsonValueKind.Null ? "null" : Text(property.Value));
                    }
                }
                else
                {
                    fields.Computed.AddRange(("n8n's JSON:\n" + json).Split('\n').Select(line => "# " + line.TrimEnd('\r')));
                    todo.Add("it wrote its fields as JSON over n8n's items - set them as Mappings or Computed here; its JSON is kept in Computed.");
                }
            }
            else
            {
                foreach (var (name, type, value) in AssignmentsOf(p))
                {
                    fields.Assign(name, type, value);
                }
            }

            var version = todo.Version > 0 ? todo.Version : p.TryGetProperty("values", out _) ? 2 : p.TryGetProperty("fields", out _) ? 3 : 3.3;
            var include = version >= 3.3 ? (Bool(p, "includeOtherFields") ? Text(p, "include") is { Length: > 0 } chosen ? chosen : "all" : "none")
                : version >= 3 ? Text(p, "include") is { Length: > 0 } named ? named : "all"
                : Bool(p, "keepOnlySet") ? "none" : "all";

            // The item's fields it kept, each as itself and before the fields it sets, which win as they do in n8n; the ones it
            // left out, left out of what passes through.
            var kept = include == "selected" ? Text(p, "includeFields").Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries) : Array.Empty<string>();
            var unwritable = kept.Where(field => field.IndexOfAny(new[] { ':', '=' }) >= 0 || field.StartsWith('#')).ToList();
            Set(step, "Mappings", string.Join("\n", kept.Except(unwritable).Select(field => field + " => " + field + " : Any").Concat(fields.Mappings)));
            Set(step, "Computed", string.Join("\n", fields.Computed));
            if (include is "all" or "except")
            {
                Set(step, "PassThroughUnmapped", "true");
            }

            if (include == "except")
            {
                Set(step, "LeaveOut", Text(p, "excludeFields"));
            }

            if (unwritable.Count > 0)
            {
                todo.Add("it kept the item's " + string.Join(", ", unwritable) + " - a name with ':' or '=' cannot be a mapping here; pass every field through to keep " + (unwritable.Count == 1 ? "it." : "them."));
            }

            var dotted = fields.Names.Where(name => name.Contains('.')).ToList();
            if (dotted.Count > 0 && Text(p, "options", "dotNotation") != "false")
            {
                todo.Add("n8n made " + string.Join(", ", dotted) + (dotted.Count == 1 ? " a nested field" : " nested fields") + " (dot notation) - here a dotted name is one field.");
            }

            if (fields.Scripts.Count > 0)
            {
                todo.Add("its " + string.Join(", ", fields.Scripts) + (fields.Scripts.Count == 1 ? " is" : " are") + " JavaScript here - run with Pipelines:Scripts:Enabled, each field read as text.");
            }

            if (fields.Kept.Count > 0)
            {
                todo.Add("its " + string.Join(", ", fields.Kept) + " could not come over as written - kept in Computed as # lines, which run nothing; rewrite " + (fields.Kept.Count == 1 ? "it." : "them."));
            }
        }

        // The fields an Edit Fields node sets, as (name, n8n's type, value as written): 3.3's assignments, 3.0's fields (the value
        // under its type's own name - its default when n8n left it out), or the first versions' values by type.
        private static IEnumerable<(string Name, string Type, string Value)> AssignmentsOf(JsonElement p)
        {
            foreach (var assignment in Items(p, "assignments", "assignments"))
            {
                yield return (Text(assignment, "name"), Text(assignment, "type") is { Length: > 0 } type ? type : "string", Text(assignment, "value"));
            }

            foreach (var field in Items(p, "fields", "values"))
            {
                var kind = Text(field, "type") is { Length: > 0 } named ? named : "stringValue";
                var value = Text(field, kind);
                yield return (Text(field, "name"), kind.Replace("Value", "", StringComparison.Ordinal), value.Length > 0 ? value : kind switch { "booleanValue" => "true", "objectValue" => "{}", _ => "" });
            }

            if (p.TryGetProperty("values", out var values) && values.ValueKind == JsonValueKind.Object)
            {
                foreach (var kind in values.EnumerateObject().Where(kind => kind.Value.ValueKind == JsonValueKind.Array))
                {
                    foreach (var value in kind.Value.EnumerateArray().Where(value => value.ValueKind == JsonValueKind.Object))
                    {
                        var text = Text(value, "value");
                        yield return (Text(value, "name"), kind.Name, text.Length == 0 && kind.Name == "boolean" ? "false" : text);
                    }
                }
            }
        }

        // What an Edit Fields node's fields become: Map fields' mapping and computed lines, and the names said on the note.
        private sealed class EditedFields
        {
            public List<string> Mappings { get; } = new();

            public List<string> Computed { get; } = new();

            public List<string> Names { get; } = new();

            public List<string> Scripts { get; } = new();

            public List<string> Kept { get; } = new();

            public void Assign(string name, string type, string value)
            {
                name = name.Trim();
                if (name.Length == 0)
                {
                    return;
                }

                Names.Add(name);
                var typed = name + TypeSuffix(type);
                if (name.IndexOfAny(new[] { ':', '=' }) >= 0 || name.StartsWith('#'))
                {
                    Keep(name, value); // a line here reads ':' as the type and '=' as the value
                }
                else if (!value.StartsWith('='))
                {
                    var constant = type is "array" or "object" ? Minified(value) : value;
                    if (constant.Contains('\n') || constant.Contains("{{", StringComparison.Ordinal) || constant.Contains("{%", StringComparison.Ordinal)
                        || constant.TrimStart().StartsWith("js:", StringComparison.OrdinalIgnoreCase))
                    {
                        Keep(name, constant);
                    }
                    else
                    {
                        Computed.Add(typed + " = " + constant);
                    }
                }
                else if (FieldPath(value[1..].Trim()) is { } path)
                {
                    Mappings.Add(path + " => " + typed);
                }
                else if (LiquidOf(value[1..].Trim()) is { } template)
                {
                    Computed.Add(typed + " = " + template);
                }
                else if (ScriptOf(value[1..].Trim()) is { } script)
                {
                    Computed.Add(typed + " = js: " + script);
                    Scripts.Add(name);
                }
                else
                {
                    Keep(name, value[1..]);
                }
            }

            private void Keep(string name, string value)
            {
                Computed.Add("# " + name + " = " + value.Replace("\r", "", StringComparison.Ordinal).Replace('\n', ' '));
                Kept.Add(name);
            }
        }

        private static string TypeSuffix(string type) => type switch
        {
            "number" => " : Number",
            "boolean" => " : Boolean",
            "array" or "object" => " : Json",
            _ => "",
        };

        private static string KindOf(JsonElement value) => value.ValueKind switch
        {
            JsonValueKind.Number => "number",
            JsonValueKind.True or JsonValueKind.False => "boolean",
            JsonValueKind.String => "string",
            _ => "object",
        };

        private static readonly Regex FieldReference = new(@"^\{\{\s*\$json((?:\.[A-Za-z_$][\w$]*|\[\s*(?:'[^']*'|""[^""]*"")\s*\])+)\s*\}\}$");
        private static readonly Regex Accessor = new(@"\.([A-Za-z_$][\w$]*)|\[\s*(?:'([^']*)'|""([^""]*)"")\s*\]");
        private static readonly Regex Braced = new(@"\{\{(.*?)\}\}", RegexOptions.Singleline);
        private static readonly Regex TopLevelField = new(@"^\s*\$json\.([A-Za-z_]\w*)\s*$");
        private static readonly Regex WholeExpression = new(@"^\{\{(.*)\}\}$", RegexOptions.Singleline);
        private static readonly Regex ItemField = new(@"\$json\.([A-Za-z_]\w*)");
        private static readonly Regex DeeperRead = new(@"\$json\.[A-Za-z_]\w*(?>\s*)(?:\[|\.(?>[A-Za-z_]\w*)(?!\s*\())");

        // {{ $json.customer.email }} (or $json["first name"]) alone: the item's field at that path, as a mapping reads it.
        private static string? FieldPath(string expression)
        {
            var match = FieldReference.Match(expression);
            if (!match.Success)
            {
                return null;
            }

            var segments = Accessor.Matches(match.Groups[1].Value)
                .Select(found => found.Groups[1].Success ? found.Groups[1].Value : found.Groups[2].Success ? found.Groups[2].Value : found.Groups[3].Value)
                .ToList();
            return segments.Any(segment => segment.Length == 0 || segment.Contains('.') || segment.Contains("=>", StringComparison.Ordinal) || segment.Contains("->", StringComparison.Ordinal))
                ? null
                : string.Join(".", segments);
        }

        // Text whose every placeholder reads one of the item's top-level fields: a Liquid template over the record, {{ field }}.
        private static string? LiquidOf(string expression)
        {
            if (expression.Contains('\n') || expression.Contains("{%", StringComparison.Ordinal) || expression.StartsWith("js:", StringComparison.OrdinalIgnoreCase))
            {
                return null;
            }

            var readable = true;
            var template = Braced.Replace(expression, placeholder =>
            {
                var field = TopLevelField.Match(placeholder.Groups[1].Value);
                readable &= field.Success;
                return field.Success ? "{{ " + field.Groups[1].Value + " }}" : placeholder.Value;
            });
            return readable ? template : null;
        }

        // One {{ JavaScript }} over the item's top-level fields: the same expression in the sandbox, each field a variable of its
        // name. One reading deeper than a top-level field ($json.customer.email, $json.items[0]) or any other of n8n's $ is not.
        private static string? ScriptOf(string expression)
        {
            var match = WholeExpression.Match(expression);
            if (!match.Success || match.Groups[1].Value.Contains("{{", StringComparison.Ordinal) || match.Groups[1].Value.Contains("}}", StringComparison.Ordinal))
            {
                return null;
            }

            var script = match.Groups[1].Value.Trim();
            if (script.Length == 0 || script.Contains('\n') || DeeperRead.IsMatch(script))
            {
                return null;
            }

            script = ItemField.Replace(script, "$1");
            return script.Contains('$') ? null : script;
        }

        private static string Unmarked(string value) => value.StartsWith('=') ? value[1..] : value;

        private static string Minified(string json)
        {
            try
            {
                using var document = JsonDocument.Parse(json);
                return JsonSerializer.Serialize(document.RootElement, ReadableJson);
            }
            catch (JsonException)
            {
                return json;
            }
        }

        private static JsonElement? JsonObjectOf(string json)
        {
            try
            {
                using var document = JsonDocument.Parse(json);
                return document.RootElement.ValueKind == JsonValueKind.Object ? document.RootElement.Clone() : null;
            }
            catch (JsonException)
            {
                return null;
            }
        }

        // n8n's conditions as rules, from a node's (or a Switch rule's) "conditions": version 2's { combinator, options.caseSensitive,
        // conditions: [ { leftValue, operator: { operation }, rightValue } ] }, or version 1's { string | number | boolean | dateTime:
        // [ { value1, operation, value2 } ] } combined by combineOperation. A rule whose operation has no counterpart here is left
        // out, and named. In a record condition (Filter) n8n's $json.field is the record's field - {{ field }} here; elsewhere a
        // placeholder reads a variable, so one still reading n8n's items is named for the author to rewrite.
        private static PipelineCondition Condition(JsonElement holder, bool records, Todo todo)
        {
            var condition = new PipelineCondition();
            var skipped = new List<string>();
            var conditions = holder.ValueKind == JsonValueKind.Object && holder.TryGetProperty("conditions", out var found) ? found : default;
            if (conditions.ValueKind == JsonValueKind.Object && conditions.TryGetProperty("conditions", out var rules) && rules.ValueKind == JsonValueKind.Array)
            {
                condition.Match = Text(conditions, "combinator") == "or" ? PipelineConditions.Any : PipelineConditions.All;
                condition.IgnoreCase = Text(conditions, "options", "caseSensitive") == "false" || Bool(holder, "options", "ignoreCase");
                foreach (var rule in rules.EnumerateArray())
                {
                    Rule(condition, Text(rule, "operator", "operation"), Text(rule, "leftValue"), Text(rule, "rightValue"), records, skipped);
                }
            }
            else if (conditions.ValueKind == JsonValueKind.Object)
            {
                condition.Match = Text(holder, "combineOperation") == "any" ? PipelineConditions.Any : PipelineConditions.All;
                foreach (var kind in conditions.EnumerateObject().Where(kind => kind.Value.ValueKind == JsonValueKind.Array))
                {
                    foreach (var rule in kind.Value.EnumerateArray())
                    {
                        Rule(condition, Text(rule, "operation"), Text(rule, "value1"), Text(rule, "value2"), records, skipped);
                    }
                }
            }

            if (condition.Rules.Count == 0 && skipped.Count == 0)
            {
                todo.Add("set its condition - n8n's had no rule this import could read.");
            }

            if (skipped.Count > 0)
            {
                todo.Add("n8n's " + string.Join(", ", skipped.Distinct()) + (skipped.Distinct().Count() == 1 ? " rule has" : " rules have") + " no counterpart here - add " + (skipped.Count == 1 ? "it" : "them") + " to its condition.");
            }

            if (condition.Rules.Any(rule => ReadsN8nItems(rule.Left) || ReadsN8nItems(rule.Right)))
            {
                todo.Add(records
                    ? "its condition reads n8n's other nodes - a placeholder here reads the record's field, or a variable."
                    : "its condition reads n8n's items ($json) - a placeholder here reads a variable; rewrite them.");
            }

            return condition;
        }

        private static void Rule(PipelineCondition condition, string operation, string left, string right, bool records, List<string> skipped)
        {
            if (OperatorOf(operation) is not { } code)
            {
                skipped.Add(operation.Length == 0 ? "unnamed" : operation);
                return;
            }

            condition.Rules.Add(new PipelineConditionRule { Left = Side(left, records), Operator = code, Right = PipelineConditions.Operator(code)?.TakesValue == false ? "" : Side(right, records) });
        }

        // n8n's operations (version 2's, then version 1's names) as this site's operators.
        private static string? OperatorOf(string operation) => operation switch
        {
            "equals" or "equal" => PipelineConditions.EqualsOperator,
            "notEquals" or "notEqual" => "not-equals",
            "contains" => "contains",
            "notContains" => "not-contains",
            "startsWith" => "starts-with",
            "endsWith" => "ends-with",
            "gt" or "larger" or "after" => "greater",
            "gte" or "largerEqual" or "afterOrEquals" => "at-least",
            "lt" or "smaller" or "before" => "less",
            "lte" or "smallerEqual" or "beforeOrEquals" => "at-most",
            "empty" or "isEmpty" or "notExists" => "empty",
            "notEmpty" or "isNotEmpty" or "exists" => "not-empty",
            "true" => "true",
            "false" => "false",
            _ => null,
        };

        // A side of a rule: n8n's expression mark ("=") dropped; in a record condition, $json.field (or $json["field"]) is the field.
        private static string Side(string value, bool records)
        {
            var text = value.StartsWith('=') ? value[1..] : value;
            return records
                ? System.Text.RegularExpressions.Regex.Replace(System.Text.RegularExpressions.Regex.Replace(text, @"\$json\.", ""), @"\$json\[\s*['""]([^'""]+)['""]\s*\]", "$1")
                : text;
        }

        private static bool ReadsN8nItems(string side) => side.Contains("$json") || side.Contains("$(") || side.Contains("$node") || side.Contains("$input");

        // n8n's schedule rule, as a cron line: its own cron, or every n minutes, hours, days or weeks at the time it names.
        private static string? Cron(JsonElement rule)
        {
            if (rule.ValueKind != JsonValueKind.Object)
            {
                return null;
            }

            var minute = Number(rule, "triggerAtMinute") ?? 0;
            var hour = Number(rule, "triggerAtHour") ?? 0;
            return Text(rule, "field") switch
            {
                "cronExpression" => Text(rule, "expression") is { Length: > 0 } expression ? expression : null,
                "seconds" => "* * * * *",
                "minutes" => $"*/{Math.Max(1, Number(rule, "minutesInterval") ?? 5)} * * * *",
                "hours" => $"{minute} */{Math.Max(1, Number(rule, "hoursInterval") ?? 1)} * * *",
                "" or "days" => $"{minute} {hour} */{Math.Max(1, Number(rule, "daysInterval") ?? 1)} * *",
                "weeks" => $"{minute} {hour} * * {Days(rule)}",
                "months" => $"{minute} {hour} {Number(rule, "triggerAtDayOfMonth") ?? 1} */{Math.Max(1, Number(rule, "monthsInterval") ?? 1)} *",
                _ => null,
            };
        }

        // The first Cron node's trigger time (n8n's own schedule before the Schedule Trigger): every minute, hour, day (at 14:00 when
        // n8n left the time at its default), week, month, every so many minutes or hours, or its own cron line.
        private static string? LegacyCron(JsonElement time)
        {
            var minute = Number(time, "minute") ?? 0;
            var hour = Number(time, "hour") ?? 14;
            var every = Math.Max(1, Number(time, "value") ?? 2);
            return Text(time, "mode") switch
            {
                "everyMinute" => "* * * * *",
                "everyHour" => $"{minute} * * * *",
                "" or "everyDay" => $"{minute} {hour} * * *",
                "everyWeek" => $"{minute} {hour} * * {(Text(time, "weekday") is { Length: > 0 } day ? day : "1")}",
                "everyMonth" => $"{minute} {hour} {Number(time, "dayOfMonth") ?? 1} * *",
                "everyX" => Text(time, "unit") == "minutes" ? $"*/{every} * * * *" : $"0 */{every} * * *",
                "custom" => Text(time, "cronExpression") is { Length: > 0 } expression ? expression : null,
                _ => null,
            };
        }

        // A cron line as a schedule here reads it: five fields. n8n's may lead with a seconds field, dropped - and named when it
        // fired more often than once a minute.
        private static string FiveFields(string cron, Todo todo)
        {
            var fields = cron.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            if (fields.Length != 6)
            {
                return cron;
            }

            if (fields[0] != "0")
            {
                todo.Add("its cron line fired within the minute (" + fields[0] + " seconds) - a schedule here fires at most once a minute.");
            }

            return string.Join(" ", fields.Skip(1));
        }

        // A list of field names as n8n keeps them: "a, b" in a text, or { fields: [ { fieldName } ] } in its older nodes.
        // n8n's Remove Duplicates over earlier executions as Remove records seen before: the value it dedupes on - a field of the
        // item, {{ $json.id }} - as the field compared; an incremental key or a date as "higher than before"; its scope and history
        // size as they were. Its "clear the history" forgets and passes the records on - remembered here, as new.
        private static void SeenBefore(JsonElement p, PipelineGraphStep step, Todo todo)
        {
            step.Type = "Stomme.RemoveSeenRecords";
            var options = p.ValueKind == JsonValueKind.Object && p.TryGetProperty("options", out var held) ? held : default;
            if (Text(options, "scope") == "workflow")
            {
                Set(step, "Scope", "ThePipeline");
            }

            Set(step, "HistorySize", Number(options, "historySize")?.ToString(CultureInfo.InvariantCulture));
            if (Text(p, "operation") == "clearDeduplicationHistory")
            {
                Set(step, "Forget", "true");
                todo.Add("it only cleared what was seen - here the records it passes on are remembered too, as new.");
                return;
            }

            var (value, higher) = Text(p, "logic") switch
            {
                "removeItemsUpToStoredIncrementalKey" => (Text(p, "incrementalDedupeValue"), true),
                "removeItemsUpToStoredDate" => (Text(p, "dateDedupeValue"), true),
                _ => (Text(p, "dedupeValue"), false),
            };
            if (higher)
            {
                Set(step, "Keep", "HigherThanBefore");
            }

            if (System.Text.RegularExpressions.Regex.Match(value, @"^=?\{\{\s*\$json(?:\.([A-Za-z_][\w.]*)|\[\s*['""]([^'""]+)['""]\s*\])\s*\}\}$") is { Success: true } field)
            {
                Set(step, "CompareFields", field.Groups[1].Success ? field.Groups[1].Value : field.Groups[2].Value);
            }
            else if (value.Length > 0)
            {
                todo.Add("it compared " + value + " - here name the field it reads in Compare fields.");
            }
        }

        private static string FieldNames(JsonElement p, string name)
        {
            var listed = Items(p, name, "fields").Select(field => Text(field, "fieldName").Trim()).Where(field => field.Length > 0).ToList();
            return listed.Count > 0 ? string.Join(", ", listed)
                : p.ValueKind == JsonValueKind.Object && p.TryGetProperty(name, out var text) && text.ValueKind == JsonValueKind.String ? text.GetString() ?? "" : "";
        }

        private static string Days(JsonElement rule) =>
            rule.TryGetProperty("triggerAtDay", out var days) && days.ValueKind == JsonValueKind.Array && days.GetArrayLength() > 0
                ? string.Join(",", days.EnumerateArray().Select(day => day.ToString()))
                : "1";

        private static string Aggregation(string kind, string field) => kind switch
        {
            "" => "",
            "count" => field.Length > 0 ? "count " + field : "count",
            "countUnique" => "count distinct " + field,
            "append" => "list " + field,
            "average" => "average " + field,
            "concatenate" => "concatenate " + field,
            "max" or "min" or "sum" => kind + " " + field,
            _ => "",
        };

        // n8n's sticky-note colours (1 to 7) as the nearest of the theme's.
        private static string? NoteColor(JsonElement p) => Number(p, "color") switch
        {
            1 or 2 => PipelineNoteColors.Amber,
            3 => PipelineNoteColors.Red,
            4 => PipelineNoteColors.Green,
            7 => PipelineNoteColors.Grey,
            _ => null,
        };

        // n8n writes an expression as "={{ ... }}": here it is an expression input, as written - its $json reads the item n8n
        // passed along, which a step here reads from a variable, so the author is told.
        private static void MoveExpressions(PipelineGraphStep step, Todo todo)
        {
            var moved = step.Inputs.Where(input => input.Value.StartsWith('=')).Select(input => input.Key).ToList();
            foreach (var input in moved)
            {
                step.InputExpressions[input] = step.Inputs[input][1..];
                step.Inputs.Remove(input);
            }

            if (moved.Count > 0)
            {
                todo.Add("its " + string.Join(", ", moved) + " " + (moved.Count == 1 ? "is an n8n expression" : "are n8n expressions") + " - $json is n8n's item; here a step reads variables.");
            }
        }

        private const string GuardrailCheckType = "Stomme.GuardrailCheck";

        private const string GuardrailSanitizeType = "Stomme.GuardrailSanitize";

        // The kinds of personal data n8n's Guardrails names that the steps here find under the same name.
        private static readonly HashSet<string> GuardrailPersonalData = new(StringComparer.Ordinal)
        {
            "EMAIL_ADDRESS", "PHONE_NUMBER", "CREDIT_CARD", "IBAN_CODE", "IP_ADDRESS", "US_SSN", "UK_NHS", "UK_NINO", "FI_PERSONAL_IDENTITY_CODE", "PL_PESEL", "ES_NIF", "CRYPTO",
        };

        // n8n's guardrails collection as the step's inputs: { "guardrails": { "pii": { "value": { "type": "selected", "entities": [...] } }, ... } }.
        private static void Guardrails(JsonElement p, PipelineGraphStep step, Todo todo, bool check)
        {
            Set(step, "Text", Text(p, "text"));
            if (!p.TryGetProperty("guardrails", out var rails) || rails.ValueKind != JsonValueKind.Object)
            {
                todo.Add("it had no guardrails chosen - choose what it checks.");
                return;
            }

            bool Has(string rail) => rails.TryGetProperty(rail, out var value) && value.ValueKind == JsonValueKind.Object;
            IEnumerable<string> Strings(params string[] path)
            {
                var element = rails;
                foreach (var name in path)
                {
                    if (element.ValueKind != JsonValueKind.Object || !element.TryGetProperty(name, out element))
                    {
                        return Enumerable.Empty<string>();
                    }
                }

                return element.ValueKind == JsonValueKind.Array
                    ? element.EnumerateArray().Where(item => item.ValueKind == JsonValueKind.String).Select(item => item.GetString()!).ToList()
                    : Enumerable.Empty<string>();
            }

            if (check)
            {
                var thresholds = new List<double>();
                void Threshold(string text)
                {
                    if (double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out var threshold))
                    {
                        thresholds.Add(threshold);
                    }
                }

                Set(step, "Keywords", Text(rails, "keywords"));
                foreach (var (rail, input, what) in new[] { ("jailbreak", "Jailbreak", "jailbreak"), ("nsfw", "Unsafe", "unsafe-content") })
                {
                    if (Has(rail))
                    {
                        Set(step, input, "true");
                        Threshold(Text(rails, rail, "value", "threshold"));
                        if (Bool(rails, rail, "customizePrompt") || Bool(rails, rail, "value", "customizePrompt"))
                        {
                            todo.Add($"its own {what} prompt is not brought over - here the site's model is told what the check is.");
                        }
                    }
                }

                if (Has("topicalAlignment"))
                {
                    Set(step, "Topic", Text(rails, "topicalAlignment", "value", "prompt"));
                    Threshold(Text(rails, "topicalAlignment", "value", "threshold"));
                }

                var custom = Items(rails, "custom", "guardrail").Select(each => (Name: Text(each, "name").Trim(), Prompt: Text(each, "prompt").Trim(), Threshold: Text(each, "threshold")))
                    .Where(each => each.Name.Length > 0 && each.Prompt.Length > 0).ToList();
                Set(step, "ModelChecks", string.Join("\n", custom.Select(each => each.Name.Replace(":", " ", StringComparison.Ordinal) + ": " + each.Prompt.ReplaceLineEndings(" "))));
                custom.ForEach(each => Threshold(each.Threshold));
                if (thresholds.Count > 0)
                {
                    Set(step, "Threshold", thresholds.Min().ToString(CultureInfo.InvariantCulture));
                    if (thresholds.Distinct().Count() > 1)
                    {
                        todo.Add($"its model checks had thresholds of their own ({string.Join(", ", thresholds.Distinct().Select(each => each.ToString(CultureInfo.InvariantCulture)))}) - here one Threshold, the lowest.");
                    }
                }

                if (Bool(p, "customizeSystemMessage"))
                {
                    todo.Add("its own system message for the model checks is not brought over.");
                }
            }

            if (Has("pii"))
            {
                if (Text(rails, "pii", "value", "type") == "selected")
                {
                    var entities = Strings("pii", "value", "entities").ToList();
                    Set(step, "PersonalData", string.Join("\n", entities.Where(GuardrailPersonalData.Contains)));
                    if (entities.Where(entity => !GuardrailPersonalData.Contains(entity)).ToList() is { Count: > 0 } left)
                    {
                        todo.Add("its personal data " + string.Join(", ", left) + " has no check here.");
                    }
                }
                else
                {
                    Set(step, "PersonalData", "all");
                }
            }

            if (Has("secretKeys"))
            {
                Set(step, "SecretKeys", Text(rails, "secretKeys", "value", "permissiveness") switch
                {
                    "strict" => "Strict",
                    "permissive" => "Permissive",
                    _ => "Balanced",
                });
            }

            if (Has("urls"))
            {
                Set(step, "CheckUrls", "true");
                Set(step, "AllowedUrls", string.Join("\n", Text(rails, "urls", "value", "allowedUrls").Split(',').Select(each => each.Trim()).Where(each => each.Length > 0 && each != "PLACEHOLDER")));
                if (Strings("urls", "value", "allowedSchemes").ToList() is { Count: > 0 } schemes)
                {
                    Set(step, "AllowedSchemes", string.Join(", ", schemes));
                }

                if (Text(rails, "urls", "value", "blockUserinfo") == "false")
                {
                    Set(step, "BlockUserInfo", "false");
                }

                if (Text(rails, "urls", "value", "allowSubdomains") == "false")
                {
                    Set(step, "AllowSubdomains", "false");
                }
            }

            var patterns = Items(rails, "customRegex", "regex").Select(each => (Name: Text(each, "name").Trim(), Value: Text(each, "value").Trim())).Where(each => each.Name.Length > 0 && each.Value.Length > 0).ToList();
            Set(step, "CustomPatterns", string.Join("\n", patterns.Select(each => each.Name.Replace(":", " ", StringComparison.Ordinal) + ": " + each.Value)));
        }

        private static void Set(PipelineGraphStep step, string input, string? value)
        {
            if (!string.IsNullOrEmpty(value))
            {
                step.Inputs[input] = value;
            }
        }

        private static (double X, double Y) Position(JsonElement node) =>
            node.TryGetProperty("position", out var position) && position.ValueKind == JsonValueKind.Array && position.GetArrayLength() >= 2
                && position[0].TryGetDouble(out var x) && position[1].TryGetDouble(out var y)
                ? (x, y)
                : (0, 0);

        // A parameter as text: a string as it is, a number or a boolean as JSON writes it, anything else - an object, a list - its JSON.
        private static string Text(JsonElement element, params string[] path)
        {
            foreach (var name in path)
            {
                if (element.ValueKind != JsonValueKind.Object || !element.TryGetProperty(name, out element))
                {
                    return "";
                }
            }

            return element.ValueKind switch
            {
                JsonValueKind.String => element.GetString() ?? "",
                JsonValueKind.Undefined or JsonValueKind.Null => "",
                _ => element.GetRawText(),
            };
        }

        private static int? Number(JsonElement element, params string[] path) =>
            int.TryParse(Text(element, path), NumberStyles.Integer, CultureInfo.InvariantCulture, out var value) ? value : null;

        private static bool Bool(JsonElement element, params string[] path) => Text(element, path) == "true";

        // A fixed collection's entries: { "sortFieldsUi": { "sortField": [ ... ] } }.
        private static IEnumerable<JsonElement> Items(JsonElement element, string collection, string list) =>
            element.ValueKind == JsonValueKind.Object && element.TryGetProperty(collection, out var holder) && holder.ValueKind == JsonValueKind.Object
                && holder.TryGetProperty(list, out var items) && items.ValueKind == JsonValueKind.Array
                ? items.EnumerateArray().Where(item => item.ValueKind == JsonValueKind.Object).ToList()
                : Enumerable.Empty<JsonElement>();

    }
}
